def _fetch_teachers_for_technician_preview(cursor):
    """Active teachers for technician test picker on /teachers."""
    rows = []
    try:
        cursor.execute("""
            SELECT e.id, e.full_name, e.employee_id
            FROM employees e
            WHERE LOWER(TRIM(COALESCE(e.role, ''))) IN ('teachers', 'teacher')
            ORDER BY e.full_name ASC
        """)
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                rows.append({
                    'id': r.get('id'),
                    'full_name': (r.get('full_name') or '').strip(),
                    'employee_id': (r.get('employee_id') or '').strip(),
                })
            else:
                rows.append({
                    'id': r[0] if len(r) > 0 else None,
                    'full_name': (r[1] if len(r) > 1 else '') or '',
                    'employee_id': (r[2] if len(r) > 2 else '') or '',
                })
    except Exception as ex:
        print(f"_fetch_teachers_for_technician_preview: {ex}")
    return rows


def employee_dashboard_path(subpath: str = '') -> str:
    """Build /<role-slug>/[subpath] (public URLs; middleware maps to /dashboard/employee/...)."""
    subpath = (subpath or '').strip('/')
    slug = session_employee_role_slug() if has_request_context() else 'employee'
    tail = '/'.join(quote(seg, safe='') for seg in subpath.split('/') if seg)
    base = f'/{slug}'
    return base + ('/' + tail if tail else '')


@app.template_global()
def employee_staff_settings_url(settings_role: str, **query) -> str:
    """Prefixed staff settings URL: /<session-slug>/settings/<role slug>[?query]; curriculum coordinator timetable uses curriculum-timetable-settings."""
    r = (settings_role or 'employee').strip()
    if role_to_slug(r) == role_to_slug('curriculum coordinator'):
        base = employee_dashboard_path('curriculum-timetable-settings')
    else:
        role_path_segment = role_to_slug(r)
        base = employee_dashboard_path(f'settings/{role_path_segment}')
    filtered = {k: v for k, v in query.items() if v is not None and str(v) != ''}
    if filtered:
        return base + '?' + urlencode(filtered)
    return base


