def allowed_communication_attachment(filename):
    """Attachments for communication centre broadcasts."""
    if not filename or '.' not in filename:
        return False
    return filename.rsplit('.', 1)[1].lower() in ALLOWED_COMMUNICATION_EXTENSIONS

def allowed_file(filename):
    """Check if file extension is allowed"""
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def allowed_payment_file(filename):
    """Check if payment proof file extension is allowed"""
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_PAYMENT_EXTENSIONS

def _parse_student_id_digits(val):
    """Parse student_id_digits to int between 1 and 6."""
    try:
        return max(1, min(6, int(val) if val is not None else 3))
    except (TypeError, ValueError):
        return 3


# In-memory cache for school_settings (avoids 2 DB round-trips per request: info_schema + SELECT)
_SCHOOL_SETTINGS_CACHE = {'data': None, 'expires_at': 0.0}
SCHOOL_SETTINGS_CACHE_TTL = int(os.environ.get('SCHOOL_SETTINGS_CACHE_TTL', '300'))


def invalidate_school_settings_cache():
    """Call after any INSERT/UPDATE to school_settings."""
    _SCHOOL_SETTINGS_CACHE['data'] = None
    _SCHOOL_SETTINGS_CACHE['expires_at'] = 0.0


def _default_school_data():
    return {
        'school_name': 'Modern School',
        'school_email': '',
        'school_phone': '',
        'school_logo': None,
        'school_hero_image': None,
        'twitter_url': '',
        'facebook_url': '',
        'instagram_url': '',
        'tiktok_url': '',
        'vimeo_url': '',
        'whatsapp_number': '',
        'school_location': '',
        'project_name': 'Elimu Centric',
        'student_id_prefix': 'STU',
        'student_id_digits': 3,
        'primary_color': '#800020',
        'secondary_color': '#A00030',
        'accent_color': '#5C0014',
        'font_family': 'Inter',
        'maintenance_mode': False,
        'allow_registration': True,
        'default_language': 'en',
        'timezone': 'Africa/Nairobi',
        'default_theme_mode': 'dark',
    }


def get_school_settings():
    """Get school settings from database (includes theme colors). Cached with TTL."""
    now = time.monotonic()
    cached = _SCHOOL_SETTINGS_CACHE['data']
    if cached is not None and now < _SCHOOL_SETTINGS_CACHE['expires_at']:
        return copy.copy(cached)

    school_data = _default_school_data()
    connection = None
    try:
        connection = get_db_connection()
        if connection:
            with connection.cursor() as cursor:
                # Single SELECT — no information_schema probe (saves a round-trip per cold cache)
                cursor.execute("SELECT * FROM school_settings ORDER BY id DESC LIMIT 1")
                result = cursor.fetchone()
                if result:
                    if isinstance(result, dict):
                        school_data = {
                            'school_name': result.get('school_name') or 'Modern School',
                            'school_email': result.get('school_email') or '',
                            'school_phone': result.get('school_phone') or '',
                            'school_logo': result.get('school_logo') or None,
                            'school_hero_image': result.get('school_hero_image') or None,
                            'twitter_url': result.get('twitter_url') or '',
                            'facebook_url': result.get('facebook_url') or '',
                            'instagram_url': result.get('instagram_url') or '',
                            'tiktok_url': result.get('tiktok_url') or '',
                            'vimeo_url': result.get('vimeo_url') or '',
                            'whatsapp_number': result.get('whatsapp_number') or '',
                            'school_location': result.get('school_location') or '',
                            'project_name': result.get('project_name') or 'Elimu Centric',
                            'student_id_prefix': (result.get('student_id_prefix') or 'STU').strip().upper()[:10],
                            'student_id_digits': _parse_student_id_digits(result.get('student_id_digits')),
                            'primary_color': (result.get('primary_color') or '#800020').strip(),
                            'secondary_color': (result.get('secondary_color') or '#A00030').strip(),
                            'accent_color': (result.get('accent_color') or '#5C0014').strip(),
                            'font_family': normalize_portal_font_family(result.get('font_family')),
                            'maintenance_mode': bool(result.get('maintenance_mode')),
                            'allow_registration': bool(result.get('allow_registration'))
                            if result.get('allow_registration') is not None
                            else True,
                            'default_language': (result.get('default_language') or 'en').strip()[:10],
                            'timezone': (result.get('timezone') or 'Africa/Nairobi').strip()[:64],
                            'default_theme_mode': (result.get('default_theme_mode') or 'dark').strip().lower()[:10],
                        }
                    else:
                        school_data = {
                            'school_name': (result[1] if len(result) > 1 else None) or 'Modern School',
                            'school_email': (result[2] if len(result) > 2 else None) or '',
                            'school_phone': (result[3] if len(result) > 3 else None) or '',
                            'school_logo': (result[4] if len(result) > 4 else None) or None,
                            'twitter_url': (result[5] if len(result) > 5 else None) or '',
                            'facebook_url': (result[6] if len(result) > 6 else None) or '',
                            'instagram_url': (result[7] if len(result) > 7 else None) or '',
                            'tiktok_url': (result[8] if len(result) > 8 else None) or '',
                            'whatsapp_number': (result[9] if len(result) > 9 else None) or '',
                            'school_location': (result[10] if len(result) > 10 else None) or '',
                            'project_name': (result[11] if len(result) > 11 else None) or 'Elimu Centric',
                            'primary_color': '#800020',
                            'secondary_color': '#A00030',
                            'accent_color': '#5C0014',
                            'font_family': 'Inter',
                            'maintenance_mode': False,
                            'allow_registration': True,
                            'default_language': 'en',
                            'timezone': 'Africa/Nairobi',
                            'default_theme_mode': 'dark',
                        }
    except Exception:
        pass
    finally:
        if connection:
            try:
                connection.close()
            except Exception:
                pass

    _SCHOOL_SETTINGS_CACHE['data'] = copy.copy(school_data)
    _SCHOOL_SETTINGS_CACHE['expires_at'] = time.monotonic() + SCHOOL_SETTINGS_CACHE_TTL
    return copy.copy(school_data)

@app.context_processor
def inject_school_settings():
    """Make school settings and active academic levels available to all templates"""
    academic_levels = []
    employees_list = []
    viewing_as_employee_info = None
    
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT id, level_category, level_name, level_description 
                    FROM academic_levels 
                    WHERE level_status = 'active'
                    ORDER BY level_name ASC
                """)
                results = cursor.fetchall()
                
                if results:
                    for row in results:
                        academic_levels.append({
                            'id': row.get('id'),
                            'level_category': row.get('level_category', ''),
                            'level_name': row.get('level_name', ''),
                            'level_description': row.get('level_description', '')
                        })
                
                # Update employee profile picture in session if user is logged in as employee
                if session.get('user_id') and session.get('role'):
                    user_role = session.get('role', '').lower()
                    if user_role in EMPLOYEE_SUB_ROLES:
                        employee_id = session.get('employee_id') or session.get('user_id')
                        cursor.execute("SELECT profile_picture FROM employees WHERE id = %s OR employee_id = %s", 
                                     (employee_id, employee_id))
                        employee = cursor.fetchone()
                        if employee and employee.get('profile_picture'):
                            # Update session with latest profile picture
                            session['profile_picture'] = employee.get('profile_picture')
                    
                    # For technicians viewing as a role, get employees list for that role
                    if user_role == 'technician' and session.get('viewing_as_employee_role'):
                        viewing_as_role = session.get('viewing_as_employee_role', '').lower()
                        role_vals = employee_role_db_match_values(viewing_as_role)
                        employees_results = []
                        if role_vals:
                            ph = ','.join(['%s'] * len(role_vals))
                            cursor.execute(f"""
                                SELECT id, employee_id, full_name, email, role
                                FROM employees
                                WHERE LOWER(TRIM(role)) IN ({ph})
                                  AND LOWER(TRIM(COALESCE(status, 'active'))) = 'active'
                                ORDER BY full_name ASC
                            """, role_vals)
                            employees_results = cursor.fetchall()
                        
                        for row in employees_results:
                            employees_list.append({
                                'id': row.get('id') if isinstance(row, dict) else row[0],
                                'employee_id': row.get('employee_id') if isinstance(row, dict) else row[1],
                                'full_name': row.get('full_name') if isinstance(row, dict) else row[2],
                                'email': row.get('email') if isinstance(row, dict) else row[3],
                                'role': row.get('role') if isinstance(row, dict) else row[4]
                            })
                        
                        # Get info about currently selected employee
                        viewing_as_employee_id = session.get('viewing_as_employee_id')
                        if viewing_as_employee_id:
                            cursor.execute("""
                                SELECT id, employee_id, full_name, email, role, profile_picture
                                FROM employees
                                WHERE id = %s
                            """, (viewing_as_employee_id,))
                            employee_result = cursor.fetchone()
                            if employee_result:
                                viewing_as_employee_info = {
                                    'id': employee_result.get('id') if isinstance(employee_result, dict) else employee_result[0],
                                    'employee_id': employee_result.get('employee_id') if isinstance(employee_result, dict) else employee_result[1],
                                    'full_name': employee_result.get('full_name') if isinstance(employee_result, dict) else employee_result[2],
                                    'email': employee_result.get('email') if isinstance(employee_result, dict) else employee_result[3],
                                    'role': employee_result.get('role') if isinstance(employee_result, dict) else employee_result[4],
                                    'profile_picture': (
                                        employee_result.get('profile_picture')
                                        if isinstance(employee_result, dict)
                                        else (employee_result[5] if len(employee_result) > 5 else None)
                                    ),
                                }
        except Exception as e:
            # Table might not exist yet, that's okay
            pass
        finally:
            if connection:
                connection.close()

    user_role = (session.get('role') or '').lower().strip()
    viewing_as_employee = (session.get('viewing_as_employee_role') or '').lower().strip()
    is_technician = user_role == 'technician'
    dashboard_content_role = normalize_employee_dashboard_content_role(
        user_role, is_technician, viewing_as_employee
    )
    if has_request_context():
        path_role = portal_role_from_request_path()
        path_norm = normalize_allocated_role(path_role) if path_role else ''
        ve_norm = normalize_allocated_role(viewing_as_employee) if viewing_as_employee else ''
        if is_technician and ve_norm:
            if path_norm and (
                path_norm == ve_norm
                or (path_norm in ('teacher', 'teachers') and ve_norm in ('teacher', 'teachers'))
            ):
                dashboard_content_role = 'teachers' if path_norm in ('teacher', 'teachers') else path_norm
            else:
                dashboard_content_role = ve_norm
        elif path_norm:
            dashboard_content_role = path_norm

    portal_display_name = session.get('full_name', 'User')
    portal_display_role = user_role
    if is_technician and viewing_as_employee_info:
        portal_display_name = viewing_as_employee_info.get('full_name') or portal_display_name
        portal_display_role = (
            viewing_as_employee_info.get('role')
            or viewing_as_employee
            or portal_display_role
        )
    elif is_technician and ve_norm:
        portal_display_role = ve_norm

    settings = get_school_settings()
    active_font = settings.get('font_family', 'Inter')
    return {
        'school_settings': settings,
        'academic_levels': academic_levels,
        'employees_list': employees_list,
        'viewing_as_employee_info': viewing_as_employee_info,
        'portal_display_name': portal_display_name,
        'portal_display_role': portal_display_role,
        'is_technician_viewing_as_employee': bool(
            is_technician and viewing_as_employee_info
        ),
        'dashboard_content_role': dashboard_content_role,
        'portal_font_families': PORTAL_FONT_FAMILIES,
        'portal_fonts_grouped': portal_fonts_grouped(),
        'portal_font_css_stack': portal_font_css_stack(active_font),
        'portal_tailwind_font_family': portal_tailwind_font_family(active_font),
        'portal_google_fonts_href': portal_google_fonts_stylesheet_href([active_font]),
        'portal_google_fonts_all_href': portal_google_fonts_stylesheet_href(),
    }


