def ensure_database_exists():
    """Check if database exists, create it if it doesn't"""
    db_name = DB_CONFIG['database']
    # Connect without specifying database
    config_without_db = {k: v for k, v in DB_CONFIG.items() if k != 'database'}
    
    try:
        connection = pymysql.connect(**config_without_db)
        with connection.cursor() as cursor:
            # Check if database exists
            cursor.execute(f"SHOW DATABASES LIKE '{db_name}'")
            result = cursor.fetchone()
            
            if not result:
                # Database doesn't exist, create it
                cursor.execute(f"CREATE DATABASE {db_name} CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci")
                connection.commit()
                print(f"Database '{db_name}' created successfully.")
            else:
                print(f"Database '{db_name}' already exists.")
        connection.close()
        return True
    except Exception as e:
        print(f"Error ensuring database exists: {e}")
        return False

def check_table_exists(connection, table_name):
    """Check if a table exists in the database"""
    try:
        with connection.cursor() as cursor:
            cursor.execute(f"""
                SELECT COUNT(*) as count 
                FROM information_schema.tables 
                WHERE table_schema = %s AND table_name = %s
            """, (DB_CONFIG['database'], table_name))
            result = cursor.fetchone()
            return result['count'] > 0
    except Exception as e:
        print(f"Error checking table existence: {e}")
        return False

def generate_student_id(connection):
    """Generate a unique student ID using format from school_settings (prefix + padded number)."""
    try:
        with connection.cursor() as cursor:
            # Get prefix and digit count from school_settings (columns added by migration 007)
            prefix = 'STU'
            digits = 3
            try:
                cursor.execute("""
                    SELECT student_id_prefix, student_id_digits 
                    FROM school_settings ORDER BY id DESC LIMIT 1
                """)
                settings = cursor.fetchone()
            except Exception:
                settings = None
            if settings:
                p = (settings.get('student_id_prefix') if isinstance(settings, dict) else (settings[0] if len(settings) > 0 else None))
                d = settings.get('student_id_digits') if isinstance(settings, dict) else (settings[1] if len(settings) > 1 else None)
                if p and isinstance(p, str) and p.strip():
                    prefix = str(p).strip().upper()[:10]  # Max 10 chars, uppercase
                if d is not None:
                    try:
                        digits = max(1, min(6, int(d)))  # Between 1 and 6 digits
                    except (TypeError, ValueError):
                        pass
            
            prefix_len = len(prefix)
            # Get the highest student ID number for this prefix
            cursor.execute("""
                SELECT student_id FROM students 
                WHERE student_id LIKE %s 
                ORDER BY CAST(SUBSTRING(student_id, %s) AS UNSIGNED) DESC 
                LIMIT 1
            """, (prefix + '%', prefix_len + 1))
            result = cursor.fetchone()
            
            if result:
                sid = result['student_id'] if isinstance(result, dict) else result[0]
                num_part = sid[prefix_len:] if len(sid) > prefix_len else ''
                try:
                    last_number = int(num_part) if num_part.isdigit() else 0
                except ValueError:
                    last_number = 0
                new_number = last_number + 1
            else:
                new_number = 1
            
            student_id = f"{prefix}{new_number:0{digits}d}"
            return student_id
    except Exception as e:
        print(f"Error generating student ID: {e}")
        return f"STU{int(datetime.now().timestamp()) % 100000:05d}"


def ensure_school_general_settings_columns(cursor):
    """Add maintenance_mode, allow_registration, default_language, timezone to school_settings."""
    cols = [
        ('maintenance_mode', "TINYINT(1) NOT NULL DEFAULT 0", 'font_family'),
        ('allow_registration', "TINYINT(1) NOT NULL DEFAULT 1", 'maintenance_mode'),
        ('default_language', "VARCHAR(10) NOT NULL DEFAULT 'en'", 'allow_registration'),
        ('timezone', "VARCHAR(64) NOT NULL DEFAULT 'Africa/Nairobi'", 'default_language'),
        ('default_theme_mode', "VARCHAR(10) NOT NULL DEFAULT 'dark'", 'timezone'),
    ]
    for col_name, col_def, after_col in cols:
        try:
            cursor.execute("SHOW COLUMNS FROM school_settings LIKE %s", (col_name,))
            if cursor.fetchone():
                continue
            cursor.execute(
                f"ALTER TABLE school_settings ADD COLUMN {col_name} {col_def} AFTER {after_col}"
            )
        except Exception as e:
            print(f"ensure_school_general_settings_columns ({col_name}): {e}")


def ensure_exam_timetable_settings_columns(cursor):
    """
    Add exam session settings storage to school_settings.
    Stored as JSON text with structure:
      { "MORNING": {"start":"08:00","duration_minutes":180}, ... }
    """
    cols = [
        ('exam_session_settings', "LONGTEXT NULL", 'timezone'),
    ]
    for col_name, col_def, after_col in cols:
        try:
            cursor.execute("SHOW COLUMNS FROM school_settings LIKE %s", (col_name,))
            if cursor.fetchone():
                continue
            cursor.execute(
                f"ALTER TABLE school_settings ADD COLUMN {col_name} {col_def} AFTER {after_col}"
            )
        except Exception as e:
            print(f"ensure_exam_timetable_settings_columns ({col_name}): {e}")


def ensure_subject_exam_total_marks_column(cursor):
    """Per-subject maximum marks for exam entry (NULL = use default 100)."""
    try:
        cursor.execute("SHOW COLUMNS FROM subjects LIKE 'exam_total_marks'")
        if cursor.fetchone():
            return
        cursor.execute(
            """
            ALTER TABLE subjects
            ADD COLUMN exam_total_marks DECIMAL(8,2) NULL DEFAULT NULL
            COMMENT 'Maximum marks for exam entry for this subject (NULL uses 100)'
            AFTER status
            """
        )
        print("OK: Added subjects.exam_total_marks column")
    except Exception as e:
        print(f"ensure_subject_exam_total_marks_column: {e}")


def ensure_subject_exam_display_order_columns(cursor):
    """Column order for marks sheets, curriculum pages, and reports (combined subjects share one order)."""
    try:
        cursor.execute("SHOW COLUMNS FROM subjects LIKE 'exam_display_order'")
        if not cursor.fetchone():
            cursor.execute(
                """
                ALTER TABLE subjects
                ADD COLUMN exam_display_order INT NULL
                COMMENT 'Sort key for exam/marks columns; combined subjects share the same value'
                AFTER exam_total_marks
                """
            )
            print("OK: Added subjects.exam_display_order")
    except Exception as e:
        print(f"ensure_subject_exam_display_order_columns (subjects): {e}")
