def normalize_login_email(email):
    return (email or '').strip().lower()


def ensure_users_portal_login_schema(cursor):
    """Add login_code / student_id on users for parent & student six-digit portal sign-in."""
    try:
        cursor.execute("SHOW COLUMNS FROM users LIKE 'login_code'")
        if not cursor.fetchone():
            cursor.execute(
                "ALTER TABLE users ADD COLUMN login_code VARCHAR(6) NULL DEFAULT NULL "
                "COMMENT 'Six-digit portal sign-in' AFTER password_hash"
            )
    except Exception as e:
        print(f"ensure_users_portal_login_schema login_code: {e}")
    try:
        cursor.execute("SHOW COLUMNS FROM users LIKE 'student_id'")
        if not cursor.fetchone():
            cursor.execute(
                "ALTER TABLE users ADD COLUMN student_id VARCHAR(20) NULL DEFAULT NULL "
                "COMMENT 'Links student users to students.student_id' AFTER login_code"
            )
    except Exception as e:
        print(f"ensure_users_portal_login_schema student_id: {e}")
    try:
        cursor.execute(
            "SELECT 1 FROM information_schema.statistics "
            "WHERE table_schema = DATABASE() AND table_name = 'users' AND index_name = 'uk_users_login_code'"
        )
        if not cursor.fetchone():
            cursor.execute("CREATE UNIQUE INDEX uk_users_login_code ON users (login_code)")
    except Exception as e:
        print(f"ensure_users_portal_login_schema index: {e}")


def _normalize_parent_admission(raw):
    """Uppercase trimmed admission / student_id for lookups."""
    return (raw or '').strip().upper()


def _parent_admission_pattern_ok(admission_key):
    if not admission_key:
        return False
    if len(admission_key) < 2 or len(admission_key) > 32:
        return False
    return bool(re.match(r'^[A-Z0-9]+$', admission_key))


def _fetch_student_parent_by_admission(cursor, admission_raw):
    """Student + parent row for portal flows. Join is case/space-insensitive on student_id.

    If a student exists but no matching parents row (or join failed due to casing), inserts a minimal
    parents row so parent portal registration can proceed, then returns the joined row.
    """
    ak = _normalize_parent_admission(admission_raw)
    if not _parent_admission_pattern_ok(ak):
        return None

    join_on = (
        "UPPER(TRIM(CAST(p.student_id AS CHAR(64)))) = UPPER(TRIM(CAST(s.student_id AS CHAR(64))))"
    )
    where_student = "UPPER(TRIM(CAST(s.student_id AS CHAR(64)))) = %s"

    left_sql = f"""
        SELECT s.student_id, s.full_name AS student_name, s.date_of_birth, s.status,
               p.full_name AS parent_name, p.email AS parent_email, p.phone AS parent_phone,
               p.id AS parent_id
        FROM students s
        LEFT JOIN parents p ON {join_on}
        WHERE {where_student}
        LIMIT 1
    """

    def _run_left():
        cursor.execute(left_sql, (ak,))
        return cursor.fetchone()

    row = _run_left()
    if not row:
        return None

    if row.get('parent_id') is not None:
        return row

    sid = (row.get('student_id') or ak).strip()
    stu_name = (row.get('student_name') or 'Student').strip() or 'Student'
    guard_name = (f'Guardian - {stu_name}')[:250]

    try:
        cursor.execute(
            """
            SELECT id FROM parents
            WHERE UPPER(TRIM(CAST(student_id AS CHAR(64)))) = UPPER(TRIM(CAST(%s AS CHAR(64))))
            LIMIT 1
            """,
            (sid,),
        )
        if cursor.fetchone():
            row = _run_left()
            return row

        cursor.execute(
            """
            INSERT INTO parents (student_id, full_name, phone, email, relationship, emergency_contact)
            VALUES (%s, %s, '070000000000', NULL, 'GUARDIAN', '070000000000')
            """,
            (sid, guard_name),
        )
        try:
            cursor.connection.commit()
        except Exception as ce:
            print(f"_fetch_student_parent_by_admission commit after parent insert: {ce}")
        row = _run_left()
        return row
    except Exception as ex:
        print(f"_fetch_student_parent_by_admission ensure parent: {ex}")
        return _run_left()


def _mask_email_for_display(email):
    """Partially hide email for parent reset hints (e.g. j***n@school.com)."""
    em = (email or '').strip().lower()
    if '@' not in em:
        return ''
    local, domain = em.split('@', 1)
    if len(local) <= 1:
        masked_local = '*'
    elif len(local) == 2:
        masked_local = local[0] + '*'
    else:
        masked_local = local[0] + ('*' * min(len(local) - 2, 6)) + local[-1]
    return f'{masked_local}@{domain}'


def _clear_parent_password_reset_session():
    session.pop('parent_pwd_reset_student_id', None)
    session.pop('parent_pwd_reset_dob_ok', None)


def _fetch_parent_portal_user(cursor, admission_raw):
    """Parent portal user: match stored student_id (child admission) or legacy 6-digit login_code."""
    admission_key = _normalize_parent_admission(admission_raw)
    if not admission_key:
        return None
    clauses = ["UPPER(TRIM(COALESCE(u.student_id,''))) = %s"]
    params = [admission_key]
    ar = (admission_raw or '').strip()
    if ar.isdigit() and len(ar) == 6:
        clauses.append("(u.login_code IS NOT NULL AND u.login_code = %s)")
        params.append(ar)
        clauses.append(
            "(u.student_id IS NOT NULL AND CHAR_LENGTH(u.student_id) >= 6 AND RIGHT(u.student_id, 6) = %s)"
        )
        params.append(ar)
    sql = "SELECT u.* FROM users u WHERE u.role = 'parent' AND (" + " OR ".join(clauses) + ") LIMIT 1"
    cursor.execute(sql, params)
    return cursor.fetchone()


def _student_display_initials(full_name):
    name = (full_name or '').strip()
    if not name:
        return '?'
    parts = name.split()
    if len(parts) >= 2:
        return (parts[0][0] + parts[-1][0]).upper()
    return name[:2].upper()


def _parent_child_linked_to_email(cursor, student_id, parent_email):
    """True if student_id is linked to this parent portal email."""
    sid = (student_id or '').strip()
    pem = (parent_email or '').strip()
    if not sid or not pem:
        return False
    try:
        cursor.execute(
            "SELECT 1 FROM parents WHERE student_id = %s AND email = %s LIMIT 1",
            (sid, pem),
        )
        return bool(cursor.fetchone())
    except Exception:
        return False


def _fetch_parent_linked_children(cursor, parent_email, user_id=None):
    """In-session children for parent dashboard switcher."""
    children = []
    pem = (parent_email or '').strip()
    if pem:
        try:
            cursor.execute(
                """
                SELECT s.student_id, s.full_name, s.current_grade, s.gender, s.status,
                       p.full_name AS parent_name, p.phone AS parent_phone
                FROM students s
                INNER JOIN parents p ON s.student_id = p.student_id
                WHERE p.email = %s AND s.status = 'in session'
                ORDER BY s.full_name ASC
                """,
                (pem,),
            )
            for row in cursor.fetchall() or []:
                children.append({
                    'student_id': (row.get('student_id') or '').strip(),
                    'full_name': (row.get('full_name') or '').strip(),
                    'current_grade': (row.get('current_grade') or '').strip(),
                    'gender': (row.get('gender') or '').strip(),
                    'status': (row.get('status') or '').strip(),
                    'parent_name': (row.get('parent_name') or '').strip(),
                    'parent_phone': (row.get('parent_phone') or '').strip(),
                })
        except Exception as ex:
            print(f"_fetch_parent_linked_children: {ex}")
    if not children and user_id:
        try:
            cursor.execute(
                "SELECT student_id FROM users WHERE id = %s AND role = 'parent' LIMIT 1",
                (user_id,),
            )
            ur = cursor.fetchone()
            usid = (ur.get('student_id') or '').strip() if ur else ''
            if usid:
                cursor.execute(
                    """
                    SELECT student_id, full_name, current_grade, gender, status
                    FROM students WHERE student_id = %s AND status = 'in session' LIMIT 1
                    """,
                    (usid,),
                )
                sr = cursor.fetchone()
                if sr:
                    children.append({
                        'student_id': (sr.get('student_id') or '').strip(),
                        'full_name': (sr.get('full_name') or '').strip(),
                        'current_grade': (sr.get('current_grade') or '').strip(),
                        'gender': (sr.get('gender') or '').strip(),
                        'status': (sr.get('status') or '').strip(),
                        'parent_name': '',
                        'parent_phone': '',
                    })
        except Exception:
            pass
    return children


