def _fetch_active_salary_records_with_balances(cursor):
    """Active salary rows with period balances (for dashboard payroll analytics)."""
    from datetime import datetime, timedelta

    salary_records_list = []
    try:
        cursor.execute("""
            SELECT es.id AS salary_id, es.employee_id, es.net_salary, es.effective_date,
                   es.payment_period, e.full_name, e.phone, e.employee_id AS emp_code
            FROM employee_salaries es
            INNER JOIN employees e ON es.employee_id = e.id
            WHERE es.is_active = TRUE
            ORDER BY e.full_name ASC
        """)
        records = cursor.fetchall() or []
        current_date = datetime.now().date()
        for record in records:
            if isinstance(record, dict):
                salary_id = record.get('salary_id')
                employee_id = record.get('employee_id')
                net_salary = float(record.get('net_salary') or 0)
                effective_date = record.get('effective_date')
                payment_period = record.get('payment_period') or 'Monthly'
            else:
                salary_id = record[0]
                employee_id = record[1]
                net_salary = float(record[2] or 0)
                effective_date = record[3]
                payment_period = record[4] or 'Monthly'
            if isinstance(effective_date, str):
                effective_date = datetime.strptime(effective_date, '%Y-%m-%d').date()
            elif hasattr(effective_date, 'date'):
                effective_date = effective_date.date()
            period_start, period_end, current_period_num = calculate_period_dates(
                effective_date, payment_period, current_date,
            )
            cursor.execute(
                """
                SELECT COALESCE(SUM(amount_paid), 0) AS total_paid
                FROM employee_salary_payments
                WHERE salary_id = %s AND payment_date >= %s AND payment_date <= %s
                """,
                (salary_id, period_start, period_end),
            )
            current_period_paid = cursor.fetchone()
            total_paid_current = float(
                (current_period_paid.get('total_paid') if isinstance(current_period_paid, dict)
                 else current_period_paid[0]) or 0
            )
            carry_forward = 0.0
            if current_period_num > 1:
                prev_period_start, prev_period_end, _ = calculate_period_dates(
                    effective_date, payment_period, period_start - timedelta(days=1),
                )
                cursor.execute(
                    """
                    SELECT COALESCE(SUM(amount_paid), 0) AS total_paid
                    FROM employee_salary_payments
                    WHERE salary_id = %s AND payment_date >= %s AND payment_date <= %s
                    """,
                    (salary_id, prev_period_start, prev_period_end),
                )
                prev_period_paid = cursor.fetchone()
                total_paid_prev = float(
                    (prev_period_paid.get('total_paid') if isinstance(prev_period_paid, dict)
                     else prev_period_paid[0]) or 0
                )
                carry_forward = max(0.0, net_salary - total_paid_prev)
            amount_to_be_paid = net_salary + carry_forward
            balance = amount_to_be_paid - total_paid_current
            salary_records_list.append({
                'salary_id': salary_id,
                'employee_id': employee_id,
                'amount_to_be_paid': amount_to_be_paid,
                'total_paid': total_paid_current,
                'balance': balance,
            })
    except Exception as e:
        print(f"_fetch_active_salary_records_with_balances: {e}")
    return salary_records_list


def _accountant_revenue_position_snapshot(revenue, total_income, total_outflow, net_position):
    """Total recorded revenue vs disbursed outflows and net remaining."""
    if total_income > 0:
        outflow_pct = round((total_outflow / total_income) * 100, 1)
        retained_pct = round((net_position / total_income) * 100, 1)
    elif total_outflow > 0:
        outflow_pct = 100.0
        retained_pct = -100.0
    else:
        outflow_pct = 0.0
        retained_pct = 0.0

    return {
        'total_revenue_display': revenue.get('total_display', '0.00'),
        'total_outflows_display': _format_kes_amount(total_outflow),
        'remaining_display': _format_kes_amount(net_position),
        'remaining': net_position,
        'fees_display': revenue.get('fees_display', '0.00'),
        'government_display': revenue.get('government_display', '0.00'),
        'private_display': revenue.get('private_display', '0.00'),
        'outflow_pct': min(outflow_pct, 100.0),
        'retained_pct': retained_pct,
    }


def _accountant_outflows_snapshot(payroll, payments):
    """Combined payroll + payables due vs disbursed for dashboard outflows card."""
    payroll_due = float(payroll.get('payroll_due') or 0)
    payroll_disbursed = float(payroll.get('paid_current_period') or 0)
    payroll_outstanding = float(payroll.get('outstanding') or 0)

    payables_due = float(payments.get('stock_in_invoiced') or 0)
    payables_disbursed = float(
        payments.get('ledger_disbursed') or payments.get('total_disbursed') or 0
    )
    payables_outstanding = float(payments.get('stock_in_outstanding') or 0)

    total_due = payroll_due + payables_due
    total_disbursed = payroll_disbursed + payables_disbursed
    total_outstanding = payroll_outstanding + payables_outstanding

    if total_due > 0:
        disbursement_pct = round((total_disbursed / total_due) * 100, 1)
    elif total_disbursed > 0:
        disbursement_pct = 100.0
    else:
        disbursement_pct = 0.0

    return {
        'total_due': total_due,
        'total_due_display': _format_kes_amount(total_due),
        'total_disbursed': total_disbursed,
        'total_disbursed_display': _format_kes_amount(total_disbursed),
        'outstanding': total_outstanding,
        'outstanding_display': _format_kes_amount(total_outstanding),
        'disbursement_pct': min(disbursement_pct, 100.0),
        'payroll_due_display': payroll.get('payroll_due_display', '0.00'),
        'payroll_disbursed_display': payroll.get('paid_current_period_display', '0.00'),
        'payables_due_display': _format_kes_amount(payables_due),
        'payables_disbursed_display': payments.get('total_disbursed_display', '0.00'),
    }


def _fetch_accountant_dashboard_analytics(cursor):
    """Combined analytics for accountant home dashboard."""
    accounts = _fetch_accountant_accounts_breakdown(cursor)
    revenue = _fetch_accountant_revenue_summary(cursor)
    payments = _fetch_accountant_payment_analytics(cursor)
    salary_records = _fetch_active_salary_records_with_balances(cursor)
    payroll = _fetch_payroll_payment_analytics(salary_records, cursor)
    try:
        fees = _fetch_accountant_fee_overview_snapshot(cursor)
    except Exception as e:
        print(f"_fetch_accountant_dashboard_analytics fees: {e}")
        fees = _accountant_dashboard_analytics_empty()['fees']
    pending_requisitions = _fetch_accountant_pending_requisition_count(cursor)

    total_income = float(revenue.get('total_amount') or 0)
    payroll_out = float(payroll.get('total_disbursed') or 0)
    payables_out = float(
        payments.get('ledger_disbursed') or payments.get('total_disbursed') or 0
    )
    total_outflow = payroll_out + payables_out
    net_position = total_income - total_outflow

    payroll_outstanding = float(payroll.get('outstanding') or 0)
    payables_outstanding = float(payments.get('stock_in_outstanding') or 0)
    fees_outstanding = float(fees.get('total_outstanding') or 0)
    total_obligations = payroll_outstanding + payables_outstanding + fees_outstanding
    outflows = _accountant_outflows_snapshot(payroll, payments)
    revenue_position = _accountant_revenue_position_snapshot(
        revenue, total_income, total_outflow, net_position
    )

    return {
        'revenue': revenue,
        'payroll': payroll,
        'payments': payments,
        'fees': fees,
        'accounts': accounts,
        'outflows': outflows,
        'revenue_position': revenue_position,
        'pending_requisitions': pending_requisitions,
        'total_income': total_income,
        'total_income_display': revenue.get('total_display', '0.00'),
        'total_outflow': total_outflow,
        'total_outflow_display': _format_kes_amount(total_outflow),
        'net_position': net_position,
        'net_position_display': _format_kes_amount(net_position),
        'payroll_outflow_display': payroll.get('total_disbursed_display', '0.00'),
        'payables_outflow_display': payments.get('total_disbursed_display', '0.00'),
        'total_obligations': total_obligations,
        'total_obligations_display': _format_kes_amount(total_obligations),
    }


def _accountant_visual_chart_payload(analytics):
    """Chart.js-ready series from combined accountant dashboard analytics."""
    rev = analytics.get('revenue') or {}
    pr = analytics.get('payroll') or {}
    inv = analytics.get('payments') or {}
    fees = float(rev.get('fees_amount') or 0)
    gov = float(rev.get('government_amount') or 0)
    priv = float(rev.get('private_amount') or 0)
    total_income = float(analytics.get('total_income') or 0)
    total_outflow = float(analytics.get('total_outflow') or 0)
    payroll_out = float(pr.get('total_disbursed') or 0)
    payables_out = float(inv.get('total_disbursed') or 0)
    return {
        'revenue_breakdown': {
            'labels': ['Student fees', 'Government', 'Private'],
            'amounts': [fees, gov, priv],
        },
        'income_vs_outflow': {
            'labels': ['Total income', 'Total disbursed'],
            'amounts': [total_income, total_outflow],
        },
        'outflow_split': {
            'labels': ['Payroll disbursed', 'Payables disbursed'],
            'amounts': [payroll_out, payables_out],
        },
        'payroll': {
            'labels': ['Payroll due', 'Paid (period)', 'Outstanding', 'Paid this month'],
            'amounts': [
                float(pr.get('payroll_due') or 0),
                float(pr.get('paid_current_period') or 0),
                float(pr.get('outstanding') or 0),
                float(pr.get('paid_this_month') or 0),
            ],
        },
        'payables': {
            'labels': ['Outstanding', 'Stock paid', 'Other', 'Invoiced'],
            'amounts': [
                float(inv.get('stock_in_outstanding') or 0),
                float(inv.get('stock_in_paid') or 0),
                float(inv.get('misc_total') or 0),
                float(inv.get('stock_in_invoiced') or 0),
            ],
        },
        'net_position': float(analytics.get('net_position') or 0),
    }


@app.route('/dashboard/employee/staff-and-salaries/salary-records')
@login_required
def salary_records():
    """Display employee salary records with payment information"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Check permissions - accountant, principal, super admin, technician can access
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_super_admin = user_role == 'super admin' or viewing_as_role == 'super admin'
    is_technician = user_role == 'technician'
    
    if not (is_accountant or is_principal or is_super_admin or is_technician):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Get filter parameters
    filter_type = request.args.get('filter', 'all')
    filter_month = request.args.get('month', '')
    filter_year = request.args.get('year', '')
    
    # Fetch salary records with employee information
    connection = get_db_connection()
    salary_records_list = []
    payment_analytics = _fetch_payroll_payment_analytics([])
    filter_info = {'type': filter_type, 'month': filter_month, 'year': filter_year}
    
    if connection:
        try:
            with connection.cursor() as cursor:
                # Ensure payment_period column exists in employee_salaries table
                try:
                    cursor.execute("ALTER TABLE employee_salaries ADD COLUMN payment_period ENUM('Daily', 'Weekly', 'Monthly', 'Quarterly', 'Semi-Annual', '3/4 Annual', 'Annually') DEFAULT 'Monthly' AFTER effective_date")
                except Exception as e:
                    # Column might already exist, ignore the error
                    pass
                
                # Create employee_salary_payments table if it doesn't exist
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS employee_salary_payments (
                        id INT AUTO_INCREMENT PRIMARY KEY,
                        employee_id INT NOT NULL,
                        salary_id INT NOT NULL,
                        amount_paid DECIMAL(15, 2) NOT NULL DEFAULT 0.00,
                        payment_date DATE NOT NULL,
                        payment_method ENUM('Cash', 'Bank Transfer', 'Cheque', 'Mobile Money', 'Credit/Debit Card') DEFAULT 'Bank Transfer',
                        reference_number VARCHAR(255),
                        notes TEXT,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                        FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE,
                        FOREIGN KEY (salary_id) REFERENCES employee_salaries(id) ON DELETE CASCADE,
                        INDEX idx_employee_id (employee_id),
                        INDEX idx_salary_id (salary_id),
                        INDEX idx_payment_date (payment_date)
                    )
                """)
                
                # Build the query with filters
                base_query = """
                    SELECT 
                        es.id as salary_id,
                        es.employee_id,
                        es.net_salary,
                        es.effective_date,
                        es.payment_period,
                        e.full_name,
                        e.phone,
                        e.employee_id as emp_code
                    FROM employee_salaries es
                    INNER JOIN employees e ON es.employee_id = e.id
                    WHERE 1=1
                """
                
                query_params = []
                
                # Add period filter
                if filter_type == 'month' and filter_month:
                    # Filter by month (YYYY-MM format) - show active salaries for that month
                    base_query += " AND es.is_active = TRUE AND DATE_FORMAT(es.effective_date, '%%Y-%%m') = %s"
                    query_params.append(filter_month)
                elif filter_type == 'year' and filter_year:
                    # Filter by year - show ALL records (active and inactive) for that year
                    base_query += " AND YEAR(es.effective_date) = %s"
                    query_params.append(int(filter_year))
                else:
                    # Default: show only active salaries
                    base_query += " AND es.is_active = TRUE"
                
                base_query += """
                    ORDER BY e.full_name ASC
                """
                
                cursor.execute(base_query, tuple(query_params) if query_params else None)
                records = cursor.fetchall()
                
                from datetime import datetime, timedelta
                from dateutil.relativedelta import relativedelta
                
                for record in records:
                    salary_id = record.get('salary_id')
                    employee_id = record.get('employee_id')
                    net_salary = float(record.get('net_salary', 0))
                    effective_date = record.get('effective_date')
                    payment_period = record.get('payment_period', 'Monthly')
                    
                    # Calculate current period based on effective_date and payment_period
                    current_date = datetime.now().date()
                    if isinstance(effective_date, str):
                        effective_date = datetime.strptime(effective_date, '%Y-%m-%d').date()
                    elif hasattr(effective_date, 'date'):
                        effective_date = effective_date.date()
                    
                    # Calculate period start and end dates
                    period_start, period_end, current_period_num = calculate_period_dates(
                        effective_date, payment_period, current_date
                    )
                    
                    # Get payments for current period
                    cursor.execute("""
                        SELECT COALESCE(SUM(amount_paid), 0) as total_paid
                        FROM employee_salary_payments
                        WHERE salary_id = %s 
                        AND payment_date >= %s 
                        AND payment_date <= %s
                    """, (salary_id, period_start, period_end))
                    current_period_paid = cursor.fetchone()
                    total_paid_current = float(current_period_paid.get('total_paid', 0) if current_period_paid else 0)
                    
                    # Calculate carry-forward balance from previous period
                    carry_forward = 0.0
                    if current_period_num > 1:
                        # Get previous period dates
                        prev_period_start, prev_period_end, _ = calculate_period_dates(
                            effective_date, payment_period, period_start - timedelta(days=1)
                        )
                        
                        # Get payments for previous period
                        cursor.execute("""
                            SELECT COALESCE(SUM(amount_paid), 0) as total_paid
                            FROM employee_salary_payments
                            WHERE salary_id = %s 
                            AND payment_date >= %s 
                            AND payment_date <= %s
                        """, (salary_id, prev_period_start, prev_period_end))
                        prev_period_paid = cursor.fetchone()
                        total_paid_prev = float(prev_period_paid.get('total_paid', 0) if prev_period_paid else 0)
                        
                        # Calculate previous period balance (net_salary - total_paid)
                        carry_forward = max(0, net_salary - total_paid_prev)
                    
                    # Amount to be paid = net_salary + carry_forward
                    amount_to_be_paid = net_salary + carry_forward
                    balance = amount_to_be_paid - total_paid_current
                    
                    salary_records_list.append({
                        'salary_id': salary_id,
                        'employee_id': employee_id,
                        'employee_code': record.get('emp_code'),
                        'employee_name': record.get('full_name'),
                        'phone': record.get('phone'),
                        'amount_to_be_paid': amount_to_be_paid,
                        'total_paid': total_paid_current,
                        'balance': balance,
                        'effective_date': effective_date,
                        'payment_period': payment_period,
                        'carry_forward': carry_forward,
                        'current_period_start': period_start,
                        'current_period_end': period_end
                    })

                payment_analytics = _fetch_payroll_payment_analytics(salary_records_list, cursor)
        
        except Exception as e:
            print(f"Error fetching salary records: {e}")
            import traceback
            traceback.print_exc()
            flash('Error loading salary records. Please try again.', 'error')
        finally:
            if connection:
                try:
                    connection.close()
                except:
                    pass
    
    return render_template('dashboards/salary_records.html', 
                         salary_records=salary_records_list,
                         payment_analytics=payment_analytics,
                         filter_info=filter_info)

@app.route('/dashboard/employee/staff-and-salaries/register-salary', methods=['POST'])
@login_required
def register_salary():
    """Register salary for an employee"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    # Check permissions - accountant, principal, super admin, technician can access
    is_accountant = user_role == 'accountant' or viewing_as_role == 'accountant'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_super_admin = user_role == 'super admin' or viewing_as_role == 'super admin'
    is_technician = user_role == 'technician'
    
    has_salary_permission = check_permission_or_role(
        'manage_salaries', ['accountant', 'head of institution', 'super admin']
    )
    if not (is_technician or has_salary_permission):
        return jsonify({'success': False, 'message': 'You do not have permission to perform this action.'}), 403
    
    try:
        data = request.get_json()
        
        # Validate required fields
        if not data.get('employee_id'):
            return jsonify({'success': False, 'message': 'Employee ID is required.'}), 400
        
        if not data.get('effective_date'):
            return jsonify({'success': False, 'message': 'Effective date is required.'}), 400

        if not data.get('payment_period'):
            return jsonify({'success': False, 'message': 'Payment period is required.'}), 400
        
        if not data.get('basic_salary') or float(data.get('basic_salary', 0)) <= 0:
            return jsonify({'success': False, 'message': 'Basic salary is required and must be greater than 0.'}), 400
        
        # Get database connection
        connection = get_db_connection()
        if not connection:
            return jsonify({'success': False, 'message': 'Database connection error.'}), 500
        
        try:
            with connection.cursor() as cursor:
                # Check if employee exists and is active
                cursor.execute(
                    "SELECT id, employee_id, full_name, status FROM employees WHERE id = %s",
                    (data.get('employee_id'),)
                )
                employee = cursor.fetchone()
                
                if not employee:
                    return jsonify({'success': False, 'message': 'Employee not found.'}), 404

                if (employee.get('status') or '').lower() != 'active':
                    return jsonify({
                        'success': False,
                        'message': 'Salary can only be registered for active employees.'
                    }), 400
                
                # Create salaries table if it doesn't exist
                cursor.execute("""
                    CREATE TABLE IF NOT EXISTS employee_salaries (
                        id INT AUTO_INCREMENT PRIMARY KEY,
                        employee_id INT NOT NULL,
                        effective_date DATE NOT NULL,
                        payment_period ENUM('Daily', 'Weekly', 'Monthly', 'Quarterly', 'Semi-Annual', '3/4 Annual', 'Annually') DEFAULT 'Monthly',
                        basic_salary DECIMAL(15, 2) NOT NULL DEFAULT 0.00,
                        house_allowance DECIMAL(15, 2) DEFAULT 0.00,
                        transport_allowance DECIMAL(15, 2) DEFAULT 0.00,
                        medical_allowance DECIMAL(15, 2) DEFAULT 0.00,
                        overtime DECIMAL(15, 2) DEFAULT 0.00,
                        bonus DECIMAL(15, 2) DEFAULT 0.00,
                        paye DECIMAL(15, 2) DEFAULT 0.00,
                        nssf DECIMAL(15, 2) DEFAULT 0.00,
                        nhif DECIMAL(15, 2) DEFAULT 0.00,
                        sacco DECIMAL(15, 2) DEFAULT 0.00,
                        staff_loans DECIMAL(15, 2) DEFAULT 0.00,
                        absenteeism DECIMAL(15, 2) DEFAULT 0.00,
                        total_earnings DECIMAL(15, 2) NOT NULL DEFAULT 0.00,
                        total_deductions DECIMAL(15, 2) NOT NULL DEFAULT 0.00,
                        net_salary DECIMAL(15, 2) NOT NULL DEFAULT 0.00,
                        is_active BOOLEAN DEFAULT TRUE,
                        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
                        FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE CASCADE,
                        INDEX idx_employee_id (employee_id),
                        INDEX idx_effective_date (effective_date),
                        INDEX idx_is_active (is_active)
                    )
                """)
                
                # Add payment_period column if it doesn't exist (for existing tables)
                try:
                    cursor.execute("ALTER TABLE employee_salaries ADD COLUMN payment_period ENUM('Daily', 'Weekly', 'Monthly', 'Quarterly', 'Semi-Annual', '3/4 Annual', 'Annually') DEFAULT 'Monthly' AFTER effective_date")
                except Exception as e:
                    # Column might already exist, ignore the error
                    pass
                
                # Block duplicate registration — use update-salary to revise existing payroll
                cursor.execute("""
                    SELECT id FROM employee_salaries 
                    WHERE employee_id = %s AND is_active = TRUE
                """, (data.get('employee_id'),))
                existing_salary = cursor.fetchone()
                if existing_salary:
                    return jsonify({
                        'success': False,
                        'message': 'This employee already has an active salary. Use Edit Salary to update it.'
                    }), 400
                
                # Insert new salary record
                cursor.execute("""
                    INSERT INTO employee_salaries (
                        employee_id, effective_date, payment_period, basic_salary, house_allowance,
                        transport_allowance, medical_allowance, overtime, bonus,
                        paye, nssf, nhif, sacco, staff_loans, absenteeism,
                        total_earnings, total_deductions, net_salary, is_active
                    ) VALUES (
                        %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, TRUE
                    )
                """, (
                    data.get('employee_id'),
                    data.get('effective_date'),
                    data.get('payment_period', 'Monthly'),
                    float(data.get('basic_salary', 0)),
                    float(data.get('house_allowance', 0)),
                    float(data.get('transport_allowance', 0)),
                    float(data.get('medical_allowance', 0)),
                    float(data.get('overtime', 0)),
                    float(data.get('bonus', 0)),
                    float(data.get('paye', 0)),
                    float(data.get('nssf', 0)),
                    float(data.get('nhif', 0)),
                    float(data.get('sacco', 0)),
                    float(data.get('staff_loans', 0)),
                    float(data.get('absenteeism', 0)),
                    float(data.get('total_earnings', 0)),
                    float(data.get('total_deductions', 0)),
                    float(data.get('net_salary', 0))
                ))
                
                connection.commit()
                
                return jsonify({
                    'success': True,
                    'message': f'Salary registered successfully for {employee.get("full_name", "employee")}.',
                    'redirect_url': employee_dashboard_path('staff-and-salaries/salary-records')
                })
        
        except Exception as e:
            connection.rollback()
            print(f"Error registering salary: {e}")
            import traceback
            traceback.print_exc()
            return jsonify({'success': False, 'message': f'Error registering salary: {str(e)}'}), 500
        
        finally:
            connection.close()
    
    except Exception as e:
        print(f"Error in register_salary route: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': 'An error occurred. Please try again.'}), 500

