@app.route('/update-student/<student_id>', methods=['POST'])
@login_required
def update_student(student_id):
    """Update student details"""
    user_role = session.get('role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check permission OR role-based access
    has_access = check_permission_or_role('edit_students', 
                                         allowed_roles=['employee', 'super admin', 'head of institution', 'deputy head of institution', 
                                                       'curriculum coordinator', 'teachers', 'accountant', 'secretary', 'librarian', 
                                                       'warden', 'transport manager', 'store manager', 'technician'])
    
    if not has_access:
        return jsonify({'success': False, 'message': 'You do not have permission to update students.'}), 403
    
    data = request.get_json()
    new_student_id = (data.get('student_id') or '').strip().upper()
    full_name = (data.get('full_name') or '').strip().upper()
    date_of_birth = (data.get('date_of_birth') or '').strip() or None
    gender = (data.get('gender') or '').strip().upper()
    current_grade = (data.get('current_grade') or '').strip()
    previous_school = (data.get('previous_school') or '').strip()
    address = (data.get('address') or '').strip()
    medical_info = (data.get('medical_info') or '').strip()
    special_needs = (data.get('special_needs') or '').strip()
    student_category = (data.get('student_category') or '').strip().lower() or None
    sponsor_name = (data.get('sponsor_name') or '').strip()
    sponsor_phone = (data.get('sponsor_phone') or '').strip()
    sponsor_email = (data.get('sponsor_email') or '').strip().lower()
    status = (data.get('status') or '').strip()
    
    # Parent information
    parent_name = (data.get('parent_name') or '').strip().upper()
    parent_phone = (data.get('parent_phone') or '').strip()
    parent_email = (data.get('parent_email') or '').strip().lower()
    relationship = (data.get('relationship') or '').strip()
    emergency_contact = (data.get('emergency_contact') or '').strip()
    
    if not full_name:
        return jsonify({'success': False, 'message': 'Student name is required.'}), 400
    
    if not new_student_id:
        return jsonify({'success': False, 'message': 'Student ID is required.'}), 400
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection error.'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Check if new student_id is different and if it already exists
            if new_student_id != student_id:
                cursor.execute("SELECT student_id FROM students WHERE student_id = %s", (new_student_id,))
                existing = cursor.fetchone()
                if existing:
                    return jsonify({'success': False, 'message': 'This Student ID is already registered to another student.'}), 400
            
            # If student_id is changing, we need to handle foreign key constraint
            if new_student_id != student_id:
                # Disable foreign key checks temporarily to allow student_id update
                cursor.execute("SET FOREIGN_KEY_CHECKS = 0")
                
                # Update student first (including student_id)
                cursor.execute("""
                    UPDATE students 
                    SET student_id = %s, full_name = %s, date_of_birth = %s, gender = %s, current_grade = %s, 
                        previous_school = %s, address = %s, medical_info = %s, special_needs = %s,
                        student_category = %s, sponsor_name = %s, sponsor_phone = %s, sponsor_email = %s,
                        status = %s, updated_at = CURRENT_TIMESTAMP
                    WHERE student_id = %s
                """, (new_student_id, full_name, date_of_birth, gender, current_grade, previous_school, address, 
                      medical_info, special_needs, student_category, sponsor_name, sponsor_phone, 
                      sponsor_email, status, student_id))
                
                # Update parents table to reference new student_id
                cursor.execute("""
                    UPDATE parents 
                    SET student_id = %s, updated_at = CURRENT_TIMESTAMP
                    WHERE student_id = %s
                """, (new_student_id, student_id))
                
                # Re-enable foreign key checks
                cursor.execute("SET FOREIGN_KEY_CHECKS = 1")
            else:
                # If student_id is not changing, just update normally
                cursor.execute("""
                    UPDATE students 
                    SET full_name = %s, date_of_birth = %s, gender = %s, current_grade = %s, 
                        previous_school = %s, address = %s, medical_info = %s, special_needs = %s,
                        student_category = %s, sponsor_name = %s, sponsor_phone = %s, sponsor_email = %s,
                        status = %s, updated_at = CURRENT_TIMESTAMP
                    WHERE student_id = %s
                """, (full_name, date_of_birth, gender, current_grade, previous_school, address, 
                      medical_info, special_needs, student_category, sponsor_name, sponsor_phone, 
                      sponsor_email, status, student_id))
            
            # Update or insert parent
            if parent_name and parent_phone and parent_email:
                cursor.execute("""
                    SELECT id FROM parents WHERE student_id = %s
                """, (new_student_id,))
                parent_exists = cursor.fetchone()
                
                if parent_exists:
                    cursor.execute("""
                        UPDATE parents 
                        SET full_name = %s, phone = %s, email = %s, relationship = %s, 
                            emergency_contact = %s, updated_at = CURRENT_TIMESTAMP
                        WHERE student_id = %s
                    """, (parent_name, parent_phone, parent_email, relationship, emergency_contact, new_student_id))
                else:
                    cursor.execute("""
                        INSERT INTO parents (student_id, full_name, phone, email, relationship, emergency_contact)
                        VALUES (%s, %s, %s, %s, %s, %s)
                    """, (new_student_id, parent_name, parent_phone, parent_email, relationship, emergency_contact))
            
            connection.commit()
            return jsonify({'success': True, 'message': 'Student updated successfully.'})
    except Exception as e:
        print(f"Error updating student: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'Error updating student details.'}), 500
    finally:
        connection.close()

@app.route('/delete-student/<student_id>', methods=['POST'])
@login_required
def delete_student(student_id):
    """Delete a student"""
    user_role = session.get('role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check permission OR role-based access
    has_access = check_permission_or_role('delete_students', 
                                         allowed_roles=['employee', 'super admin', 'head of institution', 'deputy head of institution', 
                                                       'curriculum coordinator', 'teachers', 'accountant', 'secretary', 'librarian', 
                                                       'warden', 'transport manager', 'store manager', 'technician'])
    
    if not has_access:
        return jsonify({'success': False, 'message': 'You do not have permission to delete students.'}), 403
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection error.'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Check if student exists
            cursor.execute("SELECT id FROM students WHERE student_id = %s", (student_id,))
            student = cursor.fetchone()
            
            if not student:
                return jsonify({'success': False, 'message': 'Student not found.'}), 404
            
            # Delete student (cascade will delete parent records)
            cursor.execute("DELETE FROM students WHERE student_id = %s", (student_id,))
            connection.commit()
            
            return jsonify({'success': True, 'message': 'Student deleted successfully.'})
    except Exception as e:
        print(f"Error deleting student: {e}")
        connection.rollback()
        return jsonify({'success': False, 'message': 'Error deleting student.'}), 500
    finally:
        connection.close()

@app.route('/approve-student/<student_id>', methods=['POST'])
@login_required
def approve_student(student_id):
    """Approve student admission and send congratulations email to parent"""
    user_role = session.get('role', '').lower()
    employee_id = session.get('employee_id') or session.get('user_id')
    
    # Check permission OR role-based access (approve requires edit permission)
    has_access = check_permission_or_role('edit_students', 
                                         allowed_roles=['employee', 'super admin', 'head of institution', 'deputy head of institution', 
                                                       'curriculum coordinator', 'teachers', 'accountant', 'secretary', 'librarian', 
                                                       'warden', 'transport manager', 'store manager', 'technician'])
    
    if not has_access:
        flash('You do not have permission to approve students.', 'error')
        return redirect(url_for('student_management'))
    
    connection = get_db_connection()
    if not connection:
        flash('Database connection error. Please try again later.', 'error')
        return redirect(url_for('student_management'))
    
    try:
        with connection.cursor() as cursor:
            # Check if student exists and get student details
            cursor.execute("""
                SELECT s.id, s.student_id, s.full_name, s.status,
                       p.full_name as parent_name, p.email as parent_email, p.phone as parent_phone
                FROM students s
                LEFT JOIN parents p ON s.student_id = p.student_id
                WHERE s.student_id = %s
            """, (student_id,))
            student = cursor.fetchone()
            
            if not student:
                flash('Student not found.', 'error')
                return redirect(url_for('student_management'))
            
            # Check if student is already approved
            if student.get('status') != 'pending approval':
                flash(f'Student {student.get("full_name")} is already {student.get("status")}.', 'info')
                return redirect(url_for('student_management'))
            
            # Update student status to 'in session'
            cursor.execute("""
                UPDATE students 
                SET status = 'in session', updated_at = CURRENT_TIMESTAMP
                WHERE student_id = %s
            """, (student_id,))
            
            connection.commit()
            
            student_name = student.get('full_name') or student_id
            notify = notify_parent_student_approved(
                student.get('parent_email'),
                student.get('parent_phone'),
                student.get('parent_name'),
                student_name,
                student_id,
            )
            parts = [f'{student_name} approved.']
            if notify.get('email_sent'):
                parts.append('Parent notified by email with portal setup instructions and login link.')
            elif not (student.get('parent_email') or '').strip():
                parts.append('No parent email on file — add one in student details to send portal instructions.')
            if notify.get('sms_sent'):
                parts.append('SMS sent to parent phone.')
            err_bits = [e for e in (notify.get('errors') or []) if e]
            if err_bits and not notify.get('email_sent'):
                flash(' '.join(parts) + ' ' + ' '.join(err_bits), 'warning')
            elif err_bits:
                flash(' '.join(parts) + ' Note: ' + ' '.join(err_bits), 'warning' if not notify.get('email_sent') else 'success')
            else:
                flash(' '.join(parts), 'success')
            
    except Exception as e:
        print(f"Error approving student: {e}")
        connection.rollback()
        flash('An error occurred while approving the student. Please try again.', 'error')
    finally:
        if connection:
            try:
                connection.close()
            except:
                pass  # Connection might already be closed
    
    return redirect(url_for('student_management'))


def _get_students_by_level():
    """Helper: fetch students grouped by academic level. Returns list of {level_name, level_category, students}."""
    students_by_level = []
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT id, level_name, level_category FROM academic_levels
                    WHERE level_status = 'active' ORDER BY level_name ASC
                """)
                levels = [{'level_name': r.get('level_name') if isinstance(r, dict) else r[1],
                          'level_category': r.get('level_category') if isinstance(r, dict) else (r[2] if len(r) > 2 else '')}
                         for r in (cursor.fetchall() or [])]
                cursor.execute("""
                    SELECT s.student_id, s.full_name, s.current_grade, s.status, s.gender, p.full_name as parent_name
                    FROM students s LEFT JOIN parents p ON s.student_id = p.student_id
                    ORDER BY s.full_name ASC
                """)
                level_to_students = {}
                for row in cursor.fetchall() or []:
                    st = {'student_id': row.get('student_id') if isinstance(row, dict) else row[0],
                          'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
                          'current_grade': row.get('current_grade') if isinstance(row, dict) else row[2],
                          'status': row.get('status') if isinstance(row, dict) else row[3],
                          'gender': row.get('gender') if isinstance(row, dict) else (row[4] if len(row) > 4 else ''),
                          'parent_name': row.get('parent_name') if isinstance(row, dict) else (row[5] if len(row) > 5 else '')}
                    grade = st['current_grade'] or 'Ungraded'
                    level_to_students.setdefault(grade, []).append(st)
                seen = set()
                for lv in levels:
                    ln = lv['level_name']
                    if ln in level_to_students:
                        students_by_level.append({'level_name': ln, 'level_category': lv.get('level_category', ''), 'students': level_to_students[ln]})
                        seen.add(ln)
                for grade, sts in sorted(level_to_students.items()):
                    if grade not in seen:
                        students_by_level.append({'level_name': grade, 'level_category': '', 'students': sts})
        except Exception as e:
            print(f"Error in _get_students_by_level: {e}")
        finally:
            if connection:
                try: connection.close()
                except: pass
    return students_by_level


def _students_progress_level_summaries(cursor):
    """Class names with student counts (no full student list)."""
    level_meta = {}
    try:
        cursor.execute(
            """
            SELECT id, level_name, level_category
            FROM academic_levels
            WHERE level_status = 'active'
            ORDER BY level_name ASC
            """
        )
        for row in cursor.fetchall() or []:
            ln = (row.get('level_name') if isinstance(row, dict) else row[1]) or ''
            ln = str(ln).strip()
            if not ln:
                continue
            level_meta[ln] = {
                'level_name': ln,
                'level_category': (row.get('level_category') if isinstance(row, dict) else row[2]) or '',
                'total': 0,
            }
        cursor.execute(
            """
            SELECT TRIM(COALESCE(s.current_grade, '')) AS level_name, COUNT(*) AS c
            FROM students s
            GROUP BY TRIM(COALESCE(s.current_grade, ''))
            """
        )
        out = []
        seen = set()
        for row in cursor.fetchall() or []:
            ln = (row.get('level_name') if isinstance(row, dict) else row[0]) or ''
            ln = str(ln).strip() or 'Ungraded'
            cnt = int((row.get('c') if isinstance(row, dict) else row[1]) or 0)
            cat = (level_meta.get(ln) or {}).get('level_category', '')
            out.append({'level_name': ln, 'level_category': cat, 'total': cnt})
            seen.add(ln)
        for ln, meta in sorted(level_meta.items(), key=lambda x: x[0]):
            if ln not in seen:
                out.append({'level_name': ln, 'level_category': meta['level_category'], 'total': 0})
        out.sort(key=lambda x: (x.get('level_category') or '', x.get('level_name') or ''))
        return out
    except Exception as e:
        print(f'_students_progress_level_summaries: {e}')
        return []


def _fetch_students_progress_page(cursor, level_name, page=1, per_page=50, q=''):
    """Paginated students for one class/grade on Students Progress."""
    rows = []
    total = 0
    per_page = max(1, min(int(per_page or 50), 100))
    page = max(1, int(page or 1))
    pages = 1
    level_key = (level_name or '').strip()
    if level_key == 'Ungraded':
        grade_clause = "(TRIM(COALESCE(s.current_grade, '')) = '' OR s.current_grade IS NULL)"
        params_base = []
    else:
        grade_clause = "TRIM(COALESCE(s.current_grade, '')) = %s"
        params_base = [level_key]
    search_sql = ''
    search_params = []
    q = (q or '').strip()
    if q:
        like = f'%{q}%'
        search_sql = (
            ' AND (s.full_name LIKE %s OR s.student_id LIKE %s OR COALESCE(p.full_name, "") LIKE %s) '
        )
        search_params = [like, like, like]
    try:
        count_sql = f"""
            SELECT COUNT(*) AS c
            FROM students s
            LEFT JOIN parents p ON s.student_id = p.student_id
            WHERE {grade_clause}
            {search_sql}
        """
        cursor.execute(count_sql, tuple(params_base) + tuple(search_params))
        count_row = cursor.fetchone()
        total = int((count_row.get('c') if isinstance(count_row, dict) else count_row[0]) or 0)
        pages = max(1, (total + per_page - 1) // per_page) if total else 1
        if page > pages:
            page = pages
        offset = (page - 1) * per_page
        list_sql = f"""
            SELECT s.student_id, s.full_name, s.current_grade, s.status, s.gender,
                   p.full_name AS parent_name
            FROM students s
            LEFT JOIN parents p ON s.student_id = p.student_id
            WHERE {grade_clause}
            {search_sql}
            ORDER BY s.full_name ASC
            LIMIT %s OFFSET %s
        """
        cursor.execute(list_sql, tuple(params_base) + tuple(search_params) + (per_page, offset))
        for row in cursor.fetchall() or []:
            rows.append({
                'student_id': row.get('student_id') if isinstance(row, dict) else row[0],
                'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
                'current_grade': row.get('current_grade') if isinstance(row, dict) else row[2],
                'status': row.get('status') if isinstance(row, dict) else row[3],
                'gender': row.get('gender') if isinstance(row, dict) else row[4],
                'parent_name': row.get('parent_name') if isinstance(row, dict) else row[5],
            })
    except Exception as e:
        print(f'_fetch_students_progress_page: {e}')
        rows = []
        total = 0
        pages = 1
    return {
        'students': rows,
        'page': page,
        'per_page': per_page,
        'total': total,
        'pages': pages,
        'level_name': level_key or 'Ungraded',
    }


def _attendance_register_teacher_scope():
    """Whether attendance register should be scoped to one teacher's allocated classes."""
    user_role = (session.get('role') or '').lower().strip()
    viewing_as = (session.get('viewing_as_employee_role') or '').lower().strip()
    is_teacher_role = user_role in ('teachers', 'teacher') or viewing_as in ('teachers', 'teacher')
    if not is_teacher_role:
        return False, None
    teacher_id = _subject_progress_teacher_id() or _teacher_portal_employee_pk()
    if not teacher_id:
        return True, None
    return True, teacher_id


def _get_attendance_class_level_options(is_teacher, teacher_id=None):
    """Class names for attendance filter without loading every student."""
    options = []
    connection = get_db_connection()
    if not connection:
        return options
    try:
        with connection.cursor() as cursor:
            if is_teacher and teacher_id:
                for level in _fetch_teacher_subject_progress_levels(cursor, teacher_id):
                    ln = str((level or {}).get('level_name') or '').strip()
                    if ln and ln not in options:
                        options.append(ln)
                options.sort()
            else:
                cursor.execute("""
                    SELECT DISTINCT s.current_grade
                    FROM students s
                    WHERE s.status = 'in session' AND COALESCE(s.current_grade, '') != ''
                    ORDER BY s.current_grade ASC
                """)
                for r in cursor.fetchall() or []:
                    g = r.get('current_grade') if isinstance(r, dict) else r[0]
                    if g and str(g).strip():
                        options.append(str(g).strip())
    except Exception as e:
        print(f"_get_attendance_class_level_options: {e}")
    finally:
        try:
            connection.close()
        except Exception:
            pass
    return options


def _fetch_attendance_students_page(cursor, grade, page=1, per_page=50, q=''):
    """Paginated in-session students for one class (attendance register)."""
    per_page = max(1, min(int(per_page or 50), 100))
    page = max(1, int(page or 1))
    offset = (page - 1) * per_page
    grade = (grade or '').strip()
    q = (q or '').strip()
    if not grade:
        return [], {'page': 1, 'per_page': per_page, 'total': 0, 'pages': 1}
    where = ["s.status = 'in session'", 's.current_grade = %s']
    params = [grade]
    if q:
        like = '%' + q + '%'
        where.append('(s.full_name LIKE %s OR s.student_id LIKE %s)')
        params.extend([like, like])
    where_sql = ' WHERE ' + ' AND '.join(where)
    cursor.execute(f'SELECT COUNT(*) AS c FROM students s{where_sql}', tuple(params))
    count_row = cursor.fetchone()
    total = int((count_row.get('c') if isinstance(count_row, dict) else count_row[0]) or 0)
    cursor.execute(
        f"""
        SELECT s.student_id, s.full_name, s.current_grade, s.status, s.gender, p.full_name AS parent_name
        FROM students s
        LEFT JOIN parents p ON s.student_id = p.student_id
        {where_sql}
        ORDER BY s.full_name ASC
        LIMIT %s OFFSET %s
        """,
        tuple(params) + (per_page, offset),
    )
    students = []
    for row in cursor.fetchall() or []:
        students.append({
            'student_id': row.get('student_id') if isinstance(row, dict) else row[0],
            'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
            'current_grade': row.get('current_grade') if isinstance(row, dict) else row[2],
            'status': row.get('status') if isinstance(row, dict) else row[3],
            'gender': row.get('gender') if isinstance(row, dict) else (row[4] if len(row) > 4 else ''),
            'parent_name': row.get('parent_name') if isinstance(row, dict) else (row[5] if len(row) > 5 else ''),
        })
    pages = max(1, (total + per_page - 1) // per_page) if total else 1
    if page > pages:
        page = pages
    return students, {'page': page, 'per_page': per_page, 'total': total, 'pages': pages}


def _students_by_level_for_attendance(cursor, class_level, page=1, per_page=50, q='', level_id_by_name=None):
    """Single level group with paginated students for the register."""
    class_level = (class_level or '').strip()
    if not class_level:
        return []
    students, _meta = _fetch_attendance_students_page(cursor, class_level, page, per_page, q)
    lid = (level_id_by_name or {}).get(class_level)
    return [{
        'level_name': class_level,
        'level_category': '',
        'students': students,
        'id': int(lid) if lid is not None else None,
    }]


def _attendance_visible_student_ids(students_by_level):
    ids = []
    for lg in students_by_level or []:
        for st in (lg.get('students') or []):
            sid = st.get('student_id')
            if sid is not None and str(sid).strip():
                ids.append(str(sid).strip())
    return list(dict.fromkeys(ids))


def _build_weeks_and_days(term_start, term_end, selected_week_index=1):
    """Build list of weeks, each with its days (based on term dates). Returns (weeks_list, selected_week_days)."""
    from datetime import timedelta
    weeks_options = []  # [{week_num, label, start, end, days: [{date, day_name, label}]}]
    if not term_start or not term_end:
        return weeks_options, []
    try:
        current = term_start
        week_num = 1
        selected_week_days = []
        while current <= term_end:
            week_start = current
            week_end = min(current + timedelta(days=6), term_end)
            days_in_week = []
            d = week_start
            while d <= week_end:
                day_name = d.strftime('%a')  # Mon, Tue, etc.
                day_label = f"{day_name} {d.day}"
                days_in_week.append({'date': d, 'day_name': day_name, 'label': day_label, 'date_str': d.strftime('%Y-%m-%d')})
                d += timedelta(days=1)
            weeks_options.append({
                'week_num': week_num,
                'label': f"Week {week_num} ({week_start.strftime('%d %b')} - {week_end.strftime('%d %b %Y')})",
                'start': week_start,
                'end': week_end,
                'days': days_in_week,
            })
            if week_num == selected_week_index:
                selected_week_days = days_in_week
            week_num += 1
            current = week_end + timedelta(days=1)
        if not selected_week_days and weeks_options:
            selected_week_days = weeks_options[0]['days']
        return weeks_options, selected_week_days
    except (TypeError, AttributeError, ValueError):
        return [], []


def _get_teacher_level_ids(teacher_user_id):
    """Distinct academic level names this teacher teaches (subject allocations + timetable)."""
    level_names = set()
    if not teacher_user_id:
        return level_names
    conn = get_db_connection()
    if conn:
        try:
            with conn.cursor() as cur:
                cur.execute("""
                    SELECT DISTINCT al.level_name
                    FROM teacher_subject_assignments tsa
                    INNER JOIN academic_levels al ON tsa.academic_level_id = al.id
                    WHERE tsa.teacher_id = %s
                    UNION
                    SELECT DISTINCT al.level_name
                    FROM timetables tt
                    INNER JOIN academic_levels al ON tt.academic_level_id = al.id
                    WHERE tt.teacher_id = %s
                """, (teacher_user_id, teacher_user_id))
                for r in cur.fetchall() or []:
                    ln = r.get('level_name') if isinstance(r, dict) else r[0]
                    if ln:
                        level_names.add(str(ln).strip())
        except Exception as e:
            print(f"Note: _get_teacher_level_ids union query: {e}")
            try:
                with conn.cursor() as cur:
                    cur.execute("""
                        SELECT DISTINCT al.level_name FROM teacher_subject_assignments tsa
                        INNER JOIN academic_levels al ON tsa.academic_level_id = al.id
                        WHERE tsa.teacher_id = %s
                    """, (teacher_user_id,))
                    for r in cur.fetchall() or []:
                        ln = r.get('level_name') if isinstance(r, dict) else r[0]
                        if ln:
                            level_names.add(str(ln).strip())
            except Exception as e2:
                print(f"Error in _get_teacher_level_ids fallback: {e2}")
        finally:
            try:
                conn.close()
            except Exception:
                pass
    return level_names


def _filter_students_by_level_for_ids(students_by_level_all, allowed_ids):
    """Restrict grouped students to those whose student_id is in allowed_ids."""
    allowed = {str(x).strip() for x in allowed_ids if x is not None and str(x).strip()}
    out = []
    for lg in students_by_level_all:
        sts = [s for s in (lg.get('students') or []) if str(s.get('student_id', '')).strip() in allowed]
        if sts:
            out.append({**lg, 'students': sts})
    return out


def _coerce_date_only(val):
    """Normalize DB/date-like values to a Python date."""
    if val is None:
        return None
    if isinstance(val, datetime):
        return val.date()
    if isinstance(val, date_cls):
        return val
    du = getattr(val, 'date', None)
    if callable(du):
        try:
            out = du()
            if isinstance(out, date_cls):
                return out
        except Exception:
            pass
    try:
        return datetime.strptime(str(val)[:10], '%Y-%m-%d').date()
    except Exception:
        return None


def _register_aggregate_analytics_empty():
    """Default shape for staff attendance register aggregate analytics (filtered grid)."""
    return {
        'has_data': False,
        'total_records': 0,
        'present_count': 0,
        'absent_count': 0,
        'overall_pct': 0.0,
        'by_level': [],
        'by_day': [],
    }


def _attendance_register_row_present(val):
    if val is None:
        return False
    if isinstance(val, bool):
        return val
    try:
        return int(val) != 0
    except (TypeError, ValueError):
        return str(val).lower() in ('true', '1', 'yes', 't')


def _compute_register_aggregate_analytics(cursor, term_id, selected_week_days, students_by_level):
    """Sum saved attendance rows for visible students and dates in the current register view."""
    out = _register_aggregate_analytics_empty()
    if not term_id or not selected_week_days:
        return out
    date_list = []
    date_label = {}
    for d in selected_week_days:
        ds = d.get('date_str')
        if not ds:
            continue
        date_list.append(ds)
        date_label[ds] = d.get('label') or ds
    if not date_list:
        return out
    visible = []
    sid_to_level = {}
    for lg in students_by_level or []:
        lname = str(lg.get('level_name') or '').strip() or 'Class'
        for st in (lg.get('students') or []):
            sid = st.get('student_id')
            if sid is None:
                continue
            s = str(sid).strip()
            if not s:
                continue
            visible.append(s)
            sid_to_level[s] = lname
    vis_unique = list(dict.fromkeys(visible))
    if not vis_unique:
        return out
    ph_d = ','.join(['%s'] * len(date_list))
    ph_s = ','.join(['%s'] * len(vis_unique))
    cursor.execute(
        f"""
        SELECT sar.student_id, sar.attendance_date, sar.present
        FROM student_attendance_records sar
        WHERE sar.term_id = %s
          AND sar.attendance_date IN ({ph_d})
          AND sar.student_id IN ({ph_s})
        """,
        tuple([term_id] + date_list + vis_unique),
    )
    rows = cursor.fetchall() or []
    if not rows:
        return out
    by_level = defaultdict(lambda: {'present': 0, 'total': 0})
    by_day = defaultdict(lambda: {'present': 0, 'total': 0})
    present_total = 0
    for r in rows:
        sid = str((r.get('student_id') if isinstance(r, dict) else r[0]) or '').strip()
        dt = r.get('attendance_date') if isinstance(r, dict) else r[1]
        pr = r.get('present') if isinstance(r, dict) else r[2]
        ds = dt.strftime('%Y-%m-%d') if hasattr(dt, 'strftime') else str(dt)[:10]
        is_pr = _attendance_register_row_present(pr)
        lvl = sid_to_level.get(sid, 'Unknown')
        by_level[lvl]['total'] += 1
        if is_pr:
            by_level[lvl]['present'] += 1
            present_total += 1
        by_day[ds]['total'] += 1
        if is_pr:
            by_day[ds]['present'] += 1
    n = len(rows)
    out['has_data'] = True
    out['total_records'] = n
    out['present_count'] = present_total
    out['absent_count'] = n - present_total
    out['overall_pct'] = round(100.0 * present_total / n, 1) if n else 0.0
    level_rows = []
    for ln, agg in sorted(by_level.items(), key=lambda x: (x[0] or '').lower()):
        t = agg['total']
        p = agg['present']
        level_rows.append({
            'level_name': ln,
            'present': p,
            'absent': t - p,
            'total': t,
            'pct': round(100.0 * p / t, 1) if t else 0.0,
        })
    out['by_level'] = level_rows
    day_rows = []
    for ds in date_list:
        agg = by_day.get(ds, {'present': 0, 'total': 0})
        t = agg['total']
        p = agg['present']
        day_rows.append({
            'date_str': ds,
            'label': date_label.get(ds, ds),
            'present': p,
            'absent': t - p,
            'total': t,
            'pct': round(100.0 * p / t, 1) if t else None,
        })
    out['by_day'] = day_rows
    return out


_ATTENDANCE_FIELD_KEY_RE = re.compile(r'^(.+)_(\d{4}-\d{2}-\d{2})(?:_(\d+))?$')


def _attendance_filter_args_from_form(form):
    """Build query-style args from attendance POST hidden fields for register refresh."""
    from werkzeug.datastructures import ImmutableMultiDict
    pairs = []
    for k in (
        'term_id', 'academic_year_id', 'filter_type', 'month', 'day',
        'period_start', 'period_end', 'class_level', 'page', 'per_page', 'q',
    ):
        v = form.get(k)
        if v is not None and str(v).strip() != '':
            pairs.append((k, str(v).strip()))
    return ImmutableMultiDict(pairs)


def _attendance_register_refresh_html(students_by_level, is_teacher, teacher_id):
    """Render summary + register analytics fragments after a successful save."""
    ctx = _attendance_register_get_context(
        students_by_level, is_teacher, _attendance_filter_args_from_form(request.form), teacher_id=teacher_id
    )
    tpl_ctx = {
        **ctx,
        'is_teacher_view': is_teacher,
        'is_parent_view': False,
    }
    return {
        'register_analytics_html': render_template(
            'dashboards/_attendance_register_analytics_partial.html', **tpl_ctx
        ),
    }


def _parse_attendance_checkbox_key(key):
    """Parse att_{student_id}_{date} or att_{student_id}_{date}_{subject_id}. Returns (sid, date_str, subject_id)."""
    if not key or not key.startswith('att_'):
        return None
    m = _ATTENDANCE_FIELD_KEY_RE.match(key[4:])
    if not m:
        return None
    sid = m.group(1)
    date_str = m.group(2)
    subj_raw = m.group(3)
    try:
        subject_id = int(subj_raw) if subj_raw is not None else 0
    except (TypeError, ValueError):
        subject_id = 0
    return sid, date_str, subject_id


def _build_teacher_level_attendance_columns(cursor, teacher_id, term_id, level_id, selected_week_days):
    """One column per subject scheduled on each visible day (teacher timetable)."""
    columns = []
    if not teacher_id or not term_id or not level_id or not selected_week_days:
        return columns
    try:
        for day in selected_week_days:
            dt = day.get('date')
            if not dt:
                try:
                    dt = datetime.strptime(day.get('date_str', ''), '%Y-%m-%d').date()
                except Exception:
                    continue
            weekday = dt.strftime('%A')
            cursor.execute("""
                SELECT DISTINCT t.subject_id, s.subject_name, s.subject_code
                FROM timetables t
                INNER JOIN subjects s ON s.id = t.subject_id
                WHERE t.term_id = %s AND t.academic_level_id = %s AND t.teacher_id = %s
                  AND t.day_of_week = %s
                ORDER BY s.subject_name ASC
            """, (int(term_id), int(level_id), int(teacher_id), weekday))
            for row in cursor.fetchall() or []:
                sid = row.get('subject_id') if isinstance(row, dict) else row[0]
                if sid is None:
                    continue
                sname = (row.get('subject_name', '') if isinstance(row, dict) else (row[1] if len(row) > 1 else '')) or ''
                scode = (row.get('subject_code', '') if isinstance(row, dict) else (row[2] if len(row) > 2 else '')) or ''
                short = scode or sname
                columns.append({
                    'date_str': day.get('date_str', ''),
                    'label': day.get('label', ''),
                    'subject_id': int(sid),
                    'subject_name': sname,
                    'subject_code': scode,
                    'header_label': f"{day.get('label', '')} · {short}",
                })
    except Exception as e:
        print(f"_build_teacher_level_attendance_columns: {e}")
    return columns


def _credit_subject_progress_from_attendance(cursor, level_id, subject_id, term_id, session_date, employee_id):
    """Mark one class session complete on the next open topic when attendance is saved for that subject/day."""
    if not level_id or not subject_id or not term_id or not session_date:
        return
    ensure_subject_progress_topics_table(cursor)
    ensure_subject_progress_session_log_table(cursor)
    topic_id = None
    try:
        cursor.execute("""
            SELECT id FROM subject_progress_topics
            WHERE academic_level_id = %s AND subject_id = %s AND duration_unit = 'classes'
              AND classes_completed < expected_duration_value
            ORDER BY sort_order ASC, id ASC
            LIMIT 1
        """, (int(level_id), int(subject_id)))
        trow = cursor.fetchone()
        if trow:
            topic_id = trow.get('id') if isinstance(trow, dict) else trow[0]
        cursor.execute("""
            INSERT IGNORE INTO subject_progress_session_log
                (academic_level_id, subject_id, term_id, session_date, topic_id, recorded_by_employee_id)
            VALUES (%s, %s, %s, %s, %s, %s)
        """, (int(level_id), int(subject_id), int(term_id), session_date, topic_id, employee_id))
        if cursor.rowcount and topic_id:
            cursor.execute("""
                UPDATE subject_progress_topics
                SET classes_completed = LEAST(
                    expected_duration_value,
                    classes_completed + 1
                )
                WHERE id = %s
            """, (int(topic_id),))
    except Exception as e:
        print(f"_credit_subject_progress_from_attendance: {e}")


def _attendance_register_get_context(students_by_level, is_teacher, req_args, teacher_id=None, attendance_list_meta=None):
    """Build template variables for student attendance register (GET). req_args is typically request.args."""
    term_id = req_args.get('term_id', type=int)
    academic_year_id = req_args.get('academic_year_id', type=int)
    default_filter_type = 'day'
    filter_type = (req_args.get('filter_type') or default_filter_type).strip().lower()
    if filter_type not in ('month', 'day', 'period'):
        filter_type = default_filter_type
    selected_month = (req_args.get('month') or '').strip()
    selected_day = (req_args.get('day') or '').strip()
    selected_period_start = (req_args.get('period_start') or '').strip()
    selected_period_end = (req_args.get('period_end') or '').strip()
    if filter_type == 'day' and not selected_day:
        selected_day = date_cls.today().strftime('%Y-%m-%d')
    calendar_date_min = ''
    calendar_date_max = ''
    calendar_month_min = ''
    calendar_month_max = ''
    today_server = date_cls.today().strftime('%Y-%m-%d')
    academic_years = []
    terms = []
    weeks_options = []
    selected_week_days = []
    attendance_records = {}
    attendance_summary = {}
    schedule_days_list = []
    register_aggregate_analytics = _register_aggregate_analytics_empty()
    use_subject_attendance_columns = bool(is_teacher and teacher_id)
    attendance_columns_by_level = {}
    level_id_by_name = {}

    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("SELECT id, year_name, is_current FROM academic_years ORDER BY id DESC")
                for r in cursor.fetchall() or []:
                    academic_years.append({'id': r.get('id') if isinstance(r, dict) else r[0],
                        'year_name': r.get('year_name') if isinstance(r, dict) else r[1],
                        'is_current': r.get('is_current') if isinstance(r, dict) else (r[2] if len(r) > 2 else False)})
                cursor.execute("""
                    SELECT t.id, t.term_name, t.academic_year_id, ay.year_name, t.is_current
                    FROM terms t
                    LEFT JOIN academic_years ay ON t.academic_year_id = ay.id
                    ORDER BY t.academic_year_id DESC, t.id DESC
                """)
                for r in cursor.fetchall() or []:
                    terms.append({'id': r.get('id') if isinstance(r, dict) else r[0],
                        'term_name': r.get('term_name') if isinstance(r, dict) else r[1],
                        'academic_year_id': r.get('academic_year_id') if isinstance(r, dict) else r[2],
                        'year_name': r.get('year_name') if isinstance(r, dict) else (r[3] if len(r) > 3 else ''),
                        'is_current': r.get('is_current') if isinstance(r, dict) else (r[4] if len(r) > 4 else False)})

                if not academic_year_id and academic_years:
                    current_year = next((y for y in academic_years if y.get('is_current')), None)
                    academic_year_id = (current_year or academic_years[0]).get('id')

                if academic_year_id:
                    terms = [t for t in terms if t.get('academic_year_id') == academic_year_id]

                if not term_id and terms:
                    current_term = next((t for t in terms if t.get('is_current')), None)
                    term_id = (current_term or terms[0]).get('id')

                level_id_by_name = {}
                level_name_by_id = {}
                cursor.execute("SELECT id, level_name FROM academic_levels")
                for r in cursor.fetchall() or []:
                    lid = r.get('id') if isinstance(r, dict) else r[0]
                    lname = r.get('level_name') if isinstance(r, dict) else r[1]
                    if lid and lname:
                        level_id_by_name[str(lname)] = int(lid)
                        level_name_by_id[int(lid)] = str(lname)

                level_days_map = {}
                latest_profile_days = None
                cursor.execute("""
                    SELECT study_days, applicable_levels
                    FROM academic_coordinator_settings
                    ORDER BY updated_at DESC, id DESC
                """)
                for r in cursor.fetchall() or []:
                    sd = (r.get('study_days') if isinstance(r, dict) else r[0]) or ''
                    app_levels_raw = (r.get('applicable_levels') if isinstance(r, dict) else r[1]) or '[]'
                    try:
                        app_levels = json.loads(app_levels_raw)
                    except Exception:
                        app_levels = []
                    day_list = [d.strip() for d in str(sd).split(',') if d and d.strip()]
                    if latest_profile_days is None and day_list:
                        latest_profile_days = day_list
                    for lid in app_levels:
                        try:
                            lid_int = int(lid)
                        except Exception:
                            continue
                        if day_list:
                            level_days_map[lid_int] = day_list

                visible_level_ids = set()
                for lg in students_by_level:
                    lname = str(lg.get('level_name') or '')
                    if lname and lname in level_id_by_name:
                        visible_level_ids.add(level_id_by_name[lname])
                allowed_weekdays = set()
                for lid in visible_level_ids:
                    for d in (level_days_map.get(lid) or []):
                        allowed_weekdays.add(d)
                if not allowed_weekdays:
                    if latest_profile_days:
                        allowed_weekdays = set(latest_profile_days)
                    else:
                        allowed_weekdays = {'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday'}
                schedule_days_list = sorted(list(allowed_weekdays), key=lambda d: ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].index(d) if d in ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'] else 99)

                if term_id:
                    cursor.execute("SELECT start_date, end_date FROM terms WHERE id = %s", (term_id,))
                    tr = cursor.fetchone()
                    if tr:
                        start_raw = tr.get('start_date') if isinstance(tr, dict) else tr[0]
                        end_raw = tr.get('end_date') if isinstance(tr, dict) else tr[1]
                        ts = _coerce_date_only(start_raw)
                        te = _coerce_date_only(end_raw)
                        today_d = date_cls.today()

                        selected_week_days = []
                        lo = hi = None
                        if ts and te:
                            lo = ts
                            hi = min(te, today_d)
                            if hi >= lo:
                                calendar_date_min = lo.isoformat()
                                calendar_date_max = hi.isoformat()
                                calendar_month_min = lo.strftime('%Y-%m')
                                calendar_month_max = hi.strftime('%Y-%m')

                        if ts and te and hi is not None and lo is not None and hi >= lo:
                            range_start = lo
                            range_end = hi

                            if filter_type == 'day' and selected_day:
                                try:
                                    d = datetime.strptime(selected_day, '%Y-%m-%d').date()
                                    if d < lo:
                                        d = lo
                                    elif d > hi:
                                        d = hi
                                    range_start = d
                                    range_end = d
                                except Exception:
                                    pass
                            elif filter_type == 'period':
                                try:
                                    if selected_period_start:
                                        range_start = datetime.strptime(selected_period_start, '%Y-%m-%d').date()
                                    if selected_period_end:
                                        range_end = datetime.strptime(selected_period_end, '%Y-%m-%d').date()
                                except Exception:
                                    pass
                                if range_end < range_start:
                                    range_start, range_end = range_end, range_start
                            else:
                                month_dt = None
                                if selected_month:
                                    try:
                                        month_dt = datetime.strptime(selected_month + '-01', '%Y-%m-%d').date()
                                    except Exception:
                                        month_dt = None
                                if month_dt is None:
                                    anchor = min(max(today_d, lo), hi)
                                    month_dt = anchor.replace(day=1)
                                selected_month = month_dt.strftime('%Y-%m')
                                first_day = month_dt.replace(day=1)
                                if first_day.month == 12:
                                    next_month = first_day.replace(year=first_day.year + 1, month=1, day=1)
                                else:
                                    next_month = first_day.replace(month=first_day.month + 1, day=1)
                                last_day = next_month - timedelta(days=1)
                                range_start = first_day
                                range_end = last_day

                            if isinstance(range_start, datetime):
                                range_start = range_start.date()
                            if isinstance(range_end, datetime):
                                range_end = range_end.date()

                            range_start = max(range_start, lo)
                            range_end = min(range_end, hi)
                            if range_end < range_start:
                                selected_week_days = []
                            else:
                                if filter_type == 'day':
                                    selected_day = range_start.strftime('%Y-%m-%d')
                                elif filter_type == 'period':
                                    selected_period_start = range_start.strftime('%Y-%m-%d')
                                    selected_period_end = range_end.strftime('%Y-%m-%d')
                                else:
                                    selected_month = range_start.strftime('%Y-%m')

                                cur_date = range_start
                                while cur_date <= range_end:
                                    weekday_name = cur_date.strftime('%A')
                                    include_day = (filter_type == 'day') or (weekday_name in allowed_weekdays)
                                    if include_day:
                                        selected_week_days.append({
                                            'date': cur_date,
                                            'date_str': cur_date.strftime('%Y-%m-%d'),
                                            'label': cur_date.strftime('%a %d')
                                        })
                                    cur_date += timedelta(days=1)

                    ensure_student_attendance_subject_column(cursor)
                    vis_sids = _attendance_visible_student_ids(students_by_level)
                    att_params = [term_id]
                    att_where = ['sar.term_id = %s']
                    if selected_week_days:
                        date_list = [d['date_str'] for d in selected_week_days if d.get('date_str')]
                        if date_list:
                            att_where.append(
                                'sar.attendance_date IN (' + ','.join(['%s'] * len(date_list)) + ')'
                            )
                            att_params.extend(date_list)
                    if vis_sids:
                        att_where.append(
                            'sar.student_id IN (' + ','.join(['%s'] * len(vis_sids)) + ')'
                        )
                        att_params.extend(vis_sids)
                    cursor.execute(
                        f"""
                        SELECT sar.student_id, sar.attendance_date, sar.present,
                               COALESCE(sar.subject_id, 0) AS subject_id
                        FROM student_attendance_records sar
                        WHERE {' AND '.join(att_where)}
                        """,
                        tuple(att_params),
                    )
                    for r in cursor.fetchall() or []:
                        sid = r.get('student_id') if isinstance(r, dict) else r[0]
                        dt = r.get('attendance_date') if isinstance(r, dict) else r[1]
                        pres = r.get('present') if isinstance(r, dict) else r[2]
                        subj_id = r.get('subject_id') if isinstance(r, dict) else (r[3] if len(r) > 3 else 0)
                        try:
                            subj_id = int(subj_id or 0)
                        except (TypeError, ValueError):
                            subj_id = 0
                        date_str = dt.strftime('%Y-%m-%d') if hasattr(dt, 'strftime') else str(dt)
                        if _attendance_register_row_present(pres):
                            attendance_records[(sid, date_str, subj_id)] = True
                            if subj_id == 0:
                                attendance_records[(sid, date_str)] = True

                    vis_sids_summary = _attendance_visible_student_ids(students_by_level)
                    if selected_week_days:
                        date_list = [d['date_str'] for d in selected_week_days]
                        placeholders = ','.join(['%s'] * len(date_list))
                        sum_params = [term_id] + date_list
                        sid_clause = ''
                        if vis_sids_summary:
                            sid_clause = ' AND student_id IN (' + ','.join(['%s'] * len(vis_sids_summary)) + ')'
                            sum_params.extend(vis_sids_summary)
                        cursor.execute(f"""
                            SELECT student_id, SUM(present) as present_days, COUNT(*) as total_days
                            FROM student_attendance_records
                            WHERE term_id = %s AND attendance_date IN ({placeholders}){sid_clause}
                            GROUP BY student_id
                        """, tuple(sum_params))
                    elif vis_sids_summary:
                        ph_s = ','.join(['%s'] * len(vis_sids_summary))
                        cursor.execute(f"""
                            SELECT student_id, SUM(present) as present_days, COUNT(*) as total_days
                            FROM student_attendance_records
                            WHERE term_id = %s AND student_id IN ({ph_s})
                            GROUP BY student_id
                        """, tuple([term_id] + vis_sids_summary))
                    else:
                        cursor.execute("""
                            SELECT student_id, SUM(present) as present_days, COUNT(*) as total_days
                            FROM student_attendance_records
                            WHERE term_id = %s
                            GROUP BY student_id
                        """, (term_id,))
                    for r in cursor.fetchall() or []:
                        sid = r.get('student_id') if isinstance(r, dict) else r[0]
                        pres = int(r.get('present_days') or 0) if isinstance(r, dict) else int(r[1] or 0)
                        tot = int(r.get('total_days') or 0) if isinstance(r, dict) else int(r[2] or 0)
                        pct = round(100 * pres / tot, 1) if tot else 0
                        if pct >= 80:
                            cat = 'excellent'
                        elif pct >= 60:
                            cat = 'good'
                        elif pct >= 40:
                            cat = 'fair'
                        elif tot > 0:
                            cat = 'poor'
                        else:
                            cat = 'none'
                        attendance_summary[sid] = {'present': pres, 'total': tot, 'pct': pct, 'category': cat}
                    register_aggregate_analytics = _compute_register_aggregate_analytics(
                        cursor, term_id, selected_week_days, students_by_level
                    )

                if use_subject_attendance_columns and teacher_id and term_id:
                    for _lg in students_by_level:
                        lname = str(_lg.get('level_name') or '').strip()
                        lid = _lg.get('id') or level_id_by_name.get(lname)
                        if lid is None:
                            continue
                        _lg['id'] = int(lid)
                        attendance_columns_by_level[int(lid)] = _build_teacher_level_attendance_columns(
                            cursor, teacher_id, term_id, int(lid), selected_week_days
                        )
        except Exception as e:
            print(f"Error in _attendance_register_get_context: {e}")
        finally:
            if connection:
                try:
                    connection.close()
                except Exception:
                    pass

    attendance_student_ids_csv = ''
    if students_by_level:
        _sid_list = []
        for _lg in students_by_level:
            for _st in (_lg.get('students') or []):
                _sid = _st.get('student_id')
                if _sid is not None and str(_sid).strip():
                    _sid_list.append(str(_sid).strip())
        attendance_student_ids_csv = ','.join(_sid_list)

    subject_progress_url = employee_dash_url('subject-progress')

    return {
        'students_by_level': students_by_level,
        'attendance_student_ids_csv': attendance_student_ids_csv,
        'academic_years': academic_years,
        'terms': terms,
        'weeks_options': weeks_options,
        'selected_week_days': selected_week_days,
        'selected_term_id': term_id,
        'selected_academic_year_id': academic_year_id,
        'selected_week': 1,
        'selected_filter_type': filter_type,
        'selected_month': selected_month,
        'selected_day': selected_day,
        'selected_period_start': selected_period_start,
        'selected_period_end': selected_period_end,
        'schedule_days_list': schedule_days_list,
        'attendance_records': attendance_records,
        'attendance_summary': attendance_summary,
        'register_aggregate_analytics': register_aggregate_analytics,
        'calendar_date_min': calendar_date_min,
        'calendar_date_max': calendar_date_max,
        'calendar_month_min': calendar_month_min,
        'calendar_month_max': calendar_month_max,
        'today_server': today_server,
        'use_subject_attendance_columns': use_subject_attendance_columns,
        'attendance_columns_by_level': attendance_columns_by_level,
        'subject_progress_url': subject_progress_url,
        'attendance_list_meta': attendance_list_meta or {},
    }


def _fetch_parent_attendance_analytics(student_id, req_args):
    """Aggregated attendance analytics for one student (parent dashboard)."""
    from collections import defaultdict
    from datetime import date as date_type

    def _truthy(val):
        if val is None:
            return False
        if isinstance(val, bool):
            return val
        try:
            return int(val) != 0
        except (TypeError, ValueError):
            return str(val).lower() in ('true', 'yes', 't', '1')

    student = None
    academic_years = []
    terms = []
    term_id = req_args.get('term_id', type=int)
    academic_year_id = req_args.get('academic_year_id', type=int)
    term_label = ''
    summary = {
        'total_recorded': 0, 'present': 0, 'absent': 0, 'pct': 0.0, 'category': 'none',
    }
    by_week = []
    daily_points = []
    recent_days = []

    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT student_id, full_name, current_grade, status
                    FROM students WHERE student_id = %s
                """, (student_id,))
                row = cursor.fetchone()
                if row:
                    student = {
                        'student_id': row.get('student_id') if isinstance(row, dict) else row[0],
                        'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
                        'current_grade': row.get('current_grade') if isinstance(row, dict) else row[2],
                        'status': row.get('status') if isinstance(row, dict) else row[3],
                    }

                cursor.execute("SELECT id, year_name, is_current FROM academic_years ORDER BY id DESC")
                for r in cursor.fetchall() or []:
                    academic_years.append({
                        'id': r.get('id') if isinstance(r, dict) else r[0],
                        'year_name': r.get('year_name') if isinstance(r, dict) else r[1],
                        'is_current': r.get('is_current') if isinstance(r, dict) else (r[2] if len(r) > 2 else False),
                    })

                terms_all = []
                try:
                    cursor.execute(
                        """
                        SELECT t.id, t.term_name, t.academic_year_id, ay.year_name, COALESCE(t.is_current, 0) AS is_current
                        FROM terms t
                        LEFT JOIN academic_years ay ON t.academic_year_id = ay.id
                        ORDER BY t.academic_year_id DESC, t.start_date DESC, t.id DESC
                        """
                    )
                    for r in cursor.fetchall() or []:
                        terms_all.append(
                            {
                                'id': r.get('id') if isinstance(r, dict) else r[0],
                                'term_name': r.get('term_name') if isinstance(r, dict) else r[1],
                                'academic_year_id': r.get('academic_year_id') if isinstance(r, dict) else r[2],
                                'year_name': r.get('year_name') if isinstance(r, dict) else (r[3] if len(r) > 3 else ''),
                                'is_current': _truthy(r.get('is_current') if isinstance(r, dict) else (r[4] if len(r) > 4 else False)),
                            }
                        )
                except Exception:
                    cursor.execute(
                        """
                        SELECT t.id, t.term_name, t.academic_year_id, ay.year_name
                        FROM terms t
                        LEFT JOIN academic_years ay ON t.academic_year_id = ay.id
                        ORDER BY t.academic_year_id DESC, t.start_date DESC, t.id DESC
                        """
                    )
                    for r in cursor.fetchall() or []:
                        terms_all.append(
                            {
                                'id': r.get('id') if isinstance(r, dict) else r[0],
                                'term_name': r.get('term_name') if isinstance(r, dict) else r[1],
                                'academic_year_id': r.get('academic_year_id') if isinstance(r, dict) else r[2],
                                'year_name': r.get('year_name') if isinstance(r, dict) else (r[3] if len(r) > 3 else ''),
                                'is_current': False,
                            }
                        )

                if term_id and not academic_year_id:
                    for tx in terms_all:
                        if tx.get('id') == term_id:
                            academic_year_id = tx.get('academic_year_id')
                            break

                if not academic_year_id:
                    cursor.execute(
                        """
                        SELECT id FROM academic_years
                        WHERE COALESCE(is_current, 0) = 1
                        ORDER BY id DESC
                        LIMIT 1
                        """
                    )
                    ay_row = cursor.fetchone()
                    if ay_row:
                        academic_year_id = (
                            ay_row.get('id') if isinstance(ay_row, dict) else ay_row[0]
                        )

                terms = (
                    [t for t in terms_all if t.get('academic_year_id') == academic_year_id]
                    if academic_year_id
                    else list(terms_all)
                )
                if academic_year_id and not terms:
                    terms = list(terms_all)

                if not term_id:
                    tid = None
                    if academic_year_id:
                        for t in terms:
                            if _truthy(t.get('is_current')):
                                tid = t.get('id')
                                break
                    if not tid:
                        cursor.execute(
                            """
                            SELECT t.id FROM terms t
                            WHERE COALESCE(t.is_current, 0) = 1
                            ORDER BY t.id DESC
                            LIMIT 1
                            """
                        )
                        g = cursor.fetchone()
                        if g:
                            cand = g.get('id') if isinstance(g, dict) else g[0]
                            if not academic_year_id or any(t.get('id') == cand for t in terms):
                                tid = cand
                    if not tid and academic_year_id:
                        cursor.execute(
                            """
                            SELECT id FROM terms
                            WHERE academic_year_id = %s
                            ORDER BY start_date DESC, id DESC
                            LIMIT 1
                            """,
                            (academic_year_id,),
                        )
                        g2 = cursor.fetchone()
                        if g2:
                            tid = g2.get('id') if isinstance(g2, dict) else g2[0]
                    if not tid and terms:
                        tid = terms[0].get('id')
                    elif not tid and terms_all:
                        tid = terms_all[0].get('id')
                    term_id = tid

                if term_id and academic_year_id:
                    if not any(t.get('id') == term_id for t in terms):
                        fb = next((t for t in terms if _truthy(t.get('is_current'))), None)
                        term_id = fb.get('id') if fb else (terms[0].get('id') if terms else term_id)

                if term_id:
                    cursor.execute("""
                        SELECT t.term_name, ay.year_name
                        FROM terms t
                        LEFT JOIN academic_years ay ON t.academic_year_id = ay.id
                        WHERE t.id = %s
                    """, (term_id,))
                    tl = cursor.fetchone()
                    if tl:
                        tn = tl.get('term_name') if isinstance(tl, dict) else tl[0]
                        yn = tl.get('year_name') if isinstance(tl, dict) else (tl[1] if len(tl) > 1 else '')
                        term_label = f"{tn}" + (f" ({yn})" if yn else '')

                    cursor.execute("""
                        SELECT sar.attendance_date, sar.present
                        FROM student_attendance_records sar
                        WHERE sar.student_id = %s AND sar.term_id = %s
                        ORDER BY sar.attendance_date ASC
                    """, (student_id, term_id))
                    raw_rows = cursor.fetchall() or []

                    pts = []
                    for r in raw_rows:
                        dt = r.get('attendance_date') if isinstance(r, dict) else r[0]
                        pres = r.get('present') if isinstance(r, dict) else r[1]
                        if dt is None:
                            continue
                        if isinstance(dt, datetime):
                            d = dt.date()
                        elif isinstance(dt, date_type):
                            d = dt
                        else:
                            try:
                                d = datetime.strptime(str(dt)[:10], '%Y-%m-%d').date()
                            except Exception:
                                continue
                        is_present = bool(int(pres)) if pres is not None else False
                        pts.append({'date': d, 'present': is_present})

                    summary['total_recorded'] = len(pts)
                    summary['present'] = sum(1 for p in pts if p['present'])
                    summary['absent'] = summary['total_recorded'] - summary['present']
                    if summary['total_recorded']:
                        summary['pct'] = round(100.0 * summary['present'] / summary['total_recorded'], 1)
                    p = summary['pct']
                    if summary['total_recorded'] == 0:
                        summary['category'] = 'none'
                    elif p >= 80:
                        summary['category'] = 'excellent'
                    elif p >= 60:
                        summary['category'] = 'good'
                    elif p >= 40:
                        summary['category'] = 'fair'
                    elif p > 0:
                        summary['category'] = 'poor'
                    else:
                        summary['category'] = 'none'

                    week_acc = defaultdict(lambda: [0, 0])
                    for pt in pts:
                        d = pt['date']
                        iso = d.isocalendar()
                        key = (iso[0], iso[1])
                        week_acc[key][1] += 1
                        if pt['present']:
                            week_acc[key][0] += 1
                    for (y, wnum) in sorted(week_acc.keys()):
                        pr, tot = week_acc[(y, wnum)]
                        pct_w = round(100 * pr / tot, 1) if tot else 0
                        by_week.append({
                            'label': f'Week {wnum}, {y}',
                            'present': pr,
                            'total': tot,
                            'absent': tot - pr,
                            'pct': pct_w,
                        })

                    for pt in pts:
                        d = pt['date']
                        daily_points.append({
                            'date_str': d.strftime('%Y-%m-%d'),
                            'label': d.strftime('%d %b'),
                            'value': 100.0 if pt['present'] else 0.0,
                        })

                    for pt in sorted(pts, key=lambda x: x['date'], reverse=True)[:45]:
                        d = pt['date']
                        recent_days.append({
                            'date_str': d.strftime('%Y-%m-%d'),
                            'weekday': d.strftime('%a'),
                            'display': d.strftime('%a, %d %b %Y'),
                            'present': pt['present'],
                        })
        except Exception as e:
            print(f"Error in _fetch_parent_attendance_analytics: {e}")
        finally:
            if connection:
                try:
                    connection.close()
                except Exception:
                    pass

    return {
        'student': student,
        'academic_years': academic_years,
        'terms': terms,
        'selected_term_id': term_id,
        'selected_academic_year_id': academic_year_id,
        'term_label': term_label,
        'summary': summary,
        'by_week': by_week,
        'daily_points': daily_points,
        'recent_days': recent_days,
    }


@app.route('/student-management/student-attendance', methods=['GET', 'POST'])
@login_required
def student_attendance():
    """Student Attendance register with calendar filters and schedule-day constraints."""
    has_access = check_permission_or_role('view_students',
        allowed_roles=['employee', 'super admin', 'head of institution', 'deputy head of institution',
                      'curriculum coordinator', 'teachers', 'accountant', 'secretary', 'librarian',
                      'warden', 'transport manager', 'store manager', 'technician'])
    if not has_access:
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    is_teacher, teacher_id = _attendance_register_teacher_scope()

    class_level_options = _get_attendance_class_level_options(is_teacher, teacher_id)
    selected_class_level = (request.values.get('class_level') or '').strip()
    if is_teacher and teacher_id and selected_class_level and selected_class_level not in class_level_options:
        selected_class_level = ''
    if not selected_class_level and len(class_level_options) == 1:
        selected_class_level = class_level_options[0]

    att_page = request.values.get('page', 1, type=int)
    att_per_page = request.values.get('per_page', 50, type=int)
    att_q = (request.values.get('q') or '').strip()
    attendance_list_meta = {}
    students_by_level = []

    if selected_class_level:
        conn_lv = get_db_connection()
        if conn_lv:
            try:
                with conn_lv.cursor() as cur:
                    level_id_by_name = {}
                    cur.execute("SELECT id, level_name FROM academic_levels")
                    for r in cur.fetchall() or []:
                        lid = r.get('id') if isinstance(r, dict) else r[0]
                        lname = r.get('level_name') if isinstance(r, dict) else r[1]
                        if lid and lname:
                            level_id_by_name[str(lname)] = int(lid)
                    students_by_level = _students_by_level_for_attendance(
                        cur, selected_class_level, att_page, att_per_page, att_q, level_id_by_name,
                    )
                    _, attendance_list_meta = _fetch_attendance_students_page(
                        cur, selected_class_level, att_page, att_per_page, att_q,
                    )
            except Exception as e:
                print(f"student_attendance students page: {e}")
            finally:
                try:
                    conn_lv.close()
                except Exception:
                    pass

    use_subject_attendance_post = bool(is_teacher and teacher_id)

    if request.method == 'POST':
        is_ajax = request.headers.get('X-Requested-With') == 'XMLHttpRequest'
        xhr_saved = False
        xhr_error = None
        term_id = request.form.get('term_id', type=int)
        week_dates_str = request.form.get('week_dates', '')
        student_ids_str = request.form.get('student_ids', '')
        post_register_ctx = None
        if term_id:
            post_register_ctx = _attendance_register_get_context(
                students_by_level, is_teacher, _attendance_filter_args_from_form(request.form), teacher_id=teacher_id
            )
        week_dates = [
            d.get('date_str') for d in (post_register_ctx.get('selected_week_days') or []) if d.get('date_str')
        ] if post_register_ctx else []
        if not week_dates and week_dates_str:
            week_dates = [d.strip() for d in week_dates_str.split(',') if d.strip()]
        week_dates_set = set(week_dates)
        student_ids = [s.strip() for s in student_ids_str.split(',') if s.strip()]

        def _ids_from_att_field_names():
            out = set()
            for key in request.form:
                parsed = _parse_attendance_checkbox_key(key)
                if not parsed:
                    continue
                sid, date_str, _subj = parsed
                if date_str in week_dates_set and sid:
                    out.add(sid)
            return out

        ids_from_cells = _ids_from_att_field_names() if week_dates_set else set()
        student_ids = sorted(set(student_ids) | ids_from_cells)

        if term_id and week_dates_set and student_ids:
            conn = get_db_connection()
            if not conn:
                xhr_error = 'Database connection failed.'
                if not is_ajax:
                    flash('Database connection error.', 'error')
            else:
                try:
                    with conn.cursor() as cur:
                        ensure_student_attendance_subject_column(cur)
                        level_id_by_name = _level_name_to_id_map(cur)
                        level_id_by_lower = {str(k).lower(): v for k, v in level_id_by_name.items()}

                        def resolve_level_id(grade_raw):
                            if grade_raw is None:
                                return None
                            gn = str(grade_raw).strip()
                            if not gn:
                                return None
                            if gn in level_id_by_name:
                                return level_id_by_name[gn]
                            return level_id_by_lower.get(gn.lower())

                        rows_saved = 0
                        rrole = (session.get('role') or '').lower().strip()
                        view_emp_role = (session.get('viewing_as_employee_role') or '').lower().strip()
                        emp_id = None
                        if rrole == 'technician' and view_emp_role in ('teachers', 'teacher') and session.get('viewing_as_employee_id'):
                            try:
                                emp_id = int(session.get('viewing_as_employee_id'))
                            except (TypeError, ValueError):
                                emp_id = None
                        elif session.get('user_id') is not None:
                            try:
                                emp_id = int(session.get('user_id'))
                            except (TypeError, ValueError):
                                emp_id = None
                        student_id_set_for_form = set(student_ids)
                        cell_updates = []
                        for key in request.form:
                            if not key.startswith('att_'):
                                continue
                            parsed = _parse_attendance_checkbox_key(key)
                            if not parsed:
                                continue
                            sid, date_str, subject_id = parsed
                            if sid not in student_id_set_for_form:
                                continue
                            if week_dates_set and date_str not in week_dates_set:
                                continue
                            is_present = request.form.get(key) == 'on'
                            cell_updates.append((sid, date_str, subject_id, is_present))

                        sessions_with_present = set()
                        student_level_cache = {}
                        for sid, date_str, subject_id, is_present in cell_updates:
                            if sid not in student_level_cache:
                                cur.execute("SELECT current_grade FROM students WHERE student_id = %s", (sid,))
                                row = cur.fetchone()
                                if not row:
                                    student_level_cache[sid] = None
                                else:
                                    level_name = row.get('current_grade') if isinstance(row, dict) else row[0]
                                    student_level_cache[sid] = resolve_level_id(level_name)
                            lid = student_level_cache.get(sid)
                            if not lid:
                                continue
                            subj_id = int(subject_id or 0)
                            cur.execute("""
                                INSERT INTO student_attendance_records
                                (student_id, attendance_date, academic_level_id, term_id, subject_id, present, recorded_by_employee_id)
                                VALUES (%s, %s, %s, %s, %s, %s, %s)
                                ON DUPLICATE KEY UPDATE present = VALUES(present),
                                    recorded_by_employee_id = VALUES(recorded_by_employee_id)
                            """, (sid, date_str, lid, term_id, subj_id, 1 if is_present else 0, emp_id))
                            rows_saved += 1
                            if use_subject_attendance_post and subj_id > 0 and is_present:
                                sessions_with_present.add((int(lid), subj_id, date_str))
                        if use_subject_attendance_post:
                            for lid, subj_id, sess_date in sessions_with_present:
                                _credit_subject_progress_from_attendance(
                                    cur, lid, subj_id, term_id, sess_date, emp_id
                                )
                        conn.commit()
                    if rows_saved > 0:
                        xhr_saved = True
                        if not is_ajax:
                            flash('Attendance saved successfully.', 'success')
                    elif is_ajax:
                        xhr_error = (
                            'No attendance was saved. Check that students have a valid class/grade '
                            'and that the date filter matches the register columns.'
                        )
                    elif not is_ajax:
                        flash(
                            'No attendance was saved. Check class/grade and date filter.',
                            'error',
                        )
                except Exception as e:
                    print(f"Error saving attendance: {e}")
                    if conn:
                        conn.rollback()
                    xhr_error = 'Error saving attendance.'
                    if not is_ajax:
                        flash('Error saving attendance.', 'error')
                finally:
                    try: conn.close()
                    except: pass
        elif is_ajax:
            xhr_error = 'Choose a term and ensure the register shows students and dates before saving.'

        from urllib.parse import urlencode
        if is_ajax:
            if xhr_saved:
                fragments = _attendance_register_refresh_html(students_by_level, is_teacher, teacher_id)
                return jsonify({'ok': True, **fragments})
            return jsonify({'ok': False, 'message': xhr_error or 'Save failed.'})
        params = {}
        if request.form.get('term_id'):
            params['term_id'] = request.form.get('term_id')
        if request.form.get('academic_year_id'):
            params['academic_year_id'] = request.form.get('academic_year_id')
        if request.form.get('filter_type'):
            params['filter_type'] = request.form.get('filter_type')
        if request.form.get('month'):
            params['month'] = request.form.get('month')
        if request.form.get('day'):
            params['day'] = request.form.get('day')
        if request.form.get('period_start'):
            params['period_start'] = request.form.get('period_start')
        if request.form.get('period_end'):
            params['period_end'] = request.form.get('period_end')
        if request.form.get('class_level'):
            params['class_level'] = request.form.get('class_level')
        return redirect(url_for('student_attendance') + ('?' + urlencode(params) if params else ''))

    ctx = _attendance_register_get_context(
        students_by_level, is_teacher, request.args, teacher_id=teacher_id,
        attendance_list_meta=attendance_list_meta,
    )
    merged = {
        **ctx,
        'is_teacher_view': is_teacher,
        'class_level_options': class_level_options,
        'selected_class_level': selected_class_level,
    }
    if (request.args.get('format') or '').strip().lower() == 'json':
        live_html = render_template('dashboards/_student_attendance_live_block.html', **merged)
        terms_json = [{'id': t.get('id'), 'term_name': t.get('term_name') or '', 'year_name': t.get('year_name') or ''} for t in (ctx.get('terms') or [])]
        return jsonify({
            'ok': True,
            'html': live_html,
            'attendance_meta': attendance_list_meta,
            'terms': terms_json,
            'selected_term_id': ctx.get('selected_term_id'),
            'selected_academic_year_id': ctx.get('selected_academic_year_id'),
            'calendar_date_min': ctx.get('calendar_date_min') or '',
            'calendar_date_max': ctx.get('calendar_date_max') or '',
            'calendar_month_min': ctx.get('calendar_month_min') or '',
            'calendar_month_max': ctx.get('calendar_month_max') or '',
            'selected_filter_type': ctx.get('selected_filter_type'),
            'selected_month': ctx.get('selected_month') or '',
            'selected_day': ctx.get('selected_day') or '',
            'selected_period_start': ctx.get('selected_period_start') or '',
            'selected_period_end': ctx.get('selected_period_end') or '',
            'today_server': ctx.get('today_server') or '',
        })
    return render_template('dashboards/student_attendance.html', **merged)


def _parent_dashboard_auth():
    """Shared auth + parent email resolution for /dashboard/parent/* routes (parent or technician-as-parent)."""
    user_role = session.get('role', '').lower()
    viewing_as = session.get('viewing_as_role', '')
    parent_email = session.get('email', '')
    all_students = []
    selected_student_id = request.args.get('student_id', '') or session.get('parent_view_student_id', '')
    is_technician = user_role == 'technician'

    if user_role != 'parent' and not (user_role == 'technician' and viewing_as == 'parent'):
        return None

    if is_technician and viewing_as == 'parent':
        connection = get_db_connection()
        if connection:
            try:
                with connection.cursor() as cursor:
                    cursor.execute("""
                        SELECT DISTINCT s.id, s.student_id, s.full_name, s.current_grade, s.status,
                               p.full_name as parent_name, p.email as parent_email
                        FROM students s
                        LEFT JOIN parents p ON s.student_id = p.student_id
                        WHERE s.status = 'in session'
                        ORDER BY s.full_name ASC
                    """)
                    all_students = cursor.fetchall()
            except Exception as e:
                print(f"Error fetching students for technician: {e}")
            finally:
                if connection:
                    try:
                        connection.close()
                    except Exception:
                        pass

        if selected_student_id:
            session['parent_view_student_id'] = selected_student_id
            connection = get_db_connection()
            if connection:
                try:
                    with connection.cursor() as cursor:
                        cursor.execute("""
                            SELECT p.email
                            FROM parents p
                            WHERE p.student_id = %s
                            LIMIT 1
                        """, (selected_student_id,))
                        parent_result = cursor.fetchone()
                        if parent_result:
                            parent_email = parent_result.get('email', '') if isinstance(parent_result, dict) else parent_result[0]
                except Exception as e:
                    print(f"Error fetching parent email: {e}")
                finally:
                    if connection:
                        try:
                            connection.close()
                        except Exception:
                            pass

    current_view_role = viewing_as if is_technician and viewing_as else user_role
    return {
        'parent_email': parent_email,
        'all_students': all_students,
        'selected_student_id': selected_student_id,
        'is_technician': is_technician,
        'current_view_role': current_view_role,
    }


def _parent_list_linked_children(cursor, parent_email):
    """Basic child rows for parent portal list pages."""
    children = []
    pem = (parent_email or '').strip()
    if not pem:
        return children
    try:
        cursor.execute(
            """
            SELECT DISTINCT s.student_id, s.full_name, s.current_grade
            FROM students s
            INNER JOIN parents p ON s.student_id = p.student_id
            WHERE p.email = %s AND s.status = 'in session'
            ORDER BY s.full_name ASC
            """,
            (pem,),
        )
        for row in cursor.fetchall() or []:
            if isinstance(row, dict):
                children.append({
                    'student_id': (row.get('student_id') or '').strip(),
                    'full_name': (row.get('full_name') or '').strip(),
                    'current_grade': (row.get('current_grade') or '').strip(),
                })
            else:
                children.append({
                    'student_id': (row[0] or '').strip(),
                    'full_name': (row[1] or '').strip(),
                    'current_grade': (row[2] or '').strip(),
                })
    except Exception as e:
        print(f"_parent_list_linked_children: {e}")
    return children


def _parent_may_view_student(cursor, parent_email, student_id):
    """Return (allowed, sibling_count) for a parent viewing one child."""
    pem = (parent_email or '').strip()
    sid = (student_id or '').strip()
    if not pem or not sid:
        return False, 0
    sibling_count = 0
    allowed = False
    try:
        cursor.execute(
            """
            SELECT COUNT(DISTINCT s.student_id) AS cnt
            FROM students s
            INNER JOIN parents p ON s.student_id = p.student_id
            WHERE p.email = %s AND s.status = 'in session'
            """,
            (pem,),
        )
        r = cursor.fetchone()
        sibling_count = int(r.get('cnt') if isinstance(r, dict) else (r[0] if r else 0))

        cursor.execute(
            """
            SELECT 1 FROM students s
            INNER JOIN parents p ON s.student_id = p.student_id
            WHERE p.email = %s
              AND LOWER(TRIM(s.student_id)) = LOWER(TRIM(%s))
              AND s.status = 'in session'
            LIMIT 1
            """,
            (pem, sid),
        )
        allowed = cursor.fetchone() is not None
    except Exception as e:
        print(f"_parent_may_view_student: {e}")
    return allowed, sibling_count


def _parent_student_library_books(cursor, student_id):
    """Library copies issued to a student (active and returned)."""
    ensure_library_book_student_issues_table(cursor)
    books = []
    sid = (student_id or '').strip()
    if not sid:
        return books
    try:
        cursor.execute(
            """
            SELECT
                si.id AS issue_id,
                UPPER(TRIM(si.copy_code)) AS copy_code,
                si.status,
                si.issued_at,
                si.returned_at,
                UPPER(TRIM(lb.book_name)) AS book_name,
                UPPER(TRIM(COALESCE(s.subject_name, ''))) AS subject_name,
                UPPER(TRIM(COALESCE(e.full_name, ''))) AS teacher_name,
                UPPER(TRIM(COALESCE(al.level_name, ''))) AS level_name
            FROM library_book_student_issues si
            INNER JOIN library_books lb ON lb.id = si.library_book_id
            LEFT JOIN subjects s ON s.id = si.subject_id
            LEFT JOIN employees e ON e.id = si.teacher_id
            LEFT JOIN academic_levels al ON al.id = si.academic_level_id
            WHERE LOWER(TRIM(si.student_id)) = LOWER(TRIM(%s))
            ORDER BY
                CASE WHEN si.status = 'issued' THEN 0 ELSE 1 END,
                si.issued_at DESC,
                si.copy_code ASC
            """,
            (sid,),
        )
        for row in cursor.fetchall() or []:
            if isinstance(row, dict):
                books.append({
                    'issue_id': int(row.get('issue_id') or 0),
                    'copy_code': (row.get('copy_code') or '').strip(),
                    'status': (row.get('status') or 'issued').strip(),
                    'issued_at': row.get('issued_at'),
                    'returned_at': row.get('returned_at'),
                    'book_name': (row.get('book_name') or '').strip(),
                    'subject_name': (row.get('subject_name') or '').strip(),
                    'teacher_name': (row.get('teacher_name') or '').strip(),
                    'level_name': (row.get('level_name') or '').strip(),
                })
            else:
                books.append({
                    'issue_id': int(row[0] or 0),
                    'copy_code': (row[1] or '').strip(),
                    'status': (row[2] or 'issued').strip(),
                    'issued_at': row[3] if len(row) > 3 else None,
                    'returned_at': row[4] if len(row) > 4 else None,
                    'book_name': (row[5] or '').strip() if len(row) > 5 else '',
                    'subject_name': (row[6] or '').strip() if len(row) > 6 else '',
                    'teacher_name': (row[7] or '').strip() if len(row) > 7 else '',
                    'level_name': (row[8] or '').strip() if len(row) > 8 else '',
                })
    except Exception as e:
        print(f"_parent_student_library_books: {e}")
    return books


def _compute_progress_aggregates(progress_data):
    """Build by_subject, by_period, by_exam, summary from progress rows (each with marks, year, term, exam, subject)."""
    by_subject = []
    by_period = []
    by_exam = []
    summary = {
        'overall_mean': 0,
        'pass_rate': 0,
        'total_entries': 0,
        'best_subject': None,
        'best_mean': None,
        'weakest_subject': None,
        'weakest_mean': None,
    }

    subject_marks = {}
    for p in progress_data:
        if p.get('marks') is not None:
            sn = p.get('subject_name') or 'N/A'
            if sn not in subject_marks:
                subject_marks[sn] = []
            subject_marks[sn].append(p['marks'])
    for sn, vals in sorted(subject_marks.items()):
        by_subject.append(
            {
                'subject_name': sn,
                'mean': round(sum(vals) / len(vals), 1),
                'count': len(vals),
                'min': round(min(vals), 1),
                'max': round(max(vals), 1),
            }
        )

    period_marks = {}
    for p in progress_data:
        if p.get('marks') is not None:
            label = (p.get('year_name') or '') + ' ' + (p.get('term_name') or '')
            label = label.strip() or 'Unknown'
            if label not in period_marks:
                period_marks[label] = []
            period_marks[label].append(p['marks'])
    for label, vals in sorted(period_marks.items(), reverse=True):
        by_period.insert(0, {'label': label, 'mean': round(sum(vals) / len(vals), 1), 'count': len(vals)})

    exam_order = []
    exam_rows = {}
    for p in progress_data:
        key = (p.get('year_name') or '', p.get('term_name') or '', p.get('exam_name') or '', p.get('exam_id') or 0)
        if key not in exam_rows:
            exam_rows[key] = []
            exam_order.append(key)
        exam_rows[key].append(p)
    for key in exam_order:
        rows = exam_rows[key]
        marks_list = [r['marks'] for r in rows if r.get('marks') is not None]
        subj_list = []
        for r in rows:
            if r.get('marks') is not None:
                subj_list.append({'subject_name': r['subject_name'], 'marks': r['marks']})
        if not subj_list:
            continue
        subj_list.sort(key=lambda x: x['subject_name'])
        first = rows[0]
        parts = [x for x in (first.get('year_name'), first.get('term_name'), first.get('exam_name')) if x]
        label = ' · '.join(parts) if parts else 'Unknown'
        mean = round(sum(marks_list) / len(marks_list), 1)
        pass_count = sum(1 for m in marks_list if m >= 50)
        pr = round(100 * pass_count / len(marks_list), 0)
        ed = first.get('exam_date')
        exam_date_str = ''
        if ed and hasattr(ed, 'strftime'):
            exam_date_str = ed.strftime('%Y-%m-%d')
        elif ed:
            exam_date_str = str(ed)[:10]
        by_exam.append(
            {
                'label': label,
                'year_name': first.get('year_name'),
                'term_name': first.get('term_name'),
                'exam_name': first.get('exam_name'),
                'exam_id': first.get('exam_id'),
                'exam_date_str': exam_date_str,
                'mean': mean,
                'count': len(marks_list),
                'pass_rate': pr,
                'subjects': subj_list,
            }
        )
    by_exam.sort(
        key=lambda x: (x.get('exam_date_str') or '', x.get('exam_id') or 0),
        reverse=True,
    )

    all_marks = [p['marks'] for p in progress_data if p.get('marks') is not None]
    total = len(all_marks)
    if total:
        summary['overall_mean'] = round(sum(all_marks) / total, 1)
        pass_count = sum(1 for m in all_marks if m >= 50)
        summary['pass_rate'] = round(100 * pass_count / total, 0)
        summary['total_entries'] = total
        best = max(by_subject, key=lambda x: x['mean']) if by_subject else None
        weakest = min(by_subject, key=lambda x: x['mean']) if by_subject else None
        summary['best_subject'] = best['subject_name'] if best else None
        summary['best_mean'] = best['mean'] if best else None
        summary['weakest_subject'] = weakest['subject_name'] if weakest else None
        summary['weakest_mean'] = weakest['mean'] if weakest else None

    return {
        'by_subject': by_subject,
        'by_period': by_period,
        'by_exam': by_exam,
        'summary': summary,
    }


def _parent_children_exam_summaries(student_ids):
    """Per-student exam analytics for parent child picker (in-session students only)."""
    out = {}
    ids = [str(s).strip() for s in (student_ids or []) if str(s).strip()]
    if not ids:
        return out
    connection = get_db_connection()
    if not connection:
        return out
    try:
        with connection.cursor() as cursor:
            ensure_subject_exam_total_marks_column(cursor)
            placeholders = ','.join(['%s'] * len(ids))
            cursor.execute(
                f"""
                SELECT sm.student_id,
                       COUNT(DISTINCT COALESCE(e.id, sm.exam_id)) AS exam_count,
                       COUNT(sm.id) AS mark_rows
                FROM student_marks sm
                LEFT JOIN exams e ON sm.exam_id = e.id
                WHERE TRIM(sm.student_id) IN ({placeholders})
                  AND sm.exam_id IS NOT NULL
                GROUP BY sm.student_id
                """,
                tuple(ids),
            )
            for row in cursor.fetchall() or []:
                sid = row.get('student_id') if isinstance(row, dict) else row[0]
                if not sid:
                    continue
                out[str(sid).strip()] = {
                    'exam_count': int(row.get('exam_count') if isinstance(row, dict) else row[1] or 0),
                    'mark_rows': int(row.get('mark_rows') if isinstance(row, dict) else row[2] or 0),
                }
            cursor.execute(
                f"""
                SELECT sm.student_id, sub.exam_total_marks, sm.marks
                FROM student_marks sm
                LEFT JOIN subjects sub ON sm.subject_id = sub.id
                WHERE TRIM(sm.student_id) IN ({placeholders})
                  AND sm.marks IS NOT NULL
                """,
                tuple(ids),
            )
            pct_by_student = {}
            for row in cursor.fetchall() or []:
                sid = row.get('student_id') if isinstance(row, dict) else row[0]
                if not sid:
                    continue
                sid = str(sid).strip()
                total = row.get('exam_total_marks') if isinstance(row, dict) else row[1]
                raw = row.get('marks') if isinstance(row, dict) else row[2]
                try:
                    m_raw = float(raw) if raw is not None else None
                except (TypeError, ValueError):
                    m_raw = None
                pct = raw_mark_to_percentage(m_raw, total) if m_raw is not None else None
                if pct is None:
                    continue
                pct_by_student.setdefault(sid, []).append(pct)
            for sid, vals in pct_by_student.items():
                slot = out.setdefault(sid, {'exam_count': 0, 'mark_rows': 0})
                slot['overall_mean'] = round(sum(vals) / len(vals), 1) if vals else None
    except Exception as e:
        print(f"_parent_children_exam_summaries: {e}")
    finally:
        try:
            connection.close()
        except Exception:
            pass
    return out


def _explicit_exam_progress_query(args):
    """True if the request includes filter query keys or all=1 (skip implicit current year/term/exam defaults)."""
    if not args:
        return False
    if str(args.get('all') or '').strip().lower() in ('1', 'true', 'yes'):
        return True
    fk = ('academic_year_id', 'term_id', 'exam_id', 'subject_id')
    try:
        return bool(set(args.keys()) & set(fk))
    except Exception:
        return False


def _norm_db_int(value):
    """Normalize MySQL / PyMySQL numeric ids for comparisons and dict keys (handles Decimal, str, int)."""
    if value is None:
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _resolve_marks_sheet_filter_defaults(exams, registered_current_exam, current_year_id, current_term_id):
    """
    Pick academic year, term, and exam for the marks sheet filters.
    School registered current exam always takes priority when set.
    Returns (year_id, term_id, exam_id).
    """
    year_id = current_year_id
    term_id = current_term_id
    exam_id = None

    if registered_current_exam:
        try:
            reg_ay = int(registered_current_exam.get('academic_year_id') or 0)
            reg_tid = int(registered_current_exam.get('term_id') or 0)
        except (TypeError, ValueError):
            reg_ay = reg_tid = 0
        if reg_ay > 0:
            year_id = reg_ay
        if reg_tid > 0:
            term_id = reg_tid

    if not exams:
        return year_id, term_id, exam_id

    want_name = ''
    if registered_current_exam:
        want_name = (registered_current_exam.get('exam_name') or '').strip().upper()

    scoped = [
        e for e in exams
        if str(e.get('academic_year_id')) == str(year_id) and str(e.get('term_id')) == str(term_id)
    ]

    selected = None
    want_type = registered_current_exam.get('exam_type') if registered_current_exam else None
    if scoped and want_name:
        pool_match = [
            e for e in scoped
            if str((e.get('exam_name') or '').strip().upper()) == want_name
            and (
                want_type is None
                or str((e.get('exam_type') or '').strip().upper()) == str(want_type or '').strip().upper()
            )
        ]
        if pool_match:
            pool_match.sort(key=lambda x: int(x.get('id') or 0))
            selected = pool_match[0]

    if not selected and scoped:
        today_str = date_cls.today().isoformat()
        selected = next(
            (e for e in scoped if str(e.get('exam_date') or '')[:10] == today_str),
            None,
        )
        if not selected:
            scoped.sort(key=lambda x: ((x.get('exam_date') or ''), int(x.get('id') or 0)), reverse=True)
            selected = scoped[0]

    if selected:
        exam_id = selected.get('id')

    return year_id, term_id, exam_id


def _pick_default_exam_id_for_progress(exams_by_id, year_id, term_id, registered_current_exam):
    """Pick one exam id: prefer today in scope, else registered current exam name match, else latest by date."""
    pool = list(exams_by_id.values()) if exams_by_id else []
    if not pool:
        return None
    yk = _norm_db_int(year_id)
    tk = _norm_db_int(term_id)
    if yk is not None and tk is not None:
        scoped = [e for e in pool if _norm_db_int(e.get('academic_year_id')) == yk and _norm_db_int(e.get('term_id')) == tk]
    elif yk is not None:
        scoped = [e for e in pool if _norm_db_int(e.get('academic_year_id')) == yk]
    else:
        scoped = pool
    if not scoped:
        scoped = pool
    today_str = date_cls.today().isoformat()
    for e in scoped:
        eds = (e.get('exam_date_str') or '')[:10]
        if eds == today_str:
            return _norm_db_int(e.get('id'))
    if registered_current_exam:
        want_name = (registered_current_exam.get('exam_name') or '').strip().upper()
        want_ay = registered_current_exam.get('academic_year_id')
        want_tid = registered_current_exam.get('term_id')
        want_type = registered_current_exam.get('exam_type')
        for e in sorted(scoped, key=lambda x: int(x.get('id') or 0)):
            en = (e.get('exam_name') or '').strip().upper()
            if en != want_name:
                continue
            if want_ay is not None and _norm_db_int(e.get('academic_year_id')) != _norm_db_int(want_ay):
                continue
            if want_tid is not None and _norm_db_int(e.get('term_id')) != _norm_db_int(want_tid):
                continue
            if want_type is not None and str((e.get('exam_type') or '').strip().upper()) != str(want_type):
                continue
            return _norm_db_int(e.get('id'))
    scoped_sorted = sorted(scoped, key=lambda x: ((x.get('exam_date_str') or ''), x.get('id') or 0), reverse=True)
    return _norm_db_int(scoped_sorted[0].get('id')) if scoped_sorted else None


def _fetch_student_progress_payload(student_id, filter_args=None, use_implicit_school_defaults=False):
    """Load student marks and aggregates for progress / exam report (staff and parent views).

    When filter_args is set (e.g. request.args), optional GET filters narrow aggregates:
    academic_year_id, term_id, exam_id, subject_id.

    If use_implicit_school_defaults is True (parent exam progress), a visit with no filter query keys
    defaults to the school's current academic year, current term, and a sensible current exam for that scope.
    Use ?all=1 on the URL to show all marks without those defaults.
    """

    def _row_dict_get(d, *names):
        if not isinstance(d, dict):
            return None
        for n in names:
            if n in d:
                return d[n]
        lower_map = {str(k).lower(): k for k in d}
        for n in names:
            lk = str(n).lower()
            if lk in lower_map:
                return d[lower_map[lk]]
        return None

    def _rows_as_dicts(cursor_obj, seq):
        """Normalize PyMySQL rows to dicts (handles tuple rows if cursorclass is not DictCursor)."""
        if not seq:
            return []
        desc = getattr(cursor_obj, 'description', None) or []
        keys = [d[0] for d in desc] if desc else []
        out = []
        for item in seq:
            if isinstance(item, dict):
                out.append(item)
            elif isinstance(item, (list, tuple)) and keys:
                out.append({keys[i]: item[i] for i in range(min(len(keys), len(item)))})
        return out

    sid_param = (student_id or '').strip()
    student = None
    progress_data = []
    exam_dropdown_rows = []
    school_default_year_id = None
    school_default_term_id = None
    registered_current_exam = None
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                ensure_subject_exam_total_marks_column(cursor)
                cursor.execute(
                    """
                    SELECT s.student_id, s.full_name, s.current_grade, s.status
                    FROM students s
                    WHERE LOWER(TRIM(s.student_id)) = LOWER(TRIM(%s))
                    LIMIT 1
                    """,
                    (sid_param,),
                )
                row = cursor.fetchone()
                if row:
                    student = {
                        'student_id': row.get('student_id') if isinstance(row, dict) else row[0],
                        'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
                        'current_grade': row.get('current_grade') if isinstance(row, dict) else row[2],
                        'status': row.get('status') if isinstance(row, dict) else row[3],
                    }

                if student:
                    try:
                        cursor.execute(
                            """
                            SELECT id FROM academic_years
                            WHERE is_current = TRUE AND status = 'active'
                            ORDER BY id DESC LIMIT 1
                            """
                        )
                        yrow = cursor.fetchone()
                        if yrow:
                            school_default_year_id = yrow.get('id') if isinstance(yrow, dict) else yrow[0]
                        if school_default_year_id:
                            cursor.execute(
                                """
                                SELECT id FROM terms
                                WHERE is_current = TRUE AND status = 'active' AND academic_year_id = %s
                                ORDER BY id DESC LIMIT 1
                                """,
                                (school_default_year_id,),
                            )
                            trow = cursor.fetchone()
                            if trow:
                                school_default_term_id = trow.get('id') if isinstance(trow, dict) else trow[0]
                        if not school_default_term_id and school_default_year_id:
                            cursor.execute(
                                """
                                SELECT id FROM terms
                                WHERE status = 'active' AND academic_year_id = %s
                                ORDER BY is_current DESC, id DESC LIMIT 1
                                """,
                                (school_default_year_id,),
                            )
                            trow2 = cursor.fetchone()
                            if trow2:
                                school_default_term_id = trow2.get('id') if isinstance(trow2, dict) else trow2[0]
                        if not school_default_year_id:
                            cursor.execute(
                                "SELECT id FROM academic_years WHERE status = 'active' ORDER BY id DESC LIMIT 1"
                            )
                            y2 = cursor.fetchone()
                            if y2:
                                school_default_year_id = y2.get('id') if isinstance(y2, dict) else y2[0]
                        registered_current_exam = load_registered_current_exam_dict(cursor)
                        school_default_year_id = _norm_db_int(school_default_year_id)
                        school_default_term_id = _norm_db_int(school_default_term_id)
                    except Exception as _sdef:
                        print(f"_fetch_student_progress_payload school term defaults: {_sdef}")

                    # Distinct exams for filter UI (reliable keys; separate from wide marks row shape).
                    try:
                        cursor.execute(
                            """
                            SELECT DISTINCT COALESCE(e.id, sm.exam_id) AS exam_id,
                                   e.exam_name, e.exam_type, e.exam_date,
                                   e.academic_year_id AS exam_academic_year_id, e.term_id AS exam_term_id,
                                   ay.year_name, t.term_name
                            FROM student_marks sm
                            LEFT JOIN exams e ON sm.exam_id = e.id
                            LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
                            LEFT JOIN terms t ON e.term_id = t.id
                            WHERE TRIM(sm.student_id) = TRIM(%s) AND sm.exam_id IS NOT NULL
                            ORDER BY COALESCE(e.exam_date, sm.updated_at) DESC, COALESCE(e.id, sm.exam_id) DESC
                            """,
                            (student['student_id'],),
                        )
                        exam_dropdown_rows = _rows_as_dicts(cursor, cursor.fetchall() or [])
                    except Exception as _exd:
                        print(f"_fetch_student_progress_payload exam_dropdown: {_exd}")
                        exam_dropdown_rows = []

                    cursor.execute(
                        """
                        SELECT ay.year_name, t.term_name, e.exam_name, e.exam_type, sub.subject_name, sub.subject_code,
                               sub.exam_total_marks, sm.marks,
                               COALESCE(e.id, sm.exam_id) AS exam_id,
                               e.academic_year_id AS exam_academic_year_id,
                               e.term_id AS exam_term_id, e.exam_date AS exam_date,
                               sm.subject_id AS subject_id
                        FROM student_marks sm
                        LEFT JOIN exams e ON sm.exam_id = e.id
                        LEFT JOIN subjects sub ON sm.subject_id = sub.id
                        LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
                        LEFT JOIN terms t ON e.term_id = t.id
                        WHERE TRIM(sm.student_id) = TRIM(%s)
                        ORDER BY COALESCE(e.exam_date, sm.updated_at) DESC, ay.year_name, t.term_name, e.exam_name, sub.subject_name
                        """,
                        (student['student_id'],),
                    )
                    raw = _rows_as_dicts(cursor, cursor.fetchall() or [])
                    for r in raw:
                        if not isinstance(r, dict):
                            continue
                        year_name = _row_dict_get(r, 'year_name')
                        term_name = _row_dict_get(r, 'term_name')
                        exam_name = _row_dict_get(r, 'exam_name')
                        exam_type = _row_dict_get(r, 'exam_type')
                        subject_name = _row_dict_get(r, 'subject_name') or _row_dict_get(r, 'subject_code') or 'N/A'
                        exam_total_marks = _row_dict_get(r, 'exam_total_marks')
                        marks_val = _row_dict_get(r, 'marks')
                        exam_id = _row_dict_get(r, 'exam_id')
                        exam_academic_year_id = _row_dict_get(r, 'exam_academic_year_id')
                        exam_term_id = _row_dict_get(r, 'exam_term_id')
                        exam_date = _row_dict_get(r, 'exam_date')
                        subject_id = _row_dict_get(r, 'subject_id')
                        try:
                            m_raw = float(marks_val) if marks_val is not None else None
                        except (TypeError, ValueError):
                            m_raw = None
                        m_pct = raw_mark_to_percentage(m_raw, exam_total_marks) if m_raw is not None else None
                        progress_data.append(
                            {
                                'year_name': year_name,
                                'term_name': term_name,
                                'exam_name': exam_name,
                                'exam_type': exam_type,
                                'subject_name': subject_name,
                                'marks': m_pct,
                                'marks_raw': m_raw,
                                'exam_id': _norm_db_int(exam_id),
                                'exam_academic_year_id': _norm_db_int(exam_academic_year_id),
                                'exam_term_id': _norm_db_int(exam_term_id),
                                'exam_date': exam_date,
                                'subject_id': _norm_db_int(subject_id),
                            }
                        )
        except Exception as e:
            print(f"Error fetching student progress: {e}")
            raise
        finally:
            if connection:
                try:
                    connection.close()
                except Exception:
                    pass

    def _opt_int(args, key):
        if not args:
            return None
        try:
            v = args.get(key)
        except TypeError:
            return None
        if v is None or (isinstance(v, str) and not v.strip()):
            return None
        try:
            return int(v)
        except (TypeError, ValueError):
            return None

    years_map = {}
    terms_map = {}
    exams_map = {}
    subjects_map = {}
    for p in progress_data:
        yid = _norm_db_int(p.get('exam_academic_year_id'))
        if yid is not None:
            years_map[yid] = p.get('year_name') or f'Year {yid}'
        tid = _norm_db_int(p.get('exam_term_id'))
        if tid is not None:
            terms_map[tid] = {
                'id': tid,
                'term_name': p.get('term_name') or 'Term',
                'year_name': p.get('year_name') or '',
                'academic_year_id': yid,
            }
        eid = _norm_db_int(p.get('exam_id'))
        if eid is not None and eid not in exams_map:
            parts = [x for x in (p.get('year_name'), p.get('term_name'), p.get('exam_name')) if x]
            ed = p.get('exam_date')
            eds = ed.strftime('%Y-%m-%d') if ed and hasattr(ed, 'strftime') else (str(ed)[:10] if ed else '')
            exams_map[eid] = {
                'id': eid,
                'label': ' · '.join(parts) if parts else f'Exam {eid}',
                'exam_date_str': eds,
                'academic_year_id': _norm_db_int(p.get('exam_academic_year_id')),
                'term_id': _norm_db_int(p.get('exam_term_id')),
                'exam_name': (p.get('exam_name') or ''),
                'exam_type': (p.get('exam_type') or ''),
            }
        sid = _norm_db_int(p.get('subject_id'))
        if sid is not None:
            subjects_map[sid] = p.get('subject_name') or 'Subject'

    for r in exam_dropdown_rows:
        yid = _norm_db_int(_row_dict_get(r, 'exam_academic_year_id'))
        if yid is not None:
            yn = _row_dict_get(r, 'year_name')
            years_map[yid] = yn or years_map.get(yid) or f'Year {yid}'
        tid = _norm_db_int(_row_dict_get(r, 'exam_term_id'))
        if tid is not None:
            prev = terms_map.get(tid) or {}
            terms_map[tid] = {
                'id': tid,
                'term_name': _row_dict_get(r, 'term_name') or prev.get('term_name') or 'Term',
                'year_name': _row_dict_get(r, 'year_name') or prev.get('year_name') or '',
                'academic_year_id': yid if yid is not None else _norm_db_int(prev.get('academic_year_id')),
            }
        eid = _norm_db_int(_row_dict_get(r, 'exam_id'))
        if eid is None:
            continue
        parts = [x for x in (_row_dict_get(r, 'year_name'), _row_dict_get(r, 'term_name'), _row_dict_get(r, 'exam_name')) if x]
        ed = _row_dict_get(r, 'exam_date')
        eds = ed.strftime('%Y-%m-%d') if ed and hasattr(ed, 'strftime') else (str(ed)[:10] if ed else '')
        exams_map[eid] = {
            'id': eid,
            'label': ' · '.join(parts) if parts else f'Exam {eid}',
            'exam_date_str': eds,
            'academic_year_id': _norm_db_int(_row_dict_get(r, 'exam_academic_year_id')),
            'term_id': _norm_db_int(_row_dict_get(r, 'exam_term_id')),
            'exam_name': (_row_dict_get(r, 'exam_name') or ''),
            'exam_type': (_row_dict_get(r, 'exam_type') or ''),
        }

    exam_filter_academic_years = [
        {'id': k, 'year_name': years_map[k]} for k in sorted(years_map.keys(), reverse=True)
    ]

    fa_year = None
    fa_term = None
    fa_exam = None
    fa_subj = None
    implicit_default_fallback = False

    if use_implicit_school_defaults:
        if filter_args and str(filter_args.get('all') or '').strip().lower() in ('1', 'true', 'yes'):
            pass
        elif not _explicit_exam_progress_query(filter_args):
            fa_year = school_default_year_id if school_default_year_id in years_map else None
            fa_term = school_default_term_id if school_default_term_id in terms_map else None
            fa_subj = None
            fa_exam = _pick_default_exam_id_for_progress(exams_map, fa_year, fa_term, registered_current_exam)
            if fa_exam is not None and fa_exam not in exams_map:
                fa_exam = None
        elif filter_args:
            fa_year = _norm_db_int(_opt_int(filter_args, 'academic_year_id'))
            fa_term = _norm_db_int(_opt_int(filter_args, 'term_id'))
            fa_exam = _norm_db_int(_opt_int(filter_args, 'exam_id'))
            fa_subj = _norm_db_int(_opt_int(filter_args, 'subject_id'))
    elif filter_args:
        fa_year = _norm_db_int(_opt_int(filter_args, 'academic_year_id'))
        fa_term = _norm_db_int(_opt_int(filter_args, 'term_id'))
        fa_exam = _norm_db_int(_opt_int(filter_args, 'exam_id'))
        fa_subj = _norm_db_int(_opt_int(filter_args, 'subject_id'))

    # Align filters so year/term/exam/subject stay consistent (exam drives year+term; term implies year).
    if fa_exam is not None:
        ex = exams_map.get(fa_exam)
        if ex:
            ey = _norm_db_int(ex.get('academic_year_id'))
            et = _norm_db_int(ex.get('term_id'))
            if ey is not None:
                fa_year = ey
            if et is not None:
                fa_term = et
        else:
            fa_exam = None
    if fa_year is None and fa_term is not None:
        te = terms_map.get(fa_term)
        if te:
            fa_year = _norm_db_int(te.get('academic_year_id'))
    if fa_term is not None:
        te = terms_map.get(fa_term)
        if not te:
            fa_term = None
        else:
            ty = _norm_db_int(te.get('academic_year_id'))
            if fa_year is not None and ty is not None and ty != fa_year:
                fa_term = None

    def _exam_in_scope_row(ex):
        ey = _norm_db_int(ex.get('academic_year_id'))
        et = _norm_db_int(ex.get('term_id'))
        if fa_year is not None and ey != fa_year:
            return False
        if fa_term is not None and et != fa_term:
            return False
        return True

    scoped_exam_ids = {_norm_db_int(ex.get('id')) for ex in exams_map.values() if _exam_in_scope_row(ex)}
    scoped_exam_ids.discard(None)
    if fa_exam is not None and fa_exam not in scoped_exam_ids:
        fa_exam = None

    def _progress_row_matches_scope(p, require_exam, require_subj):
        if fa_year is not None and p.get('exam_academic_year_id') != fa_year:
            return False
        if fa_term is not None and p.get('exam_term_id') != fa_term:
            return False
        if require_exam and fa_exam is not None and p.get('exam_id') != fa_exam:
            return False
        if require_subj and fa_subj is not None and p.get('subject_id') != fa_subj:
            return False
        return True

    subject_ids_scoped = set()
    for p in progress_data:
        if not _progress_row_matches_scope(p, require_exam=True, require_subj=False):
            continue
        sid = p.get('subject_id')
        if sid is not None:
            subject_ids_scoped.add(sid)
    if not subject_ids_scoped:
        for p in progress_data:
            if not _progress_row_matches_scope(p, require_exam=False, require_subj=False):
                continue
            sid = p.get('subject_id')
            if sid is not None:
                subject_ids_scoped.add(sid)
    if fa_subj is not None and fa_subj not in subject_ids_scoped:
        fa_subj = None

    exam_filter_terms = sorted(
        [
            dict(t)
            for t in terms_map.values()
            if fa_year is None or _norm_db_int(t.get('academic_year_id')) == fa_year
        ],
        key=lambda t: (str(t.get('year_name') or ''), -(t.get('id') or 0)),
    )
    exam_filter_exams = sorted(
        [ex for ex in exams_map.values() if _exam_in_scope_row(ex)],
        key=lambda x: (x.get('exam_date_str') or '', x.get('id') or 0),
        reverse=True,
    )
    exam_filter_subjects = [
        {'id': k, 'subject_name': subjects_map[k]}
        for k in sorted(subject_ids_scoped & set(subjects_map.keys()), key=lambda i: subjects_map[i].lower())
    ]

    filters_active = any(x is not None for x in (fa_year, fa_term, fa_exam, fa_subj))

    def _row_ok(p):
        if fa_year is not None and p.get('exam_academic_year_id') != fa_year:
            return False
        if fa_term is not None and p.get('exam_term_id') != fa_term:
            return False
        if fa_exam is not None and p.get('exam_id') != fa_exam:
            return False
        if fa_subj is not None and p.get('subject_id') != fa_subj:
            return False
        return True

    working = [p for p in progress_data if _row_ok(p)] if filters_active else progress_data
    ag = _compute_progress_aggregates(working)

    has_exam_marks = len(progress_data) > 0
    if (
        use_implicit_school_defaults
        and filter_args is not None
        and not _explicit_exam_progress_query(filter_args)
        and str(filter_args.get('all') or '').strip().lower() not in ('1', 'true', 'yes')
        and has_exam_marks
        and filters_active
        and len(working) == 0
    ):
        fa_year = fa_term = fa_exam = fa_subj = None
        filters_active = False
        working = progress_data
        ag = _compute_progress_aggregates(working)
        implicit_default_fallback = True
        exam_filter_terms = sorted(
            terms_map.values(),
            key=lambda t: (str(t.get('year_name') or ''), -(t.get('id') or 0)),
        )
        exam_filter_exams = sorted(
            exams_map.values(),
            key=lambda x: (x.get('exam_date_str') or '', x.get('id') or 0),
            reverse=True,
        )
        exam_filter_subjects = [
            {'id': k, 'subject_name': subjects_map[k]}
            for k in sorted(subjects_map.keys(), key=lambda i: subjects_map[i].lower())
        ]

    filter_no_results = bool(filters_active and has_exam_marks and len(working) == 0)

    return {
        'student': student,
        'progress_data': working,
        'by_subject': ag['by_subject'] if student else [],
        'by_period': ag['by_period'] if student else [],
        'by_exam': ag['by_exam'] if student else [],
        'summary': ag['summary'] if student else None,
        'has_exam_marks': has_exam_marks,
        'filter_no_results': filter_no_results,
        'filters_active': filters_active,
        'exam_filter_academic_years': exam_filter_academic_years,
        'exam_filter_terms': exam_filter_terms,
        'exam_filter_exams': exam_filter_exams,
        'exam_filter_subjects': exam_filter_subjects,
        'selected_academic_year_id': fa_year,
        'selected_term_id': fa_term,
        'selected_exam_id': fa_exam,
        'selected_subject_id': fa_subj,
        'implicit_exam_default_fallback': implicit_default_fallback,
    }


@app.route('/dashboard/parent/exam-progress')
@login_required
def parent_exam_progress():
    """List linked children; single child redirects to their exam progress detail."""
    ctx = _parent_dashboard_auth()
    if ctx is None:
        flash('You do not have permission to access this page.', 'error')
        return redirect(url_for('home'))

    parent_email = ctx['parent_email']
    children = []
    connection = get_db_connection()
    if connection and parent_email:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT DISTINCT s.student_id, s.full_name, s.current_grade
                    FROM students s
                    INNER JOIN parents p ON s.student_id = p.student_id
                    WHERE p.email = %s AND s.status = 'in session'
                    ORDER BY s.full_name ASC
                """, (parent_email,))
                for row in cursor.fetchall() or []:
                    children.append({
                        'student_id': row.get('student_id') if isinstance(row, dict) else row[0],
                        'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
                        'current_grade': row.get('current_grade') if isinstance(row, dict) else row[2],
                    })
                summaries = _parent_children_exam_summaries([c['student_id'] for c in children])
                for c in children:
                    sm = summaries.get(str(c['student_id']).strip(), {})
                    c['exam_count'] = sm.get('exam_count', 0)
                    c['overall_mean'] = sm.get('overall_mean')
        except Exception as e:
            print(f"Error listing parent exam progress children: {e}")
            flash('Error loading children.', 'error')
        finally:
            if connection:
                try:
                    connection.close()
                except Exception:
                    pass

    if len(children) == 1:
        return redirect(parent_dashboard_path(f"exam-progress/{children[0]['student_id']}"))

    return render_template(
        'dashboards/parent_exam_progress_list.html',
        children=children,
        is_technician=ctx['is_technician'],
        current_view_role=ctx['current_view_role'],
        all_students=ctx['all_students'],
        selected_student_id=ctx['selected_student_id'],
    )


@app.route('/dashboard/parent/exam-progress/<student_id>')
@login_required
def parent_exam_progress_detail(student_id):
    """Parent-safe exam progress & analytics for one linked child."""
    ctx = _parent_dashboard_auth()
    if ctx is None:
        flash('You do not have permission to access this page.', 'error')
        return redirect(url_for('home'))

    parent_email = ctx['parent_email']
    if not parent_email:
        flash('No linked parent account.', 'error')
        return redirect(parent_dashboard_path())

    allowed = False
    sibling_count = 0
    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT COUNT(DISTINCT s.student_id) AS cnt
                    FROM students s
                    INNER JOIN parents p ON s.student_id = p.student_id
                    WHERE p.email = %s AND s.status = 'in session'
                """, (parent_email,))
                r = cursor.fetchone()
                sibling_count = int(r.get('cnt') if isinstance(r, dict) else (r[0] if r else 0))

                cursor.execute("""
                    SELECT 1 FROM students s
                    INNER JOIN parents p ON s.student_id = p.student_id
                    WHERE p.email = %s AND LOWER(TRIM(s.student_id)) = LOWER(TRIM(%s)) AND s.status = 'in session'
                    LIMIT 1
                """, (parent_email, student_id))
                allowed = cursor.fetchone() is not None
        except Exception as e:
            print(f"Error verifying parent exam access: {e}")
        finally:
            if connection:
                try:
                    connection.close()
                except Exception:
                    pass

    if not allowed:
        flash('You cannot view exam progress for this student.', 'error')
        return redirect(parent_dashboard_path('exam-progress'))

    try:
        # Parent view: all recorded exams by default (not only current term/exam).
        payload = _fetch_student_progress_payload(student_id, request.args, use_implicit_school_defaults=False)
    except Exception:
        flash('Error loading student progress.', 'error')
        return redirect(parent_dashboard_path('exam-progress'))

    if not payload['student']:
        flash('Student not found.', 'error')
        return redirect(parent_dashboard_path('exam-progress'))

    summary = payload.get('summary') or {}
    by_exam = payload.get('by_exam') or []
    return render_template(
        'dashboards/parent_student_exam_progress.html',
        student=payload['student'],
        progress_data=payload['progress_data'],
        by_subject=payload['by_subject'],
        by_period=payload['by_period'],
        by_exam=by_exam,
        summary=summary,
        has_exam_marks=payload.get('has_exam_marks', False),
        filter_no_results=payload.get('filter_no_results', False),
        filters_active=payload.get('filters_active', False),
        exam_filter_academic_years=payload.get('exam_filter_academic_years', []),
        exam_filter_terms=payload.get('exam_filter_terms', []),
        exam_filter_exams=payload.get('exam_filter_exams', []),
        exam_filter_subjects=payload.get('exam_filter_subjects', []),
        selected_academic_year_id=payload.get('selected_academic_year_id'),
        selected_term_id=payload.get('selected_term_id'),
        selected_exam_id=payload.get('selected_exam_id'),
        selected_subject_id=payload.get('selected_subject_id'),
        implicit_exam_default_fallback=payload.get('implicit_exam_default_fallback', False),
        exams_count=len(by_exam),
        subjects_count=len(payload.get('by_subject') or []),
        is_technician=ctx['is_technician'],
        current_view_role=ctx['current_view_role'],
        all_students=ctx['all_students'],
        selected_student_id=ctx['selected_student_id'],
        show_sibling_nav=sibling_count > 1,
    )


def _parent_fetch_in_session_children(parent_email):
    """Linked children rows for parent portal pickers (same shape as attendance list)."""
    children = []
    if not parent_email:
        return children
    connection = get_db_connection()
    if not connection:
        return children
    try:
        with connection.cursor() as cursor:
            cursor.execute(
                """
                SELECT DISTINCT s.student_id, s.full_name, s.current_grade
                FROM students s
                INNER JOIN parents p ON s.student_id = p.student_id
                WHERE p.email = %s AND s.status = 'in session'
                ORDER BY s.full_name ASC
                """,
                (parent_email,),
            )
            for row in cursor.fetchall() or []:
                children.append(
                    {
                        'student_id': row.get('student_id') if isinstance(row, dict) else row[0],
                        'full_name': row.get('full_name') if isinstance(row, dict) else row[1],
                        'current_grade': row.get('current_grade') if isinstance(row, dict) else row[2],
                    }
                )
    except Exception as e:
        print(f"_parent_fetch_in_session_children: {e}")
    finally:
        try:
            connection.close()
        except Exception:
            pass
    return children


def _school_current_term_bundle(cursor):
    """Current school year + term ids and labels (best-effort, matches other portal defaults)."""
    year_id = None
    year_name = None
    term_id = None
    term_name = None
    try:
        cursor.execute(
            """
            SELECT id, year_name FROM academic_years
            WHERE is_current = TRUE AND status = 'active'
            ORDER BY id DESC LIMIT 1
            """
        )
        yrow = cursor.fetchone()
        if yrow:
            year_id = yrow.get('id') if isinstance(yrow, dict) else yrow[0]
            year_name = yrow.get('year_name') if isinstance(yrow, dict) else (yrow[1] if len(yrow) > 1 else None)
        if year_id:
            cursor.execute(
                """
                SELECT id, term_name FROM terms
                WHERE is_current = TRUE AND status = 'active' AND academic_year_id = %s
                ORDER BY id DESC LIMIT 1
                """,
                (year_id,),
            )
            trow = cursor.fetchone()
            if trow:
                term_id = trow.get('id') if isinstance(trow, dict) else trow[0]
                term_name = trow.get('term_name') if isinstance(trow, dict) else (trow[1] if len(trow) > 1 else None)
        if not term_id and year_id:
            cursor.execute(
                """
                SELECT id, term_name FROM terms
                WHERE status = 'active' AND academic_year_id = %s
                ORDER BY is_current DESC, id DESC LIMIT 1
                """,
                (year_id,),
            )
            trow2 = cursor.fetchone()
            if trow2:
                term_id = trow2.get('id') if isinstance(trow2, dict) else trow2[0]
                term_name = trow2.get('term_name') if isinstance(trow2, dict) else (trow2[1] if len(trow2) > 1 else None)
        if not year_id:
            cursor.execute(
                "SELECT id, year_name FROM academic_years WHERE status = 'active' ORDER BY id DESC LIMIT 1"
            )
            y2 = cursor.fetchone()
            if y2:
                year_id = y2.get('id') if isinstance(y2, dict) else y2[0]
                year_name = y2.get('year_name') if isinstance(y2, dict) else (y2[1] if len(y2) > 1 else None)
    except Exception as e:
        print(f"_school_current_term_bundle: {e}")
    return year_id, year_name, term_id, term_name


def _parent_term_options_for_timetables(cursor):
    """Active terms with year label for parent timetable term switcher."""
    opts = []
    try:
        cursor.execute(
            """
            SELECT t.id, t.term_name, ay.year_name, t.academic_year_id
            FROM terms t
            INNER JOIN academic_years ay ON ay.id = t.academic_year_id
            WHERE t.status = 'active' AND ay.status = 'active'
            ORDER BY ay.id DESC, t.is_current DESC, t.id DESC
            """
        )
        for row in cursor.fetchall() or []:
            tid = row.get('id') if isinstance(row, dict) else row[0]
            tn = row.get('term_name') if isinstance(row, dict) else (row[1] if len(row) > 1 else '')
            yn = row.get('year_name') if isinstance(row, dict) else (row[2] if len(row) > 2 else '')
            opts.append({'id': tid, 'term_name': tn or 'Term', 'year_name': yn or ''})
    except Exception as e:
        print(f"_parent_term_options_for_timetables: {e}")
    return opts


def _parent_resolve_student_level_for_timetables(cursor, parent_email, student_id):
    """Verify parent link and resolve academic_level_id from current_grade."""
    if not parent_email or not student_id:
        return None
    cursor.execute(
        """
        SELECT s.student_id, s.full_name, s.current_grade,
               al.id AS academic_level_id, al.level_name AS resolved_level_name
        FROM students s
        INNER JOIN parents p ON s.student_id = p.student_id
        LEFT JOIN academic_levels al
            ON TRIM(LOWER(s.current_grade)) = TRIM(LOWER(al.level_name))
            AND COALESCE(al.level_status, 'active') = 'active'
        WHERE p.email = %s AND LOWER(TRIM(s.student_id)) = LOWER(TRIM(%s)) AND s.status = 'in session'
        LIMIT 1
        """,
        (parent_email, student_id),
    )
    row = cursor.fetchone()
    if not row:
        return None
    if isinstance(row, dict):
        return {
            'student_id': row.get('student_id'),
            'full_name': row.get('full_name'),
            'current_grade': row.get('current_grade'),
            'academic_level_id': row.get('academic_level_id'),
            'resolved_level_name': row.get('resolved_level_name') or row.get('current_grade'),
        }
    return {
        'student_id': row[0] if len(row) > 0 else None,
        'full_name': row[1] if len(row) > 1 else None,
        'current_grade': row[2] if len(row) > 2 else None,
        'academic_level_id': row[3] if len(row) > 3 else None,
        'resolved_level_name': (row[4] if len(row) > 4 else None) or (row[2] if len(row) > 2 else None),
    }


def _parent_weekly_timetable_sections(cursor, academic_level_id, term_id):
    if not academic_level_id or not term_id:
        return []
    rows = []
    try:
        cursor.execute(
            """
            SELECT t.day_of_week, t.time_slot, al.level_name,
                   e.full_name AS teacher_name, s.subject_name, s.subject_code
            FROM timetables t
            LEFT JOIN academic_levels al ON t.academic_level_id = al.id
            LEFT JOIN employees e ON t.teacher_id = e.id
            LEFT JOIN subjects s ON s.id = t.subject_id
            WHERE t.term_id = %s AND t.academic_level_id = %s
            ORDER BY FIELD(t.day_of_week,
                'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'),
                t.time_slot
            """,
            (term_id, academic_level_id),
        )
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                rows.append(
                    {
                        'day_of_week': r.get('day_of_week'),
                        'time_slot': r.get('time_slot'),
                        'level_name': r.get('level_name'),
                        'subject_name': r.get('subject_name'),
                        'subject_code': r.get('subject_code'),
                        'teacher_name': r.get('teacher_name'),
                    }
                )
            else:
                rows.append(
                    {
                        'day_of_week': r[0] if len(r) > 0 else None,
                        'time_slot': r[1] if len(r) > 1 else None,
                        'level_name': r[2] if len(r) > 2 else None,
                        'teacher_name': r[3] if len(r) > 3 else None,
                        'subject_name': r[4] if len(r) > 4 else None,
                        'subject_code': r[5] if len(r) > 5 else None,
                    }
                )
    except Exception as e:
        print(f"_parent_weekly_timetable_sections: {e}")
    return _timetable_sections_from_rows(rows, teacher_mode=False)


def _parent_exam_timetable_sections_for_class(cursor, academic_level_id, term_id):
    if not academic_level_id or not term_id:
        return []
    rows = []
    try:
        cursor.execute(
            """
            SELECT e.exam_date, e.start_time, e.end_time, al.level_name,
                   e.exam_name, COALESCE(s.subject_name, 'Paper') AS subject_name,
                   e.venue, e.status
            FROM exams e
            LEFT JOIN academic_levels al ON e.academic_level_id = al.id
            LEFT JOIN subjects s ON e.subject_id = s.id
            WHERE e.term_id = %s AND e.academic_level_id = %s
              AND (e.status IS NULL OR e.status != 'cancelled')
            ORDER BY e.exam_date ASC, e.start_time ASC
            """,
            (term_id, academic_level_id),
        )
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                rows.append(
                    {
                        'exam_date': r.get('exam_date'),
                        'start_time': r.get('start_time'),
                        'end_time': r.get('end_time'),
                        'level_name': r.get('level_name'),
                        'exam_name': r.get('exam_name'),
                        'subject_name': r.get('subject_name'),
                        'venue': r.get('venue'),
                        'status': r.get('status'),
                    }
                )
            else:
                rows.append(
                    {
                        'exam_date': r[0] if len(r) > 0 else None,
                        'start_time': r[1] if len(r) > 1 else None,
                        'end_time': r[2] if len(r) > 2 else None,
                        'level_name': r[3] if len(r) > 3 else None,
                        'exam_name': r[4] if len(r) > 4 else None,
                        'subject_name': r[5] if len(r) > 5 else None,
                        'venue': r[6] if len(r) > 6 else None,
                        'status': r[7] if len(r) > 7 else None,
                    }
                )
    except Exception as e:
        print(f"_parent_exam_timetable_sections_for_class: {e}")
    return _exam_timetable_sections_from_rows(rows)


