@app.route('/profile/<role>')
@login_required
def profile(role):
    """Profile page for each role"""
    user_role = session.get('role', '').lower()
    
    # Validate role access
    if role == 'employee':
        if user_role not in EMPLOYEE_SUB_ROLES:
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
        
        # Get employee data
        connection = get_db_connection()
        user_data = {}
        if connection:
            try:
                with connection.cursor() as cursor:
                    employee_id = session.get('employee_id') or session.get('user_id')
                    cursor.execute("SELECT * FROM employees WHERE id = %s OR employee_id = %s", 
                                 (employee_id, employee_id))
                    employee = cursor.fetchone()
                    if employee:
                        user_data = employee
            except Exception as e:
                print(f"Error fetching employee data: {e}")
            finally:
                connection.close()
        
        return render_template('dashboards/profile_employee.html', user_data=user_data, role=user_role)
    
    elif role in ['student', 'parent']:
        if user_role != role:
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
        
        # Get user data from users table
        connection = get_db_connection()
        user_data = {}
        if connection:
            try:
                with connection.cursor() as cursor:
                    user_id = session.get('user_id')
                    cursor.execute("SELECT * FROM users WHERE id = %s AND role = %s", (user_id, role))
                    user = cursor.fetchone()
                    if user:
                        user_data = user
            except Exception as e:
                print(f"Error fetching user data: {e}")
            finally:
                connection.close()
        
        return render_template(f'dashboards/profile_{role}.html', user_data=user_data, role=role)
    
    else:
        flash('Invalid role.', 'error')
        return redirect(url_for('home'))

@app.route('/settings/<role>')
@login_required
def settings(role, _from_timetable_page=False):
    """Settings page for each role"""
    role = (role or '').strip().lower().replace('-', ' ')
    user_role = session.get('role', '').lower()
    is_technician = user_role == 'technician'
    
    # Validate role access
    if role in ('head of institution', 'deputy head of institution'):
        if user_role != role and not is_technician:
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
        
        return render_template('dashboards/settings_principal.html', role=user_role)
    
    elif role == 'curriculum coordinator':
        # Allow broader schedule-management roles to access
        schedule_management_roles = ['curriculum coordinator', 'head of institution', 'deputy head of institution', 'super admin', 'accountant', 'technician']
        if user_role not in schedule_management_roles:
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))

        if not _from_timetable_page:
            dest = employee_staff_settings_url('curriculum coordinator')
            qs = request.query_string.decode('utf-8') if request.query_string else ''
            if qs:
                dest += ('&' if '?' in dest else '?') + qs
            return redirect(dest)

        # Curriculum Coordinator settings (academic schedule management).
        connection = get_db_connection()
        settings = {}
        settings_profiles = []
        academic_levels = []
        selected_profile_id = request.args.get('profile_id', '').strip()
        if connection:
            try:
                with connection.cursor() as cursor:
                    cursor.execute("""
                        SELECT id, level_category, level_name
                        FROM academic_levels
                        WHERE COALESCE(level_status, 'active') = 'active'
                        ORDER BY level_category, level_name ASC
                    """)
                    academic_levels = cursor.fetchall() or []

                    try:
                        cursor.execute("""
                            SELECT id, profile_name, applicable_levels, is_active, updated_at,
                                   study_days, class_time_allocation, class_duration, activity_time_allocation
                            FROM academic_coordinator_settings
                            ORDER BY is_active DESC, updated_at DESC, id DESC
                        """)
                        has_is_active = True
                    except Exception:
                        cursor.execute("""
                            SELECT id, profile_name, applicable_levels, updated_at,
                                   study_days, class_time_allocation, class_duration, activity_time_allocation
                            FROM academic_coordinator_settings
                            ORDER BY updated_at DESC, id DESC
                        """)
                        has_is_active = False
                    profile_rows = cursor.fetchall() or []
                    for row in profile_rows:
                        if isinstance(row, dict):
                            raw_profile_levels = row.get('applicable_levels') or '[]'
                            profile_id = row.get('id')
                            profile_name = row.get('profile_name') or f'Profile {profile_id}'
                            is_active = bool(row.get('is_active')) if has_is_active else False
                            raw_study_days = row.get('study_days') or ''
                            raw_class_times = row.get('class_time_allocation') or '[]'
                            raw_activities = row.get('activity_time_allocation') or '[]'
                            profile_class_duration = row.get('class_duration') or 60
                        else:
                            raw_profile_levels = row[2] if row[2] else '[]'
                            profile_id = row[0]
                            profile_name = row[1] if row[1] else f'Profile {profile_id}'
                            is_active = bool(row[3]) if has_is_active and len(row) > 3 else False
                            offset = 5 if has_is_active else 4
                            raw_study_days = row[offset] if len(row) > offset and row[offset] else ''
                            raw_class_times = row[offset + 1] if len(row) > (offset + 1) and row[offset + 1] else '[]'
                            profile_class_duration = row[offset + 2] if len(row) > (offset + 2) and row[offset + 2] else 60
                            raw_activities = row[offset + 3] if len(row) > (offset + 3) and row[offset + 3] else '[]'

                        try:
                            parsed_profile_levels = json.loads(raw_profile_levels)
                        except Exception:
                            parsed_profile_levels = []
                        try:
                            parsed_class_times = json.loads(raw_class_times)
                        except Exception:
                            parsed_class_times = []
                        try:
                            parsed_activities = json.loads(raw_activities)
                        except Exception:
                            parsed_activities = []
                        parsed_days = [d.strip() for d in str(raw_study_days).split(',') if str(d).strip()]

                        settings_profiles.append({
                            'id': profile_id,
                            'profile_name': profile_name,
                            'applicable_levels': parsed_profile_levels,
                            'is_active': is_active,
                            'study_days': parsed_days,
                            'class_times': parsed_class_times if isinstance(parsed_class_times, list) else [],
                            'activities': parsed_activities if isinstance(parsed_activities, list) else [],
                            'class_duration': int(profile_class_duration) if str(profile_class_duration).isdigit() else 60,
                        })

                    # Determine which profile to load (query param, then active, then latest)
                    selected_id = None
                    if selected_profile_id.isdigit():
                        selected_id = int(selected_profile_id)
                    elif settings_profiles:
                        active_profile = next((p for p in settings_profiles if p.get('is_active')), None)
                        selected_id = active_profile['id'] if active_profile else settings_profiles[0]['id']

                    if selected_id:
                        cursor.execute("""
                            SELECT id, profile_name, study_days, applicable_levels, class_time_allocation, class_duration, activity_time_allocation
                            FROM academic_coordinator_settings
                            WHERE id = %s
                            LIMIT 1
                        """, (selected_id,))
                    else:
                        cursor.execute("""
                            SELECT id, profile_name, study_days, applicable_levels, class_time_allocation, class_duration, activity_time_allocation
                            FROM academic_coordinator_settings
                            ORDER BY updated_at DESC, id DESC
                            LIMIT 1
                        """)
                    result = cursor.fetchone()
                    if result:
                        if isinstance(result, dict):
                            settings = result
                            raw_levels = settings.get('applicable_levels') or '[]'
                            try:
                                settings['applicable_levels'] = json.loads(raw_levels)
                            except Exception:
                                settings['applicable_levels'] = []
                            if settings.get('class_time_allocation'):
                                try:
                                    settings['class_times'] = json.loads(settings['class_time_allocation'])
                                except Exception:
                                    settings['class_times'] = []
                            else:
                                settings['class_times'] = []
                            if settings.get('activity_time_allocation'):
                                try:
                                    settings['activities'] = json.loads(settings['activity_time_allocation'])
                                except Exception:
                                    settings['activities'] = []
                            else:
                                settings['activities'] = []
                        else:
                            applicable_levels_json = result[3] if result[3] else '[]'
                            class_times_json = result[4] if result[4] else '[]'
                            activities_json = result[6] if result[6] else '[]'
                            try:
                                applicable_levels = json.loads(applicable_levels_json)
                            except Exception:
                                applicable_levels = []
                            try:
                                class_times = json.loads(class_times_json)
                            except Exception:
                                class_times = []
                            try:
                                activities = json.loads(activities_json)
                            except Exception:
                                activities = []
                            settings = {
                                'id': result[0],
                                'profile_name': result[1] if result[1] else '',
                                'study_days': result[2] if result[2] else '',
                                'applicable_levels': applicable_levels,
                                'class_time_allocation': class_times_json,
                                'class_times': class_times,
                                'class_duration': result[5] if result[5] else '',
                                'activity_time_allocation': activities_json,
                                'activities': activities
                            }
            except Exception as e:
                print(f"Error fetching academic coordinator settings: {e}")
                settings['activities'] = []
            finally:
                connection.close()

        if 'activities' not in settings:
            settings['activities'] = []
        if 'class_times' not in settings:
            settings['class_times'] = []
        if 'applicable_levels' not in settings:
            settings['applicable_levels'] = []
        if 'profile_name' not in settings:
            settings['profile_name'] = ''
        if 'id' not in settings:
            settings['id'] = ''

        return render_template(
            'dashboards/settings_academic_coordinator.html',
            role=user_role,
            settings=settings,
            settings_profiles=settings_profiles,
            academic_levels=academic_levels
        )
    
    elif role == 'employee':
        employee_settings_roles = [r for r in EMPLOYEE_SUB_ROLES if r not in ('head of institution', 'super admin')]
        if user_role not in employee_settings_roles:
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
        
        return render_template('dashboards/settings_employee.html', role=user_role)
    
    elif role in ['student', 'parent']:
        if user_role != role:
            flash('You do not have permission to access this page.', 'error')
            return redirect(url_for('home'))
        
        return render_template(f'dashboards/settings_{role}.html', role=role)
    
    else:
        flash('Invalid role.', 'error')
        return redirect(url_for('home'))


