@app.route('/dashboard/employee/exam-evaluation')
@login_required
def exam_evaluation():
    """Exam & Evaluation page - register exams and allocate supervisors"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_teacher_effective_nav = user_role in ('teachers', 'teacher') or viewing_as_role in ('teachers', 'teacher')
    if is_teacher_effective_nav:
        return redirect(employee_dashboard_path('exam-timetable'))
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Fetch data for exam registration
    connection = get_db_connection()
    academic_years = []
    terms = []
    academic_levels = []
    teachers = []
    teacher_subject_pairs = []
    subjects = []
    teachers = []
    exams = []
    registered_current_exam = None
    level_combinations = []

    if connection:
        try:
            with connection.cursor() as cursor:
                # Get academic years
                cursor.execute("""
                    SELECT id, year_name, start_date, end_date, status, is_current
                    FROM academic_years
                    WHERE status = 'active'
                    ORDER BY start_date DESC
                """)
                academic_years_results = cursor.fetchall()
                for row in academic_years_results:
                    start_date_val = row.get('start_date') if isinstance(row, dict) else row[2]
                    end_date_val = row.get('end_date') if isinstance(row, dict) else row[3]
                    
                    # Convert date objects to strings
                    start_date_str = start_date_val.strftime('%Y-%m-%d') if start_date_val and hasattr(start_date_val, 'strftime') else (str(start_date_val) if start_date_val else None)
                    end_date_str = end_date_val.strftime('%Y-%m-%d') if end_date_val and hasattr(end_date_val, 'strftime') else (str(end_date_val) if end_date_val else None)
                    
                    academic_years.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'year_name': row.get('year_name', '') if isinstance(row, dict) else row[1],
                        'start_date': start_date_str,
                        'end_date': end_date_str,
                        'is_current': bool(row.get('is_current')) if isinstance(row, dict) else (bool(row[5]) if len(row) > 5 else False),
                    })
                
                # Get terms
                try:
                    cursor.execute("""
                        SELECT id, term_name, academic_year_id, start_date, end_date, status, COALESCE(is_current, 0) AS is_current
                        FROM terms
                        WHERE status = 'active'
                        ORDER BY start_date DESC
                    """)
                except Exception:
                    cursor.execute("""
                        SELECT id, term_name, academic_year_id, start_date, end_date, status
                        FROM terms
                        WHERE status = 'active'
                        ORDER BY start_date DESC
                    """)
                terms_results = cursor.fetchall()
                for row in terms_results:
                    start_date_val = row.get('start_date') if isinstance(row, dict) else (row[3] if len(row) > 3 else None)
                    end_date_val = row.get('end_date') if isinstance(row, dict) else (row[4] if len(row) > 4 else None)
                    
                    # Convert date objects to strings
                    start_date_str = start_date_val.strftime('%Y-%m-%d') if start_date_val and hasattr(start_date_val, 'strftime') else (str(start_date_val) if start_date_val else None)
                    end_date_str = end_date_val.strftime('%Y-%m-%d') if end_date_val and hasattr(end_date_val, 'strftime') else (str(end_date_val) if end_date_val else None)
                    
                    terms.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'term_name': row.get('term_name', '') if isinstance(row, dict) else row[1],
                        'academic_year_id': row.get('academic_year_id') if isinstance(row, dict) else row[2],
                        'start_date': start_date_str,
                        'end_date': end_date_str,
                        'is_current': bool(row.get('is_current')) if isinstance(row, dict) else bool(row[6] if len(row) > 6 else False),
                    })
                
                # Get academic levels
                cursor.execute("""
                    SELECT id, level_category, level_name
                    FROM academic_levels
                    WHERE level_status = 'active'
                    ORDER BY level_category, level_name ASC
                """)
                academic_levels_results = cursor.fetchall()
                for row in academic_levels_results:
                    academic_levels.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'level_category': row.get('level_category', '') if isinstance(row, dict) else row[1],
                        'level_name': row.get('level_name', '') if isinstance(row, dict) else row[2]
                    })
                
                # Get subjects
                try:
                    cursor.execute("""
                        SELECT id, subject_name, subject_code
                        FROM subjects
                        WHERE status = 'active'
                        ORDER BY subject_name ASC
                    """)
                    subjects_results = cursor.fetchall()
                    for row in subjects_results:
                        subjects.append({
                            'id': row.get('id') if isinstance(row, dict) else row[0],
                            'subject_name': row.get('subject_name', '') if isinstance(row, dict) else row[1],
                            'subject_code': row.get('subject_code', '') if isinstance(row, dict) else row[2]
                        })
                except Exception as e:
                    print(f"Note: subjects table may not exist: {e}")
                
                # Get teachers
                cursor.execute(f"""
                    SELECT emp.id,
                           {_employee_staff_identity_sql('emp')} AS employee_id,
                           emp.full_name
                    FROM employees emp
                    WHERE emp.role = 'teachers' AND emp.status = 'active'
                    ORDER BY emp.full_name ASC
                """)
                teachers_results = cursor.fetchall()
                for row in teachers_results:
                    teachers.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'employee_id': row.get('employee_id', '') if isinstance(row, dict) else row[1],
                        'full_name': row.get('full_name', '') if isinstance(row, dict) else row[2]
                    })

                # Teacher-subject allocation pairs per level
                cursor.execute(f"""
                    SELECT tsa.academic_level_id, tsa.teacher_id, tsa.subject_id,
                           e.full_name,
                           {_employee_staff_identity_sql('e')} AS employee_id,
                           s.subject_name, s.subject_code
                    FROM teacher_subject_assignments tsa
                    INNER JOIN employees e ON e.id = tsa.teacher_id
                    INNER JOIN subjects s ON s.id = tsa.subject_id
                    WHERE e.role = 'teachers'
                      AND e.status = 'active'
                      AND COALESCE(s.status, 'active') = 'active'
                    ORDER BY tsa.academic_level_id ASC, e.full_name ASC, s.subject_name ASC
                """)
                pair_rows = cursor.fetchall() or []
                for row in pair_rows:
                    if isinstance(row, dict):
                        teacher_subject_pairs.append({
                            'academic_level_id': int(row.get('academic_level_id')),
                            'teacher_id': int(row.get('teacher_id')),
                            'subject_id': int(row.get('subject_id')),
                            'teacher_name': row.get('full_name', ''),
                            'employee_id': row.get('employee_id', ''),
                            'subject_name': row.get('subject_name', ''),
                            'subject_code': row.get('subject_code', '') or ''
                        })
                    else:
                        teacher_subject_pairs.append({
                            'academic_level_id': int(row[0]),
                            'teacher_id': int(row[1]),
                            'subject_id': int(row[2]),
                            'teacher_name': row[3] if len(row) > 3 else '',
                            'employee_id': row[4] if len(row) > 4 else '',
                            'subject_name': row[5] if len(row) > 5 else '',
                            'subject_code': (row[6] if len(row) > 6 else '') or ''
                        })
                
                # Get existing exams (each row represents a subject allocation + supervisor)
                try:
                    ensure_exams_marks_lock_at_column(cursor)
                    apply_marks_lock_deadline_auto_lock(cursor)
                    connection.commit()
                    cursor.execute(f"""
                        SELECT e.id, e.exam_name, e.exam_type, e.exam_date, e.session_type, e.start_time, e.end_time,
                               e.duration_minutes, e.venue, e.status,
                               e.academic_year_id, e.term_id,
                               COALESCE(e.is_locked, 0) AS is_locked, e.locked_at, e.marks_lock_at,
                               e.academic_level_id, e.subject_id, e.supervisor_id,
                               al.level_name, al.level_category,
                               s.subject_name, s.subject_code,
                               ay.year_name, t.term_name,
                               emp.full_name as supervisor_name, {_employee_staff_identity_sql('emp')} as supervisor_employee_id
                        FROM exams e
                        LEFT JOIN academic_levels al ON e.academic_level_id = al.id
                        LEFT JOIN subjects s ON e.subject_id = s.id
                        LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
                        LEFT JOIN terms t ON e.term_id = t.id
                        LEFT JOIN employees emp ON e.supervisor_id = emp.id
                        ORDER BY e.exam_date DESC, e.start_time DESC
                    """)
                    exams_results = cursor.fetchall()
                    for row in exams_results:
                        # Convert timedelta/datetime objects to strings for JSON serialization
                        exam_date_val = row.get('exam_date') if isinstance(row, dict) else row[3]
                        start_time_val = row.get('start_time') if isinstance(row, dict) else row[5]
                        end_time_val = row.get('end_time') if isinstance(row, dict) else row[6]
                        
                        # Convert exam_date (date object) to string
                        if exam_date_val:
                            if hasattr(exam_date_val, 'strftime'):
                                exam_date_str = exam_date_val.strftime('%Y-%m-%d')
                            else:
                                exam_date_str = str(exam_date_val)
                        else:
                            exam_date_str = None
                        
                        # Convert start_time (time/timedelta object) to string
                        if start_time_val:
                            if isinstance(start_time_val, timedelta):
                                # Convert timedelta to time string (HH:MM:SS)
                                total_seconds = int(start_time_val.total_seconds())
                                hours = total_seconds // 3600
                                minutes = (total_seconds % 3600) // 60
                                seconds = total_seconds % 60
                                start_time_str = f"{hours:02d}:{minutes:02d}:{seconds:02d}"
                            elif hasattr(start_time_val, 'strftime'):
                                start_time_str = start_time_val.strftime('%H:%M:%S')
                            else:
                                start_time_str = str(start_time_val)
                        else:
                            start_time_str = None
                        
                        # Convert end_time (time/timedelta object) to string
                        if end_time_val:
                            if isinstance(end_time_val, timedelta):
                                # Convert timedelta to time string (HH:MM:SS)
                                total_seconds = int(end_time_val.total_seconds())
                                hours = total_seconds // 3600
                                minutes = (total_seconds % 3600) // 60
                                seconds = total_seconds % 60
                                end_time_str = f"{hours:02d}:{minutes:02d}:{seconds:02d}"
                            elif hasattr(end_time_val, 'strftime'):
                                end_time_str = end_time_val.strftime('%H:%M:%S')
                            else:
                                end_time_str = str(end_time_val)
                        else:
                            end_time_str = None

                        locked_raw = row.get('is_locked', 0) if isinstance(row, dict) else 0
                        is_locked_flag = bool(locked_raw) if not isinstance(locked_raw, bool) else locked_raw
                        lat = row.get('locked_at') if isinstance(row, dict) else None
                        if lat and hasattr(lat, 'strftime'):
                            locked_at_str = lat.strftime('%Y-%m-%d %H:%M:%S')
                        else:
                            locked_at_str = str(lat) if lat else None

                        mla = row.get('marks_lock_at') if isinstance(row, dict) else None
                        if mla and hasattr(mla, 'strftime'):
                            marks_lock_at_str = mla.strftime('%Y-%m-%dT%H:%M:%S')
                        else:
                            marks_lock_at_str = str(mla) if mla else None
                        
                        exams.append({
                            'id': row.get('id') if isinstance(row, dict) else row[0],
                            'exam_name': row.get('exam_name', '') if isinstance(row, dict) else row[1],
                            'exam_type': row.get('exam_type', '') if isinstance(row, dict) else row[2],
                            'exam_date': exam_date_str,
                            'session_type': row.get('session_type', '') if isinstance(row, dict) else row[4],
                            'start_time': start_time_str,
                            'end_time': end_time_str,
                            'duration_minutes': row.get('duration_minutes') if isinstance(row, dict) else row[7],
                            'venue': row.get('venue', '') if isinstance(row, dict) else row[8],
                            'status': row.get('status', 'scheduled') if isinstance(row, dict) else (row[9] if len(row) > 9 else 'scheduled'),
                            'academic_year_id': row.get('academic_year_id') if isinstance(row, dict) else None,
                            'term_id': row.get('term_id') if isinstance(row, dict) else None,
                            'is_locked': is_locked_flag,
                            'locked_at': locked_at_str,
                            'marks_lock_at': marks_lock_at_str,
                            'academic_level_id': row.get('academic_level_id') if isinstance(row, dict) else None,
                            'subject_id': row.get('subject_id') if isinstance(row, dict) else None,
                            'supervisor_id': row.get('supervisor_id') if isinstance(row, dict) else None,
                            'level_name': row.get('level_name', '') if isinstance(row, dict) else '',
                            'level_category': row.get('level_category', '') if isinstance(row, dict) else '',
                            'subject_name': row.get('subject_name', '') if isinstance(row, dict) else '',
                            'subject_code': row.get('subject_code', '') if isinstance(row, dict) else '',
                            'year_name': row.get('year_name', '') if isinstance(row, dict) else '',
                            'term_name': row.get('term_name', '') if isinstance(row, dict) else '',
                            'supervisor_name': row.get('supervisor_name', '') if isinstance(row, dict) else '',
                            'supervisor_employee_id': row.get('supervisor_employee_id', '') if isinstance(row, dict) else ''
                        })
                except Exception as e:
                    print(f"Note: exams table may not exist yet: {e}")
                    exams = []
                registered_current_exam = load_registered_current_exam_dict(cursor)
                ensure_academic_level_combination_tables(cursor)
                level_by_id = {
                    int(l['id']): l for l in academic_levels if l.get('id') is not None
                }
                level_combinations = []
                for combo in fetch_academic_level_combinations(cursor):
                    disp = _level_combo_display_row(combo, level_by_id)
                    members = []
                    for mid, mname in zip(
                        disp.get('level_ids') or [],
                        disp.get('level_names') or [],
                    ):
                        lv = level_by_id.get(int(mid), {})
                        members.append({
                            'id': int(mid),
                            'level_name': mname,
                            'level_category': lv.get('level_category') or '',
                        })
                    level_combinations.append({
                        'combo_id': disp.get('combo_id'),
                        'level_name': disp.get('level_name') or '—',
                        'members': members,
                    })
        except Exception as e:
            print(f"Error fetching exam data: {e}")
        finally:
            connection.close()
    else:
        level_combinations = []

    open_edit_id = request.args.get('open_edit', type=int)

    default_academic_year_id = ''
    default_term_id = ''
    current_year = next((y for y in academic_years if y.get('is_current')), None)
    if not current_year and academic_years:
        current_year = academic_years[0]
    if current_year and current_year.get('id') is not None:
        default_academic_year_id = str(current_year['id'])
        year_id = current_year['id']
        year_terms = [t for t in terms if t.get('academic_year_id') == year_id]
        current_term = next((t for t in year_terms if t.get('is_current')), None)
        if not current_term and year_terms:
            current_term = year_terms[0]
        if current_term and current_term.get('id') is not None:
            default_term_id = str(current_term['id'])
    
    # Session presets for UI (timetable settings)
    session_presets_ui = {
        k: {'start': v[0][:5], 'end': v[1][:5]}
        for k, v in _default_exam_session_presets().items()
    }
    conn_presets = get_db_connection()
    if conn_presets:
        try:
            with conn_presets.cursor() as cursor:
                p = _load_exam_session_presets_from_db(cursor)
                session_presets_ui = {k: {'start': v[0][:5], 'end': v[1][:5]} for k, v in p.items()}
        except Exception:
            session_presets_ui = {
                k: {'start': v[0][:5], 'end': v[1][:5]}
                for k, v in _default_exam_session_presets().items()
            }
        finally:
            conn_presets.close()

    return render_template('dashboards/exam_evaluation.html', 
                         role=user_role,
                         academic_years=academic_years,
                         default_academic_year_id=default_academic_year_id,
                         default_term_id=default_term_id,
                         terms=terms,
                         academic_levels=academic_levels,
                         level_combinations=level_combinations,
                         subjects=subjects,
                         teachers=teachers,
                         exams=exams,
                         open_edit_id=open_edit_id,
                         session_presets=session_presets_ui,
                         registered_current_exam=registered_current_exam)


@app.route('/dashboard/employee/exam-subject-settings', methods=['GET', 'POST'])
@login_required
def exam_subject_settings():
    """Per-subject exam maximum marks (curriculum coordinator / principal / technician)."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    if user_role in ('teachers', 'teacher') or viewing_as_role in ('teachers', 'teacher'):
        return redirect(employee_dashboard_path('exam-timetable'))

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    if not (is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    connection = get_db_connection()
    if not connection:
        flash('Database connection failed.', 'error')
        return redirect(employee_dashboard_path('exam-evaluation'))

    try:
        with connection.cursor() as schema_cursor:
            ensure_subject_exam_combination_schema(schema_cursor)
    except Exception as e:
        print(f"exam_subject_settings schema ensure: {e}")

    settings_anchor = employee_dashboard_path('exam-subject-settings')
    combine_hash_redirect = f"{settings_anchor}#combine-exam-subjects"

    if request.method == 'POST':
        combine_action = (request.form.get('combine_action') or '').strip().lower()

        if combine_action == 'update_code':
            try:
                with connection.cursor() as cursor:
                    ensure_subject_exam_combination_schema(cursor)
                    cid = request.form.get('combination_id', type=int)
                    if not cid:
                        flash('Missing combination.', 'error')
                    else:
                        cursor.execute(
                            """
                            SELECT m.subject_id
                            FROM subject_exam_combination_members m
                            WHERE m.combination_id = %s
                            ORDER BY m.sort_order ASC, m.subject_id ASC
                            """,
                            (cid,),
                        )
                        mids = [
                            int(r.get('subject_id') if isinstance(r, dict) else r[0])
                            for r in (cursor.fetchall() or [])
                            if (r.get('subject_id') if isinstance(r, dict) else r[0]) is not None
                        ]
                        if len(mids) < 2:
                            flash('Combination not found.', 'error')
                        else:
                            placeholders = ','.join(['%s'] * len(mids))
                            cursor.execute(
                                f"""
                                SELECT id, subject_name, subject_code FROM subjects
                                WHERE id IN ({placeholders})
                                """,
                                tuple(mids),
                            )
                            name_map = {}
                            for r in cursor.fetchall() or []:
                                sid = int(r.get('id') if isinstance(r, dict) else r[0])
                                name_map[sid] = {
                                    'subject_name': r.get('subject_name') if isinstance(r, dict) else r[1],
                                    'subject_code': r.get('subject_code') if isinstance(r, dict) else r[2],
                                }
                            member_infos = [name_map.get(mid) for mid in mids]
                            fallback = auto_combined_subject_code_from_members(member_infos)
                            raw_code = request.form.get('update_combined_code')
                            if raw_code is None:
                                raw_code = request.form.get('combined_code')
                            new_code = normalize_combined_subject_code(raw_code, fallback)
                            if not new_code:
                                flash('Enter a combined code.', 'error')
                            else:
                                cursor.execute(
                                    "SELECT id FROM subject_exam_combinations WHERE id = %s",
                                    (cid,),
                                )
                                if not cursor.fetchone():
                                    flash('Combination not found.', 'error')
                                else:
                                    cursor.execute(
                                        """
                                        UPDATE subject_exam_combinations
                                        SET combined_code = %s
                                        WHERE id = %s
                                        """,
                                        (new_code, cid),
                                    )
                                    connection.commit()
                                    flash('Combined code updated.', 'success')
            except Exception as e:
                print(f"exam_subject_settings combine update_code: {e}")
                try:
                    connection.rollback()
                except Exception:
                    pass
                flash('Could not update combined code.', 'error')
            finally:
                try:
                    connection.close()
                except Exception:
                    pass
            return redirect(combine_hash_redirect)

        if combine_action == 'delete':
            try:
                with connection.cursor() as cursor:
                    ensure_subject_exam_combination_tables(cursor)
                    cid = request.form.get('combination_id', type=int)
                    if not cid:
                        flash('Missing combination.', 'error')
                    else:
                        cursor.execute(
                            """
                            SELECT totals_snapshot_json, codes_snapshot_json
                            FROM subject_exam_combinations WHERE id = %s
                            """,
                            (cid,),
                        )
                        snap_row = cursor.fetchone()
                        snap_raw = None
                        codes_snap_raw = None
                        if snap_row:
                            if isinstance(snap_row, dict):
                                snap_raw = snap_row.get('totals_snapshot_json')
                                codes_snap_raw = snap_row.get('codes_snapshot_json')
                            else:
                                snap_raw = snap_row[0] if len(snap_row) > 0 else None
                                codes_snap_raw = snap_row[1] if len(snap_row) > 1 else None
                        cursor.execute(
                            "DELETE FROM subject_exam_combination_members WHERE combination_id = %s",
                            (cid,),
                        )
                        restore_subject_totals_from_combination_snapshot(cursor, snap_raw)
                        restore_subject_codes_from_combination_snapshot(cursor, codes_snap_raw)
                        cursor.execute(
                            "DELETE FROM subject_exam_combinations WHERE id = %s",
                            (cid,),
                        )
                        connection.commit()
                        if snap_raw or codes_snap_raw:
                            flash(
                                'Combination removed. Exam totals and subject codes for those papers '
                                'were restored to their values before the combination.',
                                'success',
                            )
                        else:
                            flash('Combination removed.', 'success')
            except Exception as e:
                print(f"exam_subject_settings combine delete: {e}")
                try:
                    connection.rollback()
                except Exception:
                    pass
                flash('Could not remove combination.', 'error')
            finally:
                try:
                    connection.close()
                except Exception:
                    pass
            return redirect(combine_hash_redirect)

        if combine_action == 'create':
            try:
                with connection.cursor() as cursor:
                    ensure_subject_exam_combination_tables(cursor)
                    raw_ids = request.form.getlist('subject_pick')
                    sid_order = []
                    seen = set()
                    for x in raw_ids:
                        try:
                            sid = int(x)
                            if sid not in seen:
                                seen.add(sid)
                                sid_order.append(sid)
                        except (TypeError, ValueError):
                            continue
                    if len(sid_order) < 2:
                        flash('Select at least two subjects to combine.', 'error')
                        try:
                            connection.close()
                        except Exception:
                            pass
                        return redirect(combine_hash_redirect)
                    placeholders = ','.join(['%s'] * len(sid_order))
                    cursor.execute(
                        f"""
                        SELECT id FROM subjects
                        WHERE id IN ({placeholders}) AND COALESCE(status, 'active') = 'active'
                        """,
                        tuple(sid_order),
                    )
                    ok_active = {r.get('id') if isinstance(r, dict) else r[0] for r in (cursor.fetchall() or [])}
                    sid_order = [s for s in sid_order if s in ok_active]
                    if len(sid_order) < 2:
                        flash('Need at least two active subjects.', 'error')
                        try:
                            connection.close()
                        except Exception:
                            pass
                        return redirect(combine_hash_redirect)
                    cursor.execute(
                        f"""
                        SELECT subject_id FROM subject_exam_combination_members
                        WHERE subject_id IN ({placeholders})
                        """,
                        tuple(sid_order),
                    )
                    conflicts = cursor.fetchall() or []
                    if conflicts:
                        flash(
                            'One or more selected subjects are already part of another combination. '
                            'Remove that combination first.',
                            'error',
                        )
                        try:
                            connection.close()
                        except Exception:
                            pass
                        return redirect(combine_hash_redirect)
                    cursor.execute(
                        "INSERT INTO subject_exam_combinations (created_at) VALUES (CURRENT_TIMESTAMP)"
                    )
                    combo_id = cursor.lastrowid
                    totals_snapshot = normalize_subject_totals_for_exam_combination(cursor, sid_order)
                    codes_snapshot = normalize_subject_codes_for_exam_combination(cursor, sid_order)
                    cursor.execute(
                        f"""
                        SELECT id, subject_name, subject_code FROM subjects
                        WHERE id IN ({placeholders})
                        """,
                        tuple(sid_order),
                    )
                    pick_map = {}
                    for r in cursor.fetchall() or []:
                        sid = int(r.get('id') if isinstance(r, dict) else r[0])
                        pick_map[sid] = {
                            'subject_name': r.get('subject_name') if isinstance(r, dict) else r[1],
                            'subject_code': r.get('subject_code') if isinstance(r, dict) else r[2],
                        }
                    auto_code = auto_combined_subject_code_from_members(
                        [pick_map.get(s) for s in sid_order]
                    )
                    combined_code = normalize_combined_subject_code(
                        request.form.get('combined_code'), auto_code
                    )
                    cursor.execute(
                        "SELECT COALESCE(MAX(COALESCE(display_order, 0)), 0) + 10 AS nx FROM subject_exam_combinations"
                    )
                    nxrow = cursor.fetchone()
                    next_ord = int(
                        (nxrow.get('nx') if isinstance(nxrow, dict) else (nxrow[0] if nxrow else 0)) or 0
                    ) or 10
                    cursor.execute(
                        """
                        UPDATE subject_exam_combinations
                        SET totals_snapshot_json = %s,
                            codes_snapshot_json = %s,
                            combined_code = %s,
                            display_order = %s
                        WHERE id = %s
                        """,
                        (
                            json.dumps(totals_snapshot),
                            json.dumps(codes_snapshot),
                            combined_code,
                            next_ord,
                            combo_id,
                        ),
                    )
                    ph_ord = ','.join(['%s'] * len(sid_order))
                    cursor.execute(
                        f"UPDATE subjects SET exam_display_order = %s WHERE id IN ({ph_ord})",
                        (next_ord,) + tuple(sid_order),
                    )
                    for order_idx, sid in enumerate(sid_order):
                        cursor.execute(
                            """
                            INSERT INTO subject_exam_combination_members (combination_id, subject_id, sort_order)
                            VALUES (%s, %s, %s)
                            """,
                            (combo_id, sid, order_idx),
                        )
                    connection.commit()
                    flash(
                        'Subjects combined for marks entry. Exam totals were preserved.',
                        'success',
                    )
            except Exception as e:
                print(f"exam_subject_settings combine create: {e}")
                try:
                    connection.rollback()
                except Exception:
                    pass
                flash('Could not save combination. Try again.', 'error')
            finally:
                try:
                    connection.close()
                except Exception:
                    pass
            return redirect(combine_hash_redirect)

        order_action = (request.form.get('exam_order_action') or '').strip().lower()
        if order_action == 'save_order':
            raw_json = (request.form.get('exam_column_order_json') or '').strip()
            try:
                slots = json.loads(raw_json)
            except (TypeError, ValueError, json.JSONDecodeError):
                flash('Invalid column order payload.', 'error')
                return redirect(f"{settings_anchor}#exam-column-order")
            if not isinstance(slots, list) or not slots:
                flash('No column order to save.', 'error')
                return redirect(f"{settings_anchor}#exam-column-order")
            try:
                with connection.cursor() as cursor:
                    ensure_subject_exam_display_order_columns(cursor)
                    cursor.execute("SELECT id FROM subjects WHERE COALESCE(status, 'active') = 'active'")
                    valid_sids = {
                        int(r.get('id') if isinstance(r, dict) else r[0])
                        for r in (cursor.fetchall() or [])
                        if (r.get('id') if isinstance(r, dict) else r[0]) is not None
                    }
                    combos_loaded = fetch_subject_exam_combinations(cursor)
                    valid_cids = {int(c['id']) for c in combos_loaded}
                    member_of = set()
                    combo_members = {}
                    for c in combos_loaded:
                        cid = int(c['id'])
                        mids = [int(x) for x in (c.get('member_subject_ids') or [])]
                        combo_members[cid] = mids
                        for mid in mids:
                            member_of.add(int(mid))
                    for slot in slots:
                        if not isinstance(slot, dict):
                            raise ValueError('invalid slot')
                        st = (slot.get('type') or '').strip().lower()
                        sid = slot.get('id')
                        try:
                            sid_int = int(sid)
                        except (TypeError, ValueError):
                            raise ValueError('invalid id')
                        if st not in ('subject', 'combo'):
                            raise ValueError('invalid type')
                        if st == 'subject' and sid_int in member_of:
                            raise ValueError('subject is part of a combination')
                        if st == 'subject' and sid_int not in valid_sids:
                            raise ValueError('unknown subject')
                        if st == 'combo' and sid_int not in valid_cids:
                            raise ValueError('unknown combination')
                    for i, slot in enumerate(slots):
                        st = (slot.get('type') or '').strip().lower()
                        sid_int = int(slot['id'])
                        ordv = (i + 1) * 10
                        if st == 'subject':
                            cursor.execute(
                                "UPDATE subjects SET exam_display_order = %s WHERE id = %s",
                                (ordv, sid_int),
                            )
                        else:
                            cursor.execute(
                                "UPDATE subject_exam_combinations SET display_order = %s WHERE id = %s",
                                (ordv, sid_int),
                            )
                            for mid in combo_members.get(sid_int, []):
                                cursor.execute(
                                    "UPDATE subjects SET exam_display_order = %s WHERE id = %s",
                                    (ordv, mid),
                                )
                    connection.commit()
                flash('Column order saved. Marks entry and reports use this order.', 'success')
            except Exception as e:
                print(f"exam_subject_settings save_order: {e}")
                try:
                    connection.rollback()
                except Exception:
                    pass
                flash('Could not save column order.', 'error')
            finally:
                try:
                    connection.close()
                except Exception:
                    pass
            return redirect(f"{settings_anchor}#exam-column-order")

        if combine_action:
            flash('Unknown action.', 'error')
            try:
                connection.close()
            except Exception:
                pass
            return redirect(combine_hash_redirect)

        try:
            with connection.cursor() as cursor:
                ensure_subject_exam_total_marks_column(cursor)
                cursor.execute(
                    """
                    SELECT id FROM subjects
                    WHERE COALESCE(status, 'active') = 'active'
                    """
                )
                id_rows = cursor.fetchall() or []
                subject_ids = []
                for r in id_rows:
                    sid = r.get('id') if isinstance(r, dict) else r[0]
                    if sid is not None:
                        subject_ids.append(int(sid))
                parsed = {}
                for sid in subject_ids:
                    raw = (request.form.get(f'exam_total_marks_{sid}') or '').strip()
                    if raw == '':
                        parsed[sid] = None
                        continue
                    try:
                        val = float(raw)
                        if val < 1 or val > 1000:
                            raise ValueError('out of range')
                        parsed[sid] = val
                    except (TypeError, ValueError):
                        flash(
                            f'Invalid total marks for one or more subjects (ID {sid}). '
                            'Use a number between 1 and 1000, or leave blank for default (100).',
                            'error',
                        )
                        return redirect(employee_dashboard_path('exam-subject-settings'))
                for sid, val in parsed.items():
                    if val is None:
                        cursor.execute(
                            "UPDATE subjects SET exam_total_marks = NULL WHERE id = %s",
                            (sid,),
                        )
                    else:
                        cursor.execute(
                            "UPDATE subjects SET exam_total_marks = %s WHERE id = %s",
                            (val, sid),
                        )
                connection.commit()
            flash('Exam total marks per subject were saved.', 'success')
        except Exception as e:
            print(f"exam_subject_settings save: {e}")
            try:
                connection.rollback()
            except Exception:
                pass
            flash('Could not save settings. Please try again.', 'error')
        finally:
            try:
                connection.close()
            except Exception:
                pass
        return redirect(employee_dashboard_path('exam-subject-settings'))

    subjects_rows = []
    subjects_by_category = []
    combinations_display = []
    exam_column_order_by_category = []
    try:
        with connection.cursor() as cursor:
            ensure_subject_exam_total_marks_column(cursor)
            ensure_subject_exam_display_order_columns(cursor)
            ensure_subject_exam_combination_schema(cursor)
            base_category_order = []
            try:
                cursor.execute(
                    """
                    SELECT DISTINCT al.level_category AS lc
                    FROM academic_levels al
                    WHERE COALESCE(al.level_status, 'active') = 'active'
                      AND TRIM(COALESCE(al.level_category, '')) <> ''
                    ORDER BY al.level_category ASC
                    """
                )
                for cr in cursor.fetchall() or []:
                    lc = cr.get('lc') if isinstance(cr, dict) else cr[0]
                    if lc and str(lc).strip():
                        base_category_order.append(str(lc).strip())
            except Exception:
                base_category_order = []

            cursor.execute(
                """
                SELECT s.id, s.subject_name, s.subject_code, s.exam_total_marks, s.exam_display_order,
                       GROUP_CONCAT(DISTINCT al.level_category ORDER BY al.level_category SEPARATOR '|') AS cat_blob
                FROM subjects s
                LEFT JOIN subject_academic_levels sal ON sal.subject_id = s.id
                LEFT JOIN academic_levels al ON al.id = sal.academic_level_id
                    AND COALESCE(al.level_status, 'active') = 'active'
                WHERE COALESCE(s.status, 'active') = 'active'
                GROUP BY s.id, s.subject_name, s.subject_code, s.exam_total_marks, s.exam_display_order
                """
            )
            _tmp_rows = []
            for row in cursor.fetchall() or []:
                if isinstance(row, dict):
                    et = row.get('exam_total_marks')
                    sid = row.get('id')
                    sname = row.get('subject_name') or ''
                    scode = row.get('subject_code') or ''
                    edo = row.get('exam_display_order')
                    cat_blob = row.get('cat_blob') or ''
                else:
                    et = row[3] if len(row) > 3 else None
                    sid = row[0]
                    sname = row[1] or ''
                    scode = row[2] or ''
                    edo = row[4] if len(row) > 4 else None
                    cat_blob = row[5] if len(row) > 5 else ''
                et_f = float(et) if et is not None else None
                mx = subject_exam_max_raw_marks(et_f)
                if mx >= 50:
                    preview_raw = 50.0
                else:
                    preview_raw = round(mx / 2.0, 4) if mx > 0 else 1.0
                if preview_raw <= 0:
                    preview_raw = 1.0
                preview_pct = raw_mark_to_percentage(preview_raw, et_f)
                seen_c = set()
                level_categories = []
                for part in str(cat_blob or '').split('|'):
                    c = part.strip()
                    if c and c not in seen_c:
                        seen_c.add(c)
                        level_categories.append(c)
                assigned = None
                for c in base_category_order:
                    if c in seen_c:
                        assigned = c
                        break
                if assigned is None:
                    if level_categories:
                        assigned = sorted(level_categories)[0]
                    else:
                        assigned = 'Uncategorized'
                et_disp = subject_exam_max_raw_marks(et_f)
                _tmp_rows.append(
                    {
                        'id': sid,
                        'subject_name': sname,
                        'subject_code': scode,
                        'exam_total_marks': et_f,
                        'exam_display_order': int(edo) if edo is not None and str(edo).strip().isdigit() else (int(edo) if isinstance(edo, int) else None),
                        'effective_max': mx,
                        'preview_example_raw': preview_raw,
                        'preview_example_pct': preview_pct,
                        'level_categories': level_categories,
                        'group_category': assigned,
                        'exam_total_marks_display': et_disp,
                    }
                )

            by_cat = defaultdict(list)
            for r in _tmp_rows:
                by_cat[r['group_category']].append(r)
            keys_set = set(by_cat.keys())
            section_order = [k for k in base_category_order if k in keys_set]
            section_order.extend(
                sorted(k for k in keys_set if k not in section_order and k != 'Uncategorized')
            )
            if 'Uncategorized' in keys_set:
                section_order.append('Uncategorized')
            subjects_by_category = [
                {
                    'category': k,
                    'subjects': sorted(
                        by_cat[k],
                        key=lambda x: (
                            int(x.get('exam_display_order') or 10**9),
                            str(x.get('subject_name') or '').lower(),
                            int(x['id']),
                        ),
                    ),
                }
                for k in section_order
            ]
            subjects_rows = [s for sec in subjects_by_category for s in sec['subjects']]
            sep = '/'
            name_map = {int(r['id']): r for r in subjects_rows}
            combos_loaded = fetch_subject_exam_combinations(cursor)
            for c in combos_loaded:
                mids = c.get('member_subject_ids') or []
                if len(mids) < 2:
                    continue
                names = []
                codes = []
                totals = []
                member_codes_original = []
                for mid in mids:
                    info = name_map.get(mid)
                    if info:
                        names.append((info.get('subject_name') or '').strip() or '—')
                        cd = (info.get('subject_code') or '').strip()
                        codes.append(cd if cd else ((info.get('subject_name') or '')[:12] or '—'))
                        member_codes_original.append(cd if cd else '—')
                        totals.append(str(subject_exam_max_raw_marks(info.get('exam_total_marks'))))
                    else:
                        names.append('—')
                        codes.append('—')
                        member_codes_original.append('—')
                        totals.append('100')
                auto_code = sep.join(codes)
                stored_code = (c.get('combined_code') or '').strip()
                combinations_display.append({
                    'id': c['id'],
                    'label_name': sep.join(names),
                    'label_code': stored_code or auto_code,
                    'combined_code': stored_code,
                    'default_code': auto_code,
                    'member_codes': member_codes_original,
                    'member_totals': totals,
                    'member_ids': mids,
                })
            exam_column_order_by_category = _build_exam_column_order_by_category(
                name_map, combos_loaded, base_category_order
            )
    except Exception as e:
        print(f"exam_subject_settings load: {e}")
        flash('Could not load subjects.', 'error')
        subjects_rows = []
        subjects_by_category = []
        combinations_display = []
        exam_column_order_by_category = []
    finally:
        try:
            connection.close()
        except Exception:
            pass

    # Flat list kept for any legacy references; UI uses exam_column_order_by_category.
    exam_column_order_slots = [
        slot
        for section in (exam_column_order_by_category or [])
        for slot in (section.get('slots') or [])
    ]

    return render_template(
        'dashboards/exam_subject_settings.html',
        role=user_role,
        subjects_rows=subjects_rows,
        subjects_by_category=subjects_by_category,
        combinations_display=combinations_display,
        exam_column_order_by_category=exam_column_order_by_category,
        exam_column_order_slots=exam_column_order_slots,
    )


@app.route('/dashboard/employee/combined-academic-levels', methods=['GET', 'POST'])
@login_required
def combined_academic_levels():
    """Combine multiple academic levels into one group (curriculum coordinator / principal / technician)."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    if not (is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    connection = get_db_connection()
    if not connection:
        flash('Database connection failed.', 'error')
        return redirect(employee_dashboard_path())

    page_url = employee_dashboard_path('combined-academic-levels')

    if request.method == 'POST':
        combine_action = (request.form.get('combine_action') or '').strip().lower()
        if combine_action == 'delete':
            try:
                with connection.cursor() as cursor:
                    ensure_academic_level_combination_tables(cursor)
                    cid = request.form.get('combination_id', type=int)
                    if not cid:
                        flash('Missing combination.', 'error')
                    else:
                        cursor.execute(
                            "DELETE FROM academic_level_combination_members WHERE combination_id = %s",
                            (cid,),
                        )
                        cursor.execute(
                            "DELETE FROM academic_level_combinations WHERE id = %s",
                            (cid,),
                        )
                        connection.commit()
                        flash('Combined academic levels group removed.', 'success')
            except Exception as e:
                print(f"combined_academic_levels delete: {e}")
                try:
                    connection.rollback()
                except Exception:
                    pass
                flash('Could not remove combination.', 'error')
            finally:
                try:
                    connection.close()
                except Exception:
                    pass
            return redirect(page_url)

        if combine_action == 'create':
            try:
                with connection.cursor() as cursor:
                    ensure_academic_level_combination_tables(cursor)
                    raw_ids = request.form.getlist('level_pick')
                    level_order = []
                    seen = set()
                    for x in raw_ids:
                        try:
                            lid = int(x)
                            if lid not in seen:
                                seen.add(lid)
                                level_order.append(lid)
                        except (TypeError, ValueError):
                            continue
                    if len(level_order) < 2:
                        flash('Select at least two academic levels to combine.', 'error')
                        try:
                            connection.close()
                        except Exception:
                            pass
                        return redirect(page_url)
                    placeholders = ','.join(['%s'] * len(level_order))
                    cursor.execute(
                        f"""
                        SELECT id FROM academic_levels
                        WHERE id IN ({placeholders}) AND COALESCE(level_status, 'active') = 'active'
                        """,
                        tuple(level_order),
                    )
                    ok_active = {
                        int(r.get('id') if isinstance(r, dict) else r[0])
                        for r in (cursor.fetchall() or [])
                    }
                    level_order = [lid for lid in level_order if lid in ok_active]
                    if len(level_order) < 2:
                        flash('Need at least two active academic levels.', 'error')
                        try:
                            connection.close()
                        except Exception:
                            pass
                        return redirect(page_url)
                    cursor.execute(
                        f"""
                        SELECT academic_level_id FROM academic_level_combination_members
                        WHERE academic_level_id IN ({placeholders})
                        """,
                        tuple(level_order),
                    )
                    if cursor.fetchall():
                        flash(
                            'One or more selected levels are already part of another combination. '
                            'Remove that combination first.',
                            'error',
                        )
                        try:
                            connection.close()
                        except Exception:
                            pass
                        return redirect(page_url)
                    cursor.execute(
                        "INSERT INTO academic_level_combinations (created_at) VALUES (CURRENT_TIMESTAMP)"
                    )
                    combo_id = cursor.lastrowid
                    for order_idx, lid in enumerate(level_order):
                        cursor.execute(
                            """
                            INSERT INTO academic_level_combination_members
                                (combination_id, academic_level_id, sort_order)
                            VALUES (%s, %s, %s)
                            """,
                            (combo_id, lid, order_idx),
                        )
                    connection.commit()
                    flash('Academic levels combined successfully.', 'success')
            except Exception as e:
                print(f"combined_academic_levels create: {e}")
                try:
                    connection.rollback()
                except Exception:
                    pass
                flash('Could not save combination. Try again.', 'error')
            finally:
                try:
                    connection.close()
                except Exception:
                    pass
            return redirect(page_url)

    levels_by_category = []
    combinations_display = []
    member_level_ids = set()
    try:
        with connection.cursor() as cursor:
            ensure_academic_level_combination_tables(cursor)
            cursor.execute(
                """
                SELECT id, level_category, level_name, level_code
                FROM academic_levels
                WHERE COALESCE(level_status, 'active') = 'active'
                ORDER BY level_category ASC, level_name ASC
                """
            )
            level_rows = cursor.fetchall() or []
            by_cat = {}
            level_meta = {}
            for row in level_rows:
                lid = int(row.get('id') if isinstance(row, dict) else row[0])
                cat = (row.get('level_category') if isinstance(row, dict) else row[1]) or 'Uncategorized'
                name = (row.get('level_name') if isinstance(row, dict) else row[2]) or '—'
                code = (row.get('level_code') if isinstance(row, dict) else row[3]) or ''
                level_meta[lid] = {'level_name': name, 'level_code': code, 'level_category': cat}
                by_cat.setdefault(cat, []).append({
                    'id': lid,
                    'level_name': name,
                    'level_code': code,
                })
            levels_by_category = [
                {'category': cat, 'levels': lvls}
                for cat, lvls in sorted(by_cat.items(), key=lambda x: x[0].lower())
            ]
            combos = fetch_academic_level_combinations(cursor)
            for combo in combos:
                mids = combo.get('member_level_ids') or []
                for mid in mids:
                    member_level_ids.add(int(mid))
                names = [level_meta.get(mid, {}).get('level_name') or '—' for mid in mids]
                codes = [
                    (level_meta.get(mid, {}).get('level_code') or '').strip()
                    for mid in mids
                ]
                cats = list({
                    level_meta.get(mid, {}).get('level_category') or 'Uncategorized'
                    for mid in mids
                })
                combinations_display.append({
                    'id': combo['id'],
                    'label_name': ' / '.join(names),
                    'label_code': ' / '.join(c for c in codes if c) or '—',
                    'categories': ', '.join(sorted(cats)),
                    'member_count': len(mids),
                })
    except Exception as e:
        print(f"combined_academic_levels load: {e}")
        flash('Could not load academic levels.', 'error')
    finally:
        try:
            connection.close()
        except Exception:
            pass

    return render_template(
        'dashboards/combined_academic_levels.html',
        role=user_role,
        levels_by_category=levels_by_category,
        combinations_display=combinations_display,
        member_level_ids=member_level_ids,
    )


