# Save Exam Route
@app.route('/dashboard/employee/exam-evaluation/save', methods=['POST'])
@login_required
def save_exam():
    """Save a new exam with multiple subject allocations + supervisors"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    data = request.get_json() or {}

    try:
        exam_name = (data.get('exam_name') or '').strip().upper()
        exam_type = (data.get('exam_type') or '').strip().upper()
        academic_year_id = int(data.get('academic_year_id', 0))
        term_id = int(data.get('term_id', 0))
        allocations = data.get('allocations') or []
        auto_generate = bool(data.get('auto_generate'))
        share_timetable = bool(data.get('share_timetable'))
        share_groups_raw = data.get('share_groups')
        base_exam_date = (data.get('base_exam_date') or '').strip()
        exam_dates_raw = data.get('exam_dates')
        level_ids_raw = data.get('level_ids')
        session_types_raw = data.get('session_types')
        custom_session_raw = data.get('custom_session')
        default_venue = (data.get('default_venue') or '').strip().upper()
    except (ValueError, TypeError) as e:
        return jsonify({'success': False, 'message': f'Invalid data: {str(e)}'}), 400

    if not all([exam_name, exam_type, academic_year_id > 0, term_id > 0]):
        return jsonify({'success': False, 'message': 'Missing required fields'}), 400

    if not auto_generate:
        if not isinstance(allocations, list) or len(allocations) == 0:
            return jsonify({'success': False, 'message': 'Please add at least one subject allocation'}), 400
    else:
        if not base_exam_date:
            return jsonify({'success': False, 'message': 'Auto-register requires a base exam start date.'}), 400
        try:
            datetime.strptime(base_exam_date, '%Y-%m-%d')
        except ValueError:
            return jsonify({'success': False, 'message': 'Invalid base exam date. Use YYYY-MM-DD.'}), 400

        selected_exam_dates: list[str] = []
        if exam_dates_raw is not None:
            if not isinstance(exam_dates_raw, list):
                return jsonify({'success': False, 'message': 'Invalid exam_dates (must be a list).'}), 400
            for d in exam_dates_raw:
                ds = str(d or '').strip()
                if not ds:
                    continue
                try:
                    datetime.strptime(ds, '%Y-%m-%d')
                except ValueError:
                    return jsonify({'success': False, 'message': f'Invalid exam date: {ds}. Use YYYY-MM-DD.'}), 400
                selected_exam_dates.append(ds)
            selected_exam_dates = sorted(set(selected_exam_dates))
        if not selected_exam_dates:
            return jsonify({'success': False, 'message': 'Auto-register requires selecting exam dates from the calendar.'}), 400

    def _time_to_minutes(t: str) -> int | None:
        try:
            parts = str(t).strip().split(':')
            if len(parts) < 2:
                return None
            h = int(parts[0])
            m = int(parts[1])
            return h * 60 + m
        except Exception:
            return None

    def _minutes_to_time_str(total_minutes: int) -> str:
        total_minutes = total_minutes % (24 * 60)
        h = total_minutes // 60
        m = total_minutes % 60
        return f"{h:02d}:{m:02d}:00"

    def _calc_end(start_time_str: str, duration_min: int) -> str:
        start_min = _time_to_minutes(start_time_str)
        if start_min is None:
            raise ValueError("Invalid start time")
        return _minutes_to_time_str(start_min + duration_min)

    # Session presets (configurable via Exam timetable settings)
    session_presets = _default_exam_session_presets()
    _tmp_conn = None
    try:
        _tmp_conn = get_db_connection()
        if _tmp_conn:
            with _tmp_conn.cursor() as _c:
                session_presets = _load_exam_session_presets_from_db(_c)
    except Exception:
        session_presets = _default_exam_session_presets()
    finally:
        try:
            if _tmp_conn:
                _tmp_conn.close()
        except Exception:
            pass
    CANONICAL_SESSION_ORDER = ['MORNING', 'MIDDAY', 'AFTERNOON', 'EVENING', 'CUSTOM']
    SESSION_ORDER = CANONICAL_SESSION_ORDER

    if auto_generate:
        selected_sessions = []
        if session_types_raw is not None:
            if not isinstance(session_types_raw, list):
                return jsonify({'success': False, 'message': 'Invalid session_types (must be a list).'}), 400
            for s in session_types_raw:
                st = str(s or '').strip().upper()
                if st:
                    selected_sessions.append(st)
            selected_sessions = sorted(set(selected_sessions), key=lambda x: CANONICAL_SESSION_ORDER.index(x) if x in CANONICAL_SESSION_ORDER else 999)

        # Require explicit session selection in Auto mode
        if not selected_sessions:
            return jsonify({'success': False, 'message': 'Auto-register requires selecting at least one session to allocate.'}), 400

        # Handle CUSTOM session (same logic as manual mode: start_time + duration -> end_time)
        if 'CUSTOM' in selected_sessions:
            if not custom_session_raw or not isinstance(custom_session_raw, dict):
                return jsonify({'success': False, 'message': 'Custom session selected but custom_session details are missing.'}), 400
            start_time = str(custom_session_raw.get('start_time') or '').strip()
            try:
                duration_minutes = int(custom_session_raw.get('duration_minutes', 0))
            except (ValueError, TypeError):
                duration_minutes = 0
            if not start_time or duration_minutes <= 0:
                return jsonify({'success': False, 'message': 'Custom session requires start time and duration (minutes).'}), 400
            try:
                end_time_str = _calc_end(start_time, duration_minutes)
            except Exception:
                return jsonify({'success': False, 'message': 'Invalid custom session start time.'}), 400
            start_time_str = (start_time if len(start_time.split(':')) == 3 else f"{start_time}:00")
            session_presets['CUSTOM'] = (start_time_str, end_time_str)

        invalid = [s for s in selected_sessions if s not in session_presets]
        if invalid:
            return jsonify({'success': False, 'message': f"Invalid session type(s): {', '.join(invalid)}"}), 400

        SESSION_ORDER = [s for s in CANONICAL_SESSION_ORDER if s in selected_sessions]
        if not SESSION_ORDER:
            return jsonify({'success': False, 'message': 'Auto-register requires selecting at least one valid session to allocate.'}), 400

        # Validate sessions do not overlap (manual presets are non-overlapping; enforce same in auto)
        def _slot_range_minutes(st: str, et: str) -> tuple[int, int] | None:
            smin = _time_to_minutes(st)
            emin = _time_to_minutes(et)
            if smin is None or emin is None:
                return None
            if emin <= smin:
                emin += 24 * 60
            return (smin, emin)

        ranges = []
        for s in SESSION_ORDER:
            st, et = session_presets[s]
            r = _slot_range_minutes(st, et)
            if not r:
                return jsonify({'success': False, 'message': 'Invalid session time configuration.'}), 500
            ranges.append((s, r[0], r[1]))
        for i in range(len(ranges)):
            for j in range(i + 1, len(ranges)):
                a = ranges[i]
                b = ranges[j]
                if a[1] < b[2] and a[2] > b[1]:
                    return jsonify({
                        'success': False,
                        'message': f"Session times overlap between {a[0]} and {b[0]}. Please adjust Custom session time or unselect one session."
                    }), 400

    normalized_allocations = []
    seen_teacher_slots = []  # for within-request conflicts: list of (teacher_id, exam_date, start_min, end_min)
    seen_class_session_slots = set()  # (academic_level_id, exam_date, session_type)

    # Normalize + validate payload (manual mode only)
    for idx, a in enumerate(allocations if not auto_generate else []):
        try:
            academic_level_id = int(a.get('academic_level_id', 0))
            subject_id = int(a.get('subject_id', 0))
            teacher_id = int(a.get('teacher_id', 0))
            allocation_exam_date = a.get('exam_date', '').strip()
            session_type = (a.get('session_type') or '').strip().upper()
        except (ValueError, TypeError):
            return jsonify({'success': False, 'message': f'Invalid allocation row at #{idx + 1}'}), 400

        if academic_level_id <= 0 or subject_id <= 0 or teacher_id <= 0 or not allocation_exam_date or not session_type:
            return jsonify({'success': False, 'message': f'Missing fields in allocation row #{idx + 1} (need: level, subject, teacher, date, session)'}), 400

        if session_type == 'CUSTOM':
            start_time = (a.get('start_time') or '').strip()
            try:
                duration_minutes = int(a.get('duration_minutes', 0))
            except (ValueError, TypeError):
                duration_minutes = 0
            if not start_time or duration_minutes <= 0:
                return jsonify({'success': False, 'message': f'Custom session requires start time and duration in row #{idx + 1}'}), 400
            end_time = _calc_end(start_time, duration_minutes)
            start_time_str = (start_time if len(start_time.split(':')) == 3 else f"{start_time}:00")
            end_time_str = end_time
        else:
            if session_type not in session_presets:
                return jsonify({'success': False, 'message': f'Invalid session type in row #{idx + 1}'}), 400
            start_time_str, end_time_str = session_presets[session_type]
            # derive duration
            smin = _time_to_minutes(start_time_str)
            emin = _time_to_minutes(end_time_str)
            duration_minutes = (emin - smin) if (smin is not None and emin is not None) else None

        # Within-request teacher conflict check (overlap on same date)
        smin = _time_to_minutes(start_time_str)
        emin = _time_to_minutes(end_time_str)
        if smin is None or emin is None:
            return jsonify({'success': False, 'message': f'Invalid time values in row #{idx + 1}'}), 400

        # Handle wrap-around (treat as same-day range; if end <= start, consider it crosses midnight)
        if emin <= smin:
            emin += 24 * 60

        for (t_id, ed, os, oe) in seen_teacher_slots:
            if t_id == teacher_id and ed == allocation_exam_date and (smin < oe and emin > os):
                return jsonify({
                    'success': False,
                    'message': f"Teacher conflict in this submission: the same teacher is allocated to multiple exams at overlapping times on the same date (row #{idx + 1})."
                }), 400

        seen_teacher_slots.append((teacher_id, allocation_exam_date, smin, emin))

        venue = (a.get('venue') or '').strip().upper()
        
        # Enforce: one subject per class/session/day (within submission)
        slot_key = (int(academic_level_id), str(allocation_exam_date), str(session_type))
        if slot_key in seen_class_session_slots:
            return jsonify({
                'success': False,
                'message': f"Invalid allocation: a class can only have one subject per session per day. Duplicate session detected in row #{idx + 1}."
            }), 400
        seen_class_session_slots.add(slot_key)

        normalized_allocations.append({
            'academic_level_id': academic_level_id,
            'subject_id': subject_id,
            'teacher_id': teacher_id,
            'exam_date': allocation_exam_date,
            'venue': venue,
            'session_type': session_type,
            'start_time': start_time_str,
            'end_time': end_time_str,
            'duration_minutes': duration_minutes,
        })
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500
    
    try:
        employee_id = session.get('employee_id') or session.get('user_id')
        created_by = None
        if employee_id:
            with connection.cursor() as cursor:
                cursor.execute("SELECT id FROM employees WHERE id = %s", (employee_id,))
                emp = cursor.fetchone()
                if emp:
                    created_by = emp.get('id') if isinstance(emp, dict) else emp[0]
        
        with connection.cursor() as cursor:
            if auto_generate:
                import random
                from collections import defaultdict

                level_ids = []
                if level_ids_raw and isinstance(level_ids_raw, list):
                    try:
                        level_ids = sorted({int(x) for x in level_ids_raw if int(x) > 0})
                    except (ValueError, TypeError):
                        return jsonify({'success': False, 'message': 'Invalid level_ids.'}), 400
                if not level_ids:
                    cursor.execute("""
                        SELECT id FROM academic_levels
                        WHERE level_status = 'active'
                        ORDER BY level_category, level_name ASC
                    """)
                    level_ids = [r.get('id') if isinstance(r, dict) else r[0] for r in cursor.fetchall()]
                if not level_ids:
                    return jsonify({'success': False, 'message': 'No active academic levels found.'}), 400

                share_groups: list[list[int]] = []
                if share_timetable:
                    if share_groups_raw is None:
                        share_groups_raw = []
                    if not isinstance(share_groups_raw, list):
                        return jsonify({'success': False, 'message': 'Invalid share_groups (must be a list).'}), 400

                    level_set = set(int(x) for x in level_ids)
                    claimed = set()
                    for g in share_groups_raw:
                        if not isinstance(g, dict):
                            continue
                        raw_ids = g.get('level_ids')
                        if not isinstance(raw_ids, list):
                            continue
                        try:
                            ids = [int(x) for x in raw_ids if int(x) > 0]
                        except (ValueError, TypeError):
                            continue
                        # subset + unique membership (first group wins)
                        uniq = []
                        for lid in ids:
                            if lid not in level_set:
                                continue
                            if lid in claimed:
                                continue
                            claimed.add(lid)
                            uniq.append(int(lid))
                        if len(uniq) >= 2:
                            share_groups.append(sorted(uniq))

                ph = ','.join(['%s'] * len(level_ids))
                cursor.execute(f"""
                    SELECT id, level_category, level_name, level_code
                    FROM academic_levels
                    WHERE id IN ({ph})
                """, tuple(level_ids))
                level_venue_by_id = {}
                for r in cursor.fetchall():
                    lid = r.get('id') if isinstance(r, dict) else r[0]
                    lcat = (r.get('level_category') if isinstance(r, dict) else (r[1] if len(r) > 1 else '')) or ''
                    lname = (r.get('level_name') if isinstance(r, dict) else (r[2] if len(r) > 2 else '')) or ''
                    lcode = (r.get('level_code') if isinstance(r, dict) else (r[3] if len(r) > 3 else '')) or ''
                    code_u = str(lcode).strip().upper()
                    if code_u:
                        label = code_u
                    else:
                        parts = [p.strip() for p in (lcat, lname) if p and str(p).strip()]
                        label = ' '.join(parts).strip().upper()
                    level_venue_by_id[lid] = label if label else f'LEVEL {lid}'

                # One query: subject-class allocations for selected levels.
                # Only active subjects + active teacher employees are considered.
                cursor.execute(f"""
                    SELECT tsa.academic_level_id, tsa.subject_id, tsa.teacher_id, s.subject_name
                    FROM teacher_subject_assignments tsa
                    INNER JOIN subjects s ON s.id = tsa.subject_id AND s.status = 'active'
                    INNER JOIN academic_levels al ON al.id = tsa.academic_level_id AND al.level_status = 'active'
                    INNER JOIN employees emp ON emp.id = tsa.teacher_id
                        AND emp.status = 'active'
                        AND (emp.role = 'teachers' OR emp.role = 'teacher')
                    WHERE tsa.academic_level_id IN ({ph})
                """, tuple(level_ids))
                assign_rows = cursor.fetchall()

                # Build per-class subject list from allocations (subjects allocated to that class only).
                subjects_by_level = defaultdict(set)  # level_id -> {subject_id}
                subject_name_by_id = {}
                if assign_rows:
                    for row in assign_rows:
                        lid = row.get('academic_level_id') if isinstance(row, dict) else row[0]
                        sid = row.get('subject_id') if isinstance(row, dict) else row[1]
                        sname = row.get('subject_name', '') if isinstance(row, dict) else (row[3] if len(row) > 3 else '')
                        if lid and sid:
                            subjects_by_level[int(lid)].add(int(sid))
                            if sid not in subject_name_by_id and sname:
                                subject_name_by_id[int(sid)] = str(sname)

                # If some selected classes have no active allocated subjects, skip them and continue.
                missing_levels = [int(lid) for lid in level_ids if int(lid) not in subjects_by_level or not subjects_by_level[int(lid)]]
                if missing_levels:
                    level_ids = [int(lid) for lid in level_ids if int(lid) not in set(missing_levels)]
                    if not level_ids:
                        return jsonify({
                            'success': False,
                            'message': f"Auto-register requires subject allocations first. None of the selected classes have active allocated subjects. Missing class IDs: {', '.join(map(str, missing_levels))}."
                        }), 400
                    # If shared timetable was requested, re-filter share groups after skipping classes.
                    if share_timetable and share_groups:
                        lvl_ok = set(int(y) for y in level_ids)
                        share_groups = [sorted([int(x) for x in grp if int(x) in lvl_ok]) for grp in share_groups]
                        share_groups = [grp for grp in share_groups if len(grp) >= 2]

                # Load all active teachers once (fallback for missing allocations)
                cursor.execute("""
                    SELECT id
                    FROM employees
                    WHERE status = 'active' AND (role = 'teachers' OR role = 'teacher')
                    ORDER BY id ASC
                """)
                all_active_teacher_ids = [r.get('id') if isinstance(r, dict) else r[0] for r in (cursor.fetchall() or [])]
                all_active_teacher_ids = [int(x) for x in all_active_teacher_ids if x]
                if not all_active_teacher_ids:
                    return jsonify({'success': False, 'message': 'No active teachers found to supervise exams.'}), 400

                # Build mapping: excluded (allocated subject teachers) per (class, subject).
                # Rule: supervisor must NOT be the allocated subject teacher for that class/subject.
                excluded_by_ls = defaultdict(set)
                if assign_rows:
                    for row in assign_rows:
                        lid = row.get('academic_level_id') if isinstance(row, dict) else row[0]
                        sid = row.get('subject_id') if isinstance(row, dict) else row[1]
                        tid = row.get('teacher_id') if isinstance(row, dict) else row[2]
                        if lid and sid and tid:
                            excluded_by_ls[(int(lid), int(sid))].add(int(tid))

                # Candidates per (class, subject): any active teacher EXCEPT the allocated subject teacher(s).
                all_active_set = set(all_active_teacher_ids)
                candidate_by_ls = defaultdict(set)
                for lid in level_ids:
                    for sid in sorted(subjects_by_level.get(int(lid), set())):
                        key = (int(lid), int(sid))
                        excluded = excluded_by_ls.get(key) or set()
                        candidates = all_active_set.difference(set(excluded))
                        if not candidates:
                            subj_name = subject_name_by_id.get(sid) or f"Subject {sid}"
                            return jsonify({
                                'success': False,
                                'message': f'No eligible supervisors for {subj_name} in class {lid}: all active teachers are allocated to teach that subject.'
                            }), 400
                        candidate_by_ls[key] = set(candidates)

                # Build tasks (one per class/subject). Supervisor selection happens per-slot to avoid conflicts.
                # Shared timetable: only the share-group classes share one timetable pattern.
                task_list = []
                shared_class_ids = set()
                if share_timetable and share_groups:
                    for grp in share_groups:
                        shared_class_ids.update(int(x) for x in grp)
                        common = None
                        for lid in grp:
                            sset = set(subjects_by_level.get(int(lid), set()))
                            common = sset if common is None else common.intersection(sset)
                        common = sorted({int(x) for x in (common or set()) if x})
                        if not common:
                            return jsonify({
                                'success': False,
                                'message': 'Shared timetable group requires classes to have at least one common active allocated subject.'
                            }), 400
                        for sid in common:
                            for lid in grp:
                                task_list.append({'academic_level_id': int(lid), 'subject_id': int(sid)})

                # Normal scheduling tasks for the remaining selected levels
                for (lid, sid) in sorted(candidate_by_ls.keys(), key=lambda k: (k[0], k[1])):
                    if int(lid) in shared_class_ids:
                        continue
                    task_list.append({'academic_level_id': lid, 'subject_id': sid})
                if not task_list:
                    return jsonify({
                        'success': False,
                        'message': 'No valid class/subject/teacher combinations after resolving allocations.'
                    }), 400

                # Schedule dates: user-selected calendar days (validated client-side too)
                schedule_dates: list[str] = selected_exam_dates[:]

                normalized_allocations.clear()
                seen_teacher_slots.clear()
                seen_class_session_slots.clear()

                # Enforce: each class has at most one subject per session per day.
                # Greedy schedule per class: for each class, fill sessions across selected days.
                next_slot_index_by_level = defaultdict(int)  # academic_level_id -> next slot idx across (days*sessions)

                # Sort tasks by class then subject for deterministic schedules
                task_list_sorted = sorted(task_list, key=lambda t: (int(t['academic_level_id']), int(t['subject_id'])))

                def _teacher_conflicts(tid: int, ed: str, s: int, e: int) -> bool:
                    for (t_id, day, os, oe) in seen_teacher_slots:
                        if int(t_id) == int(tid) and str(day) == str(ed) and (s < oe and e > os):
                            return True
                    return False

                if share_timetable and share_groups:
                    # Shared timetable mode (clusters): each group has its own shared pattern.
                    total_slots = len(schedule_dates) * len(SESSION_ORDER)
                    for grp in share_groups:
                        grp_set = set(int(x) for x in grp)
                        common_subjects = sorted({int(t['subject_id']) for t in task_list_sorted if int(t['academic_level_id']) in grp_set})
                        if len(common_subjects) > total_slots:
                            return jsonify({
                                'success': False,
                                'message': 'Not enough selected exam days/sessions to schedule all common subjects for one of the shared timetable groups.'
                            }), 400

                        for subj_idx, subject_id in enumerate(common_subjects):
                            day_offset = subj_idx // len(SESSION_ORDER)
                            sess_idx = subj_idx % len(SESSION_ORDER)
                            session_type = SESSION_ORDER[sess_idx]
                            allocation_exam_date = schedule_dates[day_offset]
                            start_time_str, end_time_str = session_presets[session_type]
                            smin = _time_to_minutes(start_time_str)
                            emin = _time_to_minutes(end_time_str)
                            if smin is None or emin is None:
                                return jsonify({'success': False, 'message': 'Invalid session preset times.'}), 500
                            if emin <= smin:
                                emin += 24 * 60

                            used_in_slot = set()
                            for level_id in grp:
                                class_slot_key = (int(level_id), allocation_exam_date, session_type)
                                if class_slot_key in seen_class_session_slots:
                                    return jsonify({
                                        'success': False,
                                        'message': 'Internal error: duplicate class slot while building shared timetable.'
                                    }), 500

                                candidates = sorted({int(x) for x in (candidate_by_ls.get((int(level_id), int(subject_id))) or set()) if x})
                                free_candidates = [
                                    tid for tid in candidates
                                    if tid not in used_in_slot and not _teacher_conflicts(tid, allocation_exam_date, smin, emin)
                                ]
                                if not free_candidates:
                                    return jsonify({
                                        'success': False,
                                        'message': 'Shared timetable requires enough available supervisors. Not enough distinct supervisors for one or more slots; try adding more teachers or selecting more days/sessions.'
                                    }), 400

                                teacher_id = random.choice(free_candidates)
                                used_in_slot.add(int(teacher_id))
                                seen_class_session_slots.add(class_slot_key)
                                seen_teacher_slots.append((int(teacher_id), allocation_exam_date, smin, emin))

                                smin_dur = _time_to_minutes(start_time_str)
                                emin_dur = _time_to_minutes(end_time_str)
                                duration_minutes = (emin_dur - smin_dur) if (
                                    smin_dur is not None and emin_dur is not None and emin_dur > smin_dur
                                ) else None

                                normalized_allocations.append({
                                    'academic_level_id': int(level_id),
                                    'subject_id': int(subject_id),
                                    'teacher_id': int(teacher_id),
                                    'exam_date': allocation_exam_date,
                                    'venue': level_venue_by_id.get(
                                        int(level_id),
                                        (default_venue or '').strip().upper() or f'LEVEL {int(level_id)}'
                                    ),
                                    'session_type': session_type,
                                    'start_time': start_time_str,
                                    'end_time': end_time_str,
                                    'duration_minutes': duration_minutes,
                                })
                # Always schedule non-shared levels using normal logic
                non_shared_levels = [int(lid) for lid in level_ids if int(lid) not in shared_class_ids]
                if non_shared_levels:
                    total_slots_per_level = len(schedule_dates) * len(SESSION_ORDER)
                    for task in task_list_sorted:
                        level_id = int(task['academic_level_id'])
                        if level_id not in set(non_shared_levels):
                            continue
                        subject_id = int(task['subject_id'])
                        candidates = sorted({int(x) for x in (candidate_by_ls.get((level_id, subject_id)) or set()) if x})
                        if not candidates:
                            return jsonify({
                                'success': False,
                                'message': 'No eligible supervisors found for one or more class/subject pairs.'
                            }), 400

                        placed = False
                        attempts = 0
                        # Try successive slots for this class until we find a free eligible supervisor.
                        while not placed and attempts < total_slots_per_level:
                            attempts += 1
                            slot_idx = next_slot_index_by_level[level_id]
                            day_offset = slot_idx // len(SESSION_ORDER)
                            sess_idx = slot_idx % len(SESSION_ORDER)
                            if day_offset >= len(schedule_dates):
                                break
                            session_type = SESSION_ORDER[sess_idx]
                            allocation_exam_date = schedule_dates[day_offset]
                            key = (level_id, allocation_exam_date, session_type)
                            next_slot_index_by_level[level_id] += 1
                            if key in seen_class_session_slots:
                                continue

                            start_time_str, end_time_str = session_presets[session_type]
                            smin = _time_to_minutes(start_time_str)
                            emin = _time_to_minutes(end_time_str)
                            if smin is None or emin is None:
                                return jsonify({'success': False, 'message': 'Invalid session preset times.'}), 500
                            if emin <= smin:
                                emin += 24 * 60

                            free_candidates = [tid for tid in candidates if not _teacher_conflicts(tid, allocation_exam_date, smin, emin)]
                            if not free_candidates:
                                # Slot exists but no eligible supervisors are free; try the next slot for this class.
                                continue

                            teacher_id = random.choice(free_candidates)
                            seen_class_session_slots.add(key)
                            seen_teacher_slots.append((teacher_id, allocation_exam_date, smin, emin))
                            placed = True

                        smin_dur = _time_to_minutes(start_time_str)
                        emin_dur = _time_to_minutes(end_time_str)
                        duration_minutes = (emin_dur - smin_dur) if (
                            smin_dur is not None and emin_dur is not None and emin_dur > smin_dur
                        ) else None

                        if not placed:
                            return jsonify({
                                'success': False,
                                'message': 'Could not auto-schedule without supervisor conflicts. Try selecting more exam days or fewer sessions.'
                            }), 400

                        normalized_allocations.append({
                            'academic_level_id': level_id,
                            'subject_id': subject_id,
                            'teacher_id': int(teacher_id),
                            'exam_date': allocation_exam_date,
                            'venue': level_venue_by_id.get(
                                level_id,
                                (default_venue or '').strip().upper() or f'LEVEL {level_id}'
                            ),
                            'session_type': session_type,
                            'start_time': start_time_str,
                            'end_time': end_time_str,
                            'duration_minutes': duration_minutes,
                        })

            if not normalized_allocations:
                return jsonify({'success': False, 'message': 'No allocations to save.'}), 400

            # Validate teacher IDs exist and are active teachers
            teacher_ids = list({na['teacher_id'] for na in normalized_allocations})
            if teacher_ids:
                placeholders = ",".join(["%s"] * len(teacher_ids))
                cursor.execute(f"""
                    SELECT id FROM employees
                    WHERE id IN ({placeholders}) AND status = 'active' AND (role = 'teachers' OR role = 'teacher')
                """, tuple(teacher_ids))
                valid_teacher_ids = { (r.get('id') if isinstance(r, dict) else r[0]) for r in cursor.fetchall() }
                invalid = [tid for tid in teacher_ids if tid not in valid_teacher_ids]
                if invalid:
                    return jsonify({'success': False, 'message': 'One or more selected teachers are invalid or inactive'}), 400

            # Rule: supervisor must not be the allocated subject teacher for that class/subject.
            # Load exclusions for the involved (level, subject) pairs once.
            pairs = {(int(na['academic_level_id']), int(na['subject_id'])) for na in normalized_allocations}
            excluded_by_pair = {}
            if pairs:
                level_ids = sorted({p[0] for p in pairs})
                subj_ids = sorted({p[1] for p in pairs})
                ph_l = ",".join(["%s"] * len(level_ids))
                ph_s = ",".join(["%s"] * len(subj_ids))
                cursor.execute(f"""
                    SELECT tsa.academic_level_id, tsa.subject_id, tsa.teacher_id
                    FROM teacher_subject_assignments tsa
                    INNER JOIN employees emp ON emp.id = tsa.teacher_id
                      AND emp.status = 'active'
                      AND (emp.role = 'teachers' OR emp.role = 'teacher')
                    WHERE tsa.academic_level_id IN ({ph_l})
                      AND tsa.subject_id IN ({ph_s})
                """, tuple(level_ids + subj_ids))
                for r in cursor.fetchall() or []:
                    lid = r.get('academic_level_id') if isinstance(r, dict) else r[0]
                    sid = r.get('subject_id') if isinstance(r, dict) else r[1]
                    tid = r.get('teacher_id') if isinstance(r, dict) else r[2]
                    if lid and sid and tid:
                        excluded_by_pair.setdefault((int(lid), int(sid)), set()).add(int(tid))

            for na in normalized_allocations:
                key = (int(na['academic_level_id']), int(na['subject_id']))
                excluded = excluded_by_pair.get(key) or set()
                if excluded and int(na['teacher_id']) in excluded:
                    return jsonify({
                        'success': False,
                        'message': 'Invalid supervisor: the selected teacher is currently allocated to teach that subject in that class. Pick a different active teacher to supervise.'
                    }), 400

            cursor.execute("""
                SELECT id FROM exams
                WHERE exam_name = %s AND academic_year_id = %s AND term_id = %s AND COALESCE(is_locked, 0) = 1
                LIMIT 1
            """, (exam_name, academic_year_id, term_id))
            if cursor.fetchone():
                return jsonify({
                    'success': False,
                    'message': 'This exam is locked. Unlock it on the Registered Exam Allocations list before adding allocations.'
                }), 400

            # For each allocation: ensure no DB conflicts + insert row
            inserted_ids = []

            # Default venue to Academic Level label when missing
            level_label_by_id = {}
            try:
                level_ids_for_venue = sorted({int(na.get('academic_level_id') or 0) for na in normalized_allocations if int(na.get('academic_level_id') or 0) > 0})
                if level_ids_for_venue:
                    ph = ",".join(["%s"] * len(level_ids_for_venue))
                    cursor.execute(f"""
                        SELECT id, level_category, level_name, level_code
                        FROM academic_levels
                        WHERE id IN ({ph})
                    """, tuple(level_ids_for_venue))
                    for r in cursor.fetchall() or []:
                        lid = r.get('id') if isinstance(r, dict) else r[0]
                        lcat = (r.get('level_category') if isinstance(r, dict) else (r[1] if len(r) > 1 else '')) or ''
                        lname = (r.get('level_name') if isinstance(r, dict) else (r[2] if len(r) > 2 else '')) or ''
                        lcode = (r.get('level_code') if isinstance(r, dict) else (r[3] if len(r) > 3 else '')) or ''
                        code_u = str(lcode).strip().upper()
                        if code_u:
                            label = code_u
                        else:
                            parts = [p.strip() for p in (lcat, lname) if p and str(p).strip()]
                            label = ' '.join(parts).strip().upper()
                        if lid:
                            level_label_by_id[int(lid)] = label if label else f"LEVEL {int(lid)}"
            except Exception:
                level_label_by_id = {}

            for na in normalized_allocations:
                allocation_exam_date = na['exam_date']

                # Enforce: one subject per class/session/day (against DB)
                cursor.execute("""
                    SELECT id FROM exams
                    WHERE academic_level_id = %s AND exam_date = %s AND session_type = %s
                    LIMIT 1
                """, (na['academic_level_id'], allocation_exam_date, na['session_type']))
                if cursor.fetchone():
                    return jsonify({
                        'success': False,
                        'message': 'Invalid allocation: this class already has a subject scheduled for that session on that day.'
                    }), 400
                
                # Prevent duplicates for the same exam/level/subject/date
                cursor.execute("""
                    SELECT id FROM exams
                    WHERE exam_name = %s AND exam_date = %s AND academic_level_id = %s AND subject_id = %s
                    LIMIT 1
                """, (exam_name, allocation_exam_date, na['academic_level_id'], na['subject_id']))
                if cursor.fetchone():
                    return jsonify({
                        'success': False,
                        'message': 'Duplicate allocation detected: this subject is already registered for that exam name and academic level on this date.'
                    }), 400

                # Teacher time conflict against existing exams on same date (overlap)
                cursor.execute("""
                    SELECT id, exam_name, academic_level_id, subject_id, start_time, end_time
                    FROM exams
                    WHERE supervisor_id = %s AND exam_date = %s
                      AND start_time IS NOT NULL AND end_time IS NOT NULL
                      AND (start_time < %s AND end_time > %s)
                    LIMIT 1
                """, (na['teacher_id'], allocation_exam_date, na['end_time'], na['start_time']))
                conflict = cursor.fetchone()
                if conflict:
                    conflict_exam_name = conflict.get('exam_name') if isinstance(conflict, dict) else conflict[1]
                    return jsonify({
                        'success': False,
                        'message': f"Teacher conflict: selected teacher already has an exam at this time on {allocation_exam_date} (existing exam: {conflict_exam_name})."
                    }), 400

                cursor.execute("""
                    INSERT INTO exams (
                        exam_name, exam_type, academic_year_id, term_id,
                        academic_level_id, subject_id, exam_date, session_type,
                        start_time, end_time, duration_minutes, supervisor_id,
                        venue, created_by
                    )
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """, (
                    exam_name,
                    exam_type,
                    academic_year_id,
                    term_id,
                    na['academic_level_id'],
                    na['subject_id'],
                    allocation_exam_date,
                    na['session_type'],
                    na['start_time'],
                    na['end_time'],
                    na['duration_minutes'],
                    na['teacher_id'],
                    (str(na.get('venue') or '').strip().upper() or level_label_by_id.get(int(na.get('academic_level_id') or 0), f"LEVEL {int(na.get('academic_level_id') or 0)}")),
                    created_by
                ))
                inserted_ids.append(cursor.lastrowid)

            connection.commit()
            return jsonify({
                'success': True,
                'message': f'Exam registered successfully with {len(inserted_ids)} allocation(s)',
                'exam_ids': inserted_ids
            })
            
    except Exception as e:
        print(f"Error saving exam: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Error saving exam: {str(e)}'}), 500
    finally:
        if connection:
            connection.close()


# Update Exam Route
@app.route('/dashboard/employee/exam-evaluation/update', methods=['POST'])
@login_required
def update_exam():
    """Update an existing exam allocation row (one row per subject/teacher/time)."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    try:
        exam_id = int(data.get('exam_id', 0))
        academic_level_id = int(data.get('academic_level_id', 0))
        subject_id = int(data.get('subject_id', 0))
        supervisor_id = int(data.get('supervisor_id', 0))
        exam_date = (data.get('exam_date') or '').strip()
        venue = (data.get('venue') or '').strip().upper()
        session_type = (data.get('session_type') or '').strip().upper()
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid data'}), 400

    if not all([exam_id > 0, academic_level_id > 0, subject_id > 0, supervisor_id > 0, exam_date, session_type]):
        return jsonify({'success': False, 'message': 'Missing required fields'}), 400

    # Session presets (keep in sync with save_exam; configurable)
    session_presets = _default_exam_session_presets()
    _tmp_conn = None
    try:
        _tmp_conn = get_db_connection()
        if _tmp_conn:
            with _tmp_conn.cursor() as _c:
                session_presets = _load_exam_session_presets_from_db(_c)
    except Exception:
        session_presets = _default_exam_session_presets()
    finally:
        try:
            if _tmp_conn:
                _tmp_conn.close()
        except Exception:
            pass

    def _time_to_minutes(t: str) -> int | None:
        try:
            parts = str(t).strip().split(':')
            if len(parts) < 2:
                return None
            h = int(parts[0])
            m = int(parts[1])
            return h * 60 + m
        except Exception:
            return None

    def _minutes_to_time_str(total_minutes: int) -> str:
        total_minutes = total_minutes % (24 * 60)
        h = total_minutes // 60
        m = total_minutes % 60
        return f"{h:02d}:{m:02d}:00"

    def _calc_end(start_time_str: str, duration_min: int) -> str:
        start_min = _time_to_minutes(start_time_str)
        if start_min is None:
            raise ValueError("Invalid start time")
        return _minutes_to_time_str(start_min + duration_min)

    # Normalize time fields
    if session_type == 'CUSTOM':
        start_time = (data.get('start_time') or '').strip()
        try:
            duration_minutes = int(data.get('duration_minutes', 0))
        except (ValueError, TypeError):
            duration_minutes = 0
        if not start_time or duration_minutes <= 0:
            return jsonify({'success': False, 'message': 'Custom session requires start time and duration'}), 400
        end_time = _calc_end(start_time, duration_minutes)
        start_time_str = (start_time if len(start_time.split(':')) == 3 else f"{start_time}:00")
        end_time_str = end_time
    else:
        if session_type not in session_presets:
            return jsonify({'success': False, 'message': 'Invalid session type'}), 400
        start_time_str, end_time_str = session_presets[session_type]
        smin = _time_to_minutes(start_time_str)
        emin = _time_to_minutes(end_time_str)
        duration_minutes = (emin - smin) if (smin is not None and emin is not None) else None

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            # Verify exam exists
            cursor.execute("SELECT id, COALESCE(is_locked, 0) AS il FROM exams WHERE id = %s", (exam_id,))
            ex = cursor.fetchone()
            if not ex:
                return jsonify({'success': False, 'message': 'Exam not found'}), 404
            il = ex.get('il') if isinstance(ex, dict) else ex[1]
            if il:
                return jsonify({'success': False, 'message': 'This exam is locked and cannot be edited. Unlock it first.'}), 400

            cursor.execute("""
                SELECT id FROM employees
                WHERE id = %s AND status = 'active' AND (role = 'teachers' OR role = 'teacher')
            """, (supervisor_id,))
            if not cursor.fetchone():
                return jsonify({
                    'success': False,
                    'message': 'Supervisor must be an active employee with role Teacher.'
                }), 400

            # Rule: supervisor must not be the allocated subject teacher for that class/subject.
            cursor.execute("""
                SELECT 1
                FROM teacher_subject_assignments tsa
                INNER JOIN employees emp ON emp.id = tsa.teacher_id
                  AND emp.status = 'active'
                  AND (emp.role = 'teachers' OR emp.role = 'teacher')
                WHERE tsa.academic_level_id = %s
                  AND tsa.subject_id = %s
                  AND tsa.teacher_id = %s
                LIMIT 1
            """, (academic_level_id, subject_id, supervisor_id))
            if cursor.fetchone():
                return jsonify({
                    'success': False,
                    'message': 'Invalid supervisor: the selected teacher is allocated to teach that subject in that class. Choose a different active teacher to supervise.'
                }), 400

            # Enforce: one subject per class/session/day (exclude this row)
            cursor.execute("""
                SELECT id FROM exams
                WHERE academic_level_id = %s AND exam_date = %s AND session_type = %s AND id != %s
                LIMIT 1
            """, (academic_level_id, exam_date, session_type, exam_id))
            if cursor.fetchone():
                return jsonify({
                    'success': False,
                    'message': 'Invalid allocation: this class already has a subject scheduled for that session on that day.'
                }), 400

            # Teacher conflict on same date (overlap) excluding this exam row
            cursor.execute("""
                SELECT id, exam_name
                FROM exams
                WHERE supervisor_id = %s AND exam_date = %s AND id != %s
                  AND start_time IS NOT NULL AND end_time IS NOT NULL
                  AND (start_time < %s AND end_time > %s)
                LIMIT 1
            """, (supervisor_id, exam_date, exam_id, end_time_str, start_time_str))
            conflict = cursor.fetchone()
            if conflict:
                conflict_exam_name = conflict.get('exam_name') if isinstance(conflict, dict) else conflict[1]
                return jsonify({
                    'success': False,
                    'message': f"Teacher conflict: selected teacher already has an exam at this time on {exam_date} (existing exam: {conflict_exam_name})."
                }), 400

            cursor.execute("""
                UPDATE exams SET
                    academic_level_id = %s,
                    subject_id = %s,
                    supervisor_id = %s,
                    exam_date = %s,
                    venue = %s,
                    session_type = %s,
                    start_time = %s,
                    end_time = %s,
                    duration_minutes = %s
                WHERE id = %s
            """, (
                academic_level_id,
                subject_id,
                supervisor_id,
                exam_date,
                venue if venue else None,
                session_type,
                start_time_str,
                end_time_str,
                duration_minutes,
                exam_id
            ))
            connection.commit()
            return jsonify({'success': True, 'message': 'Exam updated successfully'})
    except Exception as e:
        print(f"Error updating exam: {e}")
        import traceback
        traceback.print_exc()
        try:
            connection.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'message': f'Error updating exam: {str(e)}'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/exam-evaluation/eligible-supervisors', methods=['POST'])
@login_required
def exam_evaluation_eligible_supervisors():
    """Return teachers free for this slot vs those busy elsewhere, with overlap details for UX."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    try:
        exam_id = int(data.get('exam_id', 0))
        exam_date = (data.get('exam_date') or '').strip()
        session_type = (data.get('session_type') or '').strip().upper()
        academic_level_id = int(data.get('academic_level_id', 0) or 0)
        subject_id = int(data.get('subject_id', 0) or 0)
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid data'}), 400

    if exam_id <= 0 or not exam_date or not session_type:
        return jsonify({'success': False, 'message': 'Missing exam, date, or session'}), 400

    session_presets = _default_exam_session_presets()
    _tmp_conn = None
    try:
        _tmp_conn = get_db_connection()
        if _tmp_conn:
            with _tmp_conn.cursor() as _c:
                session_presets = _load_exam_session_presets_from_db(_c)
    except Exception:
        session_presets = _default_exam_session_presets()
    finally:
        try:
            if _tmp_conn:
                _tmp_conn.close()
        except Exception:
            pass

    def _time_to_minutes(t: str) -> int | None:
        try:
            parts = str(t).strip().split(':')
            if len(parts) < 2:
                return None
            return int(parts[0]) * 60 + int(parts[1])
        except Exception:
            return None

    def _minutes_to_time_str(total_minutes: int) -> str:
        total_minutes = total_minutes % (24 * 60)
        return f"{total_minutes // 60:02d}:{total_minutes % 60:02d}:00"

    def _calc_end(start_time_str: str, duration_min: int) -> str:
        sm = _time_to_minutes(start_time_str)
        if sm is None:
            raise ValueError('Invalid start time')
        return _minutes_to_time_str(sm + duration_min)

    try:
        if session_type == 'CUSTOM':
            start_time = (data.get('start_time') or '').strip()
            try:
                duration_minutes = int(data.get('duration_minutes', 0))
            except (ValueError, TypeError):
                duration_minutes = 0
            if not start_time or duration_minutes <= 0:
                return jsonify({'success': False, 'message': 'Custom session requires start time and duration'}), 400
            end_time = _calc_end(start_time, duration_minutes)
            start_time_str = start_time if len(start_time.split(':')) == 3 else f"{start_time}:00"
            end_time_str = end_time
        else:
            if session_type not in session_presets:
                return jsonify({'success': False, 'message': 'Invalid session type'}), 400
            start_time_str, end_time_str = session_presets[session_type]
    except ValueError:
        return jsonify({'success': False, 'message': 'Invalid time values'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                SELECT id FROM exams WHERE id = %s LIMIT 1
            """, (exam_id,))
            if not cursor.fetchone():
                return jsonify({'success': False, 'message': 'Exam not found'}), 404

            def _normalize_time_mysql(val):
                if val is None:
                    return None
                if isinstance(val, timedelta):
                    secs = int(val.total_seconds())
                    secs = secs % (24 * 3600)
                    mm = secs // 60
                    return f"{mm // 60:02d}:{mm % 60:02d}"
                if hasattr(val, 'strftime'):
                    return val.strftime('%H:%M')
                s = str(val).strip()
                parts = s.split(':')
                if len(parts) >= 2:
                    try:
                        return f"{int(parts[0]):02d}:{int(parts[1]):02d}"
                    except (ValueError, TypeError):
                        pass
                return s[:5] if s else ''

            cursor.execute("""
                SELECT id, exam_name, exam_date, start_time, end_time, supervisor_id
                FROM exams
                WHERE exam_date = %s
                  AND id != %s
                  AND supervisor_id IS NOT NULL
                  AND start_time IS NOT NULL
                  AND end_time IS NOT NULL
                  AND (start_time < %s AND end_time > %s)
                ORDER BY supervisor_id ASC, start_time ASC, id ASC
            """, (exam_date, exam_id, end_time_str, start_time_str))
            conflicts_by_supervisor = {}
            busy_ids = set()
            for r in cursor.fetchall() or []:
                row_id = r.get('id') if isinstance(r, dict) else r[0]
                exname = r.get('exam_name', '') if isinstance(r, dict) else r[1]
                ed = r.get('exam_date') if isinstance(r, dict) else r[2]
                st_raw = r.get('start_time') if isinstance(r, dict) else r[3]
                en_raw = r.get('end_time') if isinstance(r, dict) else r[4]
                sid_val = r.get('supervisor_id') if isinstance(r, dict) else r[5]
                if sid_val is None:
                    continue
                sid_i = int(sid_val)
                busy_ids.add(sid_i)
                if hasattr(ed, 'strftime'):
                    ed_str = ed.strftime('%Y-%m-%d')
                elif ed:
                    ed_str = str(ed)[:10]
                else:
                    ed_str = str(exam_date)
                conflicts_by_supervisor.setdefault(sid_i, []).append({
                    'exam_id': int(row_id) if row_id is not None else None,
                    'exam_name': str(exname or ''),
                    'exam_date': ed_str,
                    'start_time': _normalize_time_mysql(st_raw) or '',
                    'end_time': _normalize_time_mysql(en_raw) or '',
                })

            # Exclude allocated subject teacher(s) for the class/subject (optional inputs)
            excluded_ids = set()
            if academic_level_id > 0 and subject_id > 0:
                cursor.execute("""
                    SELECT tsa.teacher_id
                    FROM teacher_subject_assignments tsa
                    INNER JOIN employees emp ON emp.id = tsa.teacher_id
                      AND emp.status = 'active'
                      AND (emp.role = 'teachers' OR emp.role = 'teacher')
                    WHERE tsa.academic_level_id = %s AND tsa.subject_id = %s
                """, (academic_level_id, subject_id))
                for r in cursor.fetchall() or []:
                    tid = r.get('teacher_id') if isinstance(r, dict) else r[0]
                    if tid is not None:
                        excluded_ids.add(int(tid))

            # If excluded IDs are also busy, remove them so they don't appear in UI lists.
            if excluded_ids:
                busy_ids.difference_update(excluded_ids)
                for tid in list(conflicts_by_supervisor.keys()):
                    if int(tid) in excluded_ids:
                        del conflicts_by_supervisor[int(tid)]

            cursor.execute("""
                SELECT id FROM employees
                WHERE status = 'active'
                  AND (role = 'teachers' OR role = 'teacher')
                ORDER BY full_name ASC, id ASC
            """)
            eligible = []
            for r in cursor.fetchall() or []:
                tid = r.get('id') if isinstance(r, dict) else r[0]
                if tid is None:
                    continue
                tid = int(tid)
                if tid in excluded_ids:
                    continue
                if tid in busy_ids:
                    continue
                eligible.append(tid)

            eligible = sorted(set(eligible))
            conflicts_json = {
                str(int(k)): v for k, v in sorted(conflicts_by_supervisor.items(), key=lambda x: x[0])
            }

            return jsonify({
                'success': True,
                'eligible_ids': eligible,
                'busy_supervisor_ids': sorted(busy_ids),
                'conflicts_by_supervisor_id': conflicts_json,
                'slot_window_start': start_time_str,
                'slot_window_end': end_time_str,
                'exam_date': exam_date,
            })
    except Exception as e:
        print(f"Error eligible supervisors: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': str(e)}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/exam-evaluation/allocation-options', methods=['POST'])
@login_required
def exam_evaluation_allocation_options():
    """Return subjects and teacher mappings for one academic level."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    try:
        level_id = int(data.get('academic_level_id', 0))
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid academic level'}), 400

    if level_id <= 0:
        return jsonify({'success': False, 'message': 'Academic level is required'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                SELECT id, level_name
                FROM academic_levels
                WHERE id = %s
                LIMIT 1
            """, (level_id,))
            lvl = cursor.fetchone()
            if not lvl:
                return jsonify({'success': False, 'message': 'Academic level not found'}), 404

            level_name = lvl.get('level_name', '') if isinstance(lvl, dict) else (lvl[1] if len(lvl) > 1 else '')

            cursor.execute(f"""
                SELECT DISTINCT
                    s.id AS subject_id,
                    s.subject_name,
                    s.subject_code,
                    e.id AS teacher_id,
                    e.full_name,
                    {_employee_staff_identity_sql('e')} AS employee_id
                FROM teacher_subject_assignments tsa
                INNER JOIN subjects s ON s.id = tsa.subject_id
                INNER JOIN employees e ON e.id = tsa.teacher_id
                WHERE tsa.academic_level_id = %s
                  AND COALESCE(s.status, 'active') = 'active'
                  AND e.status = 'active'
                  AND (e.role = 'teachers' OR e.role = 'teacher')
                ORDER BY s.subject_name ASC, e.full_name ASC
            """, (level_id,))
            rows = cursor.fetchall() or []

            subjects = []
            subject_seen = set()
            assigned_teachers_by_subject = {}
            for r in rows:
                subject_id = r.get('subject_id') if isinstance(r, dict) else r[0]
                subject_name = r.get('subject_name', '') if isinstance(r, dict) else (r[1] if len(r) > 1 else '')
                subject_code = r.get('subject_code', '') if isinstance(r, dict) else (r[2] if len(r) > 2 else '')
                teacher_id = r.get('teacher_id') if isinstance(r, dict) else (r[3] if len(r) > 3 else None)
                full_name = r.get('full_name', '') if isinstance(r, dict) else (r[4] if len(r) > 4 else '')
                employee_id = r.get('employee_id', '') if isinstance(r, dict) else (r[5] if len(r) > 5 else '')

                if subject_id and subject_id not in subject_seen:
                    subject_seen.add(subject_id)
                    subjects.append({
                        'id': int(subject_id),
                        'subject_name': subject_name or '',
                        'subject_code': subject_code or '',
                    })

                if subject_id and teacher_id:
                    key = str(int(subject_id))
                    assigned_teachers_by_subject.setdefault(key, [])
                    assigned_teachers_by_subject[key].append({
                        'id': int(teacher_id),
                        'full_name': full_name or '',
                        'employee_id': employee_id or '',
                    })

            # Supervisor options: all active teachers EXCEPT allocated subject teachers for this class/subject
            cursor.execute(f"""
                SELECT e.id AS teacher_id, e.full_name, {_employee_staff_identity_sql('e')} AS employee_id
                FROM employees e
                WHERE e.status = 'active' AND (e.role = 'teachers' OR e.role = 'teacher')
                ORDER BY e.full_name ASC, e.id ASC
            """)
            all_active_teachers = [{
                'id': int((r.get('teacher_id') if isinstance(r, dict) else r[0])),
                'full_name': (r.get('full_name', '') if isinstance(r, dict) else (r[1] if len(r) > 1 else '')) or '',
                'employee_id': (r.get('employee_id', '') if isinstance(r, dict) else (r[2] if len(r) > 2 else '')) or '',
            } for r in (cursor.fetchall() or []) if (r.get('teacher_id') if isinstance(r, dict) else r[0]) is not None]
            all_ids = [t['id'] for t in all_active_teachers]
            all_ids_set = set(all_ids)

            excluded_ids_by_subject = {}
            supervisors_by_subject = {}
            for s in subjects:
                sid = str(int(s['id']))
                excluded = {int(t['id']) for t in (assigned_teachers_by_subject.get(sid) or []) if t.get('id') is not None}
                excluded_ids_by_subject[sid] = sorted(excluded)
                elig_ids = all_ids_set.difference(excluded)
                supervisors_by_subject[sid] = [t for t in all_active_teachers if int(t['id']) in elig_ids]

            return jsonify({
                'success': True,
                'level_name': level_name or '',
                'subjects': subjects,
                # Back-compat + clarity:
                # - assigned_teachers_by_subject: the actual allocated subject teachers for this class
                # - supervisors_by_subject: eligible exam supervisors (active teachers excluding allocated ones)
                'teachers_by_subject': assigned_teachers_by_subject,
                'assigned_teachers_by_subject': assigned_teachers_by_subject,
                'excluded_teacher_ids_by_subject': excluded_ids_by_subject,
                'supervisors_by_subject': supervisors_by_subject,
            })
    except Exception as e:
        print(f"Error allocation options: {e}")
        return jsonify({'success': False, 'message': 'Could not load allocation options'}), 500
    finally:
        connection.close()


# Delete Exam Route
@app.route('/dashboard/employee/exam-evaluation/delete', methods=['POST'])
@login_required
def delete_exam():
    """Delete an exam allocation row."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    try:
        exam_id = int(data.get('exam_id', 0))
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid exam ID'}), 400

    if exam_id <= 0:
        return jsonify({'success': False, 'message': 'Invalid exam ID'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            cursor.execute("SELECT id, COALESCE(is_locked, 0) AS il FROM exams WHERE id = %s", (exam_id,))
            ex = cursor.fetchone()
            if not ex:
                return jsonify({'success': False, 'message': 'Exam not found'}), 404
            il = ex.get('il') if isinstance(ex, dict) else ex[1]
            if il:
                return jsonify({'success': False, 'message': 'This exam is locked. Unlock it before deleting allocations.'}), 400

            cursor.execute("DELETE FROM exams WHERE id = %s", (exam_id,))
            connection.commit()
            return jsonify({'success': True, 'message': 'Exam deleted successfully'})
    except Exception as e:
        print(f"Error deleting exam: {e}")
        import traceback
        traceback.print_exc()
        try:
            connection.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'message': f'Error deleting exam: {str(e)}'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/exam-evaluation/update-registration', methods=['POST'])
@login_required
def update_exam_registration():
    """Update exam registration header for all rows in a registration group."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    old_exam_name = (data.get('old_exam_name') or '').strip().upper()
    try:
        old_academic_year_id = int(data.get('old_academic_year_id', 0))
        old_term_id = int(data.get('old_term_id', 0))
        academic_year_id = int(data.get('academic_year_id', 0))
        term_id = int(data.get('term_id', 0))
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid year/term values'}), 400

    exam_type = (data.get('exam_type') or '').strip().upper()
    exam_name = (data.get('exam_name') or '').strip().upper()

    if not old_exam_name or old_academic_year_id <= 0 or old_term_id <= 0:
        return jsonify({'success': False, 'message': 'Missing registration key'}), 400
    if not exam_name or not exam_type or academic_year_id <= 0 or term_id <= 0:
        return jsonify({'success': False, 'message': 'Missing required fields'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            cursor.execute("""
                SELECT id, COALESCE(is_locked, 0) AS il
                FROM exams
                WHERE exam_name = %s AND academic_year_id = %s AND term_id = %s
            """, (old_exam_name, old_academic_year_id, old_term_id))
            rows = cursor.fetchall() or []
            if not rows:
                return jsonify({'success': False, 'message': 'Registered exam not found'}), 404
            if any((r.get('il') if isinstance(r, dict) else r[1]) for r in rows):
                return jsonify({'success': False, 'message': 'This exam is locked. Unlock it before editing registration details.'}), 400

            cursor.execute("""
                UPDATE exams
                SET exam_name = %s,
                    exam_type = %s,
                    academic_year_id = %s,
                    term_id = %s
                WHERE exam_name = %s
                  AND academic_year_id = %s
                  AND term_id = %s
            """, (
                exam_name, exam_type, academic_year_id, term_id,
                old_exam_name, old_academic_year_id, old_term_id
            ))
            updated = cursor.rowcount or 0
            connection.commit()
            return jsonify({'success': True, 'message': f'Registration updated for {updated} allocation(s).'})
    except Exception as e:
        print(f"Error updating exam registration: {e}")
        import traceback
        traceback.print_exc()
        try:
            connection.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'message': f'Error updating registration: {str(e)}'}), 500
    finally:
        connection.close()


