def _fetch_stock_in_payment_lines_for_movements(cursor, movement_ids):
    """Payment lines for stock-in movements (oldest first)."""
    ids = [int(i) for i in (movement_ids or []) if i]
    if not ids:
        return []
    ensure_store_stock_in_payment_lines_table(cursor)
    ensure_store_stock_movements_table(cursor)
    placeholders = ','.join(['%s'] * len(ids))
    rows = []
    try:
        cursor.execute(
            f"""
            SELECT pl.id, pl.movement_id, pl.amount_paid, pl.paid_to_company_name,
                   pl.paid_to_company_phone, pl.paid_by_name, pl.payment_method,
                   pl.payment_reference, pl.created_at,
                   m.reference_number, m.total_amount, m.payment_status,
                   si.item_name, si.item_category,
                   fa.account_name AS finance_account_name
            FROM store_stock_in_payment_lines pl
            INNER JOIN store_stock_movements m ON m.id = pl.movement_id
            INNER JOIN store_inventory_items si ON si.id = m.store_item_id
            LEFT JOIN finance_accounts fa ON fa.id = pl.finance_account_id
            WHERE pl.movement_id IN ({placeholders})
            ORDER BY pl.created_at ASC, pl.id ASC
            """,
            tuple(ids),
        )
        for row in cursor.fetchall() or []:
            rows.append(_stock_in_payment_line_row_to_dict(row))
    except Exception as e:
        print(f"_fetch_stock_in_payment_lines_for_movements: {e}")
    return rows


def _fetch_supplier_payment_statement_pack(cursor, phone_key):
    """Invoices, payment lines, and misc rows for one supplier grouping key."""
    phone_key = (phone_key or '').strip()
    if not phone_key:
        return None

    ensure_store_stock_movements_table(cursor)
    ensure_store_stock_in_payment_lines_table(cursor)
    ensure_accountant_misc_payments_table(cursor)

    all_movements = _fetch_store_stock_in_list(cursor, payment_filter='all', limit=5000)
    invoices = [
        m for m in all_movements
        if _supplier_payable_phone_key(m) == phone_key
    ]
    invoices.sort(
        key=lambda m: (
            m.get('created_at').timestamp()
            if m.get('created_at') and hasattr(m.get('created_at'), 'timestamp')
            else 0
        ),
    )

    movement_ids = [int(m.get('id') or 0) for m in invoices if m.get('id')]
    payment_lines = _fetch_stock_in_payment_lines_for_movements(cursor, movement_ids)

    phone_norm = ''
    if not phone_key.startswith('__no_phone_'):
        phone_norm = _normalize_store_supplier_phone(phone_key)

    misc_payments = []
    for misc_row in _fetch_accountant_misc_payments(cursor, limit=2000):
        misc_phone = _normalize_store_supplier_phone(
            misc_row.get('paid_to_company_phone') or '',
        )
        if phone_norm and misc_phone == phone_norm:
            misc_payments.append(misc_row)

    supplier_name = '—'
    supplier_phone = '—'
    for inv in invoices:
        reg = (inv.get('supplier_name') or '').strip()
        paid_name = (inv.get('paid_to_company_name') or '').strip()
        if reg:
            supplier_name = reg.upper()
        elif paid_name and supplier_name == '—':
            supplier_name = paid_name.upper()
        ph = (inv.get('supplier_phone') or inv.get('paid_to_company_phone') or '').strip()
        if ph:
            supplier_phone = ph
    if misc_payments and supplier_name == '—':
        supplier_name = (misc_payments[0].get('paid_to_company_name') or '—').upper()
    if misc_payments and (supplier_phone == '—' or not supplier_phone):
        supplier_phone = misc_payments[0].get('paid_to_company_phone') or '—'

    total_invoiced = sum(float(m.get('total_amount') or 0) for m in invoices)
    total_paid_on_invoices = sum(float(m.get('amount_paid') or 0) for m in invoices)
    balance_due = sum(
        float(m.get('balance_due') if m.get('balance_due') is not None else 0)
        for m in invoices
    )
    payments_total = sum(float(p.get('amount_paid') or 0) for p in payment_lines)
    misc_total = sum(float(m.get('amount') or 0) for m in misc_payments)

    return {
        'phone_key': phone_key,
        'supplier_name': supplier_name,
        'supplier_phone': supplier_phone,
        'invoices': invoices,
        'payment_lines': payment_lines,
        'misc_payments': misc_payments,
        'invoice_count': len(invoices),
        'payment_line_count': len(payment_lines),
        'misc_count': len(misc_payments),
        'total_invoiced': total_invoiced,
        'total_invoiced_display': _format_kes_amount(total_invoiced),
        'total_paid_display': _format_kes_amount(total_paid_on_invoices),
        'payments_total_display': _format_kes_amount(payments_total),
        'balance_due_display': _format_kes_amount(balance_due),
        'misc_total_display': _format_kes_amount(misc_total),
    }


def _fetch_payments_invoices_statement_packs(cursor, payment_filter='outstanding'):
    """Statement packs for each supplier row on the payments / invoices page."""
    payment_filter = (payment_filter or 'outstanding').strip().lower()
    movements = _fetch_store_stock_in_list(cursor, payment_filter='all', limit=5000)
    suppliers = _aggregate_supplier_payables_by_phone(
        movements, status_filter=payment_filter,
    )
    packs = []
    for sup in suppliers:
        pack = _fetch_supplier_payment_statement_pack(cursor, sup.get('phone_key'))
        if pack:
            packs.append(pack)
    return packs, payment_filter


def _fetch_outstanding_stock_in_for_phone(cursor, phone_norm):
    """Outstanding stock-in movements for a supplier phone (oldest first)."""
    if not phone_norm or str(phone_norm).startswith('__no_phone_'):
        return []
    records = _fetch_store_stock_in_list(cursor, payment_filter='all', limit=2000)
    out = [
        row for row in records
        if _supplier_payable_phone_key(row) == phone_norm and row.get('can_pay')
    ]
    out.sort(
        key=lambda m: (
            m.get('created_at').timestamp()
            if m.get('created_at') and hasattr(m.get('created_at'), 'timestamp')
            else 0
        ),
    )
    return out


def _fetch_supplier_payable_by_phone(cursor, phone_raw):
    """Look up a registered store supplier by phone and return school payables (JSON-safe)."""
    phone_norm = _normalize_store_supplier_phone(phone_raw)
    if not phone_norm:
        return {
            'is_supplier': False,
            'ready': False,
            'message': 'Enter a valid phone number (at least 9 digits).',
        }

    ensure_store_suppliers_table(cursor)
    ensure_store_stock_movements_table(cursor)
    ensure_store_stock_in_payment_lines_table(cursor)

    supplier = _store_lookup_supplier_by_phone(cursor, phone_norm)
    if not supplier:
        return {
            'is_supplier': False,
            'ready': True,
            'supplier_phone': phone_norm,
            'message': 'This phone number is not registered as a supplier.',
        }

    stock_records = _fetch_store_stock_in_list(cursor, payment_filter='all', limit=2000)
    aggregated = _aggregate_supplier_payables_by_phone(stock_records, status_filter='all')
    payable = next((row for row in aggregated if row.get('phone_key') == phone_norm), None) or {}
    balance_due = float(payable.get('balance_due') or 0)

    return {
        'is_supplier': True,
        'ready': True,
        'supplier_id': supplier.get('id'),
        'supplier_name': supplier.get('company_name') or '',
        'supplier_phone': supplier.get('phone') or phone_norm,
        'balance_due': balance_due,
        'balance_due_display': f'{balance_due:,.2f}',
        'invoice_count': int(payable.get('invoice_count') or 0),
        'payment_status': payable.get('payment_status') or 'paid',
        'payment_status_label': payable.get('payment_status_label') or 'Paid',
        'total_invoiced': float(payable.get('total_invoiced') or 0),
        'total_paid': float(payable.get('total_paid') or 0),
        'message': 'Registered supplier — school payable balance loaded.',
    }


def _fetch_parent_supplier_info_for_student(cursor, student_id):
    """
    If a student's parent/guardian phone matches a registered store supplier,
    return supplier payables owed by the school (JSON-safe dict).
    """
    sid = (student_id or '').strip()
    if not sid:
        return {'is_supplier': False}

    ensure_store_suppliers_table(cursor)
    ensure_store_stock_movements_table(cursor)
    ensure_store_stock_in_payment_lines_table(cursor)

    cursor.execute(
        """
        SELECT full_name, phone FROM parents
        WHERE student_id = %s
        ORDER BY id ASC
        """,
        (sid,),
    )
    parents = cursor.fetchall() or []
    if not parents:
        return {'is_supplier': False}

    for parent_row in parents:
        if isinstance(parent_row, dict):
            parent_name = (parent_row.get('full_name') or '').strip()
            parent_phone = (parent_row.get('phone') or '').strip()
        else:
            parent_name = (parent_row[0] or '').strip() if len(parent_row) > 0 else ''
            parent_phone = (parent_row[1] or '').strip() if len(parent_row) > 1 else ''

        info = _fetch_supplier_payable_by_phone(cursor, parent_phone)
        if info.get('is_supplier'):
            info['parent_name'] = parent_name
            info['parent_phone'] = parent_phone
            return info

    return {'is_supplier': False}


def _apply_supplier_offset_for_fee_payment(
    cursor, supplier_phone, offset_amount, paid_by_name, student_payment_id, student_id=None,
):
    """Apply fee payment against outstanding supplier stock-in payables (no cash out)."""
    from decimal import Decimal, InvalidOperation

    try:
        offset_dec = Decimal(str(offset_amount)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        return False, 'Invalid supplier offset amount.'

    if offset_dec <= 0:
        return False, 'Supplier offset amount must be greater than zero.'

    info = _fetch_supplier_payable_by_phone(cursor, supplier_phone)
    if not info.get('is_supplier'):
        return False, 'Enter a registered supplier phone number to trade from their account.'

    available = Decimal(str(info.get('balance_due') or 0)).quantize(Decimal('0.01'))
    if available <= 0:
        return False, 'This supplier has no outstanding balance for the school to trade against.'
    if offset_dec > available:
        return False, (
            f'Supplier credit available is only KES {float(available):,.2f}.'
        )

    phone_norm = info.get('supplier_phone') or ''
    company_name = (info.get('supplier_name') or 'SUPPLIER').strip().upper()
    if not phone_norm:
        return False, 'Supplier phone could not be resolved for offset.'

    movements = _fetch_outstanding_stock_in_for_phone(cursor, phone_norm)
    if not movements:
        return False, 'No outstanding supplier invoices to offset against.'

    remaining = offset_dec
    student_ref = (student_id or '').strip()
    ref = f'Fee offset #{student_payment_id}'
    if student_ref:
        ref = f'Fee offset {student_ref} #{student_payment_id}'
    for mov in movements:
        if remaining <= Decimal('0'):
            break
        try:
            mov_balance = Decimal(str(mov.get('balance_due') or 0)).quantize(Decimal('0.01'))
        except (InvalidOperation, ValueError):
            mov_balance = Decimal('0')
        if mov_balance <= 0:
            continue
        apply_amt = min(remaining, mov_balance)
        ok, msg = _apply_stock_in_payment(
            cursor,
            mov['id'],
            apply_amt,
            company_name,
            phone_norm,
            paid_by_name,
            payment_method='Supplier Offset (School fees)',
            finance_account_id=None,
            payment_reference=ref,
            skip_account_debit=True,
        )
        if not ok:
            return False, msg or 'Could not apply supplier offset.'
        remaining = (remaining - apply_amt).quantize(Decimal('0.01'))

    if remaining > Decimal('0.01'):
        return False, 'Could not apply the full supplier offset amount.'
    return True, None


def _apply_stock_in_payment(
    cursor, movement_id, pay_amount, company_name, company_phone, paid_by_name,
    payment_method=None, finance_account_id=None, payment_reference=None,
    skip_account_debit=False,
):
    """Apply one payment line to a stock-in movement. Returns (ok, message)."""
    from decimal import Decimal, InvalidOperation

    try:
        pay_dec = Decimal(str(pay_amount)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        return False, 'Invalid payment amount.'
    if pay_dec <= 0:
        return False, 'Enter a valid payment amount greater than zero.'

    cursor.execute(
        """
        SELECT id, reference_number, movement_type, total_amount, amount_paid
        FROM store_stock_movements WHERE id = %s
        """,
        (movement_id,),
    )
    row = cursor.fetchone()
    if not row:
        return False, 'Stock in record not found.'
    if isinstance(row, dict):
        movement_type = (row.get('movement_type') or '').strip()
        ref_no = (row.get('reference_number') or '').strip()
        total_amount = row.get('total_amount')
        current_paid = row.get('amount_paid') or 0
    else:
        movement_type = (row[2] or '').strip() if len(row) > 2 else ''
        ref_no = (row[1] or '').strip() if len(row) > 1 else ''
        total_amount = row[3] if len(row) > 3 else None
        current_paid = row[4] if len(row) > 4 else 0
    if movement_type != 'in':
        return False, 'Only stock in records can be paid from this page.'
    try:
        total_dec = Decimal(str(total_amount or 0)).quantize(Decimal('0.01'))
        paid_dec = Decimal(str(current_paid or 0)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError):
        total_dec = Decimal('0')
        paid_dec = Decimal('0')
    balance = (total_dec - paid_dec).quantize(Decimal('0.01'))
    if balance <= 0:
        return False, f'{ref_no} is already fully paid.'
    if pay_dec > balance:
        return False, (
            f'Payment for {ref_no} cannot exceed the balance due ({balance}).'
        )
    new_paid = (paid_dec + pay_dec).quantize(Decimal('0.01'))
    new_status = _store_stock_payment_status(new_paid, total_dec)
    ensure_store_stock_in_payment_lines_table(cursor)
    cursor.execute(
        """
        INSERT INTO store_stock_in_payment_lines
            (movement_id, amount_paid, paid_to_company_name,
             paid_to_company_phone, paid_by_name, payment_method,
             finance_account_id, payment_reference)
        VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
        """,
        (
            movement_id, pay_dec, company_name, company_phone, paid_by_name or None,
            payment_method, finance_account_id, payment_reference,
        ),
    )
    line_id = cursor.lastrowid
    if not skip_account_debit and finance_account_id and payment_method and line_id:
        ok, err = _debit_finance_account(
            cursor,
            finance_account_id,
            pay_dec,
            payment_method,
            payment_reference,
            f'Stock-in payment {ref_no}',
            related_type='stock_in_payment_line',
            related_id=int(line_id),
            recorded_by_name=paid_by_name,
        )
        if not ok:
            return False, err
    cursor.execute(
        """
        UPDATE store_stock_movements
        SET amount_paid = %s, payment_status = %s,
            paid_to_company_name = %s, paid_to_company_phone = %s
        WHERE id = %s AND movement_type = 'in'
        """,
        (new_paid, new_status, company_name, company_phone, movement_id),
    )
    if new_status == 'paid':
        return True, f'{ref_no} fully paid ({pay_dec}).'
    remaining = (total_dec - new_paid).quantize(Decimal('0.01'))
    return True, f'{ref_no} partial ({pay_dec}); balance {remaining}.'


def _record_supplier_pay_all(
    cursor, phone_norm, pay_amount, company_name, company_phone, paid_by_name,
    payment_method=None, finance_account_id=None, payment_reference=None,
):
    """Apply payment across all outstanding invoices for a supplier phone."""
    from decimal import Decimal, InvalidOperation

    try:
        pay_total = Decimal(str(pay_amount)).quantize(Decimal('0.01'))
    except (InvalidOperation, ValueError, TypeError):
        return False, 'Invalid payment amount.'
    if pay_total <= 0:
        return False, 'Enter a valid payment amount greater than zero.'

    movements = _fetch_outstanding_stock_in_for_phone(cursor, phone_norm)
    if not movements:
        return False, 'No outstanding invoices for this supplier.'

    total_balance = Decimal('0')
    for m in movements:
        try:
            total_balance += Decimal(str(m.get('balance_due') or 0)).quantize(Decimal('0.01'))
        except (InvalidOperation, ValueError):
            pass
    if pay_total > total_balance + Decimal('0.01'):
        return False, (
            f'Payment cannot exceed total balance due ({total_balance.quantize(Decimal("0.01"))}).'
        )

    if finance_account_id and payment_method:
        ok_funds, _, fund_err = _validate_disbursement_finance_account(
            cursor, finance_account_id, payment_method, pay_total,
        )
        if not ok_funds:
            return False, fund_err or 'Insufficient funds in the selected account.'

    remaining = pay_total
    applied = 0
    notes = []
    for m in movements:
        if remaining <= Decimal('0'):
            break
        try:
            bal = Decimal(str(m.get('balance_due') or 0)).quantize(Decimal('0.01'))
        except (InvalidOperation, ValueError):
            continue
        if bal <= 0:
            continue
        chunk = min(remaining, bal)
        ok, msg = _apply_stock_in_payment(
            cursor, m['id'], chunk, company_name, company_phone, paid_by_name,
            payment_method=payment_method,
            finance_account_id=finance_account_id,
            payment_reference=payment_reference,
            skip_account_debit=False,
        )
        if not ok:
            return False, msg
        applied += 1
        notes.append(msg)
        remaining -= chunk

    if applied == 0:
        return False, 'No payment was applied.'
    summary = (
        f'Payment of KES {pay_total:,.2f} recorded across {applied} invoice(s) '
        f'for {company_name}.'
    )
    if remaining > Decimal('0.005'):
        summary += f' Unallocated: KES {remaining.quantize(Decimal("0.01")):,.2f}.'
    return True, summary


def _fetch_store_stock_movement_detail(cursor, movement_id):
    ensure_store_stock_movements_table(cursor)
    try:
        cursor.execute(
            """
            SELECT m.id, m.reference_number, m.movement_type, m.quantity,
                   m.buying_price, m.total_amount, m.payment_status, m.amount_paid,
                   m.notes, m.stock_out_purpose,
                   m.quantity_before, m.quantity_after, m.created_at,
                   m.performed_by_name,
                   si.reference_code AS item_ref, si.item_name, si.item_category, si.measure,
                   sup.company_name AS supplier_name, sup.phone AS supplier_phone
            FROM store_stock_movements m
            INNER JOIN store_inventory_items si ON si.id = m.store_item_id
            LEFT JOIN store_suppliers sup ON sup.id = m.supplier_id
            WHERE m.id = %s
            """,
            (movement_id,),
        )
        row = cursor.fetchone()
        if not row:
            return None
        if isinstance(row, dict):
            return {
                'id': int(row.get('id') or 0),
                'reference_number': (row.get('reference_number') or '').strip(),
                'movement_type': (row.get('movement_type') or '').strip(),
                'quantity': int(row.get('quantity') or 0),
                'buying_price': row.get('buying_price'),
                'total_amount': row.get('total_amount'),
                'payment_status': (row.get('payment_status') or '').strip(),
                'amount_paid': row.get('amount_paid'),
                'notes': (row.get('notes') or '').strip() or None,
                'stock_out_purpose': (row.get('stock_out_purpose') or '').strip() or None,
                'quantity_before': int(row.get('quantity_before') or 0),
                'quantity_after': int(row.get('quantity_after') or 0),
                'created_at': row.get('created_at'),
                'performed_by_name': (row.get('performed_by_name') or '').strip() or None,
                'item_ref': (row.get('item_ref') or '').strip(),
                'item_name': (row.get('item_name') or '').strip(),
                'item_category': (row.get('item_category') or '').strip(),
                'measure': (row.get('measure') or '').strip(),
                'supplier_name': (row.get('supplier_name') or '').strip() or None,
                'supplier_phone': (row.get('supplier_phone') or '').strip() or None,
            }
        return {
            'id': int(row[0] or 0),
            'reference_number': (row[1] or '').strip(),
            'movement_type': (row[2] or '').strip(),
            'quantity': int(row[3] or 0),
            'buying_price': row[4] if len(row) > 4 else None,
            'total_amount': row[5] if len(row) > 5 else None,
            'payment_status': (row[6] or '').strip() if len(row) > 6 else '',
            'amount_paid': row[7] if len(row) > 7 else 0,
            'notes': (row[8] or '').strip() or None if len(row) > 8 else None,
            'stock_out_purpose': (row[9] or '').strip() or None if len(row) > 9 else None,
            'quantity_before': int(row[10] or 0) if len(row) > 10 else 0,
            'quantity_after': int(row[11] or 0) if len(row) > 11 else 0,
            'created_at': row[12] if len(row) > 12 else None,
            'performed_by_name': (row[13] or '').strip() or None if len(row) > 13 else None,
            'item_ref': (row[14] or '').strip() if len(row) > 14 else '',
            'item_name': (row[15] or '').strip() if len(row) > 15 else '',
            'item_category': (row[16] or '').strip() if len(row) > 16 else '',
            'measure': (row[17] or '').strip() if len(row) > 17 else '',
            'supplier_name': (row[18] or '').strip() or None if len(row) > 18 else None,
            'supplier_phone': (row[19] or '').strip() or None if len(row) > 19 else None,
        }
    except Exception as e:
        print(f"_fetch_store_stock_movement_detail: {e}")
        return None


def _store_inventory_effective_role():
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_technician = user_role == 'technician'
    return viewing_as_role if is_technician and viewing_as_role else user_role


def _store_inventory_guard():
    """Redirect if current user is not allowed to manage store inventory."""
    if _store_inventory_effective_role() != 'store manager':
        flash('You do not have permission to perform this action.', 'error')
        return redirect(employee_dashboard_path())
    return None


STORE_FEE_VOTE_NAME_COL = 28


def _store_fee_vote_option_label(item_name, item_description=None):
    """Monospace-friendly option label: vote name column + description."""
    name = str(item_name or '').strip().upper()
    if not name:
        return ''
    desc = str(item_description or '').strip().upper() or '—'
    gap = max(2, STORE_FEE_VOTE_NAME_COL - len(name))
    return f'{name}{" " * gap}{desc}'


def _fetch_store_fee_structure_votes(cursor):
    """
    Fee structure votes (fee_items) for store expense category pickers.
    Returns dicts: name (stored value), description, label (aligned display).
    """
    votes = []
    seen = set()
    try:
        cursor.execute("""
            SELECT TRIM(item_name) AS item_name,
                   TRIM(MAX(item_description)) AS item_description
            FROM fee_items
            WHERE COALESCE(TRIM(item_name), '') != ''
            GROUP BY TRIM(item_name)
            ORDER BY item_name ASC
        """)
        for r in cursor.fetchall() or []:
            if isinstance(r, dict):
                raw_name = r.get('item_name') or ''
                raw_desc = r.get('item_description') or ''
            else:
                raw_name = r[0] if len(r) > 0 else ''
                raw_desc = r[1] if len(r) > 1 else ''
            name = str(raw_name).strip().upper()
            if not name or name in seen:
                continue
            seen.add(name)
            description = str(raw_desc).strip().upper() or None
            votes.append({
                'name': name,
                'description': description,
                'label': _store_fee_vote_option_label(name, description),
            })
    except Exception as e:
        print(f"_fetch_store_fee_structure_votes: {e}")
    return votes


def _fetch_store_expense_categories(cursor, extra_categories=None):
    """
    Distinct fee line item names from fee structures — store inventory expense categories.
    Optionally merges extra values (e.g. a legacy category on an existing store item).
    """
    categories = [v['name'] for v in _fetch_store_fee_structure_votes(cursor)]
    seen = set(categories)
    for raw in extra_categories or ():
        name = str(raw or '').strip().upper()
        if name and name not in seen:
            seen.add(name)
            categories.append(name)
    categories.sort(key=lambda x: x.lower())
    return categories


def _fetch_store_expense_category_picker_votes(cursor):
    """Fee structure votes plus legacy store categories for expense category pickers."""
    votes = _fetch_store_fee_structure_votes(cursor)
    seen = {v['name'] for v in votes}
    try:
        ensure_store_inventory_items_table(cursor)
        cursor.execute("""
            SELECT DISTINCT TRIM(item_category) AS item_category
            FROM store_inventory_items
            WHERE COALESCE(TRIM(item_category), '') != ''
        """)
        for r in cursor.fetchall() or []:
            legacy_cat = (r.get('item_category') if isinstance(r, dict) else r[0]) or ''
            legacy_cat = str(legacy_cat).strip().upper()
            if legacy_cat and legacy_cat not in seen:
                seen.add(legacy_cat)
                votes.append({
                    'name': legacy_cat,
                    'description': None,
                    'label': legacy_cat,
                })
    except Exception as e:
        print(f"_fetch_store_expense_category_picker_votes: {e}")
    votes.sort(key=lambda v: v['name'].lower())
    return votes


def _is_valid_store_expense_category(cursor, category, extra_allowed=None):
    """True when category matches a registered fee item name (case-insensitive)."""
    cat = str(category or '').strip().upper()
    if not cat:
        return False
    allowed = set(_fetch_store_expense_categories(cursor, extra_categories=extra_allowed))
    return cat in allowed


def _generate_store_item_reference_code(cursor):
    """Next simple reference: STI-00001, STI-00002, …"""
    ensure_store_inventory_items_table(cursor)
    cursor.execute("""
        SELECT reference_code FROM store_inventory_items
        ORDER BY id DESC LIMIT 1
    """)
    row = cursor.fetchone()
    next_num = 1
    if row:
        code = (row.get('reference_code') if isinstance(row, dict) else row[0]) or ''
        m = re.match(r'^STI-(\d+)$', str(code).strip().upper())
        if m:
            next_num = int(m.group(1)) + 1
    return f'STI-{next_num:05d}'


def _save_store_item_image(file_storage):
    """Save optional store item image; returns relative static path or None."""
    if not file_storage or not getattr(file_storage, 'filename', None):
        return None
    if file_storage.filename == '' or not allowed_file(file_storage.filename):
        return None
    timestamp = datetime.now().strftime('%Y%m%d%H%M%S')
    filename = secure_filename(file_storage.filename)
    unique_filename = f"store_{timestamp}_{filename}"
    file_path = os.path.join(STORE_INVENTORY_FOLDER, unique_filename)
    file_storage.save(file_path)
    return f"uploads/store_inventory/{unique_filename}"


def _delete_store_item_image_file(image_path):
    if not image_path:
        return
    rel = str(image_path).lstrip('/').replace('\\', '/')
    if rel.startswith('static/'):
        rel = rel[7:]
    full = os.path.join('static', rel) if not rel.startswith('static') else rel
    try:
        if os.path.isfile(full):
            os.remove(full)
    except OSError as e:
        print(f"_delete_store_item_image_file: {e}")


def _normalize_store_department_station(raw):
    """Return a valid department station label or empty string."""
    station = (raw or '').strip().upper()
    if station in STORE_DEPARTMENT_STATIONS:
        return station
    return ''


def _store_station_is_library(station):
    return (station or '').strip().upper() == STORE_LIBRARY_DEPARTMENT_STATION


def _library_book_needs_librarian_setup(academic_category, subject_id):
    cat = (academic_category or '').strip().upper()
    if cat in (LIBRARY_PENDING_ACADEMIC_CATEGORY, 'UNKNOWN', ''):
        return True
    try:
        sid = int(subject_id or 0)
    except (TypeError, ValueError):
        sid = 0
    return sid < 1


def _library_setup_levels_for_book(all_levels, level_subjects_map, academic_category, subject_id):
    """Active class levels in this category that teach the given subject (if subject set)."""
    cat = (academic_category or '').strip().upper()
    if cat in (LIBRARY_PENDING_ACADEMIC_CATEGORY, 'UNKNOWN', ''):
        return []
    try:
        sid = int(subject_id or 0)
    except (TypeError, ValueError):
        sid = 0
    out = []
    for lev in all_levels or []:
        lc = (lev.get('level_category') or '').upper()
        if lc != cat:
            continue
        if sid < 1:
            out.append(lev)
            continue
        lid = int(lev.get('id') or 0)
        subs = (level_subjects_map or {}).get(str(lid)) or (level_subjects_map or {}).get(lid) or []
        if any(int(s.get('id') or 0) == sid for s in subs):
            out.append(lev)
    return out


def _library_sync_store_department_catalog(cursor):
    """
    Create library_books rows for active store items in Library Department
    that are not yet in the librarian catalog.
    """
    ensure_store_inventory_items_table(cursor)
    ensure_library_books_table(cursor)
    migrate_library_books_store_department_link(cursor)
    try:
        cursor.execute(
            """
            SELECT si.id, si.item_category, si.item_name, si.description, si.library_book_id
            FROM store_inventory_items si
            WHERE si.item_status = 'active'
              AND UPPER(TRIM(COALESCE(si.department_station, ''))) = %s
            """,
            (STORE_LIBRARY_DEPARTMENT_STATION,),
        )
        rows = cursor.fetchall() or []
        for row in rows:
            if isinstance(row, dict):
                store_item_id = int(row.get('id') or 0)
                item_category = row.get('item_category') or ''
                item_name = row.get('item_name') or ''
                description = row.get('description')
                library_book_id = int(row.get('library_book_id') or 0) or None
            else:
                store_item_id = int(row[0] or 0)
                item_category = row[1] if len(row) > 1 else ''
                item_name = row[2] if len(row) > 2 else ''
                description = row[3] if len(row) > 3 else None
                library_book_id = int(row[4] or 0) or None if len(row) > 4 else None
            if not store_item_id:
                continue
            if library_book_id:
                cursor.execute(
                    "SELECT id FROM library_books WHERE id = %s",
                    (library_book_id,),
                )
                if cursor.fetchone():
                    continue
            _create_library_book_for_store_item(
                cursor,
                store_item_id,
                item_category,
                item_name,
                description,
            )
    except Exception as e:
        print(f"_library_sync_store_department_catalog: {e}")


def _create_library_book_for_store_item(cursor, store_item_id, item_category, item_name, description):
    """Create a library catalog row for a store item registered under Library Department."""
    ensure_library_books_table(cursor)
    migrate_library_books_store_department_link(cursor)
    cursor.execute("SELECT id FROM library_books WHERE store_item_id = %s LIMIT 1", (store_item_id,))
    existing = cursor.fetchone()
    if existing:
        lib_id = int(existing.get('id') if isinstance(existing, dict) else existing[0])
        cursor.execute(
            "UPDATE store_inventory_items SET library_book_id = %s WHERE id = %s",
            (lib_id, store_item_id),
        )
        return lib_id
    cursor.execute(
        """
        INSERT INTO library_books
            (book_category, book_name, description, buying_price, academic_category,
             subject_id, library_status, allocation_status, copies_total, store_item_id)
        VALUES (%s, %s, %s, 0, %s, NULL, 'active', 'unallocated', 0, %s)
        """,
        (
            item_category,
            item_name,
            description,
            LIBRARY_PENDING_ACADEMIC_CATEGORY,
            store_item_id,
        ),
    )
    lib_id = cursor.lastrowid
    cursor.execute(
        "UPDATE store_inventory_items SET library_book_id = %s WHERE id = %s",
        (lib_id, store_item_id),
    )
    return lib_id


def _sync_linked_library_book_from_store_item(cursor, library_book_id, item_category, item_name, description):
    if not library_book_id:
        return
    cursor.execute(
        """
        UPDATE library_books
        SET book_category = %s, book_name = %s, description = %s
        WHERE id = %s
        """,
        (item_category, item_name, description, library_book_id),
    )


def _register_store_inventory_item_from_request(cursor, request):
    """
    Register a new store catalog item from POST form fields.
    Caller must commit the connection on success.
    Returns dict: ok, message, reference_code, new_item_id.
    """
    item_category = (request.form.get('item_category') or '').strip()[:120].upper()
    item_name = (request.form.get('item_name') or '').strip()[:255].upper()
    desc_raw = (request.form.get('description') or '').strip()
    description = desc_raw.upper() if desc_raw else None
    measure = (request.form.get('measure') or '').strip().upper()
    if measure not in STORE_ITEM_MEASURES:
        measure = ''
    department_station = _normalize_store_department_station(request.form.get('department_station'))

    if not item_category or not item_name:
        return {'ok': False, 'message': 'Expense category and item name are required.'}
    if not _is_valid_store_expense_category(cursor, item_category):
        return {
            'ok': False,
            'message': (
                'Please select a valid expense category registered '
                'in Student fees → Fee structures.'
            ),
        }
    if not department_station:
        return {'ok': False, 'message': 'Please select a department station for this item.'}
    if not measure:
        return {'ok': False, 'message': 'Please select a valid measure.'}

    try:
        reference_code = _generate_store_item_reference_code(cursor)
        image_path = _save_store_item_image(request.files.get('image'))
        cursor.execute(
            """
            INSERT INTO store_inventory_items
                (reference_code, item_category, item_name, description, measure,
                 image_path, item_status, department_station)
            VALUES (%s, %s, %s, %s, %s, %s, 'active', %s)
            """,
            (
                reference_code,
                item_category,
                item_name,
                description,
                measure,
                image_path,
                department_station,
            ),
        )
        new_item_id = cursor.lastrowid
        lib_msg = ''
        if _store_station_is_library(department_station) and new_item_id:
            ensure_library_books_table(cursor)
            _create_library_book_for_store_item(
                cursor,
                new_item_id,
                item_category,
                item_name,
                description,
            )
            lib_msg = (
                ' It was also added to the library catalog for the librarian '
                'to set subject and levels.'
            )
        return {
            'ok': True,
            'message': f'Store item registered as {reference_code}.{lib_msg}',
            'reference_code': reference_code,
            'new_item_id': new_item_id,
        }
    except IntegrityError:
        return {
            'ok': False,
            'message': 'Could not save the store item (duplicate reference). Try again.',
        }
    except Exception as e:
        print(f"_register_store_inventory_item_from_request: {e}")
        return {'ok': False, 'message': 'An error occurred while registering the store item.'}


def _fetch_store_inventory_summary(cursor):
    """Aggregate counts for store catalog dashboard stats."""
    ensure_store_inventory_items_table(cursor)
    cursor.execute(
        """
        SELECT
            COUNT(*) AS total_items,
            COALESCE(SUM(quantity_on_hand), 0) AS units_on_hand,
            SUM(CASE WHEN item_status = 'suspended' THEN 1 ELSE 0 END) AS suspended_count,
            SUM(CASE WHEN item_status != 'suspended'
                     AND COALESCE(quantity_on_hand, 0) <= 5 THEN 1 ELSE 0 END) AS low_stock_count
        FROM store_inventory_items
        """
    )
    row = cursor.fetchone()
    if isinstance(row, dict):
        return {
            'total_items': int(row.get('total_items') or 0),
            'units_on_hand': int(row.get('units_on_hand') or 0),
            'suspended_count': int(row.get('suspended_count') or 0),
            'low_stock_count': int(row.get('low_stock_count') or 0),
        }
    return {
        'total_items': int(row[0] or 0) if row else 0,
        'units_on_hand': int(row[1] or 0) if row and len(row) > 1 else 0,
        'suspended_count': int(row[2] or 0) if row and len(row) > 2 else 0,
        'low_stock_count': int(row[3] or 0) if row and len(row) > 3 else 0,
    }


def _fetch_store_inventory_page(cursor, page=1, per_page=50, q=''):
    """Paginated store catalog rows."""
    ensure_store_inventory_items_table(cursor)
    ensure_store_stock_movements_table(cursor)
    per_page = max(1, min(int(per_page or 50), 100))
    page = max(1, int(page or 1))
    offset = (page - 1) * per_page
    q = (q or '').strip()
    where = []
    params = []
    if q:
        like = '%' + q + '%'
        where.append(
            '(si.item_category LIKE %s OR si.item_name LIKE %s OR si.reference_code LIKE %s '
            'OR si.description LIKE %s OR si.department_station LIKE %s)'
        )
        params.extend([like, like, like, like, like])
    where_sql = (' WHERE ' + ' AND '.join(where)) if where else ''
    cursor.execute(f'SELECT COUNT(*) AS c FROM store_inventory_items si{where_sql}', tuple(params))
    count_row = cursor.fetchone()
    total = int((count_row.get('c') if isinstance(count_row, dict) else count_row[0]) or 0)
    cursor.execute(
        f"""
        SELECT si.id, si.reference_code, si.item_category, si.item_name, si.description, si.measure,
               si.image_path, si.item_status, si.quantity_on_hand, si.department_station,
               si.library_book_id, si.created_at,
               avg_bp.avg_buying_price
        FROM store_inventory_items si
        LEFT JOIN (
            SELECT store_item_id,
                   ROUND(SUM(buying_price * quantity) / NULLIF(SUM(quantity), 0), 2) AS avg_buying_price
            FROM store_stock_movements
            WHERE movement_type = 'in'
              AND buying_price IS NOT NULL
              AND quantity > 0
            GROUP BY store_item_id
        ) avg_bp ON avg_bp.store_item_id = si.id
        {where_sql}
        ORDER BY si.department_station ASC, si.item_category ASC, si.item_name ASC, si.id ASC
        LIMIT %s OFFSET %s
        """,
        tuple(params) + (per_page, offset),
    )
    items = _store_inventory_rows_from_fetch(cursor.fetchall() or [])
    pages = max(1, (total + per_page - 1) // per_page) if total else 1
    if page > pages:
        page = pages
    return {'items': items, 'page': page, 'per_page': per_page, 'total': total, 'pages': pages}


def _store_inventory_row_dict(row):
    avg_raw = None
    if isinstance(row, dict):
        avg_raw = row.get('avg_buying_price')
        data = {
            'id': int(row.get('id') or 0),
            'reference_code': (row.get('reference_code') or '').strip(),
            'item_category': (row.get('item_category') or '').strip(),
            'item_name': (row.get('item_name') or '').strip(),
            'description': (row.get('description') or '').strip() or None,
            'measure': (row.get('measure') or '').strip(),
            'image_path': (row.get('image_path') or '').strip() or None,
            'item_status': (row.get('item_status') or 'active').strip(),
            'quantity_on_hand': int(row.get('quantity_on_hand') or 0),
            'department_station': (row.get('department_station') or '').strip(),
            'library_book_id': int(row.get('library_book_id') or 0) or None,
            'created_at': row.get('created_at'),
        }
    else:
        avg_raw = row[12] if len(row) > 12 else None
        data = {
            'id': int(row[0] or 0),
            'reference_code': (row[1] or '').strip(),
            'item_category': (row[2] or '').strip(),
            'item_name': (row[3] or '').strip(),
            'description': (row[4] or '').strip() or None,
            'measure': (row[5] or '').strip(),
            'image_path': (row[6] or '').strip() or None,
            'item_status': (row[7] or 'active').strip(),
            'quantity_on_hand': int(row[8] or 0) if len(row) > 8 else 0,
            'department_station': (row[9] or '').strip() if len(row) > 9 else '',
            'library_book_id': int(row[10] or 0) or None if len(row) > 10 else None,
            'created_at': row[11] if len(row) > 11 else None,
        }
    ca = data.get('created_at')
    if ca and hasattr(ca, 'strftime'):
        data['created_at_display'] = ca.strftime('%d %b %Y')
    elif ca:
        data['created_at_display'] = str(ca)
    else:
        data['created_at_display'] = '—'
    avg_buying_price = None
    if avg_raw is not None:
        try:
            avg_buying_price = float(avg_raw)
            if avg_buying_price < 0:
                avg_buying_price = None
        except (TypeError, ValueError):
            avg_buying_price = None
    data['avg_buying_price'] = avg_buying_price
    return data


