# Load Existing Timetable Route
@app.route('/dashboard/employee/timetable-management/register-timetable/load', methods=['POST'])
@login_required
def load_timetable():
    """Load existing timetable entries for a specific term and academic level"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    data = request.get_json()
    try:
        term_id = int(data.get('term_id', 0))
        academic_level_id = int(data.get('academic_level_id', 0))
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid ID values'}), 400
    
    if not all([term_id > 0, academic_level_id > 0]):
        return jsonify({'success': False, 'message': 'Missing required fields'}), 400
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Fetch existing timetable entries
            cursor.execute(f"""
                SELECT t.day_of_week, t.time_slot, t.teacher_id, t.subject_id,
                       e.full_name as teacher_name,
                       {_employee_staff_identity_sql('e')} AS staff_employee_number,
                       e.employee_id AS portal_employee_id,
                       s.subject_name, s.subject_code
                FROM timetables t
                LEFT JOIN employees e ON t.teacher_id = e.id
                LEFT JOIN subjects s ON s.id = t.subject_id
                WHERE t.term_id = %s AND t.academic_level_id = %s
                ORDER BY t.day_of_week, t.time_slot
            """, (term_id, academic_level_id))
            
            entries = cursor.fetchall()
            
            # Convert to list of dictionaries
            timetable_entries = []
            for entry in entries:
                if isinstance(entry, dict):
                    timetable_entries.append({
                        'day': entry.get('day_of_week', ''),
                        'time': entry.get('time_slot', ''),
                        'teacher_id': entry.get('teacher_id'),
                        'subject_id': entry.get('subject_id'),
                        'teacher_name': entry.get('teacher_name', 'Unknown'),
                        'staff_employee_number': entry.get('staff_employee_number', ''),
                        'portal_employee_id': entry.get('portal_employee_id', ''),
                        'subject_name': entry.get('subject_name', ''),
                        'subject_code': entry.get('subject_code', '') or ''
                    })
                else:
                    timetable_entries.append({
                        'day': entry[0] if len(entry) > 0 else '',
                        'time': entry[1] if len(entry) > 1 else '',
                        'teacher_id': entry[2] if len(entry) > 2 else None,
                        'subject_id': entry[3] if len(entry) > 3 else None,
                        'teacher_name': entry[4] if len(entry) > 4 else 'Unknown',
                        'staff_employee_number': entry[5] if len(entry) > 5 else '',
                        'portal_employee_id': entry[6] if len(entry) > 6 else '',
                        'subject_name': entry[7] if len(entry) > 7 else '',
                        'subject_code': (entry[8] if len(entry) > 8 else '') or ''
                    })
            
            return jsonify({
                'success': True,
                'entries': timetable_entries
            })
            
    except Exception as e:
        print(f"Error loading timetable: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Error loading timetable: {str(e)}'}), 500
    finally:
        if connection:
            connection.close()

# Check Teacher Conflict Route (Real-time)
@app.route('/dashboard/employee/timetable-management/register-timetable/check-conflict', methods=['POST'])
@login_required
def check_teacher_conflict():
    """Check if a teacher has a conflict in real-time"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    data = request.get_json()
    try:
        teacher_id = int(data.get('teacher_id', 0))
        term_id = int(data.get('term_id', 0))
        academic_level_id = int(data.get('academic_level_id', 0))
        day_of_week = data.get('day_of_week', '')
        time_slot = data.get('time_slot', '')
    except (ValueError, TypeError):
        return jsonify({'success': False, 'has_conflict': False, 'message': 'Invalid data'}), 400
    
    if not all([teacher_id > 0, term_id > 0, day_of_week, time_slot]):
        return jsonify({'success': False, 'has_conflict': False, 'message': 'Missing required fields'}), 400
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'has_conflict': False, 'message': 'Database connection failed'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Check if teacher is already assigned to another class at the same time (across all academic levels)
            # Exclude entries for the same academic level (we're editing those)
            cursor.execute("""
                SELECT t.id, t.academic_level_id, t.day_of_week, t.time_slot,
                       al.level_name, al.level_category
                FROM timetables t
                LEFT JOIN academic_levels al ON t.academic_level_id = al.id
                WHERE t.teacher_id = %s 
                  AND t.term_id = %s
                  AND t.day_of_week = %s
                  AND t.time_slot = %s
                  AND t.academic_level_id != %s
            """, (teacher_id, term_id, day_of_week, time_slot, academic_level_id))
            
            conflict = cursor.fetchone()
            
            if conflict:
                # Get teacher name
                cursor.execute("SELECT full_name FROM employees WHERE id = %s", (teacher_id,))
                teacher_result = cursor.fetchone()
                teacher_name = teacher_result.get('full_name') if isinstance(teacher_result, dict) else (teacher_result[0] if teacher_result else 'Unknown')
                
                # Get academic level name
                conflict_level = conflict.get('level_name') if isinstance(conflict, dict) else 'Unknown'
                conflict_category = conflict.get('level_category') if isinstance(conflict, dict) else ''
                
                return jsonify({
                    'success': True,
                    'has_conflict': True,
                    'message': f'Teacher {teacher_name} is already assigned to {conflict_level} ({conflict_category}) at {day_of_week} {time_slot}. A teacher can only teach one class per time period.',
                    'conflict_details': {
                        'academic_level': conflict_level,
                        'category': conflict_category,
                        'day': day_of_week,
                        'time': time_slot
                    }
                })
            
            return jsonify({
                'success': True,
                'has_conflict': False,
                'message': 'No conflict detected'
            })
            
    except Exception as e:
        print(f"Error checking conflict: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'has_conflict': False, 'message': f'Error checking conflict: {str(e)}'}), 500
    finally:
        if connection:
            connection.close()

# Auto Generate Timetable Route
def _get_current_employee_identity(cursor):
    """Resolve current session user to employee identity used for security checks."""
    employee_id_from_session = session.get('employee_id') or session.get('user_id')
    if not employee_id_from_session:
        return None
    cursor.execute("""
        SELECT id, full_name, email, password_hash
        FROM employees
        WHERE id = %s OR employee_id = %s
        LIMIT 1
    """, (employee_id_from_session, employee_id_from_session))
    row = cursor.fetchone()
    if not row:
        return None
    if isinstance(row, dict):
        return {
            'id': row.get('id'),
            'full_name': row.get('full_name', ''),
            'email': row.get('email', ''),
            'password_hash': row.get('password_hash', '')
        }
    return {
        'id': row[0],
        'full_name': row[1] if len(row) > 1 else '',
        'email': row[2] if len(row) > 2 else '',
        'password_hash': row[3] if len(row) > 3 else ''
    }


def send_timetable_overwrite_code_email(to_email, recipient_name, verification_code):
    """Send 6-digit confirmation code for timetable overwrite."""
    try:
        if not apply_mail_config_from_env_and_integration():
            print("Timetable overwrite code: SMTP not configured.")
            return False
        settings = get_school_settings()
        school_name = (settings.get('school_name') or os.environ.get('SCHOOL_NAME') or 'School').strip() or 'School'
        safe_name = (recipient_name or 'there').strip() or 'there'
        subject = f"{school_name} — Timetable overwrite confirmation code"
        html_body = f"""
        <!DOCTYPE html>
        <html><head><meta charset="UTF-8"></head>
        <body style="font-family:system-ui,sans-serif;line-height:1.6;color:#333;max-width:560px;margin:0 auto;padding:24px;">
            <p>Hello {safe_name},</p>
            <p>You requested to overwrite an existing timetable via auto-generate.</p>
            <p>Use this 6-digit code to continue:</p>
            <p style="font-size:28px;font-weight:700;letter-spacing:0.2em;color:#1e293b;">{verification_code}</p>
            <p style="color:#64748b;font-size:14px;">This code expires in 10 minutes. If this wasn't you, ignore this email.</p>
            <p style="margin-top:24px;font-size:13px;color:#94a3b8;">{school_name}</p>
        </body></html>
        """
        text_body = (
            f"Hello {safe_name},\n\n"
            f"Use this code to confirm timetable overwrite: {verification_code}\n\n"
            f"This code expires in 10 minutes. If you didn't request this, ignore it.\n\n{school_name}\n"
        )
        msg = Message(subject=subject, recipients=[to_email], html=html_body, body=text_body)
        mail.send(msg)
        return True
    except Exception as e:
        print(f"Error sending timetable overwrite code email: {e}")
        return False


@app.route('/dashboard/employee/timetable-management/register-timetable/auto-generate/request-code', methods=['POST'])
@login_required
def request_auto_generate_confirmation_code():
    """Verify password and send 6-digit code to confirm timetable overwrite."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    try:
        academic_year_id = int(data.get('academic_year_id', 0))
        term_id = int(data.get('term_id', 0))
        selected_level_id = int(data.get('academic_level_id', 0)) if data.get('academic_level_id') not in (None, '') else 0
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid ID values'}), 400

    current_password = str(data.get('current_password', '')).strip()
    if not current_password:
        return jsonify({'success': False, 'message': 'Current password is required.'}), 400
    if term_id <= 0 or academic_year_id <= 0:
        return jsonify({'success': False, 'message': 'Academic year and term are required'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            identity = _get_current_employee_identity(cursor)
            if not identity or not identity.get('password_hash'):
                return jsonify({'success': False, 'message': 'Unable to validate your account password.'}), 400
            if not check_password_hash(identity.get('password_hash'), current_password):
                return jsonify({'success': False, 'message': 'Current password is incorrect.'}), 401

            # Require overwrite confirmation only when entries already exist in scope.
            if selected_level_id > 0:
                cursor.execute("""
                    SELECT COUNT(*) AS count
                    FROM timetables
                    WHERE term_id = %s AND academic_year_id = %s AND academic_level_id = %s
                """, (term_id, academic_year_id, selected_level_id))
            else:
                cursor.execute("""
                    SELECT COUNT(*) AS count
                    FROM timetables
                    WHERE term_id = %s AND academic_year_id = %s
                """, (term_id, academic_year_id))
            row = cursor.fetchone()
            existing_count = int(row.get('count', 0)) if isinstance(row, dict) else int(row[0] if row else 0)
            if existing_count <= 0:
                return jsonify({'success': True, 'message': 'No existing timetable found. You can auto-generate directly.', 'requires_confirmation': False})

            recipient_email = (identity.get('email') or '').strip()
            if not recipient_email:
                return jsonify({'success': False, 'message': 'Your account has no email configured to receive the confirmation code.'}), 400

            code = ''.join(secrets.choice('0123456789') for _ in range(6))
            session['timetable_autogen_confirmation'] = {
                'code_hash': generate_password_hash(code),
                'academic_year_id': academic_year_id,
                'term_id': term_id,
                'academic_level_id': selected_level_id,
                'requested_by': identity.get('id'),
                'expires_at': (datetime.utcnow() + timedelta(minutes=10)).isoformat(),
                'existing_count': existing_count
            }
            session.modified = True

            sent = send_timetable_overwrite_code_email(recipient_email, identity.get('full_name') or 'User', code)
            if not sent:
                # Temporary fallback: allow confirmation flow to continue even when SMTP is unavailable.
                # Return the code once so the user can proceed without email delivery.
                return jsonify({
                    'success': True,
                    'requires_confirmation': True,
                    'delivery': 'onscreen',
                    'dev_code': code,
                    'message': 'Email delivery is currently unavailable. Use the code shown on screen to continue.',
                    'existing_count': existing_count
                })

            return jsonify({
                'success': True,
                'requires_confirmation': True,
                'message': f'Confirmation code sent to {recipient_email}.',
                'existing_count': existing_count
            })
    except Exception as e:
        print(f"Error requesting auto-generate confirmation code: {e}")
        return jsonify({'success': False, 'message': 'Error requesting confirmation code.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/timetable-management/register-timetable/auto-generate', methods=['POST'])
@login_required
def auto_generate_timetable():
    """Auto-generate timetable for all active levels or one selected level"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'

    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    try:
        academic_year_id = int(data.get('academic_year_id', 0))
        term_id = int(data.get('term_id', 0))
        selected_level_id = int(data.get('academic_level_id', 0)) if data.get('academic_level_id') not in (None, '') else 0
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid ID values'}), 400
    confirmation_code = str(data.get('confirmation_code', '')).strip()

    if term_id <= 0 or academic_year_id <= 0:
        return jsonify({'success': False, 'message': 'Academic year and term are required'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            # Validate term belongs to selected academic year
            cursor.execute("SELECT id FROM terms WHERE id = %s AND academic_year_id = %s LIMIT 1", (term_id, academic_year_id))
            if not cursor.fetchone():
                return jsonify({'success': False, 'message': 'Selected term does not belong to selected academic year.'}), 400

            # Check existing timetable in scope and enforce explicit password+6-digit code confirmation.
            if selected_level_id > 0:
                cursor.execute("""
                    SELECT COUNT(*) AS count
                    FROM timetables
                    WHERE term_id = %s AND academic_year_id = %s AND academic_level_id = %s
                """, (term_id, academic_year_id, selected_level_id))
            else:
                cursor.execute("""
                    SELECT COUNT(*) AS count
                    FROM timetables
                    WHERE term_id = %s AND academic_year_id = %s
                """, (term_id, academic_year_id))
            existing_row = cursor.fetchone()
            existing_count = int(existing_row.get('count', 0)) if isinstance(existing_row, dict) else int(existing_row[0] if existing_row else 0)

            if existing_count > 0:
                pending = session.get('timetable_autogen_confirmation') or {}
                expires_at_str = str(pending.get('expires_at') or '').strip()
                try:
                    expires_at = datetime.fromisoformat(expires_at_str) if expires_at_str else None
                except Exception:
                    expires_at = None
                is_expired = (expires_at is None) or (datetime.utcnow() > expires_at)
                pending_matches_scope = (
                    int(pending.get('academic_year_id', 0)) == academic_year_id and
                    int(pending.get('term_id', 0)) == term_id and
                    int(pending.get('academic_level_id', 0)) == selected_level_id
                )
                if not confirmation_code:
                    return jsonify({
                        'success': False,
                        'requires_confirmation': True,
                        'existing_count': existing_count,
                        'message': f'This action will overwrite {existing_count} existing timetable slot(s). Enter your current password and a 6-digit confirmation code to proceed.'
                    }), 200
                if (not pending_matches_scope) or is_expired:
                    return jsonify({
                        'success': False,
                        'requires_confirmation': True,
                        'existing_count': existing_count,
                        'message': 'Your confirmation session is missing or expired. Request a new 6-digit code and try again.'
                    }), 200
                pending_code_hash = str(pending.get('code_hash') or '')
                code_ok = False
                try:
                    code_ok = bool(pending_code_hash) and check_password_hash(pending_code_hash, confirmation_code)
                except Exception:
                    code_ok = False
                if not code_ok:
                    return jsonify({'success': False, 'message': 'Invalid confirmation code.'}), 401
                session.pop('timetable_autogen_confirmation', None)
                session.modified = True

            # Active levels (optionally scoped to one level)
            if selected_level_id > 0:
                cursor.execute("""
                    SELECT id, level_name
                    FROM academic_levels
                    WHERE id = %s AND level_status = 'active'
                    ORDER BY level_category, level_name ASC
                """, (selected_level_id,))
            else:
                cursor.execute("""
                    SELECT id, level_name
                    FROM academic_levels
                    WHERE level_status = 'active'
                    ORDER BY level_category, level_name ASC
                """)
            level_rows = cursor.fetchall() or []
            levels = []
            for row in level_rows:
                if isinstance(row, dict):
                    levels.append({'id': int(row.get('id')), 'level_name': row.get('level_name', '')})
                else:
                    levels.append({'id': int(row[0]), 'level_name': row[1] if len(row) > 1 else ''})

            if not levels:
                return jsonify({'success': False, 'message': 'No active academic levels found.'}), 400

            # Subject+teacher pairs assigned to each level via subject-class allocation
            cursor.execute(f"""
                SELECT DISTINCT
                       tsa.academic_level_id,
                       tsa.subject_id,
                       e.id AS teacher_id,
                       e.full_name,
                       {_employee_staff_identity_sql('e')} AS employee_id,
                       s.subject_code
                FROM teacher_subject_assignments tsa
                INNER JOIN employees e ON e.id = tsa.teacher_id
                LEFT JOIN subjects s ON s.id = tsa.subject_id
                WHERE e.role = 'teachers' AND e.status = 'active'
                ORDER BY tsa.academic_level_id ASC, e.full_name ASC, s.subject_code ASC
            """)
            assignment_rows = cursor.fetchall() or []
            level_pair_map = {}
            for row in assignment_rows:
                if isinstance(row, dict):
                    level_id = int(row.get('academic_level_id'))
                    subject_id = int(row.get('subject_id')) if row.get('subject_id') is not None else None
                    teacher_id = int(row.get('teacher_id'))
                    full_name = row.get('full_name', '')
                    employee_code = row.get('employee_id', '')
                    subject_code = row.get('subject_code', '')
                else:
                    level_id = int(row[0])
                    subject_id = int(row[1]) if len(row) > 1 and row[1] is not None else None
                    teacher_id = int(row[2])
                    full_name = row[3] if len(row) > 3 else ''
                    employee_code = row[4] if len(row) > 4 else ''
                    subject_code = row[5] if len(row) > 5 else ''
                if subject_id is None:
                    continue
                if level_id not in level_pair_map:
                    level_pair_map[level_id] = []
                pair_exists = any(p['teacher_id'] == teacher_id and p['subject_id'] == subject_id for p in level_pair_map[level_id])
                if not pair_exists:
                    level_pair_map[level_id].append({
                        'teacher_id': teacher_id,
                        'subject_id': subject_id,
                        'teacher_name': full_name,
                        'employee_id': employee_code,
                        'subject_code': subject_code or ''
                    })

            # Busy map from existing timetable entries in selected term
            cursor.execute("""
                SELECT day_of_week, time_slot, teacher_id
                FROM timetables
                WHERE term_id = %s
            """, (term_id,))
            busy_rows = cursor.fetchall() or []
            busy = {}
            for row in busy_rows:
                if isinstance(row, dict):
                    day = row.get('day_of_week', '')
                    time_slot = row.get('time_slot', '')
                    teacher_id = row.get('teacher_id')
                else:
                    day = row[0] if len(row) > 0 else ''
                    time_slot = row[1] if len(row) > 1 else ''
                    teacher_id = row[2] if len(row) > 2 else None
                if day and time_slot and teacher_id:
                    key = (str(day), str(time_slot))
                    if key not in busy:
                        busy[key] = set()
                    busy[key].add(int(teacher_id))

            total_slots = 0
            assigned_count = 0
            blank_count = 0
            per_level_summary = []
            generated_slots_for_level = {}
            created_by = None

            employee_id_from_session = session.get('employee_id') or session.get('user_id')
            if employee_id_from_session:
                cursor.execute("""
                    SELECT id FROM employees
                    WHERE id = %s OR employee_id = %s
                    LIMIT 1
                """, (employee_id_from_session, employee_id_from_session))
                creator_row = cursor.fetchone()
                if creator_row:
                    created_by = creator_row.get('id') if isinstance(creator_row, dict) else creator_row[0]

            # Generate for each level independently with level-eligible teachers
            for level in levels:
                level_id = int(level['id'])
                level_name = level.get('level_name', f'Level {level_id}')
                settings = _get_schedule_settings_for_level(cursor, level_id)
                days = [d.strip() for d in (settings.get('study_days') or '').split(',') if d and d.strip()]
                class_times = [ct.get('start_time') for ct in (settings.get('class_times') or []) if ct and ct.get('start_time')]
                class_times = sorted(list(dict.fromkeys([str(t) for t in class_times])))
                eligible_pairs = level_pair_map.get(level_id, [])

                level_total = len(days) * len(class_times)
                total_slots += level_total
                level_assigned = 0
                level_blank = 0
                generated_slots_for_level[level_id] = []

                if level_total == 0:
                    per_level_summary.append({
                        'level_id': level_id,
                        'level_name': level_name,
                        'profile_name': settings.get('profile_name', ''),
                        'assigned': 0,
                        'blank': 0,
                        'total': 0
                    })
                    continue

                pair_count = len(eligible_pairs)
                pointer = 0

                # Build fair-distribution targets by subject for this level.
                unique_subject_ids = sorted(list({int(p.get('subject_id')) for p in eligible_pairs if p.get('subject_id') is not None}))
                subject_target = {}
                subject_assigned_count = {}
                if unique_subject_ids:
                    base_target = level_total // len(unique_subject_ids)
                    remainder = level_total % len(unique_subject_ids)
                    for idx, subject_id in enumerate(unique_subject_ids):
                        subject_target[subject_id] = base_target + (1 if idx < remainder else 0)
                        subject_assigned_count[subject_id] = 0
                teacher_assigned_count = {}
                prev_day_subject_by_time = {}

                for day in days:
                    day_last_subject_id = None
                    current_day_subject_by_time = {}
                    for start_time in class_times:
                        key = (day, start_time)
                        occupied = busy.get(key, set())
                        selected_pair = None
                        selected_pair_idx = None

                        if pair_count > 0:
                            best_score = None
                            best_tuple = None
                            for offset in range(pair_count):
                                idx = (pointer + offset) % pair_count
                                candidate = eligible_pairs[idx]
                                candidate_teacher_id = int(candidate['teacher_id'])
                                candidate_subject_id = int(candidate['subject_id'])
                                if candidate_teacher_id in occupied:
                                    continue

                                # Lower score is better.
                                # Heavily penalize consecutive duplicate subjects in the same day.
                                score = 0
                                if day_last_subject_id is not None and candidate_subject_id == day_last_subject_id:
                                    score += 1000

                                # Penalize same subject appearing at the same time on consecutive days.
                                prev_day_subject = prev_day_subject_by_time.get(start_time)
                                if prev_day_subject is not None and candidate_subject_id == prev_day_subject:
                                    score += 120

                                # Keep subjects fairly distributed toward target counts.
                                current_subject_count = subject_assigned_count.get(candidate_subject_id, 0)
                                target_for_subject = subject_target.get(candidate_subject_id, 0)
                                if current_subject_count >= target_for_subject:
                                    score += 80 + ((current_subject_count - target_for_subject) * 20)
                                score += current_subject_count * 6

                                # Prefer spreading teacher load too.
                                score += teacher_assigned_count.get(candidate_teacher_id, 0) * 2

                                # Keep a light round-robin behavior as tie-breaker.
                                score += offset * 0.1

                                rank = (score, offset, idx)
                                if best_score is None or rank < best_score:
                                    best_score = rank
                                    best_tuple = (candidate, idx)

                            if best_tuple is not None:
                                selected_pair, selected_pair_idx = best_tuple
                                pointer = (selected_pair_idx + 1) % pair_count

                        if selected_pair:
                            selected_teacher_id = int(selected_pair['teacher_id'])
                            selected_subject_id = int(selected_pair.get('subject_id'))
                            generated_slots_for_level[level_id].append({
                                'day': day,
                                'time': start_time,
                                'teacher_id': selected_teacher_id,
                                'teacher_name': selected_pair.get('teacher_name', ''),
                                'teacher_code': selected_pair.get('employee_id', ''),
                                'subject_id': selected_subject_id,
                                'subject_code': selected_pair.get('subject_code', '')
                            })
                            if key not in busy:
                                busy[key] = set()
                            busy[key].add(selected_teacher_id)
                            day_last_subject_id = selected_subject_id
                            current_day_subject_by_time[start_time] = selected_subject_id
                            subject_assigned_count[selected_subject_id] = subject_assigned_count.get(selected_subject_id, 0) + 1
                            teacher_assigned_count[selected_teacher_id] = teacher_assigned_count.get(selected_teacher_id, 0) + 1
                            assigned_count += 1
                            level_assigned += 1
                        else:
                            current_day_subject_by_time[start_time] = None
                            blank_count += 1
                            level_blank += 1

                    prev_day_subject_by_time = current_day_subject_by_time

                per_level_summary.append({
                    'level_id': level_id,
                    'level_name': level_name,
                    'profile_name': settings.get('profile_name', ''),
                    'assigned': level_assigned,
                    'blank': level_blank,
                    'total': level_total
                })

            # Replace timetable entries for selected term/year, scoped by level when provided
            if selected_level_id > 0:
                cursor.execute("""
                    DELETE FROM timetables
                    WHERE term_id = %s AND academic_year_id = %s AND academic_level_id = %s
                """, (term_id, academic_year_id, selected_level_id))
            else:
                cursor.execute("""
                    DELETE FROM timetables
                    WHERE term_id = %s AND academic_year_id = %s
                """, (term_id, academic_year_id))

            for level in levels:
                level_id = int(level['id'])
                for slot in generated_slots_for_level.get(level_id, []):
                    if created_by:
                        cursor.execute("""
                            INSERT INTO timetables (academic_year_id, term_id, academic_level_id, day_of_week, time_slot, teacher_id, subject_id, created_by)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
                        """, (academic_year_id, term_id, level_id, slot['day'], slot['time'], slot['teacher_id'], slot.get('subject_id'), created_by))
                    else:
                        cursor.execute("""
                            INSERT INTO timetables (academic_year_id, term_id, academic_level_id, day_of_week, time_slot, teacher_id, subject_id)
                            VALUES (%s, %s, %s, %s, %s, %s, %s)
                        """, (academic_year_id, term_id, level_id, slot['day'], slot['time'], slot['teacher_id'], slot.get('subject_id')))

            connection.commit()

            return jsonify({
                'success': True,
                'message': 'Auto generation completed for all active levels.',
                'assigned_count': assigned_count,
                'blank_count': blank_count,
                'total_slots': total_slots,
                'levels_processed': len(levels),
                'level_summaries': per_level_summary
            })
    except Exception as e:
        print(f"Error auto-generating timetable: {e}")
        import traceback
        traceback.print_exc()
        if connection:
            connection.rollback()
        return jsonify({'success': False, 'message': f'Error auto-generating timetable: {str(e)}'}), 500
    finally:
        if connection:
            connection.close()

# Save Timetable Route
@app.route('/dashboard/employee/timetable-management/register-timetable/save', methods=['POST'])
@login_required
def save_timetable():
    """Save timetable assignments"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    data = request.get_json()
    if not data:
        return jsonify({'success': False, 'message': 'No data received'}), 400
    
    try:
        academic_year_id = int(data.get('academic_year_id', 0))
        term_id = int(data.get('term_id', 0))
        academic_level_id = int(data.get('academic_level_id', 0))
    except (ValueError, TypeError):
        return jsonify({
            'success': False, 
            'message': 'Invalid ID values. Please ensure Academic Year, Term, and Academic Level are selected.'
        }), 400
    
    slots = data.get('slots', [])
    
    # Debug logging
    print(f"Received data: academic_year_id={academic_year_id}, term_id={term_id}, academic_level_id={academic_level_id}, slots_count={len(slots)}")
    
    if not all([academic_year_id > 0, term_id > 0, academic_level_id > 0]):
        return jsonify({
            'success': False, 
            'message': f'Missing or invalid required fields: academic_year_id={academic_year_id}, term_id={term_id}, academic_level_id={academic_level_id}'
        }), 400
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Validate submitted slots against schedule settings for this academic level
            level_settings = _get_schedule_settings_for_level(cursor, academic_level_id)
            valid_days = set([d.strip() for d in (level_settings.get('study_days') or '').split(',') if d.strip()])
            valid_time_slots = set()
            for ct in level_settings.get('class_times', []):
                start_time = (ct or {}).get('start_time')
                if start_time:
                    valid_time_slots.add(str(start_time))

            if not valid_days or not valid_time_slots:
                return jsonify({
                    'success': False,
                    'message': 'No valid timetable schedule is configured for this level. Configure Academic Schedule Management first.'
                }), 400

            for slot in slots:
                day_name = str(slot.get('day', '')).strip()
                time_slot = str(slot.get('time', '')).strip()
                teacher_id = slot.get('teacher_id')
                subject_id = slot.get('subject_id')
                if day_name.startswith('day_'):
                    day_index = day_name.replace('day_', '')
                    day_map = {
                        '0': 'Monday', '1': 'Tuesday', '2': 'Wednesday',
                        '3': 'Thursday', '4': 'Friday', '5': 'Saturday', '6': 'Sunday'
                    }
                    day_name = day_map.get(day_index, day_name)

                if day_name not in valid_days:
                    return jsonify({'success': False, 'message': f'Invalid day "{day_name}" for this level schedule.'}), 400
                if time_slot not in valid_time_slots:
                    return jsonify({'success': False, 'message': f'Invalid class time "{time_slot}" for this level schedule.'}), 400
                if not teacher_id or not subject_id:
                    return jsonify({'success': False, 'message': 'Each timetable session must have one teacher and one subject.'}), 400
                cursor.execute("""
                    SELECT id
                    FROM teacher_subject_assignments
                    WHERE academic_level_id = %s AND teacher_id = %s AND subject_id = %s
                    LIMIT 1
                """, (academic_level_id, teacher_id, subject_id))
                if not cursor.fetchone():
                    return jsonify({'success': False, 'message': 'Invalid teacher-subject allocation for one or more slots in this level.'}), 400

            # Verify and get the actual employee ID from the database
            created_by = None
            employee_id_from_session = session.get('employee_id') or session.get('user_id')
            if employee_id_from_session:
                # Try to find the employee by ID or employee_id
                cursor.execute("""
                    SELECT id FROM employees 
                    WHERE id = %s OR employee_id = %s
                    LIMIT 1
                """, (employee_id_from_session, employee_id_from_session))
                employee_result = cursor.fetchone()
                if employee_result:
                    created_by = employee_result.get('id') if isinstance(employee_result, dict) else employee_result[0]
            # Check for teacher conflicts (same teacher, same time, same day, same term)
            for slot in slots:
                teacher_id = slot.get('teacher_id')
                day_of_week = slot.get('day')
                time_slot = slot.get('time')
                
                if not teacher_id:
                    continue
                
                # Extract day name from day key
                day_name = day_of_week
                if day_name.startswith('day_'):
                    day_index = day_name.replace('day_', '')
                    day_map = {
                        '0': 'Monday', '1': 'Tuesday', '2': 'Wednesday', 
                        '3': 'Thursday', '4': 'Friday', '5': 'Saturday', '6': 'Sunday'
                    }
                    day_name = day_map.get(day_index, day_name)
                
                # Check if teacher is already assigned to another class at the same time (across all academic levels)
                # Exclude entries for the same academic level (we'll replace those)
                cursor.execute("""
                    SELECT id, academic_level_id, day_of_week, time_slot
                    FROM timetables
                    WHERE teacher_id = %s 
                      AND term_id = %s
                      AND day_of_week = %s
                      AND time_slot = %s
                      AND academic_level_id != %s
                """, (teacher_id, term_id, day_name, time_slot, academic_level_id))
                
                conflict = cursor.fetchone()
                if conflict:
                    teacher_name = slot.get('teacher_name', 'Unknown')
                    return jsonify({
                        'success': False, 
                        'message': f'Teacher {teacher_name} is already assigned to another class at {day_name} {time_slot}. Please assign a different teacher.'
                    }), 400
            
            # Overwrite mode: replace all existing entries for this selected timetable context
            cursor.execute("""
                DELETE FROM timetables
                WHERE academic_year_id = %s
                  AND term_id = %s
                  AND academic_level_id = %s
            """, (academic_year_id, term_id, academic_level_id))
            
            # Insert new timetable entries
            inserted_count = 0
            for slot in slots:
                teacher_id = slot.get('teacher_id')
                subject_id = slot.get('subject_id')
                if not teacher_id or not subject_id:
                    continue
                
                day_of_week = slot.get('day')
                time_slot = slot.get('time')
                
                # Extract day name from day key
                day_name = day_of_week
                if day_name.startswith('day_'):
                    day_index = day_name.replace('day_', '')
                    day_map = {
                        '0': 'Monday', '1': 'Tuesday', '2': 'Wednesday', 
                        '3': 'Thursday', '4': 'Friday', '5': 'Saturday', '6': 'Sunday'
                    }
                    day_name = day_map.get(day_index, day_name)
                
                # Only include created_by if it's not None
                if created_by:
                    cursor.execute("""
                        INSERT INTO timetables (academic_year_id, term_id, academic_level_id, day_of_week, time_slot, teacher_id, subject_id, created_by)
                        VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
                    """, (academic_year_id, term_id, academic_level_id, day_name, time_slot, teacher_id, subject_id, created_by))
                else:
                    cursor.execute("""
                        INSERT INTO timetables (academic_year_id, term_id, academic_level_id, day_of_week, time_slot, teacher_id, subject_id)
                        VALUES (%s, %s, %s, %s, %s, %s, %s)
                    """, (academic_year_id, term_id, academic_level_id, day_name, time_slot, teacher_id, subject_id))
                inserted_count += 1
            
            connection.commit()
            return jsonify({
                'success': True, 
                'message': f'Timetable saved successfully! {inserted_count} time slot(s) assigned.'
            })
            
    except Exception as e:
        print(f"Error saving timetable: {e}")
        import traceback
        traceback.print_exc()
        if connection:
            connection.rollback()
        return jsonify({'success': False, 'message': f'Error saving timetable: {str(e)}'}), 500
    finally:
        if connection:
            connection.close()

# Manage Timetable Route
@app.route('/dashboard/employee/timetable-management/manage-timetable')
@login_required
def manage_timetable():
    """Manage Timetable page for academic coordinators"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_deputy_principal = user_role == 'deputy head of institution' or viewing_as_role == 'deputy head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal or is_deputy_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())
    
    # Fetch academic levels, teachers, settings, and year/term data
    connection = get_db_connection()
    academic_levels = []
    teachers = []
    teacher_subject_pairs = []
    academic_years = []
    terms = []
    settings = {
        'study_days': 'Monday,Tuesday,Wednesday,Thursday,Friday',
        'class_times': [],
        'class_duration': 60,
        'activities': []
    }
    
    if connection:
        try:
            with connection.cursor() as cursor:
                # Get academic years
                cursor.execute("""
                    SELECT id, year_name, start_date, end_date, status, is_current
                    FROM academic_years
                    WHERE status = 'active'
                    ORDER BY is_current DESC, start_date DESC
                """)
                years_results = cursor.fetchall()
                for row in years_results:
                    academic_years.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'year_name': row.get('year_name', '') if isinstance(row, dict) else row[1],
                        'is_current': row.get('is_current', 0) if isinstance(row, dict) else (row[5] if len(row) > 5 else 0)
                    })
                
                # Get terms
                cursor.execute("""
                    SELECT id, term_name, academic_year_id, is_current
                    FROM terms
                    ORDER BY academic_year_id DESC, id ASC
                """)
                terms_results = cursor.fetchall()
                for row in terms_results:
                    terms.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'term_name': row.get('term_name', '') if isinstance(row, dict) else row[1],
                        'academic_year_id': row.get('academic_year_id', 0) if isinstance(row, dict) else row[2],
                        'is_current': row.get('is_current', 0) if isinstance(row, dict) else (row[3] if len(row) > 3 else 0)
                    })
                
                # Get academic levels
                cursor.execute("""
                    SELECT id, level_category, level_name, level_description, level_status
                    FROM academic_levels
                    WHERE level_status = 'active'
                    ORDER BY level_category, level_name ASC
                """)
                academic_levels_results = cursor.fetchall()
                
                for row in academic_levels_results:
                    academic_levels.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'level_category': row.get('level_category', '') if isinstance(row, dict) else row[1],
                        'level_name': row.get('level_name', '') if isinstance(row, dict) else row[2],
                        'level_description': row.get('level_description', '') if isinstance(row, dict) else row[3],
                        'level_status': row.get('level_status', 'active') if isinstance(row, dict) else (row[4] if len(row) > 4 else 'active')
                    })
                
                # Get teachers
                cursor.execute(f"""
                    SELECT emp.id,
                           emp.full_name,
                           {_employee_staff_identity_sql('emp')} AS staff_employee_number,
                           emp.employee_id AS portal_employee_number
                    FROM employees emp
                    WHERE (emp.role = 'teachers' OR emp.role = 'teacher') AND emp.status = 'active'
                    ORDER BY emp.full_name ASC
                """)
                teachers_results = cursor.fetchall()
                for row in teachers_results:
                    teachers.append({
                        'id': row.get('id') if isinstance(row, dict) else row[0],
                        'full_name': row.get('full_name', '') if isinstance(row, dict) else row[1],
                        'staff_employee_number': row.get('staff_employee_number', '') if isinstance(row, dict) else (row[2] if len(row) > 2 else ''),
                        'portal_employee_number': row.get('portal_employee_number', '') if isinstance(row, dict) else (row[3] if len(row) > 3 else ''),
                    })

                # Teacher-subject allocation pairs by class level
                cursor.execute(f"""
                    SELECT tsa.academic_level_id, tsa.teacher_id, tsa.subject_id,
                           e.full_name,
                           {_employee_staff_identity_sql('e')} AS staff_employee_number,
                           e.employee_id AS portal_employee_number,
                           s.subject_name, s.subject_code
                    FROM teacher_subject_assignments tsa
                    INNER JOIN employees e ON e.id = tsa.teacher_id
                    INNER JOIN subjects s ON s.id = tsa.subject_id
                    WHERE e.role = 'teachers'
                      AND e.status = 'active'
                      AND COALESCE(s.status, 'active') = 'active'
                    ORDER BY tsa.academic_level_id ASC, e.full_name ASC, s.subject_name ASC
                """)
                pair_rows = cursor.fetchall() or []
                for row in pair_rows:
                    if isinstance(row, dict):
                        teacher_subject_pairs.append({
                            'academic_level_id': int(row.get('academic_level_id')),
                            'teacher_id': int(row.get('teacher_id')),
                            'subject_id': int(row.get('subject_id')),
                            'teacher_name': row.get('full_name', ''),
                            'staff_employee_number': row.get('staff_employee_number', ''),
                            'portal_employee_number': row.get('portal_employee_number', '') or '',
                            'subject_name': row.get('subject_name', ''),
                            'subject_code': row.get('subject_code', '') or ''
                        })
                    else:
                        teacher_subject_pairs.append({
                            'academic_level_id': int(row[0]),
                            'teacher_id': int(row[1]),
                            'subject_id': int(row[2]),
                            'teacher_name': row[3] if len(row) > 3 else '',
                            'staff_employee_number': row[4] if len(row) > 4 else '',
                            'portal_employee_number': row[5] if len(row) > 5 else '',
                            'subject_name': row[6] if len(row) > 6 else '',
                            'subject_code': (row[7] if len(row) > 7 else '') or ''
                        })
                
                # Keep defaults; class-specific schedule settings are resolved per selected level
                
        except Exception as e:
            print(f"Error fetching data for manage timetable: {e}")
        finally:
            if connection:
                connection.close()
    
    return render_template('dashboards/manage_timetable.html', 
                         role=user_role, 
                         academic_levels=academic_levels,
                         teachers=teachers,
                         teacher_subject_pairs=teacher_subject_pairs,
                         academic_years=academic_years,
                         terms=terms,
                         settings=settings)

# Get Timetable for Class Route
@app.route('/dashboard/employee/timetable-management/manage-timetable/get-timetable', methods=['POST'])
@login_required
def get_class_timetable():
    """Get timetable for a specific class (academic level)"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    data = request.get_json()
    try:
        academic_level_id = int(data.get('academic_level_id', 0))
        term_id = int(data.get('term_id', 0)) if data.get('term_id') else None
        academic_year_id = int(data.get('academic_year_id', 0)) if data.get('academic_year_id') else None
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid ID values'}), 400
    
    if not academic_level_id or academic_level_id <= 0:
        return jsonify({'success': False, 'message': 'Academic level is required'}), 400
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Build query based on provided filters
            query = f"""
                SELECT t.id, t.day_of_week, t.time_slot, t.teacher_id, t.subject_id, t.term_id, t.academic_level_id,
                       e.full_name as teacher_name, {_employee_staff_identity_sql('e')} AS staff_employee_number,
                       e.employee_id AS portal_employee_id,
                       al.level_name, al.level_category,
                       tr.term_name, tr.academic_year_id,
                       ay.year_name as academic_year_name,
                       s.subject_name,
                       s.subject_code
                FROM timetables t
                LEFT JOIN employees e ON t.teacher_id = e.id
                LEFT JOIN academic_levels al ON t.academic_level_id = al.id
                LEFT JOIN terms tr ON t.term_id = tr.id
                LEFT JOIN academic_years ay ON tr.academic_year_id = ay.id
                LEFT JOIN subjects s ON s.id = t.subject_id
                WHERE t.academic_level_id = %s
            """
            params = [academic_level_id]
            
            if term_id:
                query += " AND t.term_id = %s"
                params.append(term_id)
            
            if academic_year_id:
                query += " AND tr.academic_year_id = %s"
                params.append(academic_year_id)
            
            query += " ORDER BY t.day_of_week, t.time_slot"
            
            cursor.execute(query, params)
            entries = cursor.fetchall()
            
            # Get academic level info
            cursor.execute("""
                SELECT id, level_name, level_category, level_description
                FROM academic_levels
                WHERE id = %s
            """, (academic_level_id,))
            level_info = cursor.fetchone()
            
            # Convert to list of dictionaries
            timetable_entries = []
            for entry in entries:
                if isinstance(entry, dict):
                    timetable_entries.append({
                        'id': entry.get('id'),
                        'day': entry.get('day_of_week', ''),
                        'time': entry.get('time_slot', ''),
                        'teacher_id': entry.get('teacher_id'),
                        'subject_id': entry.get('subject_id'),
                        'teacher_name': entry.get('teacher_name', 'Unknown'),
                        'staff_employee_number': entry.get('staff_employee_number', ''),
                        'portal_employee_id': entry.get('portal_employee_id', ''),
                        'subject_name': entry.get('subject_name', ''),
                        'subject_code': entry.get('subject_code', ''),
                        'term_id': entry.get('term_id'),
                        'term_name': entry.get('term_name', ''),
                        'academic_year_id': entry.get('academic_year_id'),
                        'academic_year_name': entry.get('academic_year_name', '')
                    })
                else:
                    timetable_entries.append({
                        'id': entry[0] if len(entry) > 0 else None,
                        'day': entry[1] if len(entry) > 1 else '',
                        'time': entry[2] if len(entry) > 2 else '',
                        'teacher_id': entry[3] if len(entry) > 3 else None,
                        'subject_id': entry[4] if len(entry) > 4 else None,
                        'teacher_name': entry[7] if len(entry) > 7 else 'Unknown',
                        'staff_employee_number': entry[8] if len(entry) > 8 else '',
                        'portal_employee_id': entry[9] if len(entry) > 9 else '',
                        'subject_name': entry[15] if len(entry) > 15 else '',
                        'subject_code': entry[16] if len(entry) > 16 else '',
                        'term_id': entry[5] if len(entry) > 5 else None,
                        'term_name': entry[12] if len(entry) > 12 else '',
                        'academic_year_id': entry[13] if len(entry) > 13 else None,
                        'academic_year_name': entry[14] if len(entry) > 14 else ''
                    })
            
            level_data = None
            if level_info:
                if isinstance(level_info, dict):
                    level_data = {
                        'id': level_info.get('id'),
                        'level_name': level_info.get('level_name', ''),
                        'level_category': level_info.get('level_category', ''),
                        'level_description': level_info.get('level_description', '')
                    }
                else:
                    level_data = {
                        'id': level_info[0] if len(level_info) > 0 else None,
                        'level_name': level_info[1] if len(level_info) > 1 else '',
                        'level_category': level_info[2] if len(level_info) > 2 else '',
                        'level_description': level_info[3] if len(level_info) > 3 else ''
                    }

            level_settings = _get_schedule_settings_for_level(cursor, academic_level_id)
            
            return jsonify({
                'success': True,
                'academic_level': level_data,
                'entries': timetable_entries,
                'settings': {
                    'profile_name': level_settings.get('profile_name', ''),
                    'study_days': level_settings.get('study_days', ''),
                    'class_times': level_settings.get('class_times', []),
                    'class_duration': level_settings.get('class_duration', 60),
                    'activities': level_settings.get('activities', [])
                }
            })
            
    except Exception as e:
        print(f"Error loading timetable: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'success': False, 'message': f'Error loading timetable: {str(e)}'}), 500
    finally:
        if connection:
            connection.close()


TIMETABLE_RESET_NOTIFY_ROLES = (
    'curriculum coordinator',
    'deputy head of institution',
    'head of institution',
    'technician',
)


def _get_timetable_reset_stakeholder_recipients(cursor):
    """Active employees in leadership/curriculum/technician roles with a valid email."""
    placeholders = ','.join(['%s'] * len(TIMETABLE_RESET_NOTIFY_ROLES))
    cursor.execute(f"""
        SELECT full_name, email
        FROM employees
        WHERE status = 'active'
          AND email IS NOT NULL
          AND TRIM(email) <> ''
          AND role IN ({placeholders})
        ORDER BY full_name ASC
    """, TIMETABLE_RESET_NOTIFY_ROLES)
    rows = cursor.fetchall() or []
    seen = set()
    recipients = []
    for row in rows:
        if isinstance(row, dict):
            email = str(row.get('email') or '').strip()
            full_name = str(row.get('full_name') or '').strip()
        else:
            full_name = str(row[0] if len(row) > 0 else '').strip()
            email = str(row[1] if len(row) > 1 else '').strip()
        if not email:
            continue
        key = email.lower()
        if key in seen:
            continue
        seen.add(key)
        recipients.append({'email': email, 'full_name': full_name or 'Colleague'})
    return recipients


def send_timetable_reset_success_email(to_email, recipient_name, class_name, year_name, term_name, reset_by_name, deleted_count):
    """Notify one stakeholder that a class timetable was reset successfully."""
    try:
        if not apply_mail_config_from_env_and_integration():
            return False
        settings = get_school_settings()
        school_name = (settings.get('school_name') or os.environ.get('SCHOOL_NAME') or 'School').strip() or 'School'
        safe_name = (recipient_name or 'Colleague').strip() or 'Colleague'
        slots_label = f'{deleted_count} slot{"s" if deleted_count != 1 else ""}'
        reset_at = datetime.now().strftime('%d %b %Y, %I:%M %p')
        subject = f"{school_name} — Timetable reset: {class_name}"
        html_body = f"""
        <!DOCTYPE html>
        <html><head><meta charset="UTF-8"></head>
        <body style="font-family:system-ui,sans-serif;line-height:1.6;color:#333;max-width:560px;margin:0 auto;padding:24px;">
            <p>Hello {safe_name},</p>
            <p>A class timetable was reset successfully in the school management system.</p>
            <table style="width:100%;border-collapse:collapse;margin:16px 0;font-size:14px;">
                <tr><td style="padding:6px 0;color:#64748b;">Class</td><td style="padding:6px 0;font-weight:600;">{class_name}</td></tr>
                <tr><td style="padding:6px 0;color:#64748b;">Academic year</td><td style="padding:6px 0;font-weight:600;">{year_name}</td></tr>
                <tr><td style="padding:6px 0;color:#64748b;">Term</td><td style="padding:6px 0;font-weight:600;">{term_name}</td></tr>
                <tr><td style="padding:6px 0;color:#64748b;">Reset by</td><td style="padding:6px 0;font-weight:600;">{reset_by_name}</td></tr>
                <tr><td style="padding:6px 0;color:#64748b;">Entries cleared</td><td style="padding:6px 0;font-weight:600;">{slots_label}</td></tr>
                <tr><td style="padding:6px 0;color:#64748b;">When</td><td style="padding:6px 0;font-weight:600;">{reset_at}</td></tr>
            </table>
            <p style="color:#64748b;font-size:14px;">This notification was sent to curriculum coordinators, heads of institution, deputy heads, and technicians.</p>
            <p style="margin-top:24px;font-size:13px;color:#94a3b8;">{school_name}</p>
        </body></html>
        """
        text_body = (
            f"Hello {safe_name},\n\n"
            f"A class timetable was reset successfully.\n\n"
            f"Class: {class_name}\n"
            f"Academic year: {year_name}\n"
            f"Term: {term_name}\n"
            f"Reset by: {reset_by_name}\n"
            f"Entries cleared: {slots_label}\n"
            f"When: {reset_at}\n\n"
            f"{school_name}\n"
        )
        msg = Message(subject=subject, recipients=[to_email], html=html_body, body=text_body)
        mail.send(msg)
        return True
    except Exception as e:
        print(f"Error sending timetable reset success email to {to_email}: {e}")
        return False


def notify_timetable_reset_success(recipients, class_name, year_name, term_name, reset_by_name, deleted_count):
    """Email all timetable stakeholders about a successful reset."""
    if not recipients:
        return 0
    sent = 0
    for recipient in recipients:
        if send_timetable_reset_success_email(
            recipient.get('email'),
            recipient.get('full_name'),
            class_name,
            year_name,
            term_name,
            reset_by_name,
            deleted_count,
        ):
            sent += 1
    return sent


def send_timetable_reset_code_email(to_email, recipient_name, verification_code, class_name=''):
    """Send 6-digit confirmation code for timetable reset."""
    try:
        if not apply_mail_config_from_env_and_integration():
            print("Timetable reset code: SMTP not configured.")
            return False
        settings = get_school_settings()
        school_name = (settings.get('school_name') or os.environ.get('SCHOOL_NAME') or 'School').strip() or 'School'
        safe_name = (recipient_name or 'there').strip() or 'there'
        class_hint = f' for <strong>{class_name}</strong>' if class_name else ''
        subject = f"{school_name} — Timetable reset confirmation code"
        html_body = f"""
        <!DOCTYPE html>
        <html><head><meta charset="UTF-8"></head>
        <body style="font-family:system-ui,sans-serif;line-height:1.6;color:#333;max-width:560px;margin:0 auto;padding:24px;">
            <p>Hello {safe_name},</p>
            <p>You requested to reset a class timetable{class_hint}.</p>
            <p>Use this 6-digit code to confirm the reset:</p>
            <p style="font-size:28px;font-weight:700;letter-spacing:0.2em;color:#1e293b;">{verification_code}</p>
            <p style="color:#64748b;font-size:14px;">This code expires in 10 minutes. If this wasn't you, ignore this email.</p>
            <p style="margin-top:24px;font-size:13px;color:#94a3b8;">{school_name}</p>
        </body></html>
        """
        text_body = (
            f"Hello {safe_name},\n\n"
            f"Use this code to confirm timetable reset: {verification_code}\n\n"
            f"This code expires in 10 minutes. If you didn't request this, ignore it.\n\n{school_name}\n"
        )
        msg = Message(subject=subject, recipients=[to_email], html=html_body, body=text_body)
        mail.send(msg)
        return True
    except Exception as e:
        print(f"Error sending timetable reset code email: {e}")
        return False


def _validate_timetable_reset_confirmation(academic_year_id, term_id, academic_level_id, confirmation_code):
    """Validate password+email confirmation session for timetable reset."""
    if not confirmation_code:
        return False, 'Enter your current password and the 6-digit confirmation code sent to your email.'
    pending = session.get('timetable_reset_confirmation') or {}
    expires_at_str = str(pending.get('expires_at') or '').strip()
    try:
        expires_at = datetime.fromisoformat(expires_at_str) if expires_at_str else None
    except Exception:
        expires_at = None
    is_expired = (expires_at is None) or (datetime.utcnow() > expires_at)
    pending_matches_scope = (
        int(pending.get('academic_year_id', 0)) == academic_year_id and
        int(pending.get('term_id', 0)) == term_id and
        int(pending.get('academic_level_id', 0)) == academic_level_id
    )
    if not pending_matches_scope or is_expired:
        return False, 'Your confirmation session is missing or expired. Request a new 6-digit code and try again.'
    pending_code_hash = str(pending.get('code_hash') or '')
    code_ok = False
    try:
        code_ok = bool(pending_code_hash) and check_password_hash(pending_code_hash, confirmation_code)
    except Exception:
        code_ok = False
    if not code_ok:
        return False, 'Invalid confirmation code.'
    return True, ''


@app.route('/dashboard/employee/timetable-management/reset/request-code', methods=['POST'])
@login_required
def request_timetable_reset_confirmation_code():
    """Verify password and send 6-digit code to confirm timetable reset."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_deputy_principal = user_role == 'deputy head of institution' or viewing_as_role == 'deputy head of institution'

    if not (is_academic_coordinator or is_technician or is_principal or is_deputy_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    try:
        academic_level_id = int(data.get('academic_level_id', 0))
        academic_year_id = int(data.get('academic_year_id', 0))
        term_id = int(data.get('term_id', 0))
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid reset payload'}), 400

    current_password = str(data.get('current_password', '')).strip()
    if not current_password:
        return jsonify({'success': False, 'message': 'Current password is required.'}), 400
    if academic_level_id <= 0:
        return jsonify({'success': False, 'message': 'Academic level is required'}), 400
    if term_id <= 0 or academic_year_id <= 0:
        return jsonify({'success': False, 'message': 'Academic year and term are required'}), 400

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    try:
        with connection.cursor() as cursor:
            identity = _get_current_employee_identity(cursor)
            if not identity or not identity.get('password_hash'):
                return jsonify({'success': False, 'message': 'Unable to validate your account password.'}), 400
            if not check_password_hash(identity.get('password_hash'), current_password):
                return jsonify({'success': False, 'message': 'Current password is incorrect.'}), 401

            cursor.execute("""
                SELECT id FROM terms
                WHERE id = %s AND academic_year_id = %s
                LIMIT 1
            """, (term_id, academic_year_id))
            if not cursor.fetchone():
                return jsonify({'success': False, 'message': 'Selected term does not belong to selected academic year.'}), 400

            cursor.execute("SELECT level_name FROM academic_levels WHERE id = %s", (academic_level_id,))
            level_row = cursor.fetchone()
            if not level_row:
                return jsonify({'success': False, 'message': 'Academic level not found'}), 404
            class_name = level_row.get('level_name', '') if isinstance(level_row, dict) else (level_row[0] if level_row else '')

            recipient_email = (identity.get('email') or '').strip()
            if not recipient_email:
                return jsonify({'success': False, 'message': 'Your account has no email configured to receive the confirmation code.'}), 400

            code = ''.join(secrets.choice('0123456789') for _ in range(6))
            session['timetable_reset_confirmation'] = {
                'code_hash': generate_password_hash(code),
                'academic_year_id': academic_year_id,
                'term_id': term_id,
                'academic_level_id': academic_level_id,
                'requested_by': identity.get('id'),
                'expires_at': (datetime.utcnow() + timedelta(minutes=10)).isoformat(),
            }
            session.modified = True

            sent = send_timetable_reset_code_email(recipient_email, identity.get('full_name') or 'User', code, class_name)
            if not sent:
                return jsonify({
                    'success': True,
                    'delivery': 'onscreen',
                    'dev_code': code,
                    'message': 'Email delivery is currently unavailable. Use the code shown on screen to continue.',
                })

            return jsonify({
                'success': True,
                'message': f'Confirmation code sent to {recipient_email}.',
            })
    except Exception as e:
        print(f"Error requesting timetable reset confirmation code: {e}")
        return jsonify({'success': False, 'message': 'Error requesting confirmation code.'}), 500
    finally:
        connection.close()


@app.route('/dashboard/employee/timetable-management/reset', methods=['POST'])
@login_required
def reset_timetable_for_level():
    """Reset timetable by clearing all saved entries for one academic level."""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()

    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_deputy_principal = user_role == 'deputy head of institution' or viewing_as_role == 'deputy head of institution'

    if not (is_academic_coordinator or is_technician or is_principal or is_deputy_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403

    data = request.get_json() or {}
    try:
        academic_level_id = int(data.get('academic_level_id', 0))
        academic_year_id = int(data.get('academic_year_id', 0)) if data.get('academic_year_id') else None
        term_id = int(data.get('term_id', 0)) if data.get('term_id') else None
    except (ValueError, TypeError):
        return jsonify({'success': False, 'message': 'Invalid reset payload'}), 400

    confirmation_code = str(data.get('confirmation_code', '')).strip()

    if academic_level_id <= 0:
        return jsonify({'success': False, 'message': 'Academic level is required'}), 400
    if not academic_year_id or not term_id:
        return jsonify({'success': False, 'message': 'Academic year and term are required for reset.'}), 400

    code_ok, code_message = _validate_timetable_reset_confirmation(
        academic_year_id, term_id, academic_level_id, confirmation_code
    )
    if not code_ok:
        status = 401 if confirmation_code else 200
        payload = {'success': False, 'message': code_message}
        if not confirmation_code:
            payload['requires_confirmation'] = True
        return jsonify(payload), status

    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500

    deleted = 0
    notify_payload = None
    try:
        with connection.cursor() as cursor:
            cursor.execute("SELECT level_name FROM academic_levels WHERE id = %s", (academic_level_id,))
            level_row = cursor.fetchone()
            if not level_row:
                return jsonify({'success': False, 'message': 'Academic level not found'}), 404
            class_name = level_row.get('level_name', '') if isinstance(level_row, dict) else (level_row[0] if level_row else '')
            class_name = str(class_name or 'Class').strip() or 'Class'

            year_name = ''
            term_name = ''
            if term_id and academic_year_id:
                cursor.execute("""
                    SELECT ay.year_name, tr.term_name
                    FROM terms tr
                    INNER JOIN academic_years ay ON ay.id = tr.academic_year_id
                    WHERE tr.id = %s AND tr.academic_year_id = %s
                    LIMIT 1
                """, (term_id, academic_year_id))
                period_row = cursor.fetchone()
                if not period_row:
                    return jsonify({'success': False, 'message': 'Selected term does not belong to selected academic year.'}), 400
                if isinstance(period_row, dict):
                    year_name = str(period_row.get('year_name') or '').strip()
                    term_name = str(period_row.get('term_name') or '').strip()
                else:
                    year_name = str(period_row[0] if len(period_row) > 0 else '').strip()
                    term_name = str(period_row[1] if len(period_row) > 1 else '').strip()

            identity = _get_current_employee_identity(cursor)
            reset_by_name = str((identity or {}).get('full_name') or 'A staff member').strip() or 'A staff member'
            stakeholder_recipients = _get_timetable_reset_stakeholder_recipients(cursor)

            if term_id and academic_year_id:
                cursor.execute("""
                    DELETE FROM timetables
                    WHERE academic_level_id = %s
                      AND term_id = %s
                """, (academic_level_id, term_id))
            elif term_id:
                cursor.execute("""
                    DELETE FROM timetables
                    WHERE academic_level_id = %s
                      AND term_id = %s
                """, (academic_level_id, term_id))
            elif academic_year_id:
                cursor.execute("""
                    DELETE FROM timetables
                    WHERE academic_level_id = %s
                      AND academic_year_id = %s
                """, (academic_level_id, academic_year_id))
            else:
                cursor.execute("DELETE FROM timetables WHERE academic_level_id = %s", (academic_level_id,))
            deleted = cursor.rowcount or 0
            connection.commit()

            notify_payload = {
                'recipients': stakeholder_recipients,
                'class_name': class_name,
                'year_name': year_name or '—',
                'term_name': term_name or '—',
                'reset_by_name': reset_by_name,
                'deleted_count': deleted,
            }

        session.pop('timetable_reset_confirmation', None)
        session.modified = True

        if notify_payload:
            try:
                notify_timetable_reset_success(**notify_payload)
            except Exception as mail_err:
                print(f"Timetable reset success notification error: {mail_err}")

        return jsonify({
            'success': True,
            'message': f'Timetable reset complete. Cleared {deleted} timetable entr{"y" if deleted == 1 else "ies"}.'
        })
    except Exception as e:
        print(f"Error resetting timetable: {e}")
        try:
            connection.rollback()
        except Exception:
            pass
        return jsonify({'success': False, 'message': 'Error resetting timetable.'}), 500
    finally:
        connection.close()

# Get Teacher Conflicts Route
@app.route('/dashboard/employee/timetable-management/get-teacher-conflicts', methods=['POST'])
@login_required
def get_teacher_conflicts():
    """Get all teachers who are busy at a specific day/time (assigned to other classes)"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    is_deputy_principal = user_role == 'deputy head of institution' or viewing_as_role == 'deputy head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal or is_deputy_principal):
        return jsonify({'success': False, 'message': 'Permission denied'}), 403
    
    data = request.get_json()
    day = data.get('day')
    time = data.get('time')
    term_id = data.get('term_id')
    exclude_class_id = data.get('exclude_class_id')  # Current class being edited
    
    if not day or not time:
        return jsonify({'success': False, 'message': 'Day and time are required'}), 400
    
    connection = get_db_connection()
    if not connection:
        return jsonify({'success': False, 'message': 'Database connection failed'}), 500
    
    try:
        with connection.cursor() as cursor:
            # Get all teachers assigned to this day/time in other classes (for the same term)
            query = """
                SELECT t.teacher_id, e.full_name as teacher_name, al.level_name as class_name
                FROM timetables t
                LEFT JOIN employees e ON t.teacher_id = e.id
                LEFT JOIN academic_levels al ON t.academic_level_id = al.id
                WHERE t.day_of_week = %s AND t.time_slot = %s
            """
            params = [day, time]
            
            if term_id:
                query += " AND t.term_id = %s"
                params.append(term_id)
            
            if exclude_class_id:
                query += " AND t.academic_level_id != %s"
                params.append(exclude_class_id)
            
            cursor.execute(query, params)
            conflicts = cursor.fetchall()
            
            # Convert to dictionary: teacher_id -> class_name
            conflict_dict = {}
            for row in conflicts:
                if isinstance(row, dict):
                    teacher_id = row.get('teacher_id')
                    class_name = row.get('class_name', 'Another class')
                else:
                    teacher_id = row[0]
                    class_name = row[2] if len(row) > 2 else 'Another class'
                
                if teacher_id:
                    conflict_dict[teacher_id] = class_name
            
            return jsonify({
                'success': True,
                'conflicts': conflict_dict
            })
            
    except Exception as e:
        print(f"Error checking teacher conflicts: {e}")
        return jsonify({'success': False, 'message': f'Error: {str(e)}'}), 500
    finally:
        if connection:
            connection.close()

# Timetable Analytics Route
@app.route('/dashboard/employee/timetable-management/timetable-analytics')
@login_required
def timetable_analytics():
    """Timetable Analytics page for academic coordinators"""
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    
    is_academic_coordinator = user_role == 'curriculum coordinator' or viewing_as_role == 'curriculum coordinator'
    is_technician = user_role == 'technician'
    is_principal = user_role == 'head of institution' or viewing_as_role == 'head of institution'
    
    if not (is_academic_coordinator or is_technician or is_principal):
        flash('You do not have permission to access this page.', 'error')
        return redirect(employee_dashboard_path())

    level_analytics = []
    subject_analytics = []
    teacher_analytics = []
    summary = {
        'total_slots': 0,
        'total_levels': 0,
        'total_subjects': 0,
        'total_teachers': 0
    }
    current_context = {
        'academic_year_id': None,
        'academic_year_name': '',
        'term_id': None,
        'term_name': ''
    }

    connection = get_db_connection()
    if connection:
        try:
            with connection.cursor() as cursor:
                cursor.execute("""
                    SELECT ay.id AS academic_year_id, ay.year_name, t.id AS term_id, t.term_name
                    FROM academic_years ay
                    INNER JOIN terms t ON t.academic_year_id = ay.id
                    WHERE COALESCE(ay.is_current, 0) = 1
                      AND COALESCE(t.is_current, 0) = 1
                    LIMIT 1
                """)
                context_row = cursor.fetchone()
                if context_row:
                    if isinstance(context_row, dict):
                        current_context['academic_year_id'] = context_row.get('academic_year_id')
                        current_context['academic_year_name'] = context_row.get('year_name', '')
                        current_context['term_id'] = context_row.get('term_id')
                        current_context['term_name'] = context_row.get('term_name', '')
                    else:
                        current_context['academic_year_id'] = context_row[0] if len(context_row) > 0 else None
                        current_context['academic_year_name'] = context_row[1] if len(context_row) > 1 else ''
                        current_context['term_id'] = context_row[2] if len(context_row) > 2 else None
                        current_context['term_name'] = context_row[3] if len(context_row) > 3 else ''

                # Fallback to latest active term if current flags are missing
                if not current_context['term_id']:
                    cursor.execute("""
                        SELECT ay.id AS academic_year_id, ay.year_name, t.id AS term_id, t.term_name
                        FROM terms t
                        INNER JOIN academic_years ay ON ay.id = t.academic_year_id
                        WHERE COALESCE(ay.status, 'active') = 'active'
                          AND COALESCE(t.status, 'active') = 'active'
                        ORDER BY ay.start_date DESC, t.start_date DESC, t.id DESC
                        LIMIT 1
                    """)
                    fallback_row = cursor.fetchone()
                    if fallback_row:
                        if isinstance(fallback_row, dict):
                            current_context['academic_year_id'] = fallback_row.get('academic_year_id')
                            current_context['academic_year_name'] = fallback_row.get('year_name', '')
                            current_context['term_id'] = fallback_row.get('term_id')
                            current_context['term_name'] = fallback_row.get('term_name', '')
                        else:
                            current_context['academic_year_id'] = fallback_row[0] if len(fallback_row) > 0 else None
                            current_context['academic_year_name'] = fallback_row[1] if len(fallback_row) > 1 else ''
                            current_context['term_id'] = fallback_row[2] if len(fallback_row) > 2 else None
                            current_context['term_name'] = fallback_row[3] if len(fallback_row) > 3 else ''

                term_id = current_context['term_id']
                if term_id:
                    cursor.execute("""
                        SELECT
                            al.id AS academic_level_id,
                            al.level_name,
                            COUNT(DISTINCT CONCAT(t.day_of_week, '|', t.time_slot)) AS scheduled_slots,
                            COUNT(DISTINCT tsa.subject_id) AS allocated_subjects,
                            COUNT(DISTINCT tsa.teacher_id) AS allocated_teachers
                        FROM academic_levels al
                        LEFT JOIN timetables t
                               ON t.academic_level_id = al.id
                              AND t.term_id = %s
                        LEFT JOIN teacher_subject_assignments tsa
                               ON tsa.academic_level_id = al.id
                        WHERE COALESCE(al.level_status, 'active') = 'active'
                        GROUP BY al.id, al.level_name
                        ORDER BY al.level_category, al.level_name
                    """, (term_id,))
                    for row in (cursor.fetchall() or []):
                        if isinstance(row, dict):
                            level_analytics.append({
                                'academic_level_id': row.get('academic_level_id'),
                                'level_name': row.get('level_name', ''),
                                'scheduled_slots': int(row.get('scheduled_slots') or 0),
                                'allocated_subjects': int(row.get('allocated_subjects') or 0),
                                'allocated_teachers': int(row.get('allocated_teachers') or 0)
                            })
                        else:
                            level_analytics.append({
                                'academic_level_id': row[0] if len(row) > 0 else None,
                                'level_name': row[1] if len(row) > 1 else '',
                                'scheduled_slots': int(row[2] or 0) if len(row) > 2 else 0,
                                'allocated_subjects': int(row[3] or 0) if len(row) > 3 else 0,
                                'allocated_teachers': int(row[4] or 0) if len(row) > 4 else 0
                            })

                    cursor.execute("""
                        SELECT
                            s.id AS subject_id,
                            s.subject_name,
                            COALESCE(s.subject_code, '') AS subject_code,
                            COUNT(DISTINCT tsa.academic_level_id) AS levels_allocated,
                            COUNT(DISTINCT tsa.teacher_id) AS teachers_allocated,
                            COUNT(DISTINCT CASE WHEN t.term_id = %s THEN CONCAT(t.academic_level_id, '|', t.day_of_week, '|', t.time_slot) END) AS scheduled_slots
                        FROM subjects s
                        LEFT JOIN teacher_subject_assignments tsa ON tsa.subject_id = s.id
                        LEFT JOIN timetables t
                               ON t.subject_id = s.id
                              AND t.term_id = %s
                        WHERE COALESCE(s.status, 'active') = 'active'
                        GROUP BY s.id, s.subject_name, s.subject_code
                        HAVING levels_allocated > 0 OR teachers_allocated > 0 OR scheduled_slots > 0
                        ORDER BY s.subject_name ASC
                    """, (term_id, term_id))
                    for row in (cursor.fetchall() or []):
                        if isinstance(row, dict):
                            subject_analytics.append({
                                'subject_id': row.get('subject_id'),
                                'subject_name': row.get('subject_name', ''),
                                'subject_code': row.get('subject_code', ''),
                                'levels_allocated': int(row.get('levels_allocated') or 0),
                                'teachers_allocated': int(row.get('teachers_allocated') or 0),
                                'scheduled_slots': int(row.get('scheduled_slots') or 0)
                            })
                        else:
                            subject_analytics.append({
                                'subject_id': row[0] if len(row) > 0 else None,
                                'subject_name': row[1] if len(row) > 1 else '',
                                'subject_code': row[2] if len(row) > 2 else '',
                                'levels_allocated': int(row[3] or 0) if len(row) > 3 else 0,
                                'teachers_allocated': int(row[4] or 0) if len(row) > 4 else 0,
                                'scheduled_slots': int(row[5] or 0) if len(row) > 5 else 0
                            })

                    cursor.execute(f"""
                        SELECT
                            e.id AS teacher_id,
                            e.full_name,
                            {_employee_staff_identity_sql('e')} AS staff_employee_number,
                            COUNT(DISTINCT tsa.academic_level_id) AS levels_allocated,
                            COUNT(DISTINCT tsa.subject_id) AS subjects_allocated,
                            COUNT(DISTINCT CASE WHEN t.term_id = %s THEN CONCAT(t.academic_level_id, '|', t.day_of_week, '|', t.time_slot) END) AS scheduled_slots
                        FROM employees e
                        LEFT JOIN teacher_subject_assignments tsa ON tsa.teacher_id = e.id
                        LEFT JOIN timetables t
                               ON t.teacher_id = e.id
                              AND t.term_id = %s
                        WHERE (e.role = 'teachers' OR e.role = 'teacher')
                          AND COALESCE(e.status, 'active') = 'active'
                        GROUP BY e.id, e.full_name, {_employee_staff_identity_sql('e')}
                        HAVING levels_allocated > 0 OR subjects_allocated > 0 OR scheduled_slots > 0
                        ORDER BY e.full_name ASC
                    """, (term_id, term_id))
                    for row in (cursor.fetchall() or []):
                        if isinstance(row, dict):
                            teacher_analytics.append({
                                'teacher_id': row.get('teacher_id'),
                                'full_name': row.get('full_name', ''),
                                'staff_employee_number': row.get('staff_employee_number', ''),
                                'levels_allocated': int(row.get('levels_allocated') or 0),
                                'subjects_allocated': int(row.get('subjects_allocated') or 0),
                                'scheduled_slots': int(row.get('scheduled_slots') or 0)
                            })
                        else:
                            teacher_analytics.append({
                                'teacher_id': row[0] if len(row) > 0 else None,
                                'full_name': row[1] if len(row) > 1 else '',
                                'staff_employee_number': row[2] if len(row) > 2 else '',
                                'levels_allocated': int(row[3] or 0) if len(row) > 3 else 0,
                                'subjects_allocated': int(row[4] or 0) if len(row) > 4 else 0,
                                'scheduled_slots': int(row[5] or 0) if len(row) > 5 else 0
                            })

                summary['total_levels'] = len(level_analytics)
                summary['total_subjects'] = len(subject_analytics)
                summary['total_teachers'] = len(teacher_analytics)
                summary['total_slots'] = sum(int(x.get('scheduled_slots', 0) or 0) for x in level_analytics)
        except Exception as e:
            print(f"Error loading timetable analytics: {e}")
        finally:
            connection.close()

    return render_template(
        'dashboards/timetable_analytics.html',
        role=user_role,
        summary=summary,
        current_context=current_context,
        level_analytics=level_analytics,
        subject_analytics=subject_analytics,
        teacher_analytics=teacher_analytics
    )

