def _finance_overview_has_access():
    user_role = session.get('role', '').lower()
    viewing_as_role = session.get('viewing_as_employee_role', '').lower()
    is_technician = user_role == 'technician'
    is_secretary = user_role == 'secretary' or viewing_as_role == 'secretary'
    has_view = check_permission_or_role('view_student_fees', ['accountant', 'head of institution'])
    has_manage = check_permission_or_role('manage_fees', ['accountant', 'head of institution'])
    return is_technician or has_view or has_manage or is_secretary


def _finance_overview_class_filter_options(cursor):
    options = []
    cursor.execute(
        """
        SELECT level_name FROM academic_levels
        WHERE level_status = 'active'
        ORDER BY level_name ASC
        """
    )
    for r in cursor.fetchall() or []:
        ln = r.get('level_name') if isinstance(r, dict) else r[0]
        if ln:
            options.append(ln)
    return options


def _finance_overview_payment_maps(cursor, student_ids):
    payment_counts = {}
    latest_payment = {}
    if not student_ids:
        return payment_counts, latest_payment
    ph = ','.join(['%s'] * len(student_ids))
    try:
        cursor.execute(
            f"""
            SELECT student_id, COUNT(*) AS c
            FROM student_payments
            WHERE student_id IN ({ph})
            GROUP BY student_id
            """,
            student_ids,
        )
        for row in cursor.fetchall() or []:
            payment_counts[row.get('student_id') if isinstance(row, dict) else row[0]] = int(
                (row.get('c') if isinstance(row, dict) else row[1]) or 0
            )
    except Exception as e:
        print(f"_finance_overview_payment_maps counts: {e}")
    try:
        cursor.execute(
            f"""
            SELECT id, student_id, payment_date
            FROM student_payments
            WHERE student_id IN ({ph})
            ORDER BY payment_date DESC, id DESC
            """,
            student_ids,
        )
        for row in cursor.fetchall() or []:
            sid = row.get('student_id') if isinstance(row, dict) else row[1]
            pid = row.get('id') if isinstance(row, dict) else row[0]
            if sid not in latest_payment:
                latest_payment[sid] = pid
    except Exception as e:
        print(f"_finance_overview_payment_maps latest: {e}")
    return payment_counts, latest_payment


def _finance_overview_row_from_student(cursor, row, cy, ct, level_by_name, payment_counts, latest_payment):
    student_id = row.get('student_id') if isinstance(row, dict) else row[0]
    full_name = row.get('full_name') if isinstance(row, dict) else row[1]
    student_category = row.get('student_category') if isinstance(row, dict) else (row[2] if len(row) > 2 else '')
    current_grade = row.get('current_grade') if isinstance(row, dict) else (row[3] if len(row) > 3 else '')
    current_grade = (current_grade or '') or ''
    level_id = level_by_name.get(current_grade) if current_grade else None
    fs = None
    amounts = None
    if level_id:
        fs = _reports_select_fee_structure_for_student(cursor, level_id, student_category, cy, ct)
        if fs:
            amounts = _reports_compute_student_fee_balance(cursor, student_id, student_category, level_id, fs)
    if amounts:
        bal = amounts['balance']
        total_amt = amounts['total_amount']
        paid_amt = amounts['paid_amount']
    else:
        bal = None
        total_amt = None
        paid_amt = None
    return {
        'student_id': student_id,
        'full_name': full_name or '—',
        'class_name': current_grade or '—',
        'total_amount': total_amt,
        'paid_amount': paid_amt,
        'balance': bal,
        'payment_count': payment_counts.get(student_id, 0),
        'latest_payment_id': latest_payment.get(student_id),
    }


def _fetch_finance_overview_students_page(cursor, page=1, per_page=50, q='', grade='', sort='name_asc'):
    per_page = max(1, min(int(per_page or 50), 100))
    page = max(1, int(page or 1))
    offset = (page - 1) * per_page
    q = (q or '').strip()
    grade = (grade or '').strip()
    order_col, order_dir = FINANCE_OVERVIEW_LIST_SORTS.get(sort, FINANCE_OVERVIEW_LIST_SORTS['name_asc'])
    if order_col == 'full_name':
        order_sql = f's.full_name {order_dir}'
    elif order_col == 'current_grade':
        order_sql = f's.current_grade {order_dir}, s.full_name ASC'
    else:
        order_sql = f's.student_id {order_dir}'

    cy, ct = _reports_current_year_term_ids(cursor)
    level_by_name = {}
    cursor.execute("SELECT id, level_name FROM academic_levels WHERE level_status = 'active'")
    for r in cursor.fetchall() or []:
        lid = r.get('id') if isinstance(r, dict) else r[0]
        ln = r.get('level_name') if isinstance(r, dict) else r[1]
        if ln:
            level_by_name[ln] = lid

    where = ["s.status = 'in session'"]
    params = []
    if grade:
        where.append('s.current_grade = %s')
        params.append(grade)
    if q:
        like = '%' + q + '%'
        where.append('(s.full_name LIKE %s OR s.student_id LIKE %s OR s.current_grade LIKE %s)')
        params.extend([like, like, like])
    where_sql = ' WHERE ' + ' AND '.join(where)

    cursor.execute(f'SELECT COUNT(*) AS c FROM students s{where_sql}', tuple(params))
    count_row = cursor.fetchone()
    total = int((count_row.get('c') if isinstance(count_row, dict) else count_row[0]) or 0)

    cursor.execute(
        f"""
        SELECT s.student_id, s.full_name, s.student_category, s.current_grade
        FROM students s
        {where_sql}
        ORDER BY {order_sql}
        LIMIT %s OFFSET %s
        """,
        tuple(params) + (per_page, offset),
    )
    raw = cursor.fetchall() or []
    sids = []
    for r in raw:
        sid = r.get('student_id') if isinstance(r, dict) else r[0]
        if sid:
            sids.append(sid)
    payment_counts, latest_payment = _finance_overview_payment_maps(cursor, sids)
    students = [
        _finance_overview_row_from_student(cursor, r, cy, ct, level_by_name, payment_counts, latest_payment)
        for r in raw
    ]
    pages = max(1, (total + per_page - 1) // per_page) if total else 1
    if page > pages:
        page = pages
    return {'students': students, 'page': page, 'per_page': per_page, 'total': total, 'pages': pages}


def _fetch_finance_overview_summary_payload(cursor):
    """School-wide totals + per-class roll-up (computed once per request)."""
    bundle = _finance_overview_student_fee_bundle(cursor)
    summaries = _finance_overview_class_summaries(bundle.get('student_rows') or [])
    return {
        'totals': {
            'student_count': len(bundle.get('student_rows') or []),
            'total_outstanding': bundle.get('total_outstanding', 0.0),
            'sum_total_amount': bundle.get('sum_total_amount', 0.0),
            'sum_paid_amount': bundle.get('sum_paid_amount', 0.0),
        },
        'class_summaries': summaries,
    }


def _build_class_exam_performance_bundle(cursor, lev, term_id=None, academic_year_id=None):
    """Exam aggregates for one class (scaled marks /100 using exam subject settings)."""
    level_name = lev['level_name']
    subject_stats = {}
    all_marks_for_class = []
    students_in_class = set()
    try:
        ensure_subject_exam_total_marks_column(cursor)
        cursor.execute(
            """
            SELECT e.id, e.exam_name, e.subject_id, e.exam_date,
                   s.subject_name, s.subject_code, s.exam_total_marks, s.exam_display_order,
                   ay.year_name, t.term_name
            FROM exams e
            LEFT JOIN subjects s ON e.subject_id = s.id
            LEFT JOIN academic_years ay ON e.academic_year_id = ay.id
            LEFT JOIN terms t ON e.term_id = t.id
            WHERE e.academic_level_id = %s
            AND (%s IS NULL OR e.term_id = %s)
            AND (%s IS NULL OR e.academic_year_id = %s)
            ORDER BY COALESCE(s.exam_display_order, 1000000000) ASC,
                     s.subject_name ASC,
                     e.exam_name ASC
            """,
            (lev['id'], term_id, term_id, academic_year_id, academic_year_id),
        )
        exam_rows = cursor.fetchall() or []
        for ex in exam_rows:
            exam_id = ex.get('id') if isinstance(ex, dict) else ex[0]
            subject_id = ex.get('subject_id') if isinstance(ex, dict) else ex[2]
            if isinstance(ex, dict):
                subject_name = ex.get('subject_name') or ex.get('subject_code') or 'N/A'
                subject_etm = ex.get('exam_total_marks')
                subject_edo = ex.get('exam_display_order')
            else:
                subject_name = ex[4] or ex[5] or 'N/A'
                subject_etm = ex[6] if len(ex) > 6 else None
                subject_edo = ex[7] if len(ex) > 7 else None
            if not subject_id:
                continue
            if subject_id not in subject_stats:
                try:
                    edo_n = int(subject_edo) if subject_edo is not None and str(subject_edo).strip().isdigit() else (int(subject_edo) if isinstance(subject_edo, int) else 10**9)
                except (TypeError, ValueError):
                    edo_n = 10**9
                subject_stats[subject_id] = {
                    'subject_name': subject_name,
                    'exam_total_marks': subject_etm,
                    'exam_display_order': edo_n,
                    'exam_ids': [],
                    'marks': [],
                    'mean': 0,
                    'min': None,
                    'max': None,
                    'count': 0,
                    'pass_count': 0,
                    'pass_rate': 0,
                }
            subject_stats[subject_id]['exam_ids'].append(exam_id)
            cursor.execute(
                """
                SELECT sm.student_id, sm.marks, sub.exam_total_marks
                FROM student_marks sm
                INNER JOIN students st ON sm.student_id = st.student_id
                INNER JOIN subjects sub ON sm.subject_id = sub.id
                WHERE sm.exam_id = %s AND st.current_grade = %s
                """,
                (exam_id, level_name),
            )
            for mr in cursor.fetchall() or []:
                sid = mr.get('student_id') if isinstance(mr, dict) else mr[0]
                mval = mr.get('marks') if isinstance(mr, dict) else mr[1]
                etm = mr.get('exam_total_marks') if isinstance(mr, dict) else (mr[2] if len(mr) > 2 else None)
                if etm is None:
                    etm = subject_stats[subject_id].get('exam_total_marks')
                scaled = raw_mark_to_percentage(mval, etm)
                if scaled is not None:
                    subject_stats[subject_id]['marks'].append(scaled)
                    all_marks_for_class.append(scaled)
                    students_in_class.add(sid)
                    if scaled >= 50:
                        subject_stats[subject_id]['pass_count'] += 1
        subject_list = []

        def _class_exam_subject_sort_key(kv):
            sid_i, sd = kv
            try:
                eo = int(sd.get('exam_display_order') or 10**9)
            except (TypeError, ValueError):
                eo = 10**9
            try:
                sid_key = int(sid_i)
            except (TypeError, ValueError):
                sid_key = 0
            return (eo, str(sd.get('subject_name') or '').lower(), sid_key)

        for _sid, sdata in sorted(subject_stats.items(), key=_class_exam_subject_sort_key):
            marks = sdata['marks']
            if marks:
                sdata['mean'] = round_mark_display(sum(marks) / len(marks)) or 0
                sdata['min'] = round_mark_display(min(marks))
                sdata['max'] = round_mark_display(max(marks))
                sdata['count'] = len(marks)
                sdata['pass_rate'] = round_mark_display(100 * sdata['pass_count'] / len(marks)) if marks else 0
            else:
                sdata['mean'] = 0
                sdata['min'] = None
                sdata['max'] = None
                sdata['count'] = 0
                sdata['pass_rate'] = 0
            subject_list.append(
                {
                    'subject_name': sdata['subject_name'],
                    'mean': sdata['mean'],
                    'min': sdata['min'],
                    'max': sdata['max'],
                    'count': sdata['count'],
                    'pass_rate': sdata['pass_rate'],
                }
            )
        class_mean = (
            round_mark_display(sum(all_marks_for_class) / len(all_marks_for_class)) if all_marks_for_class else 0
        )
        pass_n = sum(1 for m in all_marks_for_class if m >= 50)
        class_pass_rate = (
            round_mark_display(100 * pass_n / len(all_marks_for_class)) if all_marks_for_class else 0
        )
        class_max = round_mark_display(max(all_marks_for_class)) if all_marks_for_class else None
        class_min = round_mark_display(min(all_marks_for_class)) if all_marks_for_class else None
        return {
            'subjects': subject_list,
            'class_mean': class_mean,
            'class_max': class_max,
            'class_min': class_min,
            'class_pass_rate': class_pass_rate,
            'student_count': len(students_in_class),
            'total_marks_entries': len(all_marks_for_class),
        }
    except Exception as e:
        print(f"_build_class_exam_performance_bundle: {e}")
        return {
            'subjects': [],
            'class_mean': 0,
            'class_max': None,
            'class_min': None,
            'class_pass_rate': 0,
            'student_count': 0,
            'total_marks_entries': 0,
        }


def _term_date_bounds(cursor, term_id):
    if not term_id:
        return None, None
    cursor.execute("SELECT start_date, end_date FROM terms WHERE id = %s", (term_id,))
    r = cursor.fetchone()
    if not r:
        return None, None
    a = r.get('start_date') if isinstance(r, dict) else r[0]
    b = r.get('end_date') if isinstance(r, dict) else r[1]
    return a, b


def _coerce_academic_report_filters(f):
    """Normalize academic report filters from JSON POST or GET query args."""
    if not f:
        f = {}
    out = {}
    for key in ('academic_year_id', 'term_id', 'level_id', 'teacher_id'):
        v = f.get(key)
        if v in (None, '', 'null'):
            out[key] = None
        else:
            try:
                out[key] = int(v)
            except (TypeError, ValueError):
                out[key] = None
    sid = f.get('student_id')
    if sid is None or sid == '' or sid == 'null':
        out['student_id'] = None
    else:
        out['student_id'] = str(sid).strip() or None
    # Exams: support multi-select exam_names (preferred) and legacy single exam_name.
    exam_names_raw = f.get('exam_names', None)
    if exam_names_raw in (None, '', 'null'):
        exam_names = None
    elif isinstance(exam_names_raw, list):
        exam_names = [str(x).strip() for x in exam_names_raw if str(x).strip()]
    else:
        # Accept comma-separated strings or single value
        s = str(exam_names_raw).strip()
        if not s:
            exam_names = None
        else:
            exam_names = [p.strip() for p in s.split(',') if p.strip()]

    exam_name = f.get('exam_name')
    if (exam_name is None or exam_name == '' or exam_name == 'null') and exam_names:
        exam_name = exam_names[0]
    if exam_name is None or exam_name == '' or exam_name == 'null':
        out['exam_name'] = None
    else:
        out['exam_name'] = str(exam_name).strip() or None
    out['exam_names'] = exam_names
    et = f.get('exam_type')
    if et is None or et == '' or et == 'null':
        out['exam_type'] = None
    else:
        out['exam_type'] = str(et).strip() or None
    for dk in ('date_from', 'date_to'):
        dv = f.get(dk)
        if dv is None or dv == '' or dv == 'null':
            out[dk] = None
        else:
            out[dk] = str(dv).strip() or None
    tv = (f.get('timetable_view') or '').strip().lower()
    out['timetable_view'] = tv if tv in ('student', 'teacher') else 'student'
    lv = (f.get('level_view') or 'individual').strip().lower()
    out['level_view'] = lv if lv in ('individual', 'combined') else 'individual'
    return out


def _sql_filter_academic_level_ids(q, params, column, level_ids):
    """Append AND filter for one or many academic_level_id values."""
    if not level_ids:
        return q, params
    if len(level_ids) == 1:
        q += f" AND {column} = %s"
        params.append(level_ids[0])
    else:
        ph = ','.join(['%s'] * len(level_ids))
        q += f" AND {column} IN ({ph})"
        params.extend(level_ids)
    return q, params


def _sql_filter_student_current_grade(q, params, level_ids, table_alias=None):
    """Append AND filter matching students.current_grade to level name(s)."""
    if not level_ids:
        return q, params
    prefix = f"{table_alias}." if table_alias else ""
    if len(level_ids) == 1:
        q += (
            f" AND {prefix}current_grade = (SELECT level_name FROM academic_levels"
            f" WHERE id = %s LIMIT 1)"
        )
        params.append(level_ids[0])
    else:
        ph = ','.join(['%s'] * len(level_ids))
        q += (
            f" AND {prefix}current_grade IN (SELECT level_name FROM academic_levels"
            f" WHERE id IN ({ph}))"
        )
        params.extend(level_ids)
    return q, params


def _resolve_academic_report_level_scope(cursor, level_view, level_id):
    """Resolve level_ids for academic reports (individual class or combined group)."""
    ensure_academic_level_combination_tables(cursor)
    combos = fetch_academic_level_combinations(cursor)
    cursor.execute("""
        SELECT id, level_name, level_category, level_code
        FROM academic_levels
        WHERE level_status = 'active'
        ORDER BY level_name
    """)
    levels = []
    for row in cursor.fetchall() or []:
        levels.append({
            'id': row.get('id') if isinstance(row, dict) else row[0],
            'level_name': row.get('level_name') if isinstance(row, dict) else row[1],
            'level_category': row.get('level_category') if isinstance(row, dict) else (row[2] if len(row) > 2 else ''),
            'level_code': row.get('level_code') if isinstance(row, dict) else (row[3] if len(row) > 3 else ''),
        })
    return _exam_analytics_resolve_level_scope(level_view, level_id, levels, combos)


def _academic_report_home_class_value(row):
    """Learner's enrolled class (students.current_grade) for combined cohort tables."""
    if not isinstance(row, dict):
        return ''
    return str(row.get('home_class') or row.get('current_grade') or '').strip()


def _academic_report_cols_with_home_class(cols, is_combined_level, insert_after='full_name'):
    """Add home_class column when the report merges multiple levels into one roster."""
    if not is_combined_level:
        return list(cols)
    out = list(cols)
    if 'home_class' in out:
        return out
    try:
        idx = out.index(insert_after)
        out.insert(idx + 1, 'home_class')
    except ValueError:
        out.append('home_class')
    return out


def _group_class_list_rows(rows, is_combined_level=False, combined_display_name=None):
    """Split flat student rows into sections by current_grade (for all-classes reports)."""
    from itertools import groupby
    if not rows:
        return []

    if is_combined_level:
        label = (combined_display_name or '').strip() or 'Combined class'
        rows_sorted = sorted(
            rows,
            key=lambda r: (
                str(r.get('full_name') or '').lower(),
                str(r.get('student_id') or '').lower(),
            ),
        )
        return [{'class_name': label, 'rows': rows_sorted}]

    def _grade_key(r):
        g = (r.get('current_grade') or '').strip()
        return g if g else '— Unassigned —'

    rows_sorted = sorted(rows, key=lambda r: (_grade_key(r).lower(), (r.get('full_name') or '').lower()))
    sections = []
    for class_name, group in groupby(rows_sorted, key=_grade_key):
        sections.append({'class_name': class_name, 'rows': list(group)})
    return sections


def _academic_report_mark_with_grade_text(mark, grade_code):
    """Single cell text: scaled mark and grade code together (e.g. '85 EE22')."""
    if mark is None or mark == '':
        return ''
    if isinstance(mark, (int, float)):
        mstr = round_mark_display(mark)
        if mstr is None:
            mstr = str(mark)
    else:
        mstr = str(mark).strip()
    if not mstr:
        return ''
    g = (grade_code or '').strip()
    return f'{mstr} {g}' if g else mstr


def _academic_report_subject_cell_export_value(row, subject_key, meta):
    """Mark + grade in one export cell for exam all-students performance."""
    mark = row.get(subject_key)
    if mark is None or mark == '':
        sm = row.get('subject_marks')
        if isinstance(sm, dict):
            mark = sm.get(subject_key, '')
    grades = row.get('subject_grades')
    if isinstance(grades, dict) and subject_key in grades:
        code = (grades.get(subject_key) or '').strip()
    else:
        code = _academic_report_grade_code_for_pct(
            mark, meta, row.get('academic_level_id'),
        )
    return _academic_report_mark_with_grade_text(mark, code)


def _academic_report_export_cell_value(col_key, row, meta=None, report_type=None):
    """Scalar value for CSV/Excel cells: skip nested dict/list (e.g. internal row payloads)."""
    if not isinstance(row, dict):
        return row
    ck = str(col_key) if col_key is not None else ''
    if report_type == 'exam_all_students_performance' and meta:
        subject_cols = meta.get('subject_columns') or []
        if ck in subject_cols:
            return _academic_report_subject_cell_export_value(row, ck, meta)
    if ck in row:
        v = row[ck]
    else:
        v = None
        ck_st = ck.strip()
        for rk in row:
            if isinstance(rk, str) and rk.strip() == ck_st:
                v = row[rk]
                break
        if v is None:
            return ''
    # Single-value list/tuple from DB/ORM (would otherwise export as blank)
    while isinstance(v, (list, tuple)) and len(v) == 1:
        v = v[0]
    if isinstance(v, (dict, list, set)):
        return ''
    if isinstance(v, bytes):
        try:
            v = v.decode('utf-8', errors='replace')
        except Exception:
            return ''
    return v if v is not None else ''


def _academic_report_export_body_sections(bundle, report_type):
    """
    Build [{class_name, rows, section_title?}, ...] for spreadsheet section breaks.
    section_title, when set, is printed as the full banner row (else 'Class: {class_name}').
    Returns None to use a single flat row list.
    """
    from collections import defaultdict

    meta = bundle.get('meta') or {}
    rows = bundle.get('rows') or []
    if not isinstance(rows, list) or not rows:
        return None

    preset = meta.get('class_sections')
    if preset and report_type in ('class_list_attendance', 'class_list_exam'):
        return preset

    if report_type == 'exam_all_students_performance':
        # Combined cohort: export one continuous table (preserve row order), no per-class bands.
        if meta.get('is_combined_level_view') or meta.get('merge_single_cohort'):
            return None
        by_label = defaultdict(list)
        for row in rows:
            if not isinstance(row, dict):
                continue
            label = (
                (row.get('current_grade') or row.get('home_class') or row.get('level_name') or '')
                .strip()
            ) or '—'
            by_label[label].append(row)
        keys = sorted(by_label.keys(), key=lambda x: (x == '—', str(x).lower()))
        return [
            {
                'class_name': k,
                'section_title': f'Class · {k}' if k != '—' else 'Class · (unassigned)',
                'rows': by_label[k],
            }
            for k in keys
        ]

    if report_type in ('exam_individual', 'exam_individual_performance'):
        by_sid = defaultdict(list)
        for row in rows:
            if not isinstance(row, dict):
                continue
            sid = (row.get('student_id') or '').strip() or '—'
            by_sid[sid].append(row)
        keys = sorted(
            by_sid.keys(),
            key=lambda s: (
                str((by_sid[s][0].get('full_name') or '') if by_sid[s] else '').lower(),
                str(s).lower(),
            ),
        )
        out = []
        for sid in keys:
            block = by_sid[sid]
            name = (block[0].get('full_name') or '').strip() if block else ''
            if name and sid != '—':
                title = f'Student · {name} ({sid})'
            elif name:
                title = f'Student · {name}'
            else:
                title = f'Student · {sid}'
            out.append({'class_name': sid, 'section_title': title, 'rows': block})
        return out or None

    if report_type == 'attendance_individual':
        by_sid = defaultdict(list)
        for row in rows:
            if not isinstance(row, dict):
                continue
            sid = (row.get('student_id') or '').strip() or '—'
            by_sid[sid].append(row)
        keys = sorted(
            by_sid.keys(),
            key=lambda s: (
                str((by_sid[s][0].get('full_name') or '') if by_sid[s] else '').lower(),
                str(s).lower(),
            ),
        )
        out = []
        for sid in keys:
            block = by_sid[sid]
            name = (block[0].get('full_name') or '').strip() if block else ''
            ln = (block[0].get('level_name') or '').strip() if block else ''
            if name and sid != '—':
                title = f'Student · {name} ({sid})'
            elif name:
                title = f'Student · {name}'
            else:
                title = f'Student · {sid}'
            if ln:
                title = f'{title} · {ln}'
            out.append({'class_name': sid, 'section_title': title, 'rows': block})
        return out or None

    if report_type == 'exam_class_performance':
        by_lv = defaultdict(list)
        for row in rows:
            if not isinstance(row, dict):
                continue
            ln = (row.get('level_name') or '').strip() or '—'
            by_lv[ln].append(row)
        keys = sorted(by_lv.keys(), key=lambda x: (x == '—', str(x).lower()))
        if len(keys) <= 1:
            k0 = keys[0]
            return [{'class_name': k0, 'section_title': f'Class · {k0}', 'rows': by_lv[k0]}]
        return [{'class_name': k, 'section_title': f'Class · {k}', 'rows': by_lv[k]} for k in keys]

    if report_type == 'attendance_class' and len(rows) > 1:
        by_lv = defaultdict(list)
        for row in rows:
            if not isinstance(row, dict):
                continue
            ln = (row.get('level_name') or '').strip() or '—'
            by_lv[ln].append(row)
        keys = sorted(by_lv.keys(), key=lambda x: (x == '—', str(x).lower()))
        if len(keys) <= 1:
            return None
        return [{'class_name': k, 'section_title': f'Class · {k}', 'rows': by_lv[k]} for k in keys]

    if report_type in ('timetable_subject', 'timetable_teacher'):
        by_lv = defaultdict(list)
        for row in rows:
            if not isinstance(row, dict):
                continue
            ln = (row.get('level_name') or '').strip() or '—'
            by_lv[ln].append(row)
        keys = sorted(by_lv.keys(), key=lambda x: (x == '—', str(x).lower()))
        if len(keys) <= 1:
            return None
        return [{'class_name': k, 'section_title': f'Class · {k}', 'rows': by_lv[k]} for k in keys]

    return None


def _academic_report_export_section_heading_row(sec):
    """One spreadsheet row label for a section break (CSV list / Excel HTML)."""
    st = (sec.get('section_title') or '').strip()
    if st:
        return st
    return f"Class: {sec.get('class_name', '')}".strip()


def _academic_report_export_column_header_label(col_key):
    """Human-readable spreadsheet column title (CSV / Excel header row)."""
    ck = str(col_key or '')
    if ck == 'grade_points':
        return 'GP'
    if ck == 'grade':
        return 'Overall Grd'
    if ck in ('home_class', 'current_grade'):
        return 'Class'
    return ck.replace('_', ' ').title()


def _academic_report_school_export_banner_lines():
    """Short school identity lines for CSV / Excel letterhead (no logo in CSV)."""
    school = get_school_settings() or {}
    name = (school.get('school_name') or 'School').strip() or 'School'
    lines = [name]
    loc = (school.get('school_location') or '').strip()
    if loc:
        lines.append(loc)
    bits = []
    ph = (school.get('school_phone') or '').strip()
    if ph:
        bits.append(f'Tel: {ph}')
    em = (school.get('school_email') or '').strip()
    if em:
        bits.append(f'Email: {em}')
    if bits:
        lines.append(' · '.join(bits))
    return lines


def _academic_report_bundle_summary_lines(bundle, report_type):
    """Report title + key applied filters for export letterhead (CSV / Excel).

    Omits exam type, teacher, student, date range, timetable view, and generated
    timestamp so the sheet stays focused on cohort + exam context.
    """
    out = []
    title = (bundle.get('title') or '').strip() or str(report_type or '').replace('_', ' ').title()
    out.append(f'Report: {title}')
    meta = bundle.get('meta') or {}
    af = meta.get('applied_filters')
    if not isinstance(af, dict):
        return out
    pairs = [
        ('academic_year', 'Academic year'),
        ('term', 'Term'),
        ('class_level', 'Class'),
        ('level_view', 'Level view'),
        ('exam_name', 'Exam'),
    ]
    for key, label in pairs:
        v = af.get(key)
        if v is None:
            continue
        vs = str(v).strip()
        if not vs or vs.lower() in ('null', 'none'):
            continue
        out.append(f'{label}: {vs}')
    return out


def _academic_report_subject_mark_cols_for_export(columns, meta):
    """Subject column keys for exam all-students footer / summaries."""
    colset = set(columns or [])
    subject_cols = [c for c in (meta.get('subject_columns') or []) if c in colset]
    if subject_cols:
        return subject_cols
    fixed = _exam_all_students_performance_fixed_col_keys()
    return [c for c in (columns or []) if c not in fixed]


def _exam_all_students_performance_fixed_col_keys():
    return {
        'position', 'admission_number', 'full_name', 'student_id', 'total_marks',
        'grade', 'grade_points', 'mean', 'level_name', 'current_grade', 'home_class',
        'student_photo', 'subject_marks', 'subject_grades', 'class_subject_columns',
        'rank_sort_total', 'rank_sort_mean', 'academic_level_id',
    }


def _academic_report_grade_code_for_pct(marks_value, meta, level_id=None):
    """Grade code for a percentage using meta grade_bands / class_grade_bands."""
    if marks_value is None or marks_value == '':
        return ''
    default_bands = meta.get('grade_bands') or []
    class_bands_raw = meta.get('class_grade_bands') or {}
    class_bands = {}
    if isinstance(class_bands_raw, dict):
        for k, v in class_bands_raw.items():
            try:
                class_bands[int(k)] = v
            except (TypeError, ValueError):
                continue
    bands = resolve_grade_bands(level_id, class_bands, default_bands)
    code, _ = grade_code_and_points_from_pct(marks_value, bands)
    return (code or '').strip()


def _exam_all_students_performance_footer_rows(columns, meta, student_rows):
    """
    Summary rows for CSV/Excel after student rows:
    (1) Subject mean per class (+ mean GP), (2) class mean of total % (total_marks).
    Combined cohort: repeat per member class, then a combined (all) pair.
    """
    if not columns or not isinstance(student_rows, list) or not student_rows:
        return []
    is_combined = bool(meta.get('is_combined_level_view') or meta.get('merge_single_cohort'))
    if is_combined:
        from collections import defaultdict

        by_class = defaultdict(list)
        for row in student_rows:
            if not isinstance(row, dict):
                continue
            label = _academic_report_home_class_value(row) or '—'
            by_class[label].append(row)
        member_names = list(meta.get('combined_member_level_names') or [])
        class_order = [n for n in member_names if n in by_class and by_class[n]]
        for key in sorted(by_class.keys(), key=lambda x: (x == '—', str(x).lower())):
            if key not in class_order:
                class_order.append(key)
        footers = []
        for class_name in class_order:
            footers.extend(
                _exam_all_students_performance_footer_pair(
                    columns, meta, by_class[class_name], class_name,
                )
            )
        combined_label = (meta.get('combined_display_name') or '').strip() or 'Combined'
        footers.extend(
            _exam_all_students_performance_footer_pair(
                columns, meta, student_rows, combined_label,
            )
        )
        return footers
    return _exam_all_students_performance_footer_pair(columns, meta, student_rows, None)


def _exam_all_students_performance_footer_pair(columns, meta, student_rows, class_label):
    """Two footer rows for one cohort slice (single class or combined group)."""
    if not columns or not student_rows:
        return []
    colset = set(columns)
    subject_cols = _academic_report_subject_mark_cols_for_export(columns, meta)

    def _fnum(row, key):
        if not isinstance(row, dict):
            return None
        v = row.get(key)
        if v is None or v == '':
            return None
        try:
            return float(v)
        except (TypeError, ValueError):
            return None

    def blank_row():
        return {c: '' for c in columns}

    if class_label:
        subj_mean_label = f'Subject mean ({class_label})'
        class_mean_label = f'Class mean (avg total %) ({class_label})'
    else:
        subj_mean_label = 'Subject mean (class)'
        class_mean_label = 'Class mean (avg total %)'
    row_subj = blank_row()
    for c in columns:
        if c == 'full_name':
            row_subj[c] = subj_mean_label
        elif c == 'home_class' and class_label:
            row_subj[c] = class_label
        elif c in ('position', 'admission_number'):
            row_subj[c] = ''
    footer_level_id = None
    for r in student_rows:
        if isinstance(r, dict) and r.get('academic_level_id') is not None:
            footer_level_id = r.get('academic_level_id')
            break
    for sc in subject_cols:
        vals = [_fnum(r, sc) for r in student_rows]
        vals = [x for x in vals if x is not None]
        mean_mark = round_mark_display(sum(vals) / len(vals)) if vals else ''
        mean_grade = (
            _academic_report_grade_code_for_pct(mean_mark, meta, footer_level_id)
            if mean_mark != '' and mean_mark is not None
            else ''
        )
        row_subj[sc] = _academic_report_mark_with_grade_text(mean_mark, mean_grade)

    if 'grade_points' in colset:
        gp_vals = [_fnum(r, 'grade_points') for r in student_rows]
        gp_vals = [x for x in gp_vals if x is not None]
        row_subj['grade_points'] = round_mark_display(sum(gp_vals) / len(gp_vals)) if gp_vals else ''

    totals = [_fnum(r, 'total_marks') for r in student_rows]
    totals = [x for x in totals if x is not None]
    class_avg = round_mark_display(sum(totals) / len(totals)) if totals else None

    row_class = blank_row()
    for c in columns:
        if c == 'full_name':
            row_class[c] = class_mean_label
        elif c == 'home_class' and class_label:
            row_class[c] = class_label
        elif c == 'total_marks':
            row_class[c] = class_avg if class_avg is not None else ''

    return [row_subj, row_class]


def _write_exam_all_students_performance_footers(writer, columns, meta, student_rows):
    """Append blank line + summary rows to CSV (writer = csv.writer)."""
    footers = _exam_all_students_performance_footer_rows(columns, meta, student_rows)
    if not footers:
        return
    writer.writerow([])
    for fr in footers:
        writer.writerow([
            _academic_report_export_cell_value(
                c, fr, meta=meta, report_type='exam_all_students_performance',
            )
            for c in columns
        ])


def _make_academic_report_csv_response(bundle, report_type):
    """Build CSV download response from a successful report bundle."""
    columns = bundle.get('columns') or []
    rows = bundle.get('rows') or []
    sections = _academic_report_export_body_sections(bundle, report_type)
    si = StringIO()
    si.write('\ufeff')
    writer = csv.writer(si)
    for line in _academic_report_school_export_banner_lines():
        writer.writerow([line])
    writer.writerow([])
    for line in _academic_report_bundle_summary_lines(bundle, report_type):
        writer.writerow([line])
    writer.writerow([])
    writer.writerow([_academic_report_export_column_header_label(c) for c in columns])
    meta = bundle.get('meta') or {}
    if sections:
        for i, sec in enumerate(sections):
            if i > 0:
                writer.writerow([])
            writer.writerow([_academic_report_export_section_heading_row(sec)])
            sec_rows = sec.get('rows') or []
            for row in sec_rows:
                writer.writerow([
                    _academic_report_export_cell_value(c, row, meta=meta, report_type=report_type)
                    for c in columns
                ])
            if report_type == 'exam_all_students_performance' and sec_rows:
                _write_exam_all_students_performance_footers(writer, columns, meta, sec_rows)
    else:
        for row in rows:
            writer.writerow([
                _academic_report_export_cell_value(c, row, meta=meta, report_type=report_type)
                for c in columns
            ])
        if report_type == 'exam_all_students_performance' and rows:
            _write_exam_all_students_performance_footers(writer, columns, meta, rows)
    output = make_response(si.getvalue())
    safe_name = re.sub(r'[^a-zA-Z0-9_-]+', '_', report_type)[:60]
    output.headers['Content-Type'] = 'text/csv; charset=utf-8'
    output.headers['Content-Disposition'] = f'attachment; filename={safe_name}.csv'
    return output


def _make_academic_report_excel_response(bundle, report_type):
    """Build a real .xlsx workbook (openpyxl) so Excel does not warn about format/extension mismatch."""
    from io import BytesIO

    try:
        from openpyxl import Workbook
        from openpyxl.styles import Alignment, Font, PatternFill
        from openpyxl.utils import get_column_letter
    except ImportError as ie:
        return make_response(
            f'Excel export requires openpyxl: {ie}',
            500,
            {'Content-Type': 'text/plain; charset=utf-8'},
        )

    columns = list(bundle.get('columns') or [])
    rows = bundle.get('rows') or []
    sections = _academic_report_export_body_sections(bundle, report_type)
    meta = bundle.get('meta') or {}
    ncol = max(1, len(columns))

    wb = Workbook()
    ws = wb.active
    raw_title = (bundle.get('title') or report_type or 'Report').strip()
    sheet_name = re.sub(r'[\[\]:*?/\\]', '_', raw_title)[:31].strip('_') or 'Report'
    ws.title = sheet_name

    header_font = Font(bold=True)
    header_fill = PatternFill(start_color='DDEBF7', end_color='DDEBF7', fill_type='solid')
    banner_font = Font(bold=True)
    banner_fill = PatternFill(start_color='FFF2CC', end_color='FFF2CC', fill_type='solid')
    school_head_font = Font(bold=True, size=14)
    school_meta_font = Font(bold=True, size=11)
    letterhead_sub_font = Font(size=10)

    nrow = 1
    xls_string_id_cols = frozenset({
        'student_id', 'admission_number', 'teacher_id', 'invigilator_employee_id',
    })

    def merge_full_data_width():
        if ncol > 1:
            ws.merge_cells(start_row=nrow, start_column=1, end_row=nrow, end_column=ncol)

    def push_letterhead_line(text, font=None, wrap=True):
        nonlocal nrow
        merge_full_data_width()
        cell = ws.cell(row=nrow, column=1, value=text)
        cell.alignment = Alignment(horizontal='left', vertical='center', wrap_text=wrap)
        if font:
            cell.font = font
        nrow += 1

    def write_excel_letterhead():
        """School logo (optional), name, contact, report title and filter summary."""
        nonlocal nrow
        school = get_school_settings() or {}
        name = (school.get('school_name') or 'School').strip() or 'School'
        logo_key = school.get('school_logo')
        logo_path = None
        if logo_key:
            raw = str(logo_key).strip().replace('\\', '/').lstrip('/')
            if raw and not raw.startswith('..'):
                cand = os.path.normpath(os.path.join(app.root_path, 'static', raw))
                root_static = os.path.normpath(os.path.join(app.root_path, 'static'))
                if cand.startswith(root_static) and os.path.isfile(cand):
                    logo_path = cand
        img_ok = False
        if logo_path and ncol >= 2:
            try:
                from openpyxl.drawing.image import Image as XLImage
                img = XLImage(logo_path)
                h0 = float(img.height or 1)
                w0 = float(img.width or 1)
                max_side = 72.0
                scale = min(max_side / max(h0, 1e-6), max_side / max(w0, 1e-6), 1.0)
                img.height = int(h0 * scale)
                img.width = int(w0 * scale)
                anchor_row = nrow
                ws.add_image(img, f'A{anchor_row}')
                ws.merge_cells(start_row=anchor_row, start_column=2, end_row=anchor_row, end_column=ncol)
                c = ws.cell(row=anchor_row, column=2, value=name)
                c.font = school_head_font
                c.alignment = Alignment(horizontal='left', vertical='center', wrap_text=True)
                try:
                    ws.row_dimensions[anchor_row].height = min(96, max(48, float(img.height) * 0.75 + 12))
                except (TypeError, ValueError):
                    ws.row_dimensions[anchor_row].height = 56
                nrow = anchor_row + 1
                img_ok = True
            except Exception:
                img_ok = False
        if not img_ok:
            push_letterhead_line(name, school_head_font)
        loc = (school.get('school_location') or '').strip()
        if loc:
            push_letterhead_line(loc, letterhead_sub_font)
        bits = []
        ph = (school.get('school_phone') or '').strip()
        if ph:
            bits.append(f'Tel: {ph}')
        em = (school.get('school_email') or '').strip()
        if em:
            bits.append(f'Email: {em}')
        if bits:
            push_letterhead_line(' · '.join(bits), letterhead_sub_font)
        push_letterhead_line('')
        for ln in _academic_report_bundle_summary_lines(bundle, report_type):
            push_letterhead_line(ln, school_meta_font if str(ln).startswith('Report:') else letterhead_sub_font)
        push_letterhead_line('')

    def write_header():
        nonlocal nrow
        for ci, col_key in enumerate(columns, start=1):
            label = _academic_report_export_column_header_label(col_key)
            cell = ws.cell(row=nrow, column=ci, value=label)
            cell.font = header_font
            cell.fill = header_fill
            cell.alignment = Alignment(horizontal='center', vertical='center', wrap_text=True)
        nrow += 1

    def write_banner(text):
        nonlocal nrow
        if ncol > 1:
            ws.merge_cells(start_row=nrow, start_column=1, end_row=nrow, end_column=ncol)
        cell = ws.cell(row=nrow, column=1, value=str(text))
        cell.font = banner_font
        cell.fill = banner_fill
        cell.alignment = Alignment(horizontal='left', vertical='center', wrap_text=True)
        nrow += 1

    def write_data_row(row_dict):
        nonlocal nrow
        if not isinstance(row_dict, dict):
            nrow += 1
            return
        from decimal import Decimal

        for ci, col_key in enumerate(columns, start=1):
            val = _academic_report_export_cell_value(
                col_key, row_dict, meta=meta, report_type=report_type,
            )
            cell = ws.cell(row=nrow, column=ci)
            if val is None:
                cell.value = None
            elif isinstance(val, str) and val.strip() == '':
                cell.value = None
            elif isinstance(val, bool):
                cell.value = val
            elif isinstance(val, (int, float, Decimal)) and not isinstance(val, bool):
                if isinstance(val, float) and (val != val):  # NaN
                    cell.value = None
                else:
                    cell.value = val
            else:
                st = str(val).strip()
                if not st:
                    cell.value = None
                elif str(col_key) in xls_string_id_cols:
                    cell.value = st
                elif re.fullmatch(r'-?\d+(\.\d+)?', st):
                    try:
                        f = float(st)
                        cell.value = int(f) if abs(f - round(f)) < 1e-9 else f
                    except (TypeError, ValueError, ArithmeticError):
                        cell.value = st
                else:
                    cell.value = st
        nrow += 1

    if not columns:
        write_excel_letterhead()
        ws.cell(row=nrow, column=1, value='No export columns for this report.')
    else:
        write_excel_letterhead()
        write_header()
        freeze_top = nrow
        if sections:
            for si, sec in enumerate(sections):
                write_banner(_academic_report_export_section_heading_row(sec))
                sec_rows = sec.get('rows') or []
                for row in sec_rows:
                    write_data_row(row)
                if report_type == 'exam_all_students_performance' and sec_rows:
                    nrow += 1
                    for fr in _exam_all_students_performance_footer_rows(columns, meta, sec_rows):
                        write_data_row(fr)
                if si < len(sections) - 1:
                    nrow += 1
        else:
            for row in rows:
                write_data_row(row)
            if report_type == 'exam_all_students_performance' and rows:
                nrow += 1
                for fr in _exam_all_students_performance_footer_rows(columns, meta, rows):
                    write_data_row(fr)

        ws.freeze_panes = f'A{freeze_top}'

        for ci in range(1, ncol + 1):
            letter = get_column_letter(ci)
            key = str(columns[ci - 1]) if ci <= len(columns) else ''
            ws.column_dimensions[letter].width = min(48, max(10, len(key) + 4))

    buf = BytesIO()
    wb.save(buf)
    buf.seek(0)
    data = buf.getvalue()

    output = make_response(data)
    safe_name = re.sub(r'[^a-zA-Z0-9_-]+', '_', report_type)[:60]
    output.headers['Content-Type'] = (
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
    )
    output.headers['Content-Disposition'] = f'attachment; filename={safe_name}.xlsx'
    return output


def _build_timetable_grid(rows, teacher_mode=False, compact_class_cell=False):
    """Grid: days x time slots; each cell is a list of entry dicts."""
    day_order = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    days_present = set()
    slots = set()
    for r in rows:
        d = r.get('day_of_week') or ''
        if d:
            days_present.add(d)
        t = r.get('time_slot') or ''
        if t:
            slots.add(t)
    days = [d for d in day_order if d in days_present]
    slots_sorted = sorted(slots)
    cells = {}
    for d in days:
        cells[d] = {}
        for s in slots_sorted:
            cells[d][s] = []
    for r in rows:
        d = r.get('day_of_week')
        t = r.get('time_slot')
        if not d or t is None or t == '' or d not in cells or t not in cells[d]:
            continue
        if teacher_mode:
            code = (r.get('subject_code') or '').strip()
            if compact_class_cell:
                sec = str(r.get('subject_name') or '').strip()
            else:
                sec = ' · '.join(x for x in (r.get('level_name'), r.get('subject_name')) if x)
            cells[d][t].append({
                'primary': r.get('teacher_name') or '—',
                'secondary': sec,
                'badge': code,
            })
        else:
            code = (r.get('subject_code') or '').strip()
            if compact_class_cell:
                sec = ' · '.join(x for x in (r.get('teacher_name'),) if x)
            else:
                sec = ' · '.join(x for x in (r.get('level_name'), r.get('teacher_name')) if x)
            cells[d][t].append({
                'primary': r.get('subject_name') or '—',
                'secondary': sec,
                'badge': code,
            })
    return {'days': days, 'slots': slots_sorted, 'cells': cells}


def _timetable_sections_from_rows(rows, teacher_mode):
    """One timetable grid per class (level_name) — easier to read than a merged sheet."""
    from collections import defaultdict
    by_level = defaultdict(list)
    for r in rows:
        ln = str((r.get('level_name') or '')).strip() or '—'
        by_level[ln].append(r)
    order = sorted(by_level.keys(), key=lambda x: (x == '—', x.lower()))
    sections = []
    for ln in order:
        sub = by_level[ln]
        grid = _build_timetable_grid(sub, teacher_mode, compact_class_cell=True)
        if grid.get('days') and grid.get('slots'):
            sections.append({'level_name': ln, 'timetable': grid})
    return sections


def _exam_timetable_sections_from_rows(rows):
    from collections import defaultdict
    by_level = defaultdict(list)
    for r in rows:
        ln = str((r.get('level_name') or '')).strip() or '—'
        by_level[ln].append(r)
    order = sorted(by_level.keys(), key=lambda x: (x == '—', x.lower()))
    return [
        {'level_name': ln, 'exam_timetable_grid': _build_exam_timetable_grid(by_level[ln])}
        for ln in order if by_level[ln]
    ]


def _build_exam_schedule_by_date(rows):
    from collections import defaultdict
    by_date = defaultdict(list)
    for r in rows:
        by_date[r.get('exam_date') or ''].append(r)
    dates = sorted(k for k in by_date.keys() if k)
    return [{'date': d, 'exams': sorted(by_date[d], key=lambda x: (str(x.get('start_time') or ''), x.get('level_name') or ''))} for d in dates]


def _exam_time_sort_key(row):
    st = str(row.get('start_time') or '99:99')
    parts = st.replace('.', ':').split(':')
    try:
        h = int(parts[0])
        m = int(parts[1]) if len(parts) > 1 else 0
        s = int(parts[2]) if len(parts) > 2 else 0
    except (TypeError, ValueError):
        return (99, 99, 99)
    return (h, m, s)


def _exam_time_label(r):
    st = str(r.get('start_time') or '').strip()
    et = str(r.get('end_time') or '').strip()
    if et and et != st:
        return f"{st} – {et}"
    return st or '—'


def _format_exam_date_header(iso_str):
    if not iso_str:
        return ''
    try:
        from datetime import datetime as _dt
        d = _dt.strptime(str(iso_str)[:10], '%Y-%m-%d')
        return d.strftime('%a %d %b %Y')
    except (TypeError, ValueError):
        return str(iso_str)


def _build_exam_timetable_grid(rows):
    """Rows = time sessions; columns = exam dates — like a printed exam timetable."""
    if not rows:
        return {'dates': [], 'date_headers': [], 'time_labels': [], 'cells': {}}
    dates = sorted(set(r.get('exam_date') for r in rows if r.get('exam_date')))
    label_to_row = {}
    for r in rows:
        lbl = _exam_time_label(r)
        if lbl not in label_to_row:
            label_to_row[lbl] = r
    time_labels = sorted(label_to_row.keys(), key=lambda lbl: _exam_time_sort_key(label_to_row[lbl]))
    date_headers = [{'iso': d, 'label': _format_exam_date_header(d)} for d in dates]
    cells = {d: {lbl: [] for lbl in time_labels} for d in dates}
    for r in rows:
        d = r.get('exam_date')
        if not d or d not in cells:
            continue
        lbl = _exam_time_label(r)
        if lbl not in cells[d]:
            continue
        cells[d][lbl].append(r)
    for d in dates:
        for lbl in time_labels:
            cells[d][lbl].sort(key=lambda x: (str(x.get('level_name') or ''), str(x.get('exam_name') or '')))
    return {'dates': dates, 'date_headers': date_headers, 'time_labels': time_labels, 'cells': cells}


def _build_attendance_by_student(rows):
    from collections import defaultdict
    by_sid = defaultdict(lambda: {'full_name': '', 'level_name': '', 'rows': []})
    for r in rows:
        sid = r.get('student_id')
        by_sid[sid]['full_name'] = r.get('full_name') or ''
        by_sid[sid]['level_name'] = r.get('level_name') or ''
        by_sid[sid]['rows'].append(r)
    for sid in by_sid:
        by_sid[sid]['rows'].sort(key=lambda x: (x.get('attendance_date') or '',))
    ordered = sorted(by_sid.items(), key=lambda x: ((x[1]['full_name'] or x[0] or '').lower(), x[0]))
    return [{'student_id': sid, **data} for sid, data in ordered]


def _build_exam_marks_by_student(rows):
    from collections import defaultdict
    by_sid = defaultdict(lambda: {'full_name': '', 'level_name': '', 'academic_level_id': None, 'marks': []})
    for r in rows:
        sid = r.get('student_id')
        by_sid[sid]['full_name'] = r.get('full_name') or ''
        by_sid[sid]['level_name'] = r.get('level_name') or ''
        if r.get('academic_level_id') is not None:
            by_sid[sid]['academic_level_id'] = r.get('academic_level_id')
        by_sid[sid]['marks'].append(r)
    for sid in by_sid:
        by_sid[sid]['marks'].sort(
            key=lambda x: (
                x.get('exam_date') or '',
                int(x.get('_exam_cat_i', 10**6)),
                int(x.get('exam_display_order') or 1000000000),
                str(x.get('subject_name') or ''),
            )
        )
    ordered = sorted(by_sid.items(), key=lambda x: ((x[1]['full_name'] or x[0] or '').lower(), x[0]))
    return [{'student_id': sid, **data} for sid, data in ordered]


def _preview_display_context(report_type, bundle):
    """Extra template variables for rich preview layouts (not used for CSV)."""
    rows = bundle.get('rows') or []
    meta = bundle.get('meta') or {}
    ctx = {
        'layout': 'plain',
        'timetable': None,
        'timetable_sections': None,
        'exam_schedule': None,
        'exam_timetable_grid': None,
        'exam_timetable_sections': None,
        'attendance_register': None,
        'exam_by_student': None,
    }
    if report_type in ('timetable_subject', 'timetable_teacher'):
        ctx['layout'] = 'timetable'
        teacher_mode = report_type == 'timetable_teacher' or (meta.get('timetable_view') or '').lower() == 'teacher'
        ctx['timetable_sections'] = _timetable_sections_from_rows(rows, teacher_mode)
        ctx['timetable'] = None
    elif report_type == 'timetable_exam':
        ctx['layout'] = 'exam_timetable'
        ctx['exam_schedule'] = _build_exam_schedule_by_date(rows)
        ctx['exam_timetable_sections'] = _exam_timetable_sections_from_rows(rows)
        ctx['exam_timetable_grid'] = None
    elif report_type == 'attendance_class':
        ctx['layout'] = 'attendance_summary'
    elif report_type == 'attendance_individual':
        ctx['layout'] = 'attendance_register'
        ctx['attendance_register'] = _build_attendance_by_student(rows)
    elif report_type in ('exam_class_performance', 'exam_subject_performance', 'exam_teacher_performance'):
        ctx['layout'] = 'exam_performance' if report_type != 'exam_teacher_performance' else 'exam_teacher'
    elif report_type in ('exam_individual', 'exam_individual_performance'):
        ctx['layout'] = 'exam_marks'
        ctx['exam_by_student'] = _build_exam_marks_by_student(rows)
    elif report_type == 'exam_all_students_performance':
        ctx['layout'] = 'exam_all_student_cards'
    elif report_type == 'class_list_attendance':
        if meta.get('class_sections'):
            ctx['layout'] = 'class_list_grouped'
            ctx['class_sections'] = meta['class_sections']
        else:
            ctx['layout'] = 'plain'
    elif report_type == 'class_list_exam':
        if meta.get('class_sections'):
            ctx['layout'] = 'class_list_grouped'
            ctx['class_sections'] = meta['class_sections']
        else:
            ctx['layout'] = 'class_list'
    return ctx


def _build_academic_report_payload(cursor, report_type, f):
    """Return dict with title, columns, rows, meta; or {'error': str}."""
    from collections import defaultdict

    def _float_marks(x):
        if x is None:
            return None
        try:
            return float(x)
        except (TypeError, ValueError):
            return None

    def _str_opt(v):
        if v is None or v == '' or v == 'null':
            return None
        return str(v).strip() or None

    ay = f.get('academic_year_id')
    tid = f.get('term_id')
    lid = f.get('level_id')
    level_view = (f.get('level_view') or 'individual').strip().lower()
    if level_view not in ('individual', 'combined'):
        level_view = 'individual'
    level_scope = _resolve_academic_report_level_scope(cursor, level_view, lid)
    if level_view == 'combined':
        if not lid:
            return {
                'error': 'Select a class to generate a combined level report.',
            }
        if not level_scope.get('is_combined_view'):
            return {
                'error': (
                    'No combined level group includes the selected class. '
                    'Create groups under Settings → Combined academic levels, or use Individual class.'
                ),
            }
    level_ids = list(level_scope.get('level_ids') or [])
    is_combined_level = bool(level_scope.get('is_combined_view'))
    teacher_id = f.get('teacher_id')
    timetable_view = (f.get('timetable_view') or 'student').lower()
    student_id = _str_opt(f.get('student_id'))
    exam_names = f.get('exam_names') if isinstance(f, dict) else None
    if not isinstance(exam_names, list):
        exam_names = None
    else:
        exam_names = [str(x).strip() for x in exam_names if str(x).strip()]
        if not exam_names:
            exam_names = None
    exam_name = _str_opt(f.get('exam_name'))
    if not exam_name and exam_names:
        exam_name = exam_names[0]
    exam_type_f = _str_opt(f.get('exam_type'))
    date_from = _str_opt(f.get('date_from'))
    date_to = _str_opt(f.get('date_to'))

    # Only auto-fill dates from term for attendance reports (optional dates elsewhere)
    if report_type in ('attendance_class', 'attendance_individual', 'class_list_attendance') and tid and (not date_from or not date_to):
        df, dt = _term_date_bounds(cursor, tid)
        if df and dt:
            if hasattr(df, 'strftime'):
                date_from = date_from or df.strftime('%Y-%m-%d')
                date_to = date_to or dt.strftime('%Y-%m-%d')
            else:
                date_from = date_from or str(df)[:10]
                date_to = date_to or str(dt)[:10]

    meta = {}

    def _exam_name_clause_and_params():
        if exam_names:
            upex = [str(x).strip() for x in exam_names if str(x).strip()]
            if not upex:
                return "", []
            placeholders = ','.join(['%s'] * len(upex))
            return f" AND UPPER(TRIM(e.exam_name)) IN ({placeholders})", [x.upper() for x in upex]
        if exam_name:
            en = str(exam_name).strip()
            if exam_type_f:
                return (
                    " AND UPPER(TRIM(e.exam_name)) = UPPER(TRIM(%s)) AND UPPER(TRIM(COALESCE(e.exam_type, ''))) = %s",
                    [en, exam_type_f.strip().upper()],
                )
            return " AND UPPER(TRIM(e.exam_name)) = UPPER(TRIM(%s))", [en]
        return "", []

    def _load_grade_bands_for_reports():
        default_bands = []
        subject_bands = {}
        class_bands = {}
        try:
            cursor.execute("""
                SELECT code, level_label, meaning, start_mark, end_mark, allocation_points
                FROM grade_registrations
                WHERE start_mark IS NOT NULL AND end_mark IS NOT NULL
                ORDER BY start_mark DESC, end_mark DESC
            """)
            for grow in (cursor.fetchall() or []):
                if isinstance(grow, dict):
                    ap = grow.get('allocation_points')
                    default_bands.append({
                        'code': (grow.get('code') or '').strip(),
                        'label': (grow.get('level_label') or '').strip(),
                        'meaning': (grow.get('meaning') or '').strip(),
                        'start': float(grow.get('start_mark') or 0),
                        'end': float(grow.get('end_mark') or 0),
                        'allocation_points': float(ap) if ap is not None else None,
                    })
                else:
                    apv = grow[5] if len(grow) > 5 else None
                    default_bands.append({
                        'code': ((grow[0] if len(grow) > 0 else '') or '').strip(),
                        'label': ((grow[1] if len(grow) > 1 else '') or '').strip(),
                        'meaning': ((grow[2] if len(grow) > 2 else '') or '').strip(),
                        'start': float(grow[3] or 0) if len(grow) > 3 else 0.0,
                        'end': float(grow[4] or 0) if len(grow) > 4 else 0.0,
                        'allocation_points': float(apv) if apv is not None else None,
                    })
        except Exception as ge:
            print(f"Note: grade_registrations lookup skipped on academic reports: {ge}")

        try:
            cursor.execute("""
                SELECT subject_id, code, level_label, start_mark, end_mark, allocation_points
                FROM subject_grade_mark_overrides
                WHERE start_mark IS NOT NULL AND end_mark IS NOT NULL
                ORDER BY subject_id ASC, start_mark DESC, end_mark DESC
            """)
            for srow in (cursor.fetchall() or []):
                if isinstance(srow, dict):
                    sid = int(srow.get('subject_id') or 0)
                    ap = srow.get('allocation_points')
                    band = {
                        'code': (srow.get('code') or '').strip(),
                        'label': (srow.get('level_label') or '').strip(),
                        'start': float(srow.get('start_mark') or 0),
                        'end': float(srow.get('end_mark') or 0),
                        'allocation_points': float(ap) if ap is not None else None,
                    }
                else:
                    sid = int(srow[0] or 0) if len(srow) > 0 else 0
                    apv = srow[5] if len(srow) > 5 else None
                    band = {
                        'code': ((srow[1] if len(srow) > 1 else '') or '').strip(),
                        'label': ((srow[2] if len(srow) > 2 else '') or '').strip(),
                        'start': float(srow[3] or 0) if len(srow) > 3 else 0.0,
                        'end': float(srow[4] or 0) if len(srow) > 4 else 0.0,
                        'allocation_points': float(apv) if apv is not None else None,
                    }
                if sid <= 0:
                    continue
                if sid not in subject_bands:
                    subject_bands[sid] = []
                subject_bands[sid].append(band)
        except Exception as se:
            print(f"Note: subject_grade_mark_overrides lookup skipped on academic reports: {se}")

        class_bands = build_class_grade_bands_from_profiles(cursor)

        code_to_default_pts = {}
        for b in default_bands:
            ck = (b.get('code') or '').strip().upper()
            if ck and b.get('allocation_points') is not None:
                code_to_default_pts[ck] = b['allocation_points']
        for _sid, blist in subject_bands.items():
            for b in blist:
                if b.get('allocation_points') is None:
                    ck = (b.get('code') or '').strip().upper()
                    if ck in code_to_default_pts:
                        b['allocation_points'] = code_to_default_pts[ck]
        for _lid, blist in class_bands.items():
            for b in blist:
                if b.get('allocation_points') is None:
                    ck = (b.get('code') or '').strip().upper()
                    if ck in code_to_default_pts:
                        b['allocation_points'] = code_to_default_pts[ck]

        return default_bands, subject_bands, class_bands

    def _grade_from_settings(marks_value, default_bands, level_id=None, class_bands=None):
        if marks_value is None:
            return ''
        bands = resolve_grade_bands(level_id, class_bands or {}, default_bands)
        band = match_grade_band(marks_value, bands)
        if not band:
            return ''
        return (band.get('code') or band.get('label') or '').strip()

    def _grade_points_from_settings(marks_value, default_bands, level_id=None, class_bands=None):
        """Allocation / grade points using class grading setting or school default."""
        if marks_value is None or marks_value == '':
            return None
        bands = resolve_grade_bands(level_id, class_bands or {}, default_bands)
        _gc, pts = grade_code_and_points_from_pct(marks_value, bands)
        return pts

    def _lookup_name(query, value):
        if value is None or value == '':
            return None
        try:
            cursor.execute(query, (value,))
            rr = cursor.fetchone()
            if not rr:
                return None
            return rr.get('name') if isinstance(rr, dict) else rr[0]
        except Exception:
            return None

    def _short_exam_label(exam_name):
        """User-friendly exam title (drop year/term prefix when redundant)."""
        s = str(exam_name or '').strip()
        if not s:
            return ''
        parts = [p.strip() for p in s.split(' - ') if p.strip()]
        if len(parts) >= 3:
            term_part = next((p for p in parts if p.upper().startswith('TERM')), parts[-2])
            return f"{term_part} · {parts[-1]}"
        if len(parts) == 2:
            return parts[-1]
        return s

    def _resolve_exam_window():
        """Get first-to-latest exam span for current filters."""
        q = """
            SELECT exam_name, exam_date
            FROM exams
            WHERE 1=1
        """
        p = []
        if ay:
            q += " AND academic_year_id = %s"
            p.append(ay)
        if tid:
            q += " AND term_id = %s"
            p.append(tid)
        q, p = _sql_filter_academic_level_ids(q, p, 'academic_level_id', level_ids)
        if student_id:
            q += " AND id IN (SELECT DISTINCT exam_id FROM student_marks WHERE student_id = %s)"
            p.append(student_id)
        q += " ORDER BY exam_date ASC, id ASC"
        try:
            cursor.execute(q, p)
            items = cursor.fetchall() or []
        except Exception:
            return None
        if not items:
            return None
        first = items[0]
        last = items[-1]
        if isinstance(first, dict):
            first_name = str(first.get('exam_name') or '').strip()
            first_date_obj = first.get('exam_date')
        else:
            first_name = str(first[0] if len(first) > 0 else '').strip()
            first_date_obj = first[1] if len(first) > 1 else None
        if isinstance(last, dict):
            last_name = str(last.get('exam_name') or '').strip()
            last_date_obj = last.get('exam_date')
        else:
            last_name = str(last[0] if len(last) > 0 else '').strip()
            last_date_obj = last[1] if len(last) > 1 else None

        first_date = first_date_obj.strftime('%Y-%m-%d') if hasattr(first_date_obj, 'strftime') else (str(first_date_obj)[:10] if first_date_obj else '')
        last_date = last_date_obj.strftime('%Y-%m-%d') if hasattr(last_date_obj, 'strftime') else (str(last_date_obj)[:10] if last_date_obj else '')

        count = len(items)
        short_first = _short_exam_label(first_name)
        short_last = _short_exam_label(last_name)
        if count <= 1 and short_first:
            label = short_first
        elif count > 1 and short_first and short_first == short_last:
            label = f"{short_first} ({count} sittings)"
        elif count > 1 and short_first:
            label = f"{short_first} (+{count - 1} more)"
        elif short_first:
            label = short_first
        else:
            label = 'All exams'
        return {
            'first_exam_name': first_name,
            'first_exam_date': first_date,
            'last_exam_name': last_name,
            'last_exam_date': last_date,
            'exam_count': count,
            'label': label,
        }

