@app.route('/dashboard/employee/accounts/register', methods=['POST'])
@login_required
def register_finance_account():
    """Save a finance account record."""
    redir = _accountant_guard()
    if redir:
        return redir

    def _accounts_redirect(open_form=False):
        after = (request.form.get('after_register') or '').strip().lower()
        if after == 'petty-cash-book':
            url = employee_dash_url('accounts/petty-cash-book')
            if open_form:
                url += '?register=1'
            return url
        url = employee_dash_url('accounts')
        if open_form:
            url += '?register=1'
        return url

    redirect_url = _accounts_redirect()
    redirect_url_open = _accounts_redirect(open_form=True)

    after_register = (request.form.get('after_register') or '').strip().lower()
    existing_account_id = request.form.get('existing_finance_account_id', type=int)
    category_raw_early = (request.form.get('account_category') or '').strip().lower()
    if (
        after_register == 'petty-cash-book'
        and category_raw_early == 'petty cash'
        and existing_account_id
    ):
        petty_cash_vote_names = _parse_expense_vote_names_from_form(request.form)
        if not petty_cash_vote_names:
            flash('Please select at least one expense vote for this petty cash account.', 'error')
            return redirect(redirect_url_open)
        selected_payment_modes = _parse_finance_account_payment_mode_list(request.form)
        payment_records, payment_err = _prepare_finance_account_payment_records(
            request.form, selected_payment_modes
        )
        if payment_err:
            flash(payment_err, 'error')
            return redirect(redirect_url_open)
        description = normalize_text(
            request.form.get('account_description'), allow_empty=True
        )
        connection = get_db_connection()
        if not connection:
            flash('Could not connect to the database.', 'error')
            return redirect(redirect_url_open)
        try:
            with connection.cursor() as cursor:
                ok, message = _link_existing_account_to_petty_cash_book(
                    cursor,
                    existing_account_id,
                    description,
                    petty_cash_vote_names,
                    payment_records,
                )
                if ok:
                    connection.commit()
                    flash(message, 'success')
                    return redirect(
                        employee_dash_url('accounts/petty-cash-book')
                        + f'?finance_account_id={int(existing_account_id)}'
                    )
                connection.rollback()
                flash(message or 'Could not link account.', 'error')
                return redirect(redirect_url_open)
        except Exception as e:
            connection.rollback()
            print(f"register_finance_account link petty cash: {e}")
            flash('Could not link the account to the petty cash book.', 'error')
            return redirect(redirect_url_open)
        finally:
            connection.close()

    fields, field_err = _prepare_finance_account_fields_from_form(request.form)
    if field_err:
        flash(field_err, 'error')
        return redirect(redirect_url_open)
    category = fields['category']
    name = fields['name']
    description = fields['description']
    level_ids_raw = fields['level_ids_raw']
    selected_payment_modes = _parse_finance_account_payment_mode_list(request.form)
    payment_records, payment_err = _prepare_finance_account_payment_records(
        request.form, selected_payment_modes
    )
    if payment_err:
        flash(payment_err, 'error')
        return redirect(redirect_url_open)

    fields = _apply_finance_account_company_from_bank(
        fields, payment_records, selected_payment_modes
    )
    company_name = fields.get('company_name')
    company_number = fields.get('company_number')

    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(redirect_url_open)

    level_ids = []
    try:
        with connection.cursor() as cursor:
            ensure_finance_accounts_table(cursor)
            level_ids = _filter_valid_academic_level_ids(cursor, level_ids_raw)
    finally:
        connection.close()

    is_petty_cash = (category or '').strip().lower() == 'petty cash'
    petty_cash_vote_names = []
    if is_petty_cash:
        # Petty cash accounts are managed from the Petty cash book page (votes are chosen there).
        # Prevent registering them from the general accounts page where the UI does not show votes.
        if after_register != 'petty-cash-book':
            flash('Petty cash accounts must be registered from the Petty cash book page.', 'error')
            return redirect(
                employee_dash_url('accounts/petty-cash-book') + '?register=1'
            )
        petty_cash_vote_names = _parse_expense_vote_names_from_form(request.form)
        if not petty_cash_vote_names:
            flash('Please select at least one expense vote for this petty cash account.', 'error')
            return redirect(redirect_url_open)
    elif not level_ids:
        flash('Select at least one academic level to link to this account.', 'error')
        return redirect(redirect_url_open)

    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(redirect_url_open)

    try:
        with connection.cursor() as cursor:
            ensure_finance_accounts_table(cursor)
            recorded_by = (
                session.get('full_name') or session.get('username') or ''
            ).strip()
            cursor.execute(
                """
                INSERT INTO finance_accounts
                    (account_category, account_name, account_description,
                     company_name, company_number, recorded_by_name)
                VALUES (%s, %s, %s, %s, %s, %s)
                """,
                (
                    category,
                    name,
                    description or None,
                    company_name,
                    company_number,
                    recorded_by or None,
                ),
            )
            account_id = cursor.lastrowid
            if is_petty_cash:
                _save_finance_account_expense_votes(cursor, account_id, petty_cash_vote_names)
            elif level_ids:
                _save_finance_account_academic_levels(cursor, account_id, level_ids)
            _save_finance_account_payment_methods(cursor, account_id, payment_records)
            connection.commit()
            if is_petty_cash:
                flash(f'Petty cash account "{name}" registered.', 'success')
            else:
                level_count = len(level_ids)
                flash(
                    f'Account "{name}" ({category}) registered and linked to '
                    f'{level_count} class{"es" if level_count != 1 else ""}.',
                    'success',
                )
    except Exception as e:
        print(f"register_finance_account: {e}")
        flash('Could not save the account. Please try again.', 'error')
        return redirect(redirect_url_open)
    finally:
        connection.close()

    return redirect(redirect_url)


@app.route('/dashboard/employee/accounts/edit', methods=['POST'])
@app.route('/dashboard/employee/accounts/<int:account_id>/edit', methods=['POST'])
@login_required
def edit_finance_account(account_id=None):
    """Update a registered finance account."""
    redir = _accountant_guard()
    if redir:
        return redir

    account_id = request.form.get('finance_account_id', type=int) or account_id
    if not account_id:
        flash('Invalid account.', 'error')
        return redirect(employee_dash_url('accounts'))

    redirect_url = employee_dash_url('accounts')
    edit_url = redirect_url + f'?edit={account_id}'

    fields, field_err = _prepare_finance_account_fields_from_form(request.form)
    if field_err:
        flash(field_err, 'error')
        return redirect(edit_url)

    category = fields['category']
    name = fields['name']
    description = fields['description']
    level_ids_raw = fields['level_ids_raw']
    selected_payment_modes = _parse_finance_account_payment_mode_list(request.form)
    payment_records, payment_err = _prepare_finance_account_payment_records(
        request.form, selected_payment_modes
    )
    if payment_err:
        flash(payment_err, 'error')
        return redirect(edit_url)

    fields = _apply_finance_account_company_from_bank(
        fields, payment_records, selected_payment_modes
    )
    company_name = fields.get('company_name')
    company_number = fields.get('company_number')

    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(edit_url)

    level_ids = []
    try:
        with connection.cursor() as cursor:
            ensure_finance_accounts_table(cursor)
            if not _finance_account_exists(cursor, account_id):
                flash('Account not found.', 'error')
                return redirect(redirect_url)
            level_ids = _filter_valid_academic_level_ids(cursor, level_ids_raw)
            if not level_ids:
                flash('Select at least one academic level to link to this account.', 'error')
                return redirect(edit_url)
            cursor.execute(
                """
                UPDATE finance_accounts
                SET account_category = %s,
                    account_name = %s,
                    account_description = %s,
                    company_name = %s,
                    company_number = %s
                WHERE id = %s
                """,
                (
                    category,
                    name,
                    description,
                    company_name,
                    company_number,
                    account_id,
                ),
            )
            if not _finance_account_exists(cursor, account_id):
                flash('Account not found.', 'error')
                return redirect(redirect_url)
            _save_finance_account_academic_levels(cursor, account_id, level_ids)
            _save_finance_account_payment_methods(cursor, account_id, payment_records)
            connection.commit()
            flash(f'Account "{name}" updated successfully.', 'success')
    except Exception as e:
        print(f"edit_finance_account: {e}")
        connection.rollback()
        flash('Could not update the account. Please try again.', 'error')
        return redirect(edit_url)
    finally:
        connection.close()

    return redirect(redirect_url)


@app.route('/dashboard/employee/accounts/<int:account_id>/toggle-suspend', methods=['POST'])
@login_required
def toggle_finance_account_suspend(account_id):
    """Suspend or unsuspend a finance account."""
    redir = _accountant_guard()
    if redir:
        return redir

    redirect_url = employee_dash_url('accounts')
    connection = get_db_connection()
    if not connection:
        flash('Could not connect to the database.', 'error')
        return redirect(redirect_url)

    try:
        with connection.cursor() as cursor:
            ensure_finance_accounts_table(cursor)
            connection.commit()
            existing = _fetch_finance_account_by_id(cursor, account_id)
            if not existing:
                flash('Account not found.', 'error')
                return redirect(redirect_url)
            was_suspended = (existing.get('account_status') or 'active') == 'suspended'
            cursor.execute(
                """
                UPDATE finance_accounts
                SET account_status = IF(account_status = 'suspended', 'active', 'suspended')
                WHERE id = %s
                """,
                (account_id,),
            )
            connection.commit()
            label = existing.get('account_name') or 'Account'
            if was_suspended:
                flash(f'"{label}" is active again.', 'success')
            else:
                flash(f'"{label}" has been suspended.', 'success')
    except Exception as e:
        print(f"toggle_finance_account_suspend: {e}")
        connection.rollback()
        flash('Could not update account status.', 'error')
    finally:
        connection.close()

    return redirect(redirect_url)


